window.__D("text/zohar-hebrew-translation/c028",{"p":[[9522012178,"<p>רַבִּי חִיָּיא פָּתַח וְאָמַר פָּסוּק אַחֲרָיו, לֹא תְקַלֵּל חֵרֵשׁ וְלִפְנֵי עִוֵּר וְגוֹ'. פָּסוּק זֶה כְּמַשְׁמָעוֹ, אֲבָל מִפָּרָשָׁה זוֹ כֻּלָּהּ לָמַדְנוּ מִמֶּנָּה דְּבָרִים אֲחֵרִים, וְכֻלָּם תְּלוּיִים זֶה בָּזֶה. בֹּא רְאֵה, מִי שֶׁמְּקַלֵּל אֶת חֲבֵרוֹ, וְהוּא לְפָנָיו, וּמְבַיֵּשׁ אוֹתוֹ, כְּאִלּוּ שָׁפַךְ אֶת דָּמוֹ, וַהֲרֵי בֵּאַרְנוּ. וּפָסוּק זֶה כְּשֶׁאֵין חֲבֵרוֹ עִמּוֹ, וְהוּא קִלֵּל אוֹתוֹ, אוֹתוֹ הַדִּבּוּר עוֹלֶה.</p>\n<p>שֶׁאֵין לְךְ דִּבּוּר וְדִבּוּר שֶׁיּוֹצֵא מִפִּיו שֶׁאֵין לוֹ קוֹל. אוֹתוֹ קוֹל עוֹלֶה לְמַעְלָה, וְכַמָּה מַלְאֲכֵי חַבָּלָה מִתְחַבְּרִים לְאוֹתוֹ הַקּוֹל, עַד שֶׁעוֹלֶה וּמֵעִיר אֶת הַתְּהוֹם הַגָּדוֹל, כְּמוֹ שֶׁבֵּאֲרוּהָ, וְכַמָּה הֵם שֶׁמִּתְעוֹרְרִים עַל הָאָדָם. אוֹי לְמִי שֶׁמּוֹצִיא דָּבָר רַע מִפִּיו, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁוֹל, כְּמַשְׁמָעוֹ. וּפֵרְשׁוּהָ, בְּמִי שֶׁגּוֹרֵם לְאַחֵר לַחֲטֹא. וְכֵן מִי שֶׁמַּכֶּה אֶת בְּנוֹ הַגָּדוֹל. וְלִפְנֵי עִוֵּר לֹא תִתֵּן וְגוֹ', בְּמִי שֶׁלֹּא הִגִּיעַ לְהוֹרָאָה וּמוֹרֶה, (כמו שנאמר) שֶׁכָּתוּב (משלי ז) כִּי רַבִּים חֲלָלִים הִפִּילָה וַעֲצֻמִים כָּל הֲרֻגֶיהָ. וְזֶה עָבַר, מִשּׁוּם וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁוֹל, מִשּׁוּם שֶׁהִכְשִׁיל אֶת חֲבֵרוֹ לָעוֹלָם הַבָּא.</p>\n<p>שֶׁשָּׁנִינוּ, מִי שֶׁהוֹלֵךְ בְּדֶרֶךְ יְשָׁרָה בַּתּוֹרָה וּמִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה כָּרָאוּי, יֵשׁ לוֹ תָּמִיד חֵלֶק טוֹב לָעוֹלָם הַבָּא. שֶׁאוֹתוֹ דְּבַר הַתּוֹרָה שֶׁהוֹצִיא מִפִּיו, הוֹלֵךְ וּמְשׁוֹטֵט בָּעוֹלָם, וְעוֹלֶה לְמַעְלָה. וְכַמָּה עֶלְיוֹנִים קְדוֹשִׁים מִתְחַבְּרִים עִם אוֹתוֹ הַדָּבָר, וְעוֹלֶה בְּדֶרֶךְ יְשָׁרָה, וּמִתְעַטֵּר בַּעֲטָרָה קְדוֹשָׁה, וְרוֹחֵץ הַנָּהָר שֶׁל הָעוֹלָם הַבָּא, שׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן, וּמִתְקַבֵּל בּוֹ וְנִשְׁאָב לְתוֹכוֹ, וּמִתְעַנֵּג (ונטע) סְבִיב אוֹתוֹ הַנָּהָר, הָעֵץ הָעֶלְיוֹן. וְאָז שׁוֹפֵעַ וְיוֹצֵא אוֹר עֶלְיוֹן וּמִתְעַטֵּר עִם אוֹתוֹ אָדָם כָּל יוֹם, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וּמִי שֶׁעוֹסֵק (שלומד) בַּתּוֹרָה וְלֹא מִשְׁתַּדֵּל בָּהּ בְּדֶרֶךְ אֱמֶת וּבְדֶרֶךְ יְשָׁרָה, אוֹתוֹ הַדָּבָר עוֹלֶה וְסוֹטֶה בַדְּרָכִים, וְאֵין מִי שֶׁיִּתְחַבֵּר עִמּוֹ, וְהַכֹּל דּוֹחִים אוֹתוֹ הַחוּצָה, וְהוֹלֵךְ וּמְשׁוֹטֵט בָּעוֹלָם וְלֹא יִמְצָא מָקוֹם. מִי גָרַם לוֹ אֶת זֶה? אוֹתוֹ שֶׁהִסְטָה אוֹתוֹ מִדֶּרֶךְ הַיָּשָׁר. זֶהוּ שֶׁכָּתוּב וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁוֹל. וּמִשּׁוּם כָּךְ כָּתוּב, וְיָרֵאתָ מֵּאֱלֹהֶיךְ אֲנִי ה'.</p>\n<p>וּמִי שֶׁתְּשׁוּקָתוֹ לַעֲסֹק בַּתּוֹרָה וְלֹא מוֹצֵא מִי שֶׁיְּלַמֵּד אוֹתוֹ, וְהוּא בְּאַהֲבַת הַתּוֹרָה לוֹמֵד אוֹתָהּ, וּמְגַמְגֵּם בָּהּ בְּגִמְגּוּם שֶׁאֵינוֹ יוֹדֵעַ - כָּל דִּבּוּר וְדִבּוּר עוֹלֶה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שָׂמֵחַ בְּאוֹתוֹ דִבּוּר וּמְקַבֵּל אוֹתוֹ, וְנוֹטֵעַ אוֹתוֹ סְבִיב אוֹתוֹ הַנַּחַל, וְנַעֲשִׂים מֵאוֹתָם דִּבּוּרִים עֵצִים גְּדוֹלִים, וְנִקְרָאִים עַרְבֵי נַחַל. זֶהוּ שֶׁכָּתוּב (משלי ה) בְּאַהֲבָתָהּ תִּשְׁגֶּה תָמִיד.</p>\n<p>וְדָוִד הַמֶּלֶךְ אָמַר, (תהלים פו) הוֹרֵנִי ה' דַּרְכֶּךְ אֲהַלֵּךְ בַּאֲמִתֶּךְ. וְכָתוּב (שם כז) וּנְחֵנִי בְּאֹרַח מִישׁוֹר לְמַעַן שׁוֹרְרָי. אַשְׁרֵי אוֹתָם שֶׁיּוֹדְעִים אֶת דַּרְכֵי הַתּוֹרָה וּמִשְׁתַּדְּלִים בָּהּ בְּדֶרֶךְ יְשָׁרָה, שֶׁהֵם נוֹטְעִים עֲצֵי חַיִּים לְמַעְלָה, שֶׁכֻּלָּם רְפוּאָה. וּמִשּׁוּם כָּךְ כָּתוּב, (מלאכי כ) תּוֹרַת אֱמֶת הָיְתָה בְּפִיהוּ. וְכִי יֵשׁ תּוֹרָה שֶׁאֵינָהּ אֱמֶת? כֵּן, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁמּוֹרֶה מִי שֶׁלֹּא יוֹדֵעַ, וְאֵינוֹ אֱמֶת, וְאוֹתוֹ שֶׁלּוֹמֵד מִמֶּנּוּ, לוֹמֵד דָּבָר שֶׁאֵינוֹ אֱמֶת. וּמִשּׁוּם כָּךְ כָּתוּב, תּוֹרַת אֱמֶת הָיְתָה בְּפִיהוּ.</p>\n<p>וְעִם כָּל זֶה, צָרִיךְ אָדָם לִלְמֹד דִּבְרֵי תוֹרָה מִכָּל אָדָם, אֲפִלּוּ מִמִּי שֶׁאֵינוֹ יוֹדֵעַ. מִשּׁוּם שֶׁעַל כֵּן יִתְעוֹרֵר בַּתּוֹרָה, וְיָבא לִלְמֹד מִמִּי שֶׁיּוֹדֵעַ, וְאַחַר כָּךְ נִמְצָא שֶׁהוֹלֵךְ בַּתּוֹרָה בְּדֶרֶךְ אֱמֶת. בֹּא רְאֵה, יִשְׁתַּדֵּל אָדָם בָּעוֹלָם בַּתּוֹרָה וּבְמִצְווֹתֶיהָ אֲפִלּוּ שֶׁאֵין עוֹשֶׂה לִשְׁמָהּ, שֶׁמִּתּוֹךְ שֶׁלֹּא לִשְׁמָהּ בָּא לִשְׁמָהּ.</p>"],[9522012179,"<p>רַבִּי יוֹסֵי פָּתַח בַּפָּסוּק אַחֲרָיו וְאָמַר, לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט וְגוֹ'. לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט, כְּמַשְׁמָעוֹ. אֲבָל הֲרֵי נֶאֱמַר, שֶׁבַּפָּרָשָׁה הַזּוֹ יֵשׁ בָּהּ דְּבָרִים עֶלְיוֹנִים וְנִכְבָּדִים בְּמִצְווֹת הַתּוֹרָה. מִסּוֹף הַפָּסוּק הַזֶּה מַשְׁמָע, שֶׁכָּתוּב בְּצֶדֶק תִּשְׁפֹּט עֲמִיתֶךְ. בּא רְאֵה, שְׁתֵּי דְרָגוֹת הֵן כָּאן - מִשְׁפָּט וָצֶדֶק. מַה בֵּין זֶה לָזֶה? אֶלָּא אֶחָד רַחֲמִים וְאֶחָד דִּין, וְזֶה מִתְבַּשֵּׂם עִם זֶה.</p>\n<p>כְּשֶׁמִּתְעוֹרֵר צֶדֶק, הוּא דָּן דִּין אֶת הַכֹּל כְּאֶחָד, שֶׁאֵין בּוֹ רַחֲמִים וְלֹא וַתְּרָנוּת. כְּשֶׁמִּתְעוֹרֵר מִשְׁפָּט, יֵשׁ בּוֹ רַחֲמִים. יָכוֹל יִהְיֶה הַכֹּל בְּמִשְׁפָּט? בָּא הַכָּתוּב וְאוֹמֵר, בְּצֶדֶק תִּשְׁפֹּט עֲמִיתֶךְ. מָה הַטַּעַם? מִשּׁוּם שֶׁצֶּדֶק לֹא דָן אֶת זֶה וְעוֹזֵב אֶת זֶה, אֶלָּא כֻּלָּם כְּאֶחָד בְּמִשְׁקָל אֶחָד. כְּמוֹ כֵן, לֹא תִשָּׂא פְנֵי דָל וְלֹא תֶהְדַּר פְּנֵי גָדוֹל, אֶלָּא כֻּלָּם בְּמִשְׁקָל אֶחָד, בְּצֶדֶק. יָכוֹל יִהְיֶה הַכֹּל בְּצֶדֶק בִּלְבַדּוֹ? בָּא הַכָּתוּב וְאָמַר תִּשְׁפֹּט, שֶׁצָּרִיךְ לְחַבֵּר אוֹתָם כְּאֶחָד שֶׁלֹּא יִמָּצֵא זֶה בְּלִי זֶה, וְזוֹהִי שְׁלֵמוּת הַדִּין.</p>\n<p>וְכָל כָּךְ לָמָּה? מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מָצוּי שָׁם. וּמִשּׁוּם כָּךְ צָרִיךְ לְהַשְׁלִים אֶת הַדִּין. כְּמוֹ שֶׁהוּא עוֹשֶׂה לְמַטָּה, כְּמוֹ שֶׁלּוֹ מַמָּשׁ עוֹשֶׂה לְמַעְלָה. וּבֹא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא שָׂם כִּסֵּא שֶׁל דִּין בְּשָׁעָה שֶׁיּוֹשְׁבִים הַדַּיָּנִים, זֶהוּ שֶׁכָּתוּב (תהלים ט) כּוֹנֵן לַמִּשְׁפָּט כִּסְאוֹ. וּמִשָּׁם נִתְקָן כִּסְאוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִי הוּא הַכִּסֵּא? אֵלּוּ הֵם צֶדֶק וּמִשְׁפָּט. זֶהוּ שֶׁכָּתוּב (שם פט) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךְ. וּמִי שֶׁדָּן דִּין, צָרִיךְ לָדוּן (לשבת) בְּכִסֵּא הַמֶּלֶךְ. וְאִם פּוֹגֵם אֶחָד מֵהֶם, כְּאִלּוּ פָּגַם אֶת כִּסֵּא הַמֶּלֶךְ. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא מִסְתַּלֵּק מִבֵּין הַדַּיָּנִים, וְלֹא עוֹמֵד בְּדִינֵיהֶם. וּמָה אוֹמֵר? (שם יב) עַתָּה אָקוּם יֹאמַר ה' וְגוֹ'. וְרוּחַ הַקֹּדֶשׁ אוֹמֶרֶת, (שם נז) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים.</p>"],[9522012180,"<p>לֹא תִשְׂנָא אֶת אָחִיךְ בִּלְבָבֶךְ הוֹכֵחַ תּוֹכִיחַ אֶת עֲמִיתֶךְ וְגוֹ'. מִצְוָה זוֹ לְהוֹכִיחַ אֶת אוֹתוֹ שֶׁחָטָא לְהַרְאוֹת לוֹ אַהֲבָה רַבָּה, שֶׁאוֹהֵב אוֹתוֹ, כְּדֵי שֶׁהוּא לֹא יֵעָנֵשׁ. שֶׁהֲרֵי כָּתוּב בַּקָּדוֹשׁ בָּרוּךְ הוּא, כִּי אֶת אֲשֶׁר יֶאֱהַב ה' יוֹכִיחַ. וּכְמוֹ שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא וּמוֹכִיחַ אֶת מִי שֶׁאוֹהֵב אוֹתוֹ, כָּךְ יִלְמַד אָדָם מֵאוֹתָהּ הַדֶּרֶךְ וְיוֹכִיחַ אֶת חֲבֵרוֹ. בַּמֶּה מוֹכִיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם? הוּא מוֹכִיחוֹ בְּאַהֲבָה בַּסֵּתֶר. אִם יְקַבֵּל אוֹתוֹ - יָפֶה. וְאִם לֹא מוֹכִיחוֹ בֵּין אוֹהֲבָיו, אִם יְקַבֵּל - יָפֶה, וְאִם לֹא - מוֹכִיחוֹ בְגָלוּי לְעֵין כֹּל. אִם יְקַבֵּל - יָפֶה. וְאִם לֹא - מֵנִיחַ אוֹתוֹ וְלֹא מוֹכִיחַ אוֹתוֹ, וְעוֹזֵב אוֹתוֹ שֶׁיֵּלֵךְ וְיַעֲשֶׂה אֶת רְצוֹנוֹ.</p>\n<p>בָּרִאשׁוֹנָה מוֹדִיעָה לוֹ בַסֵּתֶר, כְּדֵי לְהוֹכִיחַ אוֹתוֹ וּלְעוֹרֵר אוֹתוֹ, שֶׁלֹּא יַכִּיר בּוֹ בֶּן אָדָם. וְזֶה הוּא בֵּינוֹ לְבֵינוֹ. אִם מְקַבֵּל - טוֹב, וְאִם לֹא - מוֹדִיעַ לוֹ בֵּין אוֹהֲבָיו. בִּזְמַן שֶׁהַכֹּהֵן הַגָּדוֹל הָיָה בָעוֹלָם, נָתַן לוֹ מַחֲלָה בְמִטָּתוֹ, וּבָאוּ אוֹהֲבָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמוֹדִיעִים לוֹ, שֶׁאִם יֵשׁ בּוֹ חוֹבָה שֶׁיָּשׁוּב מִמֶּנָּה וִיעַיֵּן בִּדְבָרָיו. אִם מְקַבֵּל - מוּטָב, וְאִם לֹא - מוֹכִיחַ אוֹתוֹ בְגָלוּי, בְּמָמוֹנוֹ, בְּבָנָיו, שֶׁכֻּלָּם מְדַבְּרִים עָלָיו וְיָבוֹאוּ אֵלָיו. אִם מְקַבֵּל - מוּטָב, וְאִם לֹא - מַתִּיר לוֹ קוֹנוֹ לַעֲשׂוֹת רְצוֹנוֹ, וְלֹא מַחֲזִיק בּוֹ לְעוֹלָמִים. כְּגוֹן זֶה צָרִיךְ לוֹ לְהוֹכִיחַ לַחֲבֵרוֹ בָּרִאשׁוֹנָה בַּסֵּתֶר, וְאַחַר כָּךְ בֵּין אוֹהֲבָיו, וּלְבַסּוֹף בְּגָלוּי. מִכָּאן וּלְהָלְאָה יַעֲזֹּב לוֹ וְיַעֲשֶׂה כִרְצוֹנוֹ.</p>\n<p>וְעַל זֶה כָּתוּב הוֹכֵחַ תּוֹכִיחַ. הוֹכֵחַ - בַּסֵּתֶר, שֶׁלֹּא יֵדַע בּוֹ בֶּן אָדָם. תּוֹכִיחַ - בֵּין חֲבֵרָיו וְאוֹהֲבָיו. אֶת עֲמִיתֶךְ - בְּגָלוּי. וְעַל כֵּן לֹא כָתוּב בָּרִאשׁוֹנָה תּוֹכִיחַ, אֶלָּא הוֹכֵחַ. וְעוֹד הוֹכֵחַ - אִם הוּא אָדָם שֶׁיִּתְבַּיֵּשׁ, לֹא יֹאמַר לוֹ וְלֹא יוֹכִיחַ אוֹתוֹ אֲפִלּוּ בַּסֵּתֶר, אֶלָּא יֹאמַר לְפָנָיו כְּמִי שֶׁמְּסַפֵּר בִּדְבָרִים אֲחֵרִים. וּבְתוֹךְ אוֹתָם דְּבָרִים יַזְכִּיר מִי שֶׁעוֹשֶׂה אוֹתוֹ הַחֵטְא הוּא כָּךְ וְכָךְ, כְּדֵי שֶׁהוּא יֵדַע בְּעַצְמוֹ וְיַעֲזֹב אֶת אוֹתוֹ הַחֵטְא. וְעַל כֵּן הוֹכֵחַ. וְאִם לֹא - תּוֹכִיחַ. וְאַחַר כָּךְ אֶת עֲמִיתֶךְ - בְּגָלוּי. מִכָּאן וָהָלְאָה - וְלֹא תִשָּׂא עָלָיו חֵטְא.</p>\n<p>דָּבָר אַחֵר וְלֹא תִשָּׂא עָלָיו חֵטְא - שֶׁהֲרֵי כֵּיוָן שֶׁאָדָם מוֹכִיחַ אֶת חֲבֵרוֹ וּמִזְדַּמֵּן לְהוֹכִיחוֹ בְּגָלוּי, לֹא יַעֲלֶה לְפָנָיו אוֹתוֹ חֵטְא שֶׁעָשָׂה, שֶׁאָסוּר לוֹ וַדַּאי, אֶלָּא יֹאמַר סְתָם, וְלֹא יַעֲלֶה עָלָיו אוֹתוֹ חֵטְא בְּגָלוּי, וְלֹא יִרְשֹׁם עָלָיו חֵטְא. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל כְּבוֹדוֹ שֶׁל אָדָם אֲפִלּוּ בָּרְשָׁעִים. (עד כאן רעיא מהימנא).</p>\n<p>פָּתַח וְאָמַר, וַיְהִי קוֹל הַשֹּׁפָר הוֹלֵךְ וְגוֹ'. וַיְהִי קוֹל הַשֹּׁפָר, כָּאן נֶחְלְקוּ סִפְרֵי הַקַּדְמוֹנִים וְכוּ', עַד שֶׁבָּאוּ רַבִּי אַבָּא וְרַבִּי יְהוּדָה, וְהוֹדוּ לְרַבִּי אָחָא.</p>"],[9522012181,"<p>קָמוּ, עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי אֶלְעָזָר, לֹא תֵלֵךְ רָכִיל בְּעַמֶּיךְ, לֹא תִשְׂנָא אֶת אָחִיךְ, לֹא תִקֹּם וְלֹא תִטֹּר. הֲרֵי בֵּאַרְנוּ אוֹתָם, וְכֻלָּם הִתְעורְרוּ עֲלֵיהֶם הַחֲבֵרִים. אֲבָל נֶאֱמַר דָּבָר בַּפָּרָשָׁה הַזּו. כָּתוּב אֶת חֻקֹּתַי תִּשְׁמֹרוּ, בְּהֶמְתְּךְ לֹא תַרְבִּיעַ כִּלְאַיִם, שָׂדְךְ לֹא תִזְרַע כִּלְאָיִם, וּבֶגֶד כִּלְאַיִם שַׁעַטְנֵז לֹא יַעֲלֶה עָלֶיךְ.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, אַתֶּם עֵדַי נְאֻם ה' וְעַבְדִּי אֲשֶׁר בָּחַרְתִּי לְמַעַן תֵּדְעוּ וְתַאֲמִינוּ וְגוֹ'. אַתֶּם עֵדַי, אֵלּוּ הֵם יִשְׂרָאֵל. וְשָׁנִינוּ, אֵלּוּ הֵם שָׁמַיִם וָאָרֶץ, שֶׁכָּתוּב (דברים ד) הַעִידתִי בָכֶם הַיּוֹם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. אֲבָל יִשְׂרָאֵל הֵם עֵדִים אֵלּוּ עַל אֵלּוּ, וְשָׁמַיִם וְאֶרֶץ וְהַכֹּל עֵדִים עֲלֵיהֶם. וְעַבְדִּי אֲשֶׁר בָּחַרְתִּי - זֶה יַעֲקֹב, שֶׁכָּתוּב (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר, וְכָתוּב אַל תִּירָא עַבְדִּי יַעֲקֹב. וְיֵשׁ אוֹמְרִים, זֶה דָּוִד. וְנִקְרָא דָּוִד עַבְדִּי, שֶׁכָּתוּב (שם לז) לְמַעֲנִי וּלְמַעַן דָּוִד עַבְדִּי אֲשֶׁר בָּחַרְתִּי, זֶה דָּוִד הָעֶלְיוֹן.</p>\n<p>לְמַעַן תֵּדְעוּ וְתַאֲמִינוּ לִי וְתָבִינוּ כִּי אֲנִי הוּא (ישעיה מג). מַה זֶּה כִּי אֲנִי הוּא? שֶׁהִתְרַצֵּיתִי בְּאוֹתוֹ דָוִד וּבְאוֹתוֹ יַעֲקֹב, אֲנִי הוּא הֵם מַמָּשׁ. לְפָנַי לֹא נוֹצַר אֵל, שֶׁשָּׁנִינוּ, קָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַעֲקֹב אֵל, שֶׁכָּתוּב (בראשית לו) וַיִּקְרָא אֵל אֱלֹהֵי יִשְׂרָאֵל. הַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לְיַעֲקֹב אֵל. זֶהוּ שֶׁכָּתוּב לְפָנַי לֹא נוֹצַר אֵל וְאַחֲרַי לֹא יִהְיֶה. וּמִשּׁוּם כָּךְ אֲנִי הוּא, הַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר. וְאַחֲרַי לֹא יִהְיֶה, שֶׁהֲרֵי דָּוִד נִקְרָא כָּךְ, וְאֵין אַחֲרָיו אַחֵר.</p>\n<p>בֹּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, תִּקֵּן כָּל דָּבָר וְדָבָר, כָּל אֶחָד וְאֶחָד בְּצִדּוֹ, וּמִנָּה עֲלֵיהֶם כֹּחוֹת עֶלְיוֹנִים. וְאֵין לְךְ אֲפִלּוּ עֵשֶׂב קָטָן בָּאָרֶץ שֶׁאֵין לוֹ כֹּחַ עֶלְיוֹן לְמַעְלָה. וְכָל מַה שֶּׁעוֹשִׂים עִם כָּל אֶחָד וְאֶחָד, (שתי נוסחאות) וְכָל מַה שֶּׁכָּל אֶחָד וְאֶחָד עוֹשֶׂה, הַכֹּל הוּא בְּחֹזֶק שֶׁל אוֹתוֹ הַכֹּחַ הָעֶלְיוֹן שֶׁמְּמֻנֶּה עָלָיו מִלְמַעְלָה. וְכָל הַהַנְהָגוֹת גְּזוּרוֹת מִן הַדִּין, עַל דִּין הֵם נוֹסְעִים, וְעַל הַדִּין הֵם עוֹמְדִים. אֵין מִי שֶׁיּוֹצֵא מִמְּקוֹמוֹ הַחוּצָה.</p>\n<p>וְכָל הַמְמֻנִּים, מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, נִתְמַנּוּ שַׁלִּיטִים עַל כָּל דָּבָר וְדָבָר, וְכֻלָּם מִתְנַהֲגִים עַל הַנְהָגָה אַחֶרֶת עֶלְיוֹנָה שֶׁנּוֹטְלִים כָּל אֶחָד וְאֶחָד, כְּמוֹ שֶׁכָּתוּב (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ. כֵּיוָן שֶׁנּוֹטְלִים אוֹתוֹ חֹק, כֻּלָּם נִקְרָאִים חֻקּוֹת, וְאוֹתוֹ הַחֹק שֶׁנִּתָּן לָהֶם בָּא מִשָּׁמַיִם, וְאָז נִקְרָאִים חֻקּוֹת שָׁמַיִם. וּמִנַּיִן שֶׁבָּאִים מִשָּׁמַיִם? שֶׁכָּתוּב (תהלים פא) כִּי חֹק לְיִשְׂרָאֵל הוּא.</p>\n<p>וְעַל כֵּן כָּתוּב אֶת חֻקֹּתַי תִּשְׁמֹרוּ, מִשּׁוּם שֶׁכָּל אֶחָד וְאֶחָד מְמֻנֶּה עַל דָּבָר יָדוּעַ בָּעוֹלָם, בְּאוֹתוֹ הַחֹק. מִשּׁוּם כָּךְ אָסוּר לְהַחֲלִיף מִינִים וּלְהַכְנִיס מִין בְּמִין אַחֵר, מִשּׁוּם שֶׁעוֹקֵר אֶת כָּל כֹּחַ וְכֹחַ מִמְּקוֹמוֹ, (ומכחיש פמליא של מעלה) וּמַכְחִישׁ אֶת פִּרְסוּם הַמֶּלֶךְ.</p>\n<p>כִּלְאַיִם, מַהוּ כִּלְאַיִם? כְּמִי שֶׁנּוֹתֵן מִישֶׁהוּ אַחֵר בְּבֵית הָאֲסוּרִים, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לז) אֶל בֵּית הַכֶּלֶא, כְּדֵי לֹא לַעֲשׂוֹת דָּבָר. כִּלְאַיִם - מְנִיעָה, שֶׁמּוֹנֵעַ אֶת כָּל אוֹתָם הַכֹּחוֹת מִן הַמַּעֲשֶׂה שֶׁלָּהֶם. כִּלְאַיִם - עִרְבּוּבְיָה, שֶׁעוֹשֶׂה עִרְבּוּבְיָה בַּכֹּחַ שֶׁלְּמַעְלָה וּמַכְחִישׁ אֶת פִּרְסוּם הַמֶּלֶךְ, כְּמוֹ שֶׁנֶּאֱמַר וּבֶגֶד כִּלְאַיִם שַׁעַטְנֵז לֹא יַעֲלֶה עָלֶיךְ.</p>\n<p>בֹּא רְאֵה, כָּתוּב (בראשית ב) וּמֵעֵץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ כִּי בְּיוֹם אֲכָלְךְ מִמֶּנּוּ מוֹת תָּמוּת. וַהֲרֵי נִתְבָּאֵר, שֶׁשִּׁנָּה מִצְוַת הַמֶּלֶךְ, וְהֶחֱלִיף עֵץ חַיִּים, שֶׁבּוֹ הִשְׁתַּלֵּם הַכֹּל וּבוֹ תְּלוּיָה הָאֱמוּנָה, וְנִדְבַּק בְּמָקוֹם אַחֵר. וַהֲרֵי שָׁנִינוּ, בַּכֹּל צָרִיךְ אָדָם לְהַרְאוֹת מַעֲשֶׂה כְּמוֹ שֶׁלְּמַעְלָה וְלַעֲשׂוֹת מַעֲשֶׂה כְּמוֹ שֶׁצָּרִיךְ. וְאִם שִׁנָּה בְּדָבָר אַחֵר, הוּא מַשְׁפִּיעַ לְהַשְׁרוֹת בּוֹ דָּבָר אַחֵר שֶׁלֹּא צָרִיךְ.</p>\n<p>וּבֹא רְאֵה, בְּשָׁעָה שֶׁאָדָם מַרְאֶה לְמַטָּה בְּדֶרֶךְ יְשָׁרָה כְּמוֹ שֶׁצָּרִיךְ, שׁוֹפַעַת וְיוֹצֵאת וְשׁוֹרָה עָלָיו רוּחַ קְדוֹשָׁה עֶלְיוֹנָה. וּבְשָׁעָה שֶׁהוּא מַרְאֶה מַעֲשֶׂה לְמַטָּה בְּדֶרֶךְ עֲקֻמָּה, שֶׁאֵינָהּ דֶּרֶךְ יְשָׁרָה, אָז שׁוֹפַעַת וְיוֹצֵאת וְשׁוֹרָה עָלָיו רוּחַ אַחֶרֶת, שֶׁלֹּא צְרִיכָה, שֶׁמַּסְטָה אֶת הָאָדָם לְצַד רַע. מִי מוֹשֵׁךְ עָלָיו אוֹתָהּ הָרוּחַ? הֱוֵה אוֹמֵר, אוֹתוֹ מַעֲשֶׂה שֶׁהֶרְאָה בְּצַד אַחֵר.</p>\n<p>כָּתוּב (משלי לא) דָּרְשָׁה צֶמֶר וּפִשְׁתִּים. דָּרְשָׁה, מַהוּ דָּרְשָׁה? שֶׁמְּבַקֶּשֶׁת וְדוֹרֶשֶׁת עַל צֶמֶר וּפִשְׁתִּים, מִי שֶׁמְּחַבֵּר אוֹתָם כְּאֶחָד. וְאִם תֹּאמַר לָמָּה בְּצִיצִית מֻתָּר? הֲרֵי פֵּרְשׁוּהָ. אֲבָל שָׁם הוּא אוֹתוֹ לְבוּשׁ בְּתִקּוּנוֹ, בְּהַשְׁלָמַת הַמַּעֲשֶׁה כָּרָאוּי.</p>\n<p>(וזה) עוֹד, דָּרְשָׁה צֶמֶר וּפִשְׁתִּים - לַעֲשׂוֹת נְקָמָה בְּמִי שֶׁמְּחַבֵּר אוֹתָם יַחַד. אֲבָל מָתַי שׁוֹרָה? בְּשָׁעָה שֶׁהוּא בִּשְׁלֵמוּת, שֶׁכָּתוּב וַתַּעַשׂ בְּחֵפֶץ כַּפֶּיהָ. וְצִיצִית, הֲרֵי בֵּאַרְנוּ שֶׁשָּׁם בְּאוֹתוֹ הַכְּלָל שֶׁל הַשְּׁלֵמוּת נִמְצָא, וְלֹא עוֹשֶׂה דָבָר. אֲבָל בְּשָׁעָה שֶׁלֹּא נִמְצָא בִשְׁלֵמוּת, מִי שֶׁבָּא לְחַבְּרָם יַחַד, מְעוֹרֵר עָלָיו רוּחַ שֶׁאֵינָהּ צְרִיכָה.</p>\n<p>מִי מוֹכִיחַ דָּבָר זֶה? קַיִן וְהֶבֶל מוֹכִיחִים, שֶׁזֶּה בָּא מִצַּד אֶחָד, וְזֶה בָּא מִצַּד אַחֵר, וּמִשּׁוּם כָּךְ אֵינֶנּוּ צְרִיכִים לְחַבְּרָם יַחַד. (מי מוכיח דבר זה, ' קין והבל מוכיחים) וְקָרְבָּנוֹ שֶׁל קַיִן הִתְרַחֵק מִלִּפְנֵי קָרְבָּנוֹ שֶׁל הֶבֶל.</p>\n<p>וְעַל כֵּן, וּבֶגֶד כִּלְאַיִם שַׁעַטְנֵז לֹא יַעֲלֶה עָלֶיךְ. לֹא יַעֲלֶה עָלֶיךְ סְתָם, לֹא יַעֲלֶה עָלֶיךְ רוּחַ אַחֶרֶת לִשְׁלֹט בְּךְ. וְצָרִיךְ לוֹ לָאָדָם לְהַרְאוֹת מַעֲשֶׂה כָּשֵׁר כְּמוֹ שֶׁרָאוּי, וּבְאוֹתוֹ מַעֲשֶׂה שׁוֹרָה עָלָיו רוּחַ קְדוֹשָׁה, רוּחַ עֶלְיוֹנָה, לְהִתְקַדֵּשׁ בּוֹ. בָּא לְהִתְקַדֵּשׁ - מְקַדְּשִׁים אוֹתוֹ, שֶׁכָּתוּב וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים כִּי קָדוֹשׁ אֲנִי ה'.</p>\n<p>כָּתוּב וּמֵעֵץ הַדַּעַת טוֹב וָרָע. וּמָה עַל זֶה גָּרַם אָדָם מִיתָה בָּעוֹלָם - מִי שֶׁמַּרְאֶה מַעֲשֶׂה אַחֵר שֶׁלֹּא צָרִיךְ עַל אַחַת כַּמָּה וְכַמָּה. שׁוֹר וַחֲמוֹר מוֹכִיחִים. מִצַּד זֶה נִקְרָא שׁוֹר, וּמִצַּד זֶה נִקְרָא חֲמוֹר. וְעַל כֵּן כָּתוּב, (דברים כב) לֹא תַחֲרשׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו. אַל תַּעֲשֶׂה עִרְבּוּבְיָה יַחַד, מִשּׁוּם שֶׁמִּתְעוֹרֵר לְהִתְחַבֵּר הַצַּד הָאַחֵר כְּאֶחָד לְהָרַע לָעוֹלָם. וּמִי שֶׁמַּפְרִידָם, מַרְבֶּה שָׁלוֹם בָּעוֹלָם. אַף כָּאן מִי שֶׁמַּפְרִיד אוֹתָם בְּאוֹתוֹ גָוֶן כְּמוֹ שֶׁאָמְרוּ, שֶׁלֹּא נִמְצָא שׁוֹעַ טָווּי וְנוּז כְּאֶחָד, זֶה אָדָם שֶׁמַּרְבֶּה שָׁלוֹם עָלָיו וְעַל כָּל הָעוֹלָם.</p>\n<p>קָרְבָּנוֹ שֶׁל קַיִן הָיָה פִּשְׁתִּים, וְקָרְבָּנוֹ שֶׁל הֶבֶל הָיוּ צֶמֶר, לֹא זֶה כְּזֶה, וְלֹא זֶה כְּזֶה. סוֹד הַדָּבָר - קַיִן הָיָה כִּלְאַיִם, עִרְבּוּבְיָה שֶׁאֵינָהּ נִצְרֶכֶת, הַצַּד הָאַחֵר, שֶׁאֵינוֹ מִינָם שֶׁל אָדָם וְחַוָּה, וְקָרְבָּנוֹ מֵאוֹתוֹ הַצַּד הוּא בָּא. הֶבֶל מִצַּד אֶחָד שֶׁל אָדָם וְחַוָּה. וּבְמֵעֶיהָ שֶׁל חַוָּה הִתְחַבְּרוּ שְׁנֵי הַצְּדָדִים הַלָּלוּ. וּמִשּׁוּם שֶׁהִתְחַבְּרוּ כְאֶחָד, לֹא בָאָה מֵהֶם תּוֹעֶלֶת לָעוֹלָם וְנֶאֶבְדוּ.</p>\n<p>וְעַד הַיּוֹם הַזֶּה הַצַּד שֶׁלָּהֶם קַיָּם. וּמִי שֶׁמַּרְאֶה אֶת עַצְמוֹ בַּמַּעֲשֶׂה שֶׁל הַחִבּוּר הַזֶּה, מְעוֹרֵר עָלָיו אֶת אוֹתָם הַצְּדָדִים כְּאֶחָד, וְיָכוֹל לְהִנָּזֵק, וְשׁוֹרָה עָלָיו רוּחַ אַחֶרֶת שֶׁאֵינָהּ צְרִיכָה. וְיִשְׂרָאֵל צְרִיכִים לְעוֹרֵר עֲלֵיהֶם רוּחַ קְדֻשָּׁה לִהְיוֹת קְדוֹשִׁים, לְהִמָּצֵא בְשָׁלוֹם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>כָּתוּב (ויקרא ו) וְלָבַשׁ הַכֹּהֵן מִדּוֹ בַד וּמִכְנְסֵי בַד יִהְיוּ עַל בְּשָׂרוֹ, (שם טז) וּבְאַבְנֵט בַּד יַחְגֹּר. לָמָּה נִקְרָא בַּד, יְחִידִי? מִשּׁוּם שֶׁלֹּא צָרִיךְ לְחַבֵּר אֶת הַפִּשְׁתִּים הַזֶּה עִם אַחֵר, וְעַל כֵּן לֹא כָתוּב מִדּוֹ פִּשְׁתִּים, אֶלָּא בַּד, יְחִידִי.</p>\n<p>וְלָמָּה הַכֹּהֵן צָרִיךְ לְהֵרָאוֹת בָּזֶה? אֶלָּא לְבוּשֵׁי הַבַּד הַלָּלוּ צָרִיךְ לְהֵרָאוֹת בָּהֶם עַל מִזְבַּח הָעוֹלָה, כְּשֶׁהָיָה מְפַנֶּה אֶת הַדֶּשֶׁן (האפר) שֶׁל דֶּשֶׁן הָעוֹלָה, שֶׁהֲרֵי הָעוֹלָה בָּאָה מֵהַצַּד שֶׁל עֲבוֹדָה זָרָה וְהִרְהוּר רַע. וּמִשּׁוּם כָּךְ צָרִיךְ לְהֵרָאוֹת בָּהֶם בִּלְבַדָּם, וְלֹא בְּעִרְבּוּבְיָה כְּפִי שֶׁאָמַרְנוּ, כְּדֵי שֶׁיִּתְכַּפְּרוּ לָאָדָם כָּל אוֹתָם חֲטָאִים שֶׁבָּאִים מֵאוֹתוֹ הַצַּד.</p>\n<p>וּכְשֶׁנִּכְנַס לַמִּקְדָּשׁ, הַמָּקוֹם שֶׁשָּׁם נִמְצֵאת הַשְּׁלֵמוּת וְכָל אוֹתָן עֲבוֹדוֹת הַשְּׁלֵמוּת, אַף עַל גַּב שֶׁהִתְחַבְּרוּ, אֵין לָנוּ בָּזֶה עִנְיָן, כְּמוֹ שֶׁאָמַרְנוּ בְצִיצִית, מִשּׁוּם שֶׁשָּׁם נִמְצְאוּ וְהִתְחַבְּרוּ כָּל אוֹתָם הַמִּינִים שֶׁלְּמַעְלָה, וְכָל אוֹתָם כְּלֵי הַמִּקְדָּשׁ, נִמְצָאִים בּוֹ כַּמָּה מִינִים שׁוֹנִים זֶה מִזֶּה, וְכֻלָּם נִכְלְלוּ שָׁם כְּמוֹ שֶׁלְּמַעְלָה. אַשְׁרֵיהֶם יִשְׂרָאֵל, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרַת אֱמֶת, תּוֹרָה שֶׁל אֱמוּנָה, וְאָהַב אוֹתָם מִכָּל שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, שֶׁכָּתוּב (מלאכי א) אָהַבְתִּי אֶתְכֶם אָמַר ה'.</p>"],[9522012182,"<p>פָּתַח רַבִּי חִיָּיא אַחֲרָיו וְאָמַר, כִּי תָבֹאוּ אֶל הָאָרֶץ וּנְטַעְתֶּם כָּל עֵץ מַאֲכָל וְגוֹ', וּבַשָּׁנָה הָרְבִיעִת יִהְיֶה כָּל פִּרְיוֹ קֹדֶשׁ הִלּוּלִים לַה'. כִּי תָבאוּ אֶל הָאָרֶץ, הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים. אֲבָל בּא רְאֵה, שֶׁהֲרֵי הָאִילָן אֵינוֹ עוֹשֶׂה פֵרוֹת, אֶלָּא בָּאָרֶץ, וְהָאָרֶץ מוֹצִיאָה אוֹתָם וּמַרְאָה אֶת אוֹתוֹ הַפְּרִי לָעוֹלָם. וְאֵין הָאָרֶץ עוֹשֶׂה פֵּרוֹת אֶלָּא מִתּוֹךְ אוֹתוֹ כֹּחַ אַחֵר שֶׁמֵּעָלֶיהָ, כְּמוֹ שֶׁהַנְּקֵבָה אֵינָהּ עוֹשָׂה פֵּרוֹת אֶלָּא מִתּוֹךְ כֹּחַ הַזָּכָר.</p>\n<p>וְאוֹתוֹ הַפְּרִי לֹא נִשְׁלָם בִּשְׁלֵמוּת עַד שָׁלֹשׁ שָׁנִים, וְהַכֹּחַ לֹא נִפְקָד עָלָיו לְמַעְלָה עַד שֶׁנִּשְׁתַּלֵּם. אַחַר שֶׁהִשְׁתַּלֵּם, נִפְקָד עָלָיו הַכֹּחַ, וְהָאָרֶץ מִתְתַּקֶּנֶת בּוֹ. שֶׁהֲרֵי עַד שָׁלֹשׁ שָׁנִים אֵין הָאָרֶץ מִתְתַּקֶּנֶת בּוֹ וְלֹא (נמצאת) מִשְׁתַּלֶּמֶת (מתבשמת) (מסכימה) עִמּוֹ. אַחַר שֶׁהִשְׁתַּלְּמוּ וְהִתְתַּקְּנוּ כְאֶחָד, אֲזַי זוֹ שְׁלֵמוּת.</p>\n<p>בֹּא רְאֵה, הַנְּקֵבָה, עַד שֶׁמִּתְעַבֶּרֶת שָׁלֹשׁ פְּעָמִים, פְּרֵי מֵעֶיהָ לֹא נִשְׁלָם. אַחַר שְׁלֹשָׁה הֶרְיוֹנוֹת הַנְּקֵבָה מִתְתַּקֶּנֶת בְּאוֹתוֹ הַפְּרִי, וּמַסְכִּימִים כְּאֶחָד. אֲזַי אוֹתוֹ הַפְּרִי הוּא שְׁלֵמוּת הַכֹּל וְהַיֹּפִי שֶׁל הַכֹּל. אַחַר שֶׁיָּצָא, עַד שָׁלֹשׁ שָׁנִים אֵין לוֹ כֹּחַ לְמַעְלָה, שֶׁהֲרֵי אָז הִיא הַבְשָׁלָתוֹ. לֵוִי נִרְצָה מֵהַכֹּל, שְׁלִישִׁי לְאִמּוֹ, שֶׁהִתְתַּקְּנָה בוֹ וְהִסְכִּימָה (והתבשמה) עִמּוֹ.</p>\n<p>אַחַר שָׁלֹשׁ שָׁנִים הִתְמַנָּה עָלָיו (התמנה עליה) כֹּחַ עֶלְיוֹן לְמַעְלָה, וּבַשָּׁנָה הָרְבִיעִית יִהְיֶה כָּל פִּרְיוֹ קֹדֶשׁ הִלּוּלִים. מַהוּ קֹדֶשׁ הִלּוּלִים? תִּשְׁבָּחוֹת לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. עַד כָּאן. מִכָּאן וְאֵילָךְ סוֹד הַדָּבָר, שֶׁבַּשָּׁנָה הָרְבִיעִית מִזְדַּוֶּגֶת כְּנֶסֶת יִשְׂרָאֵל עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהִלּוּלָה אַחַת נִמְצֵאת, שֶׁכָּתוּב קֹדֶשׁ הִלּוּלִים, הִלּוּלָה וְשִׂמְחָה בְּפַעַם (בזווג) אַחַת.</p>\n<p>מַה זֶּה הַשָּׁנָה (הרביעית) ? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְשָׁנִינוּ, שָׁנָה הָרְבִיעִית זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא עַמּוּד רְבִיעִי לַכִּסֵּא, וְהַכֹּל אֶחָד, שֶׁהֲרֵי אָז מִזְדַּוֵּג הַקָּדוֹשׁ בָּרוּךְ הוּא עִם כְּנֶסֶת יִשְׂרָאֵל, וְאָז הִיא קֹדֶשׁ, וְנִמְצֵאת הִלּוּלָה קְדוֹשָׁה, (והקדוש ברוך הוא מזדוג עמה) וְאָז הַחֲיָלוֹת מִתְמַנִּים עַל הָעוֹלָם, עַל כָּל דָּבָר וְדָבָר כָּרָאוּי לוֹ. מִכָּאן וָהָלְאָה כֻּלָּם מִתְבָּרְכִים וּמֻתָּרִים לְמַאֲכָל, שֶׁהֲרֵי כֻּלָּם בִּשְׁלֵמוּת הַכֹּל, בַּשְּׁלֵמוּת שֶׁל מַעְלָה וּמַטָּה.</p>\n<p>וְעַד שֶׁלֹּא נִשְׁלָם בַּכֹּל מִמַּטָּה וּמִמַּעְלָה, אָסוּר לֶאֱכֹל מִמֶּנּוּ. וּמִי שֶׁאוֹכֵל מִמֶּנּוּ, כְּמִי שֶׁאֵין לוֹ חֵלֶק בַּקָּדוֹשׁ בָּרוּךְ הוּא וּבִכְנֶסֶת יִשְׂרָאֵל, שֶׁהֲרֵי אוֹתוֹ הַפְּרִי עוֹמֵד בְּלִי רְשׁוּת עֶלְיוֹנָה קְדוֹשָׁה, שֶׁאֵינָהּ שׁוֹרָה עָלָיו עַד שֶׁיִּשְׁתַּלֵּם. וּבְלִי רְשׁוּת תַּחְתּוֹנָה, שֶׁהֲרֵי לֹא הִסְכִּימָה (התבשמה) כֹּחַ הָאָרֶץ בּוֹ. וְאוֹתוֹ שֶׁאָכַל מִמֶּנּוּ, מַרְאֶה אֶת עַצְמוֹ שֶׁאֵין לוֹ חֵלֶק לְמַעְלָה וּלְמַטָּה, וְאִם בֵּרַךְ עָלָיו, זוֹ בְּרָכָה לְבַטָּלָה, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַד עַכְשָׁו לֹא שׁוֹרֶה עָלָיו, וְאֵין בּוֹ חֵלֶק. הָרַחֲמָן יַצִּילֵנוּ מֵאוֹתָם שֶׁאֵינָם מַשְׁגִּיחִים לִכְבוֹד רִבּוֹנָם.</p>\n<p>אַשְׁרֵי הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ. מִשּׁוּם שֶׁבְּאוֹתוֹ זְמַן יִסְתַּלֵּק הַנָּחָשׁ, שֶׁשָּׁרָה עִם הַנְּקֵבָה בָּרִאשׁוֹנָה, וְיָבֹא הַזָּכָר לִשְׁרוֹת בִּמְקוֹמוֹ כְּבָרִאשׁוֹנָה, וְהַכֹּל יִהְיֶה שָׁלֵם. לָמַדְנוּ, בִּזְמַן שֶׁצַּדִּיק שׁוֹרֶה בָּעוֹלָם וְכוּ', עַד צַדִּיק כַּתָּמָר יִפְרָח.</p>"],[9522012183,"<p>רַבִּי יוֹסֵי פָּתַח בְּפָסוּק וְאָמַר, לֹא תֹאכְלוּ עַל הַדָּם. הֲרֵי בְּכַמָּה מְקוֹמוֹת פֵּרְשׁוּהָ הַחֲבֵרִים, וְכָל הַפְּסוּקִים הַלָּלוּ אַחֲרָיו, וְכָל אֶחָד וְאֶחָד בְּגָלוּי. אֲבָל יֵשׁ לְהִתְעוֹרֵר בַּפָּסוּק הַזֶּה, שֶׁכָּתוּב מִפְּנֵי שֵׂיבָה תָּקוּם וְגוֹ'. מִפְּנֵי שֵׂיבָה, שֵׂיבָה שֶׁל הַתּוֹרָה סְתָם. תָּקוּם, מִכָּאן שֶׁצָּרִיךְ אָדָם לַעֲמֹד בְּעָמְדוֹ (מכאן שצריך אדם לעמד) מִלִּפְנֵי סֵפֶר תּוֹרָה, וְכָךְ רַב הַמְנוּנָא (ייסא) סָבָא, כְּשֶׁהָיָה רוֹאֶה סֵפֶר תּוֹרָה, הָיָה קָם מִלְּפָנָיו וְאוֹמֵר: מִפְּנֵי שֵׂיבָה תָּקוּם. (כשהיה רואה חמש של התורה, היה עומד מלפניו) (עושה לו הדור) (והיה אומר, ' והדרת פני זקן) כְּמוֹ כֵן צָרִיךְ אָדָם לַעֲמֹד בִּמְקוֹמוֹ מִלִּפְנֵי תַּלְמִיד חָכָם, מִשּׁוּם שֶׁהוּא עוֹמֵד בְּמָקוֹם (בדיוקן) קָדוֹשׁ עֶלְיוֹן. וְרָמַז לַכֹּהֵן הָעֶלְיוֹן (וכאן רמז לעתיק) הַקָּדוֹשׁ הָעֶלְיוֹן, שֶׁכָּתוּב וְהָדַרְתָּ פְּנֵי זָקֵן, שֶׁהוּא בָּעוֹלָם. אָמַר רַבִּי שִׁמְעוֹן, מִכָּאן רֶמֶז לַתּוֹרָה שֶׁבִּכְתָב, וְרֶמֶז לַתּוֹרָה שֶׁבְּעַל פֶּה.</p>\n<p>וְעוֹד שָׁנִינוּ, הַפָּסוּק הַזֶּה בָּא לִדְרָשָׁה. מִפְּנֵי שֵׂיבָה תָּקוּם, כְּמוֹ שֶׁהֵעִירוּ בוֹ הַחֲבֵרִים, מִפְּנֵי שֵׂיבָה תָּקוּם, הִזְהִיר אֶת הָאָדָם טֶרֶם שֶׁיַּעֲלֶה לְשֵׂיבָה שֶׁיַּעֲמֹד בְּקִיּוּם טוֹב בָּעוֹלָם, מִשּׁוּם שֶׁזֶּהוּ הַהִדּוּר שֶׁלּוֹ. אֲבָל לְסוֹף יָמָיו אֵין לָאָדָם שֶׁבַח כָּל כָּךְ, כְּשֶׁהוּא זָקֵן, וְאֵינוֹ יָכוֹל לַעֲשׂוֹת רַע. אֶלָּא הַשֶּׁבַח שֶׁלּוֹ כְּשֶׁהוּא בְּכֹחוֹ, וְהוּא טוֹב. וּשְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ וְאוֹמֵר, (שם ב) גַּם בְּמַעֲלָלָיו יִתְנַכֶּר נָעַר וְגוֹ'. כְּמוֹ כֵן כָּתוּב, (קהלת יב) וּזְכֹר אֶת בּוֹרְאֶיךְ בִּימֵי בְּחוּרֹתֶיךְ. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי (כך הוא) שֶׁהַדֶּרֶךְ הַזּוֹ מְתֻקֶּנֶת לְפָנֵינוּ, וְזוֹהִי דַּרְכּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9522012184,"<p>פָּתַח וְאָמַר, (תהלים א) כִּי יוֹדֵעַ ה' דֶּרֶךְ צַדִּיקִים וְדֶרֶךְ רְשָׁעִים תֹּאבֵד. מַה זֶּה כִּי יוֹדֵעַ ה'? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹדֵעַ וּמַשְׁגִּיחַ עַל דַּרְכֵי הַצַּדִּיקִים לְהֵיטִיב לָהֶם וּלְהָגֵן עֲלֵיהֶם, וְהוּא הוֹלֵךְ לִפְנֵיהֶם לִשְׁמֹר אוֹתָם. וּמִשּׁוּם כָּךְ, מִי שֶׁיּוֹצֵא לַדֶּרֶךְ, צָרִיךְ שֶׁאוֹתָהּ הַדֶּרֶךְ תִּהְיֶה דַרְכּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וִישַׁתֵּף אוֹתוֹ עִמּוֹ. וּמִשּׁוּם כָּךְ כָּתוּב, כִּי יוֹדֵעַ ה' דֶּרֶךְ צַדִּיקִים וְדֶרֶךְ רְשָׁעִים תֹּאבֵד. הִיא מֵעַצְמָהּ, מִשּׁוּם שֶׁאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מַכִּיר בְּאוֹתָהּ דֶּרֶךְ שֶׁלָּהֶם, וְאֵינוֹ הוֹלֵךְ עִמָּם.</p>\n<p>כָּתוּב דֶּרֶךְ, וְכָתוּב אֹרַח. מַה בֵּין זֶה לָזֶה? אֶלָּא, דֶּרֶךְ - שֶׁשְּׁאָר קַרְסֻלֵּי בְּנֵי אָדָם הָלְכוּ בָהּ. אֹרַח - שֶׁהוּא נִפְתָּח מִזְּמַן מוּעָט (זה ארח, כמו שנאמר (איוב לד) וארח לחברה עם פעלי און), וְעַל הָאֹרַח הַזֶּה כָּתוּב, (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם. אָמֵן כֵּן יְהִי רָצוֹן. בָּרוּךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלוֹךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522012185,"<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה אֱמֹר אֶל הַכֹּהֲנִים בְּנֵי אַהֲרֹן וְאָמַרְתָּ אֲלֵהֶם לְנֶפֶשׁ לֹא יִטַּמָּא בְּעַמָּיו. אָמַר רַבִּי יוֹסֵי, מָה הַטַּעַם זֶה כְּנֶגֶד זֶה, שֶׁכָּתוּב לְמַעְלָה, וְאִישׁ אוֹ אִשָּׁה כִּי יִהְיֶה בָהֶם אוֹב אוֹ יִדְּעֹנִי מוֹת יוּמָתוּ, וְסָמוּךְ לוֹ אֱמֹר אֶל הַכֹּהֲנִים? אֶלָּא (משמע) כֵּיוָן שֶׁהִזְהִיר אֶת יִשְׂרָאֵל לְקַדֵּשׁ אוֹתָם בַּכֹּל, הִזְהִיר אֶת הַכֹּהֲנִים לְקַדֵּשׁ אוֹתָם, וְכֵן אֶת הַלְוִיִּם. לַכֹּהֲנִים מִנַּיִן? שֶׁכָּתוּב אֱמֹר אֶל הַכֹּהֲנִים. וּמִנַּיִן לַלְוִיִּם? שֶׁכָּתוּב (במדבר יא) וְאֶל הַלְוִיִּם תְּדַבֵּר וְאָמַרְתָּ אֲלֵהֶם. כְּדֵי שֶׁיִּמָּצְאוּ כֻלָּם צַדִּיקִים קְדוֹשִׁים טְהוֹרִים.</p>\n<p>אֱמֹר אֶל הַכֹּהֲנִים בְּנֵי אַהֲרֹן. מָה הַטַּעַם כָּאן בְּנֵי אַהֲרֹן? וְכִי לֹא יָדַעְנוּ שֶׁהֵם בְּנֵי אַהֲרֹן? אֶלָּא בְּנֵי אַהֲרֹן וְלֹא בְּנֵי לֵוִי, שֶׁאַהֲרֹן הוּא רֵאשִׁיתָם שֶׁל כָּל הַכֹּהֲנִים שֶׁל הָעוֹלָם, שֶׁבּוֹ הִתְרַצָּה הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהַכֹּל כְּדֵי לַעֲשׂוֹת שָׁלוֹם בָּעוֹלָם. וּמִשּׁוּם שֶׁאַהֲרֹן, דְּרָכָיו הֶעֱלוּ אוֹתוֹ לָזֶה, שֶׁכָּל יָמָיו שֶׁל אַהֲרֹן הָיָה מִשְׁתַּדֵּל לְהַרְבּוֹת שָׁלוֹם בָּעוֹלָם. וּמִשּׁוּם שֶׁדְּרָכָיו כָּךְ, הֶעֱלָה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לָזֶה, לְהַכְנִיס שָׁלוֹם בְּפָמַלְיָא שֶׁל מַעְלָה, וּמִשּׁוּם כָּךְ - אֱמֹר אֶל הַכֹּהֲנִים בְּנֵי אַהֲרֹן.</p>\n<p>אֱמֹר אֶל הַכֹּהֲנִים בְּנֵי אַהֲרֹן וְאָמַרְתָּ אֲלֵהֶם. רַבִּי יְהוּדָה פָּתַח, (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ וְגוֹ'. מָה רַב טוּבְךְ, כַּמָּה עֶלְיוֹן וְנִכְבָּד אוֹתוֹ הָאוֹר הָעֶלְיוֹן שֶׁנִּקְרָא טוֹב, שֶׁכָּתוּב וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, וְזֶה הוּא הָאוֹר הַגָּנוּז, שֶׁבּוֹ עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא טוֹב בָּעוֹלָם, וְלֹא מוֹנֵעַ אוֹתוֹ בְּכָל יוֹם, מִכֵּיוָן שֶׁבּוֹ מִתְקַיֵּם הָעוֹלָם וְעוֹמֵד עָלָיו. אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ, שֶׁשָּׁנִינוּ, אוֹר עֶלְיוֹן עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁבָּרָא אֶת הָעוֹלָם, וְגָנַז אוֹתוֹ לַצַּדִּיקִים לֶעָתִיד לָבֹא. זֶהוּ שֶׁכָּתוּב אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ.</p>\n<p>פָּעַלְתָּ לַחוֹסִים בָּךְ. פָּעַלְתָּ, בִּזְמַן שֶׁנִּבְרָא הָעוֹלָם אוֹתוֹ הָאוֹר הָיָה עוֹמֵד וּמֵאִיר מֵרֹאשׁ הָעוֹלָם לְסוֹפֵי הָעוֹלָם. כְּשֶׁהִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָם הָרְשָׁעִים שֶׁעֲתִידִים לַעֲמֹד, גָּנַז אֶת אוֹתוֹ הָאוֹר, שֶׁכָּתוּב (איובלח) וְיִמָּנַע מֵרְשָׁעִים אוֹרָם. וְעָתִיד לְהָאִיר לַצַּדִּיקִים לָעוֹלָם הַבָּא, וְזֶה הוּא אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ, וְכָתוּב (מלאכי ג) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ.</p>"],[9522012186,"<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁבֶּן אָדָם עוֹמֵד לָלֶכֶת לְאוֹתוֹ הָעוֹלָם וְהוּא בְּבֵית חָלְיוֹ, בָּאִים עָלָיו שְׁלֹשָׁה שְׁלוּחִים, וְרוֹאֶה שָׁם מַה שֶּׁלֹּא יָכוֹל לִרְאוֹת אָדָם כְּשֶׁהוּא בָּעוֹלָם הַזֶּה. וְאוֹתוֹ הַיּוֹם הוּא יוֹם הַדִּין הָעֶלְיוֹן, שֶׁמְּבַקֵּשׁ הַמֶּלֶךְ אֶת פִּקְדוֹנוֹ. אַשְׁרֵי הָאִישׁ שֶׁמֵּשִׁיב לַמֶּלֶךְ אֶת פִּקְדוֹנוֹ, כְּמוֹ שֶׁנִּתַּן לוֹ בְּתוֹכוֹ. אִם אוֹתוֹ הַפִּקָּדוֹן הִתְטַנֵּף בְּטִנּוּפֵי הַגּוּף, מַה יֹּאמַר לְבַעַל הַפִּקָּדוֹן?</p>\n<p>מֵרִים עֵינָיו, וְרוֹאֶה אֶת מַלְאַךְ הַמָּוֶת עוֹמֵד לְפָנָיו, וְחַרְבּוֹ שְׁלוּפָה בְּיָדוֹ, קוֹשֵׁר בִּקְשָׁרִים בַּמַּאֲסָר שֶׁל אוֹתוֹ הָאִישׁ. וְאֵין לַנֶּפֶשׁ קֹשִׁי בַּכֹּל כִּפְרֵדָתָהּ מִן הַגּוּף. וְאָדָם לֹא מֵת עַד שֶׁרוֹאֶה אֶת הַשְּׁכִינָה, וּמִתּוֹךְ גֹּדֶל הַתְּשׁוּקָה לַשְּׁכִינָה, הַנֶּפֶשׁ יוֹצֵאת לְקַבֵּל אֶת הַשְּׁכִינָה. אַחַר שֶׁיָּצְאָה, מִי הַנֶּפֶשׁ שֶׁנִּדְבֶּקֶת בָּהּ (ותתקבל) וִיקַבֵּל בַּגּוּף (לתוכה) ? וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים הָאֵלֶּה.</p>\n<p>אַחַר שֶׁיָּצְאָה הַנֶּפֶשׁ מִן הַגּוּף וְנִשְׁאָר הַגּוּף בְּלִי רוּחַ, אָסוּר לְהַשְׁאִירוֹ בְּלִי קְבוּרָה, שֶׁכָּתוּב (דברים כא) לֹא תָלִין נִבְלָתוֹ עַל הָעֵץ כִּי קָבוֹר תִּקְבְּרֶנּוּ בַּיּוֹם הַהוּא. מִשּׁוּם שֶׁמֵּת שֶׁיִּשְׁתַּהֶה כ\"ד שָׁעוֹת, שֶׁהֵם יוֹמָם וָלַיְלָה, בְּלִי קְבוּרָה, נוֹתֵן חֻלְשָׁה בְּאֵיבְרֵי הַמֶּרְכָּבָה, וּמְעַכֵּב אֶת מַעֲשֵׂה הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְּהֵעָשׂוֹת, שֶׁאֶפְשָׁר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹזֵר עָלָיו כְּדֵי לָבֹא בְּגִלְגּוּל אַחֵר מִיָּד בְּאוֹתוֹ יוֹם שֶׁנִּפְטָר לְהֵיטִיב לוֹ, וְכָל זְמַן שֶׁלֹּא נִקְבָּר הַגּוּף, הַנְּשָׁמָה לֹא נִכְנֶסֶת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא יְכוֹלָה לִהְיוֹת בְּגוּף אַחֵר עַד שֶׁיִּקָּבֵר הָרִאשׁוֹן. וְזֶה דּוֹמֶה לְאָדָם שֶׁמֵּתָה אִשְׁתּוֹ, לֹא רָאוּי לוֹ לִשָּׂא אִשָּׁה אַחֶרֶת עַד שֶׁקּוֹבֵר אֶת הָרִאשׁוֹנָה, וּמִשּׁוּם כָּךְ אָמְרָה תוֹרָה, לֹא תָלִין נִבְלָתוֹ עַל הָעֵץ.</p>\n<p>דָּבָר אַחֵר - כְּשֶׁנִּפְרֶדֶת הַנְּשָׁמָה מִן הַגּוּף וְרוֹצָה לָלֶכֶת לְאוֹתוֹ הָעוֹלָם, לֹא תִכָּנֵס לְאוֹתוֹ הָעוֹלָם עַד שֶׁנּוֹתְנִים לָהּ גּוּף אַחֵר מֵאוֹר, וְאַחַר כָּךְ יְכוֹלָה לְהִכָּנֵס. וּמֵאֵלִיָּהוּ תֵּדַע, שֶׁהָיוּ לוֹ שְׁנֵי גוּפִים, אֶחָד שֶׁבּוֹ נִרְאֶה לְמַטָּה לִבְנֵי אָדָם, וְאֶחָד שֶׁבּוֹ נִרְאֶה לְמַעְלָה בֵּין מַלְאָכִים עֶלְיוֹנִים קְדוֹשִׁים. וְכָל עוֹד שֶׁהַגּוּף לֹא נִקְבָּר, זֶהוּ צַעַר לַנְּשָׁמָה, וְרוּחַ טֻמְאָה מִזְדַּמֶּנֶת לִשְׁרוֹת עָלָיו וּלְטַמֵּא אֶת אוֹתוֹ הַגּוּף.</p>\n<p>וּמִשּׁוּם שֶׁאוֹתָהּ רוּחַ הַטֻּמְאָה מִזְדַּמֶּנֶת, לֹא צָרִיךְ לְאִישׁ לְהָלִין אֶת אוֹתוֹ הַגּוּף לַיְלָה אֶחָד, כִּי רוּחַ טֻמְאָה נִמְצֵאת בַּלַּיְלָה וּמִשְׁתַּטַּחַת בְּכָל הָאָרֶץ לִמְצֹא גוּף בְּלִי נֶפֶשׁ לְטַמֵּא אוֹתָהּ, וְנִטְמָא יוֹתֵר, וְעַל כֵּן הִזְהִיר אֶת הַכֹּהֲנִים וְאָמַר, לְנֶפֶשׁ לֹא יִטַּמָּא בְּעַמָּיו. מִשּׁוּם שֶׁהֵם קְדוֹשִׁים, לֹא תִשְׁרֶה עֲלֵיהֶם רוּחַ טֻמְאָה, וְלֹא יִטַּמְּאוּ.</p>"],[9522012187,"<p>אֱמֹר אֶל הַכֹּהֲנִים. רַבִּי יִצְחָק אָמַר, אֱמֹר אֶל הַכֹּהֲנִים, בְּלַחַשׁ. כְּמוֹ שֶׁכָּל מַעֲשֵׂי הַכֹּהֲנִים בְּלַחַשׁ, כָּךְ אֲמִירָתָם בְּלַחַשׁ. אֱמֹר וְאָמַרְתָּ - פַּעַם אַחַת וּפַעֲמַיִם, לְהַזְהִיר אוֹתָם עַל קְדֻשָּׁתָם כְּדֵי שֶׁלֹּא יִטַּמְּאוּ. שֶׁמִּי שֶׁמְּשַׁמֵּשׁ בַּאֲתַר קָדוֹשׁ, צָרִיךְ שֶׁיִּמָּצֵא קָדוֹשׁ בַּכֹּל. לְנֶפֶשׁ לֹא יִטַּמָּא, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁגּוּף בְּלִי רוּחַ טָמֵא הוּא, וְשׁוֹרָה עָלָו רוּחַ טֻמְאָה, שֶׁהֲרֵי תְּשׁוּקָתָם שֶׁל הָרוּחוֹת הַטְּמֵאוֹת הִיא אֶל גּוּפוֹת יִשְׂרָאֵל, מִכֵּיוָן שֶׁהִתְרוֹקְנָה מֵהֶם הָרוּחַ הַקְּדוֹשָׁה, וְעִם כְּלִי שֶׁל קֹדֶשׁ הֵם בָּאִים לְהִתְחַבֵּר. וְהַכֹּהֲנִים, שֶׁהֵם קְדוֹשִׁים קְדֻשָּׁה עַל קְדֻשָּׁה, לֹא צְרִיכִים כְּלָל לְהִטָּמֵא, כִּי כָּתוּב כִּי נֵזֶר אֱלֹהָיו עַל רֹאשׁוֹ. וְכָתוּב כִּי שֶׁמֶן מִשְׁחַת אֱלֹהָיו עָלָיו אֲנִי ה'.</p>\n<p>וְהוּא כְּמוֹ שֶׁלְּמַעְלָה עוֹמֵד לְמַטָּה, שֶׁכָּתוּב (תהלים קלג) כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ יֹרֵד עַל הַזָּקָן זְקַן אַהֲרֹן שֶׁיֹּרֵד עַל פִּי מִדּוֹתָיו. הַפָּסוּק הַזֶּה בֵּאַרְנוּ. אֲבָל כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ, זֶהוּ שֶׁמֶן מִשְׁחַת קֹדֶשׁ הָעֶלְיוֹן, שֶׁשּׁוֹפֵעַ וְיוֹצֵא מִמְּקוֹם הַנָּהָר הֶעָמֹק שֶׁל הַכֹּל. דָּבָר אַחֵר, שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵרֹאשׁ שֶׁל כָּל הָרָאשִׁים, הַנִּסְתָּר שֶׁל כָּל הַנִּסְתָּרִים. עַל הָרֹאשׁ, וַדַּאי עַל הָרֹאשׁ, רֹאשׁוֹ שֶׁל אָדָם הָרִאשׁוֹן.</p>\n<p>יֹרֵד עַל הַזָּקָן - זֶה הַזָּקָן הַנִּכְבָּד, כְּמוֹ שֶׁבֵּאֲרוּהָ. זְקַן אַהֲרֹן - זֶה הַכֹּהֵן הַגָּדוֹל שֶׁלְּמַעְלָה, וַהֲרֵי פֵּרְשׁוּהָ. וְאוֹתוֹ שֶׁמֶן יֹרֵד עַל פִּי מִדּוֹתָיו, שֶׁמֵּאוֹתָן הַמִּדּוֹת שׁוֹפֵעַ וְיוֹצֵא וְיוֹרֵד לַתַּחְתּוֹנִים. וּכְמוֹ זֶה שׁוֹפֵעַ וּמִתְעַטֵּר הַכֹּהֵן הַתַּחְתּוֹן בִּשֶׁמֶן מִשְׁחָה לְמַטָּה.</p>\n<p>הַפָּסוּקֹ הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ, וְאֵין סוֹפוֹ רֹאשׁוֹ. כָּתוּב אֱמֹר אֶל הַכֹּהֲנִים בְּנֵי אַהֲרֹן וְאָמַרְתָּ אֲלֵהֶם לְנֶפֶשׁ לֹא יִטַּמָּא. לֹא יִטַּמְּאוּ הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה לֹא יִטַּמָּא? אֶלָּא עַל אוֹתוֹ הַכֹּהֵן הָעֶלְיוֹן מִכֻּלָּם הוּא אָמַר. אָמַר רַבִּי יְהוּדָה, וַהֲרֵי כָּתוּב וְהַכֹּהֵן הַגָּדוֹל מֵאֶחָיו? אֶלָּא וַדַּאי כָּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר. וְאָמַר רַבִּי יִצְחָק, הַכֹּהֵן שֶׁעוֹמֵד לְמַטָּה, כְּמוֹ שֶׁלְּמַעְלָה, בִּקְדֻשָּׁה הוּא צָרִיךְ לְהִמָּצֵא יוֹתֵר מֵהַכֹּל, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>"],[9522012188,"<p>מִצְוָה זוֹ, שֶׁיְּסַדֵּר הַכֹּהֵן בְּכָל יוֹם נֵרוֹת בְּבֵית הַמִּקְדָּשׁ, וַהֲרֵי בֵּאַרְנוּ בְּסוֹד הַמְּנוֹרָה. וְהוּא סוֹד כְּמוֹ שֶׁלְּמַעְלָה, מִשּׁוּם שֶׁהָאוֹר הָעֶלְיוֹן בְּשֶׁמֶן מִשְׁחָה יוֹרֵד עַל רֹאשׁ הַכֹּהֵן בָּרִאשׁוֹנָה, וְאַחַר כָּךְ הוּא מַדְלִיק וּמֵאִיר אֶת כָּל הַנֵּרוֹת, שֶׁכָּתוּב כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ וְגוֹ', וְכָתוּב כִּי שֶׁמֶן מִשְׁחַת אֱלֹהָיו עָלָיו וְגוֹ'. וְעַל כֵּן נִתְּנָה רְשׁוּת לַכֹּהֵן לְבַדּוֹ לְסַדֵּר אֶת הַנֵּרוֹת וּלְהַדְלִיק אוֹתָם בְּכָל יוֹם פַּעֲמַיִם, כְּנֶגֶד אוֹר הַיִּחוּד פַּעֲמַיִם, קָרְבָּן בְּכָל יוֹם פַּעֲמַיִם, וְהַכֹּל צָרִיךְ.</p>\n<p>וְעַל יְדֵי הַכֹּהֵן מְאִירִים הַנֵּרוֹת בַּכֹּל, לְמַעְלָה וּלְמַטָּה, לִשְׂמֹחַ בְּשִׂמְחָה וּלְהִמָּצֵא שִׂמְחָה בְּכָל הַצְּדָדִים בְּהַדְלָקַת הַנֵּרוֹת, שֶׁהֲרֵי שְׁנֵי אֵלֶּה עַל יְדֵי הַכֹּהֵן, לְהַמְצִיא שִׂמְחָה בְּכָל הַצְּדָדִים, וְאֵלּוּ הֵם הַדְלָקַת הַנֵּרוֹת וְהַקְּטֹרֶת, וַהֲרֵי בֵּאַרְנוּ שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. (עד כאן רעיא מהימנא).</p>"],[9522012189,"<p>וְלַאֲחֹתוֹ הַבְּתוּלָה הַקְּרוֹבָה אֵלָיו וְגוֹ'. מַה כָּתוּב לְמַעְלָה? כִּי אִם לִשְׁאֵרוֹ הַקָּרֹב אֵלָיו וְגוֹ'. רַבִּי אַבָּא פָּתַח, (ישעיה סג) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגוֹ'. מִי זֶה בָּא מֵאֱדוֹם? עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִלְבֹּשׁ בִּגְדֵי נְקָמָה עַל אֱדוֹם, שֶׁהֶחֱרִיבוּ אֶת בֵּיתוֹ וְשָׂרְפוּ אֶת הֵיכָלוֹ, וְהִגְלוּ אֶת כְּנֶסֶת יִשְׂרָאֵל בֵּין הָעַמִּים, וְלַעֲשׂוֹת לָהֶם נִקְמַת עוֹלָמִים, עַד שֶׁיִּמָּצְאוּ כָּל הֶהָרִים מֵהָרֵי הָעוֹלָם מְלֵאִים מֵהֲרוּגֵי הָעַמִּים, וְלִקְרֹא לְכָל עוֹף הַשָּׁמַיִם עֲלֵיהֶם, וְכָל חַיּוֹת הַבָּר יִזּוֹנוּ מֵהֶם שְׁנֵים עָשָׂר חֳדָשִׁים, וְעוֹף הַשָּׁמַיִם שֶׁבַע שָׁנִים, עַד שֶׁלֹּא תִסְבֹּל הָאָרֶץ אֶת הַנִּוּוּל שֶׁלָּהֶם. זֶהוּ שֶׁכָּתוּב (שם לד) כִּי זֶבַח לַה' בְּבָצְרָה וְטֶבַח גָּדוֹל בְּאֶרֶץ אֱדוֹם, עַד שֶׁאוֹתָם לְבוּשִׁים יִטַּמְּאוּ. זֶהוּ שֶׁכָּתוּב (שם סג) וְכָל מַלְבּוּשַׁי אֶגְאָלְתִּי.</p>\n<p>חֲמוּץ בְּגָדִים מִבָּצְרָה, מִשּׁוּם שֶׁמִּמֶּנָּה יָצְאוּ אוּכְלוּסֵי הָעוֹלָם לִצְבּא עַל יְרוּשָׁלַיִם, וְהֵם הִתְחִילוּ לִשְׂרֹף אֶת הַהֵיכָל, וּבְנֵי אֱדוֹם מְהָרְסִים אֶת הַחוֹמוֹת, וְעָקְרוּ אֶת אַבְנֵי הַיְסוֹד. זֶהוּ שֶׁכָּתוּב (תהלים קלז) זְכֹר ה' לִבְנֵי אֱדוֹם וְגוֹ', הָאֹמְרִים עָרוּ עָרוּ עַד הַיְסוֹד בָּהּ.</p>\n<p>זְהִ הָדוּר בִּלְבוּשׁוֹ, בְּאוֹתָם לְבוּשֵׁי הַנְּקָמָה שֶׁעָתִיד לִלְבֹּשׁ. צֹעֶה בְּרֹב כֹּחוֹ, מַה זֶּה צֹעֶה? מְשַׁבֵּר, כְּמוֹ שֶׁכָּתוּב (תהלים מה) עַמִּים תַּחְתֶּיךְ יִפְּלוּ וְגוֹ'. אָמְרוּ יִשְׂרָאֵל לִישַׁעְיָה, מִי הוּא זֶה שֶׁיַּעֲשֶׂה כָּל כָּךְ? פָּתַח וְאָמַר, (ישעיהסג) אֲנִי מְדַבֵּר בִּצְדָקָה, אוֹתוֹ שֶׁהוּא רַב לְהוֹשִׁיעַ, אוֹתוֹ שֶׁכָּתוּב בּוֹ (תהלים לג) אֹהֵב צְדָקָה וּמִשְׁפָּט. וְהוּא צְדָקָה מַמָּשׁ, וְהוּא רַב לְהוֹשִׁיעַ.</p>\n<p>וְכָל כָּךְ לָמָּה? מִשּׁום שֶׁגָּרְמוּ לִכְנֶסֶת יִשְׂרָאֵל לִהְיוֹת שׁוֹכֶבֶת לֶעָפָר בַּגָּלוּת וְלִנְפֹּל לָאָרֶץ, כְּמוֹ שֶׁכָּתוּב (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל. וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא יִלְבַּשׁ לְבוּשֵׁי נְקָמָה עֲלֵיהֶם לְטַמֵּא אוֹתָם בְּרֹב הַהֲרוּגִים, שֶׁכָּתוּב וְכָל מַלְבּוּשַׁי אֶגְאָלְתִּי.</p>\n<p>וְכָל כָּךְ לָמָּה? שֶׁכָּתוּב וְלַאֲחֹתוֹ הַבְּתוּלָה הַקְּרוֹבָה אֵלָיו אֲשֶׁר לֹא הָיְתָה לְאִישׁ. שֶׁאֵינָהּ חֶלְקוֹ שֶׁל - עֵשָׂו, וְלֹא הָיְתָה בְגוֹרָלוֹ שֶׁל אוֹתוֹ שֶׁכָּתוּב בּוֹ (בראשית כה) אִישׁ יֹדֵעַ צַיִד אִישׁ שָׂדֶה. לָהּ יִטַּמָּא, בְּאוֹתָם לְבוּשֵׁי נְקָמָה, שֶׁעָתִיד לְהִטָּמֵא בֵּין אוֹתָם הַהֲמוֹנִים, שֶׁכָּתוּב בּוֹ לָהּ יִטַּמָּא, בִּשְׁבִילָהּ, מִשּׁוּם שֶׁהִיא שׁוֹכֶבֶת לֶעָפָר, וְהוּא רוֹצֶה לְהָקִים אוֹתָהּ. זֶהוּ שֶׁכָּתוּב (ישעיה ס) קוּמִי אוֹרִי כִּי בָא אוֹרֵךְ. ((עמוס ט) ביום ההוא אקים את סכת דויד הנפלת).</p>"],[9522012190,"<p>לֹא יִקְרְחֻה קָרְחָה בְּרֹאשָׁם. רַבִּי יוֹסֵי אָמַר, לֹא יִקְרְחֻה בְּהֵ\"א, מָה הַטַּעַם? אֶלָּא, אוֹתוֹ שֶׁמֶן עֶלְיוֹן, שֶׁהוּא שֶׁמֶן מִשְׁחַת קֹדֶשׁ, שֶׁמַּשְׁלִים אֶת כָּל שִׁבְעַת הַיָּמִים כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב (ויקרא ח) כִּי שִׁבְעַת יָמִים יְמַלֵּא אֶת יֶדְכֶם, אוֹתוֹ שֶׁמֶן עֶלְיוֹן הוּסַר מִמֶּנּוּ וְנִקְרַח, אִם הוּא פָּגַם אֶת רֹאשׁוֹ. מִשּׁוּם שֶׁרֹאשׁוֹ שֶׁל הַכֹּהֵן הָעֶלְיוֹן הִנּוֹ אוֹתוֹ שֶׁמֶן עֶלְיוֹן, וְעַל כֵּן לֹא צָרִיךְ לַכֹּהֵן שֶׁלְּמַטָּה לְהַרְאוֹת בְּעַצְמוֹ פְּגָם כְּלָל, וַהֲרֵי זֶה נֶאֱמַר. וּמִשּׁוּם כָּךְ כָּתוּב בְּהֵ\"א.</p>\n<p>פָּתַח וְאָמַר, (תהלים קכו) בְּשׁוּב ה' אֶת שִׁיבַת צִיּוֹן הָיִינוּ כְּחֹלְמִים. בְּשׁוּב ה' אֶת שִׁיבַת, זֶה נֶאֱמַר בְּגָלוּת בָּבֶל, שֶׁלֹּא נִמְצְאוּ יוֹתֵר בַּגָּלוּת אֶלָּא שִׁבְעִים שָׁנִים, שֶׁכָּתוּב (ירמיה כט) כִּי לְפִי מְלֹאת לְבָבֶל שִׁבְעִים שָׁנָה אֶפְקֹד אֶתְכֶם. וְכָתוּב הָיִינוּ כְּחֹלְמִים, מַה זֶּה כְּחֹלְמִים? אֶלָּא הֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים, שֶׁיֵּשׁ שִׁבְעִים שָׁנִים בַּחֲלוֹם.</p>"],[9522012191,"<p>וּבֹא רְאֵה, כָּתוּב כִּי שִׁבְעַת יָמִים יְמַלֵּא אֶת יֶדְכֶם. מִי שִׁבְעַת הַיָּמִים? הֲרֵי נִתְבָּאֵר, אוֹתוֹ מָקוֹם עֶלְיוֹן שֶׁהוּא כְּלָל שֶׁל כָּל שֵׁשֶׁת הָאֲחֵרִים נִקְרָא שִׁבְעַת יָמִים, וְנִקְרָא תְשׁוּבָה. שָׁנִינוּ, מִי שֶׁיּוֹשֵׁב בְּתַעֲנִית בְּשַׁבָּת, קוֹרְעִים לוֹ גְּזַר דִּינוֹ שֶׁל שִׁבְעִים שָׁנָה, וְשִׁבְעִים שָׁנָה הֵם שֶׁבַע פְּנֵי הַמֶּלֶךְ, שֶׁאֲפִלּוּ הִסְכִּימוּ כֻלָּם עָלָיו (הכל) לְרַע, נִקְרָע אוֹתוֹ גְּזַר הַדִּין. מָה הַטַּעַם? מִשּׁוּם שֶׁאָחַז בְּאוֹתוֹ הַיּוֹם בַּכְּלָל שֶׁל כֻּלָּם, שֶׁנִּקְרָא שִׁבְעָה, וְנִקְרָא תְשׁוּבָה, וּמִשּׁוּם כָּךְ בְּכֻלָּם הוּא אָחַז, וְחָזַר בִּתְשׁוּבָה, וְנִקְרַע גְּזַר הַדִּין בְּכֻלָּם. וְעַל כֵּן שִׁבְעִים שָׁנָה יֵשׁ בַּחֲלוֹם.</p>\n<p>כְּמוֹ כֵן הַכֹּהֵן מִתְעַטֵּר בְּשִׁבְעָה, שֶׁנִּקְרָא שִׁבְעַת יָמִים. אִם פָּגַם אֶת רֹאשׁוֹ, אוֹתוֹ שִׁבְעָה שֶׁהוּא כְּלָל שֶׁל כֻּלָּם, מַקְרִיחַ מִמֶּנּוּ כָּל אוֹתָהּ קְדֻשָּׁה שֶׁל כֻּלָּם שֶׁשּׁוֹרָה עָלָיו. וְעַל כֵּן הֻזְהֲרוּ שֶׁלּא יִקְרְחֻה קָרְחָה בְּרֹאשָׁם, וְיִמָּצְאוּ פְגוּמִים מֵהַכֹּל. וּמִשּׁוּם כָּךְ הַכֹּהֵן צָרִיךְ לְהִמָּצֵא בִשְׁלֵמוּת יוֹתֵר מֵהַכֹּל, כָּל שֶׁכֵּן אוֹתוֹ שֶׁהוּא עֶלְיוֹן מִכֻּלָּם.</p>\n<p>אָמַר רַבִּי אַבָּא, כָּאן בְּהֵ\"א תַּחְתּוֹנָה, כָּאן בְּהֵ\"א עֶלְיוֹנָה. כֹּהֵן גָּדוֹל, שֶׁהוּא עֶלְיוֹן מִכֻּלָּם, בְּהֵ\"א עֶלְיוֹנָה, שֶׁכָּתוּב אֲשֶׁר יוּצַק עַל רֹאשׁוֹ שֶׁמֶן הַמִּשְׁחָה וּמִלֵּא אֶת יָדוֹ וְגוֹ'. וּמִלֵּא אֶת יָדוֹ, שֶׁכָּתוּב שִׁבְעַת יָמִים יְמַלֵּא אֶת יֶדְכֶם. כֹּהֵן אַחֵר בְּה' תַּחְתּוֹנָה, שֶׁכָּתוּב לֹא יִקְרְחֻה קָרְחָה בְּרֹאשָׁם, וְכָתוּב אַחֲרָיו, וְלֹא יְחַלְּלוּ שֵׁם אֱלֹהֵיהֶם. וְהַשֵּׁם הַזֶּה הִנּוֹ יָדוּעַ. וּמִשּׁוּם כָּךְ כָּתוּב, וְהַכֹּהֵן הַגָּדוֹל מֵאֶחָיו אֲשֶׁר יוּצַק עַל רֹאשׁוֹ שֶׁמֶן הַמִּשְׁחָה לִלְבֹּשׁ אֶת הַבְּגָדִים, כְּמוֹ שֶׁאָמַרְנוּ. וּמִשּׁוּם שֶׁהוּא קָדוֹשׁ כְּמוֹ שֶׁלְּמַעְלָה, כָּתוּב וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא.</p>"],[9522012192,"<p>רַבִּי אַבָּא פָּתַח וְאָמַר, (דניאל ט) לְךְ ה' הַצְּדָקָה וְלָנוּ בֹּשֶׁת הַפָּנִים כְּהַיּוֹם הַזֶּה לְאִישׁ יְהוּדָה וּלְיֹשְׁבֵי יְרוּשָׁלם. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, וּמִתּוֹךְ אַהֲבָתָם נָתַן לָהֶם תּוֹרַת אֱמֶת, לָדַעַת אֶת דֶּרֶךְ הַמֶּלֶךְ הַקָּדוֹשׁ. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, כְּאִלּוּ הִשְׁתַּדֵּל בַּקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהַתּוֹרָה כֻּלָּהּ שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הִיא. וּמִשּׁוּם כָּךְ, מִי שֶׁמִּתְעַסֵּק בַּתּוֹרָה, מִתְעַסֵּק בִּשְׁמוֹ, וּמִי שֶׁמִּתְרַחֵק מִן הַתּוֹרָה, הוּא רָחוֹק מֵהַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>בֹּא רְאֵה, לְךְ ה' הַצְּדָקָה, כְּמוֹ שֶׁנֶּאֱמַר (דברי הימים א כט) לְךְ ה' הַגְּדֻלָּה וְהַגְּבוּרָה. מִי הַצְּדָקָה? הַמָּקוֹם שֶׁכָּל הַפָּנִים הַמְּאִירוֹת אֲחוּזִים בּוֹ, וְהוּא אוֹחֵז בְּכֻלָּם וּבוֹ נִמְצָאִים. וְלָנוּ בֹּשֶׁת הַפָּנִים, הַמָּקוֹם שֶׁכָּל הַפָּנִים הַמְּאִירוֹת מִתְרַחֲקִים מִמֶּנּוּ. צְדָקָה, אֱמֶת קְשׁוֹט, וְאוֹר הַכֹּל, וְאוֹר שֶׁל פָּנִים שִׂמְחַת הַכֹּל. בֹּשֶׁת, בּוּשָׁה וְהָרִחוּק שֶׁל הָאֱמֶת מִי שֶׁמִּתְבַּיֵּשׁ, מִשּׁוּם שֶׁהָאֱמֶת, שֶׁהִיא צְדָקָה, הִתְרַחֲקָה מִמֶּנּוּ רִחוּק שֶׁל פָּנִים מְאִירוֹת.</p>\n<p>בֹּא רְאֵה, הַכֹּהֵן הָעֶלְיוֹן צָרִיךְ לְהֵרָאוֹת בִּיפִי הַפָּנִים, בְּהֶאָרַת הַפָּנִים, בְּשִׂמְחָה יוֹתֵר מֵהַכֹּל, וְלֹא צָרִיךְ לְהֵרָאוֹת בּוֹ עַצְבוּת וְרֹגֶז, אֶלָּא הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. אַשְׁרֵי חֶלְקוֹ, שֶׁעָלָיו כָּתוּב אֲנִי חֶלְקְךְ וְנַחֲלָתְךְ. וְכָתוּב (דברים יח) ה' הוּא נַחֲלָתוֹ. וְעַל כֵּן צָרִיךְ לְהֵרָאוֹת שָׁלֵם בַּכֹּל, בְּעַצְמוֹ, בִּלְבוּשׁוֹ, שֶׁלֹּא יִפְגֹּם עַצְמוֹ כְּלָל, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>"],[9522012193,"<p>וְהוּא אִשָּׁה בִבְתוּלֶיהָ יִקָּח. רַבִּי שִׁמְעוֹן פָּתַח, (שם כב) וְהִנֵּה הוּא שָׂם עֲלִילֹת דְּבָרִים וְגוֹ'. וְכָתוּב וְעָנְשׁוּ אֹתוֹ מֵאָה כֶסֶף וְגוֹ', כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל. וְכִי בְּתוּלַת יִשְׂרָאֵל הִיא? בְּתוּלַת אָבִיהָ אוֹ בְּתוּלַת בַּעְלָהּ הִיא. מַה זֶּה בְּתוּלַת יִשְׂרָאֵל כָּאן? זֶהוּ שֶׁכָּתוּב (דברים לב) שְׁאַל אָבִיךְ וְיַגֵּדְךְ זְקֵנֶיךְ וְיֹאמְרוּ לָךְ. אַף כָּאן הַכֹּהֵן שֶׁעוֹמֵד כְּמוֹ שֶׁלְּמַעְלָה, כָּתוּב וְהוּא אִשָּׁה בִבְתוּלֶיהָ יִקָּח, כָּךְ גַּם בִּבְתוּלֶיהָ, שֶׁלֹּא תֵצֵא מִשַּׁעַר חֲצֵרָהּ פַּעַם הַחוּצָה, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522012194,"<p>רַבִּי שִׁמְעוֹן הָיָה הוֹלֵךְ בַּדֶּרֶךְ, וְהָיוּ עִמּוֹ רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי וְרַבִּי חִזְקִיָּה. פָּתַח רַבִּי שִׁמְעון וְאָמַר, (תהלים קיא) טֶרֶף נָתַן לִירֵאָיו יִזְכֹּר לְעוֹלָם בְּרִיתוֹ. טֶרֶף נָתַן לִירֵאָיו - אֵלּוּ הֵם הַצַּדִּיקִים, אוֹתָם יִרְאֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁכָּל מִי שֶׁיָּרֵא מִמֶּנּוּ נִקְרָא מֵאַנְשֵׁי בֵּית הַמֶּלֶךְ, וְעָלָיו כָתוּב (שם קיב) אַשְׁרֵי אִישׁ יָרֵא אֶת ה'.</p>\n<p>מַהוּ טֶרֶף נָתַן לִירֵאָיו? אֶלָּא כְּמוֹ שֶׁכָּתוּב, (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ. מִכָּאן לָמַדְנוּ, שֶׁכָּל אָדָם שֶׁעוֹסֵק בַּתּוֹרָה בַּלַּיְלָה, וְקָם בַּחֲצוֹת הַלַּיְלָה, בְּשָׁעָה שֶׁכְּנֶסֶת יִשְׂרָאֵל מִתְעוֹרֶרֶת לְהַתְקִין בַּיִת לַמֶּלֶךְ - זֶה מִשְׁתַּתֵּף עִמָּהּ, וְזֶה נִקְרָא מִבֵּית הַמֶּלֶךְ, וְנוֹתְנִים לוֹ כָּל יוֹם מֵאוֹתָם תִּקּוּנֵי הַבַּיִת. זֶהוּ שֶׁכָּתוּב וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ. מִי זֶה בֵּיתָהּ? כָּל אוֹתָם שֶׁמִּשְׁתַּתְּפִים עִמָּה בַּלַּיְלָה נִקְרָאִים בֵּיתָהּ, בְּנֵי בֵיתָהּ. וּמִשּׁוּם כָּךְ, טֶרֶף נָתַן לִירֵאָיו.</p>\n<p>מַה זֶּה טֶרֶף? טֶרֶף מַמָּשׁ, שֶׁהִיא נוֹטֶלֶת מִמָּקוֹם רָחוֹק עֶלְיוֹן, שֶׁכָּתוּב (משלי לא) מִמֶּרְחָק תָּבִיא לַחְמָהּ. וּמִי זוֹכֶה לַטֶּרֶף הַזֶּה? סוֹף הַכָּתוּב מוֹכִיחַ, שֶׁכָּתוּב (תהלים קיא) יִזְכֹּר לְעוֹלָם בְּרִיתוֹ. מִי שֶׁמִּתְבּוֹנֵן (שמשתדל) בַּתּוֹרָה לְהִשְׁתַּתֵּף עִמָּהּ בַּלַּיְלָה. וְלֹא עוֹד, אֶלָּא שֶׁצַּדִּיק אֶחָד עֶלְיוֹן יֵשׁ לוֹ לַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא מִשְׁתַּתֵּף עִמּוֹ, וְיוֹרְשִׁים שְׁנֵיהֶם אֶת כְּנֶסֶת יִשְׂרָאֵל, שֶׁכָּתוּב (ישעיה ס) צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ.</p>"],[9522012195,"<p>עוֹד פָּתַח וְאָמַר, וְלֹא יְחַלֵּל זַרְעוֹ בְּעַמָּיו כִּי אֲנִי ה' מְקַדְּשׁוֹ. בֹּא רְאֵה, כָּל מִי שֶׁמּוֹצִיא זֶרַע לְבַטָּלָה, לֹא זוֹכֶה לִרְאוֹת פְּנֵי שְׁכִינָה, וְנִקְרָא רָע, שֶׁכָּתוּב (תהלים ה) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגֻרְךְ רָע. זֶה מִי שֶׁמּוֹצִיא אוֹתוֹ בְּיָדוֹ, אוֹ בְּאִשָּׁה אַחֶרֶת שֶׁאֵינָהּ כְּשֵׁרָה. וְאִם תֹּאמַר שֶׁמּוֹצִיא אוֹתוֹ בְּאִשָּׁה שֶׁאֵינָהּ מִתְעַבֶּרֶת, כָּךְ גַּם? לֹא. אֶלָּא כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>וְעַל כֵּן יְבַקֵּשׁ אָדָם מֵהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיַּזְמִין לוֹ כְּלִי כָּשֵׁר, שֶׁלֹּא יִפְגֹּם זַרְעוֹ. מִי שֶׁמּוֹצִיא זֶרַע בִּכְלִי שֶׁלֹּא כָשֵׁר, פּוֹגֵם אֶת זַרְעוֹ. אוֹי לְמִי שֶׁפּוֹגֵם אֶת זַרְעוֹ. וּמַה בִּשְׁאָר בְּנֵי אָדָם כָּךְ - בְּכֹהֵן שֶׁעוֹמֵד לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה בִּקְדֻשָּׁה עֶלְיוֹנָה עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>בְּעַמָּיו, מַה זֶּה בְּעַמָּיו? שֶׁהֲרֵי כָּתוּב לְמַעְלָה, אַלְמָנָה וּגְרוּשָׁה וַחֲלָלָה זֹּנָה אֶת אֵלֶּה לֹא יִקָּח, וְכָתוּב וְלֹא יְחַלֵּל זַרְעוֹ בְּעַמָּיו. בָּהֶם הָיָה צָרִיךְ לִהְיוֹת, מַה זֶּה בְּעַמָּיו? אֶלָּא דָּבָר זֶה קָלוֹן בְּעַמָּיו, פְּגָם בְּעַמָּיו, וְעַל כֵּן כָּתוּב, כִּי אִם בְּתוּלָה מֵעַמָּיו יִקַּח אִשָּׁה, מֵעַמָּיו וַדַּאי, הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. כִּי אֲנִי ה' מְקַדְּשׁוֹ, מַה זֶּה מְקַדְּשׁוֹ? אֶלָּא אֲנִי הוּא אוֹתוֹ שֶׁמְּקַדֵּשׁ אוֹתוֹ בְּכָל יוֹם, וּמִשּׁוּם כָּךְ לֹא יִפְגֹּם זַרְעוֹ וְלֹא יִמָּצֵא בּוֹ פְּגָם. (ומשום זה) שֶׁהֲרֵי אֲנִי ה' מְקַדְּשׁוֹ, שֶׁאֲנִי רוֹצֶה לְקַדֵּשׁ אוֹתוֹ, וְיִמָּצֵא קָדוֹשׁ בַּכֹּל, שֶׁקָּדוֹשׁ יִשְׁתַּמֵּשׁ עַל יְדֵי קָדוֹשׁ.</p>\n<p>בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׁתַּמֵּשׁ עַל יְדֵי הַכֹּהֵן, וְיִמָּצֵא קָדוֹשׁ כְּשֶׁבָּא לְשַׁמֵּשׁ, וּמִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׁתַּמֵּשׁ עַל יְדֵי הַכֹּהֵן שֶׁהוּא קָדוֹשׁ, הַכֹּהֵן יִשְׁתַּמֵּשׁ עַל יְדֵי טָהוֹר, שֶׁהִתְקַדֵּשׁ בְּטָהֳרָתוֹ, וּמִי הוּא? זֶה לֵוִי. אָדָם (כהן) אַחֵר יִשְׁתַּמֵּשׁ עַל יְדֵי קָדוֹשׁ אַחֵר, כְּדֵי שֶׁכֻּלָּם יִמָּצְאוּ בִקְדֻשָּׁה לְשַׁמֵּשׁ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁעֲלֵיהֶם כָּתוּב (ויקרא כ) וָאַבְדִּל אֶתְכֶם מִן הָעַמִּים לִהְיוֹת לִי. כַּמָּה פְרוּשִׁים הֵם יִשְׂרָאֵל בִּקְדֻשָּׁה לְשַׁמֵּשׁ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, זֶהוּ שֶׁכָּתוּב (שם) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדֹשִׁים כִּי אֲנִי ה' אֱלֹהֵיכֶם.</p>\n<p>עוֹד פָּתַח וְאָמַר, (תהלים ג) לַה' הַיְשׁוּעָה עַל עַמֶּךְ בִרְכָתֶךְ סֶּלָה. לַה' הַיְשׁוּעָה - כָּךְ שָׁנִינוּ, אַשְׁרֵיהֶם יִשְׂרָאֵל, שֶׁלְּכָל מָקוֹם שֶׁגָּלוּ, שְׁכִינָה גָּלְתָה עִמָּהֶם. כְּשֶׁיֵּצְאוּ יִשְׂרָאֵל מֵהַגָּלוּת, לְמִי הַגְּאֻלָּה - לְיִשְׂרָאֵל אוֹ לַקָּדוֹשׁ בָּרוּךְ הוּא? אֶלָּא הֲרֵי פֵּרְשׁוּהָ בְּכַמָּה כְתוּבִים, וְכָאן - לַה' הַיְשׁוּעָה וַדַּאי. מָתַי? עַל עַמְּךְ בִרְכָתֶךְ סֶּלָה. בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַשְׁגִּיחַ בִּבְרָכוֹת עַל יִשְׂרָאֵל לְהוֹצִיא אוֹתָם מִן הַגָּלוּת וּלְהֵיטִיב לָהֶם, אֲזַי - לַה' הַיְשׁוּעָה וַדַּאי. וְעַל כֵּן שָׁנִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָשׁוּב עִם יִשְׂרָאֵל מִן הַגָּלוּת. זֶהוּ שֶׁכָּתוּב, (דברים ד) וְשָׁב ה' אֱלֹהֶיךְ אֶת שְׁבוּתְךְ וְרִחֲמֶךְ.</p>"],[9522012196,"<p>כִּי אִם בְּתוּלָה מֵעַמָּיו יִקַּח אִשָּׁה. פָּתַח הָרוֹעֶה הַנֶּאֱמָן וְאָמַר, מִצְוָה זוֹ שֶׁיִּשָּׂא כֹּהֵן גָּדוֹל בְּתוּלָה, זֶהוּ שֶׁכָּתוּב אַלְמָנָה וּגְרוּשָׁה וַחֲלָלָה זֹּנָה אֶת אֵלֶּה לֹא יִקָּח כִּי אִם בְּתוּלָה מֵעַמָּיו יִקַּח אִשָּׁה. וְלָמָּה צְרִיכִים שֶׁלֹּא יִשָּׂא אֶלָּא בְּתוּלָה בְּלִי פְגָם? אֶלָּא אִשָּׁה הִיא כּוֹס שֶׁל בְּרָכָה. טָעֲמוּ - פְּגָמוֹ. וְכֹהֵן שֶׁמַּקְרִיב קָרְבָּן לִפְנֵי ה', צָרִיךְ שֶׁהוּא יִהְיֶה שָׁלֵם בְּלִי פְגָם, שָׁלֵם בְּאֵיבָרָיו בְּלִי פְגָם, שֶׁמּוּמִים פּוֹסְלִים בְּכֹהֲנִים. שָׁלֵם בְּגוּפוֹ, שָׁלֵם בִּנְקֵבָתוֹ, לְקַיֵם בָּהּ (שיר ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ.</p>\n<p>שֶׁקָּרְבָּן הוּא מִנְחָה, וּצְרִיכִים יִשְׂרָאֵל לִשְׁלֹחַ אֶת מִנְחָתָם לַמֶּלֶךְ עִם אִישׁ (בגוף) שָׁלֵם, שֶׁהֵם בַּהֵפֶךְ שֶׁל הַצַּד הָאַחֵר, שֶׁהֲרֵי בְּיַד אִישׁ עִתִּי פָּגוּם הָיוּ שׁוֹלְחִים לוֹ דּוֹרוֹן, שֶׁכָּתוּב (ויקרא טז) גּוֹרָל אֶחָד לַה' וְגוֹרָל אֶחָד לַעֲזָאזֵל. שֶׁאֱלֹהִים אֲחֵרִים כֻּלָּם פְּגוּמִים מִצַּד הַצָּפוֹן, וְכֵן רֹב בָּתֵּי הָעֲבוֹדָה זָרָה הֵם פְּגוּמִים בַּנְּקֵבָה שֶׁלָּהֶם, חָרְבָּה, לִילִית, פְּגוּמָה וְכוּ'.</p>\n<p>(ורועה הנאמן) הוּא ו' מָלֵא, וְהוּא בְּסִדּוּר זֶה הי\"ו. ה' אַחֲרוֹנָה, כּוֹס מָלֵא בִּרְכַּת ה', מִצַּד הַיָּמִין וּמִצַּד הַגְּבוּרָה שֶׁהוּא דִּין, הַשְּׁכִינָה נִקְרֵאת הוי\"ה, זֶהוּ שֶׁכָּתוּב (שמות ט) הִנֵּה יַ\"ד יְהֹוָ\"ה הוֹיָה בְּמִקְנְךְ אֲשֶׁר בַּשָּׂדֶה. קָם רוֹעֶה הַנֶּאֱמָן וְהִשְׁתַּטַּח לְפָנָיו, וְאָמַר: אַשְׁרֵי חֶלְקִי שֶׁבַּעֲלֵי הַגְּבִירָה (והגבירה) הֵם בְּעֶזְרִי. (עד כאן רעיא מהימנא).</p>"],[9522012197,"<p>אִישׁ מִזַּרְעֲךְ לְדֹרֹתָם אֲשֶׁר יִהְיֶה בוֹ מוּם. רַבִּי יִצְחָק אָמַר, מִשּׁוּם שֶׁהוּא פָּגוּם, וּמִי שֶׁהוּא פָּגוּם לֹא רָאוּי לְשַׁמֵּשׁ בַּקֹּדֶשׁ. וַהֲרֵי פֵּרְשׁוּהָ, שֶׁאָדָם שֶׁנִּמְצָא פָגוּם אֵין בּוֹ אֱמוּנָה, וְאוֹתוֹ הַפְּגָם מֵעִיד עָלָיו, כָּל שֶׁכֵּן כֹּהֵן, שֶׁצָּרִיךְ לְהִמָּצֵא שָׁלֵם, בַּעַל הָאֱמוּנָה, יוֹתֵר מֵהַכֹּל, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>רַבִּי אֶלְעָזָר הָיָה יוֹשֵׁב בַּהֵיכָל שֶׁל בֵּית חָמִיו, וְהוּא הָיָה אוֹמֵר, לִזְלִיגַת הַדְּמָעוֹת שֶׁבַּהֵיכָל יֵשׁ עֵצָה לִמְצֹא. בֵּין כָּךְ עָבַר אִישׁ אֶחָד פָּגוּם בְּעַיִן אַחַת. אָמַר חָמִיו, נִשְׁאַל אֶת זֶה. אָמַר, הוּא פָּגוּם וְלֹא נֶאֱמָן. אָמַר, נִשְׁאַל אוֹתוֹ. בָּאוּ וְשָׁאֲלוּ אוֹתוֹ. אָמַר לוֹ, מִיהוּ הַמְאֻשָּׁר שֶׁבָּעוֹלָם? אָמַר, הֶעָשִׁיר, אֲבָל אִם יִנָּתֵק, עִמּוֹ אֲנִי מִכֻּלָּם. (העשיר, אבל אם ינתק, אוי על זה, עמו אני מכלם) אָמַר רַבִּי אֶלְעָזָר, מִדְּבָרָיו נִשְׁמָע שֶׁאֵין בּוֹ אֱמוּנָה, וְלֹא בֶּן אֱמוּנָה הוּא. בּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר, כָּל אִישׁ אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב, שֶׁהֲרֵי הַקְּדֻשָּׁה שֶׁלְּמַעְלָה אֵינָהּ שׁוֹרָה בְּמָקוֹם פָּגוּם.</p>\n<p>פָּתַח וְאָמַר, (ישעיה ח) לְתוֹרָה וְלִתְעוּדָה אִם לֹא יֹאמְרוּ כַּדָּבָר הַזֶּה. לְתוֹרָה וְלִתְעוּדָה, מִי הִיא תּוֹרָה, וּמִי הִיא תְּעוּדָה? אֶלָּא תּוֹרָה - זוֹ תּוֹרָה שֶׁבִּכְתָב. תְּעוּדָה - זוֹ תּוֹרָה שֶׁבְּעַל פֶּה. תּוֹרָה שֶׁבְּעַל פֶּה אֵינָהּ שׁוֹרָה בְמָקוֹם פָּגוּם, שֶׁהֲרֵי מִתּוֹרָה שֶׁבִּכְתָב נִבְנֵית. כָּתוּב צוֹר תְּעוּדָה חֲתוֹם תּוֹרָה בְּלִמֻּדָי. צוֹר תְּעוּדָה - זוֹ תּוֹרָה שֶׁבְּעַל פֶּה, מִשּׁוּם שֶׁשָּׁם נִצְרָר צְרוֹר הַחַיִּים, וּבִתְעוּדָה נִקְשָׁר קֶשֶׁר הַחַיִּים (קשרהאמונה) שֶׁלְּמַעְלָה, לִהְיוֹת הַכֹּל אֶחָד.</p>\n<p>וּמִשָּׁם לְמַטָּה נִפְרָדוֹת הַדְּרָכִים וְהַשְּׁבִילִים, וּמִשָּׁם נִפְרָדוֹת הַדְּרָכִים בְּכָל הָעוֹלָמוֹת. זֶהוּ שֶׁכָּתוּב, (בראשית ב) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים.</p>\n<p>חֲתוֹם תּוֹרָה, חֲתִימָה שֶׁל הַתּוֹרָה, שֶׁהִיא תּוֹרָה שֶׁבִּכְתָב, בְּאֵיזֶה מָקוֹם? בְּלִמֻּדָי, אֵלּוּ הַנְּבִיאִים, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ז) וַיָּקֶם אֶת הָעַמּוּד הַיְמָנִי וַיִּקְרָא אֶת שְׁמוֹ יָכִין וַיָּקֶם אֶת הָעַמּוּד הַשְּׂמָאלִי וַיִּקְרָא אֶת שְׁמוֹ בֹּעַז. וּמִשָּׁם נִפְרָדוֹת הַדְּרָכִים לַנְּבִיאִים הַנֶּאֱמָנִים. וְאֵלֶּה עוֹמְדִים בְּקִיּוּם לַגּוּף, לְשֵׁשֶׁת הָאוֹרוֹת, זֶהוּ שֶׁכָּתוּב (שיר ח) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ. וְהַכֹּל לֹא עוֹמֵד אֶלָּא בִּשְׁלֵמוּת, וְלֹא שׁוֹרָה קְדֻשָּׁה שֶׁל הַכֹּל אֶלָּא בִּשְׁלֵמוּת, כְּשֶׁמִּתְחַבְּרִים זֶה עִם זֶה, הַכֹּל הוּא שָׁלֵם, הַכֹּל הוּא אֶחָד, לֹא נִפְגָּם הַמָּקוֹם. וְלָכֵן נִקְרֵאת כְּנֶסֶת יִשְׂרָאֵל שָׁלֵם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית יד) וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם, (תהלים עו) וַיְהִי בְשָׁלֵם סוּכּוֹ.</p>\n<p>וּמִשּׁוּם כָּךְ לֹא שׁוֹרֶה הַכֹּל אֶלָּא בְּמָקוֹם שָׁלֵם. וְעַל כֵּן כָל אִישׁ אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב. כְּמוֹ כֵן הַקָּרְבָּן שֶׁבּוֹ מוּם לֹא יִתְקָרֵב. מָה הַטַּעַם? שֶׁכָּתוּב כִּי לֹא לְרָצוֹן יִהְיֶה לָכֶם. וְאִם תֹּאמַר, הֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא שׁוֹרֶה אֶלָּא בְּמָקוֹם שָׁבוּר, בִּכְלִי שָׁבוּר, שֶׁכָּתוּב (ישעיה נז) וְאֶת דַּכָּא וּשְׁפַל רוּחַ. הַמָּקוֹם הַזֶּה הוּא שָׁלֵם יוֹתֵר מֵהַכֹּל, (שכתוב (ישעיה נז) ואת דכא ושפל רוח) מִשּׁוּם שֶׁמַּנְמִיךְ עַצְמוֹ לְהַשְׁרוֹת עָלָיו אֶת גֵּאוּת הַכֹּל, הַגֵּאוּת שֶׁלְּמַעְלָה, וְזֶהוּ שָׁלֵם. אֲבָל לֹא כָתוּב, וְאֶת עִוֵּר וְשָׁבוּר וְחָרוּם וְשָׂרוּעַ, אֶלָּא וְאֶת דַּכָּא וּשְׁפַל רוּחַ. מִי שֶׁמַּנְמִיךְ עַצְמוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא זוֹקֵף אוֹתוֹ.</p>\n<p>וּמִשּׁוּם כָּךְ, הַכֹּהֵן שֶׁעוֹמֵד לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה צָרִיךְ לִהְיוֹת שָׁלֵם יוֹתֵר מֵהַכֹּל, וְלֹא יֵרָאֶה פָגוּם, וְעַל כֵּן הִזְהִיר אֶת הַכֹּהֲנִים, שֶׁכָּתוּב אִישׁ מִזַּרְעֲךְ לְדרֹתָם אֲשֶׁר יִהְיֶה בוֹ מוּם.</p>\n<p>עוֹד פָּתַח וְאָמַר, (מלאכי א) וְכִי תַגִּשׁוּן עִוֵּר לִזְבֹּחַ אֵין רָע וְכִי תַגִּישׁוּ פִּסֵּחַ וְחֹלֶה אֵין רָע. וְכִי הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר אֵין רָע? אִם כָּךְ טוֹב הוּא! אֶלָּא סוֹף הַכָּתוּב מוֹכִיחַ, שֶׁיִּשְׂרָאֵל בְּאוֹתָם הַיָּמִים הָיוּ מְמַנִּים כֹּהֲנִים בַּעֲלֵי מוּמִים עַל גַּבֵּי הַמִּזְבֵּחַ וּלְשַׁמֵּשׁ עַל הַמִּקְדָּשׁ, וְאוֹמְרִים: מָה אִכְפַּת לַקָּדוֹשׁ בָּרוּךְ הוּא זֶה אוֹ אַחֵר. וְהֵם הָיוּ שֶׁאוֹמְרִים אֵין רָע. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֵשִׁיב לָהֶם אוֹתוֹ דָּבָר שֶׁהָיוּ אוֹמְרִים. אָמַר: יִשְׂרָאֵל, אַתֶּם אוֹמְרִים כְּשֶׁמַּקְרִיבִים בַּעֲלֵי מוּמִים לַעֲבוֹדָתִי אֵין רָע, מָה אִכְפַּת לוֹ לַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>בְּסוֹף הַפָּסוּק מַה כָּתוּב? הַקְרִיבֵהוּ נָא לְפֶחָתֶךְ הֲיִרְצְךְ אוֹ הֲיִשָּׂא פָנֶיךְ. אָדָם מִכֶּם, אִם תִּרְצוּ לְשַׁלֵּם לַמֶּלֶךְ וּלְהַקְרִיב לְפָנָיו דּוֹרוֹן, אַתֶּם שׁוֹלְחִים לוֹ עִם פְּגָם אוֹ לֹא?! הֲיִרְצְךְ אוֹ הֲיִשָּׂא פָנֶיךְ בְּאוֹתוֹ הַדּוֹרוֹן?! כָּל שֶׁכֵּן וְכָל שֶׁכֵּן כְּשֶׁאַתֶּם מַקְרִיבִים לְפָנַי אָדָם פָּגוּם לְהַקְרִיב דּוֹרוֹן, הֲרֵי הַדּוֹרוֹן שֶׁלָּכֶם נִמְסָר לַכֶּלֶב, שֶׁוַּדַּאי אָדָם שֶׁהוּא פָּגוּם, פָּגוּם הוּא מֵהַכֹּל, פָּגוּם הוּא בָּאֱמוּנָה. וְעַל כֵּן כָל אִישׁ אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב.</p>\n<p>אָמַר רַבִּי יוֹסֵי, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁלִים עִם יִשְׂרָאֵל וְשֶׁיִּמָּצְאוּ שְׁלֵמִים בַּכֹּל, שֶׁהֲרֵי לֹא יִהְיוּ בָהֶם כְּלָל בַּעֲלֵי מוּמִים, מִשּׁוּם שֶׁיִּהְיוּ תִקּוּנוֹ שֶׁל עוֹלָם, כְּמוֹ הַכֵּלִים הַלָּלוּ וּלְבוּשׁוֹ שֶׁל אָדָם שֶׁהֵם תִּקּוּן הַגּוּף. זֶהוּ שֶׁכָּתוּב (איוב לח) וַיִּתְיַצְּבוּ כְּמוֹ לְבוּשׁ.</p>\n<p>(דבר אחר) בֹּא רְאֵה, כְּשֶׁיִּתְעוֹרְרוּ מֵהֶעָפָר, כְּמוֹ שֶׁנִּכְנְסוּ כָּךְ יָקוּמוּ, חִגְרִים אוֹ סוּמִים נִכְנְסוּ, חִגְרִים וְסוּמִים - יָקוּמוּ, בְאוֹתוֹ לְבוּשׁ. שֶׁלֹּא יֹאמְרוּ שֶׁאַחֵר הוּא שֶׁהִתְעוֹרֵר. וְאַחַר כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא יְרַפֵּא אוֹתָם וְיִמָּצְאוּ שְׁלֵמִים לְפָנָיו, וְאָז יִהְיֶה הָעוֹלָם שָׁלֵם בַּכֹּל, אָז - (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>"],[9522012198,"<p>שׁוֹר אוֹ כֶשֶׂב אוֹ עֵז כִּי יִוָּלֵד וְהָיָה שִׁבְעַת יָמִים תַּחַת אִמּוֹ וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (תהלים לו) צִדְקָתְךְ כְּהַרְרֵי אֵל מִשְׁפָּטֶיךְ תְּהוֹם רַבָּה אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'. בַּפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן בּוֹ, אֲבָל בּא רְאֵה, צֶדֶק - כֶּתֶר קָדוֹשׁ עֶלְיוֹן. כְּהַרְרֵי אֵל - כְּמוֹ אוֹתָם הָרִים עֶלְיוֹנִים קְדוֹשִׁים שֶׁנִּקְרָאִים הָרֵי אֲפַרְסְמוֹן זַךְ. וּמִשּׁוּם שֶׁהִיא עוֹלָה לְהִתְקַשֵּׁר בָּהֶם לְמַעְלָה, כָּל דִּינֶיהָ בְּמִשְׁקָל אֶחָד לַכֹּל, שֶׁאֵין בְּאוֹתוֹ הַדִּין רַחֲמִים. מִשְׁפָּטֶיךְ תְּהוֹם רַבָּה - מִשְׁפָּט שֶׁהוּא רַחֲמִים יוֹרֵד לְמַטָּה לְאוֹתָהּ הַדַּרְגָּה לְתַקֵּן עוֹלָמוֹת, וְחָס עַל הָעוֹלָם, וְעוֹשֶׂה דִּין בְּרַחֲמִים לְבַשֵּׂם אֶת הָעוֹלָם.</p>\n<p>וּמִשּׁוּם שֶׁהוּא רַחֲמִים - אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'. לַכֹּל בְּמִשְׁקָל אֶחָד. אָדָם וּבְהֵמָה, הֲרֵי פֵּרְשׁוּהָ, מִי שֶׁהוּא אָדָם וְשָׂם אֶת עַצְמוֹ כַּבְּהֵמָה. אָדָם וּבְהֵמָה - דִּין אָדָם וְדִין בְּהֵמָה אֶחָד הוּא. אָדָם - (בראשית יז) וּבֶן שְׁמֹנַת יָמִים יִמּוֹל לָכֶם כָּל זָכָר. בְּהֵמָה - וְהָיָה שִׁבְעַת יָמִים תַּחַת אִמּוֹ וּמִיּוֹם הַשְּׁמִינִי וָהָלְאָה יֵרָצֶה לְקָרְבַּן אִשֶּׁה לַה', כְּדֵי שֶׁתַּעֲבֹר עֲלֵיהֶם שַׁבָּת אַחַת, וַהֲרֵי פֵּרְשׁוּהָ.</p>"],[9522012199,"<p>רַבִּי חִיָּיא פָּתַח, (שופטים ה) ה' בְּצֵאתְךְ מִשֵּׂעִיר בְּצַעְדְּךְ מִשְּׂדֵה אֱדוֹם אֶרֶץ רָעָשָׁה גַּם שָׁמַיִם נָטָפוּ. בּא רְאֵה, אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם, וְהֵם נִדְבָּקִים בּוֹ וְנִקְרָאִים קְדוֹשִׁים, עַם קָדוֹשׁ. וְכֵן עַד שֶׁהֶעֱלָה אוֹתָם לְדַרְגָּה עֶלְיוֹנָה שֶׁנִּקְרֵאת קֹדֶשׁ, שֶׁכָּתוּב (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה. כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁהֲרֵי יִשְׂרָאֵל מִשְּׁמוֹנָה יָמִים נִדְבָּקִים בִּשְׁמוֹ וּרְשׁוּמִים בִּשְׁמוֹ וְהֵם שֶׁלּוֹ, כְּמוֹ שֶׁנֶּאֱמַר וּמִי כְעַמְּךְ כְּיִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ. וְהָעֲמָמִים לֹא נִדְבָּקִים בּוֹ וְלֹא הוֹלְכִים בְּהַנְהָגוֹתָיו, וְהָרֹשֶׁם הַקָּדוֹשׁ נֶעְדָּר מֵהֶם, עַד שֶׁהֵם נִדְבָּקִים לַצַּד הָאַחֵר שֶׁאֵינוֹ קָדוֹשׁ.</p>\n<p>וּבֹא רְאֵה, בְּשָׁעָה שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת תּוֹרָה לְיִשְׂרָאֵל, הִזְמִין אוֹתָהּ לִבְנֵי עֵשָׂו. אָמַר לָהֶם: רוֹצִים אַתֶּם לְקַבֵּל תּוֹרָה? בְּאוֹתָהּ שָׁעָה רָגְזָה הָאָרֶץ הַקְּדוֹשָׁה, וְרָצְתָה לְהִכָּנֵס לְנֶקֶב תְּהוֹם רַבָּה. אָמְרָה לְפָנָיו: רִבּוֹן הָעוֹלָם, שַׁעֲשׁוּעֵי הַשִּׂמְחָה (של העולם) אַלְפַּיִם שָׁנִים טֶרֶם שֶׁנִּבְרָא הָעוֹלָם, יִזְדַּמְּנוּ לְפָנָיו (יזדמנו תוך) (יזדמן לפני) עֲרֵלִים שֶׁאֵינָם רְשׁוּמִים בִּבְרִיתְךְ?!</p>\n<p>אָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא: כִּסֵּא כִּסֵּא, יֹאבְדוּ אֶלֶף אֻמּוֹת כְּמוֹתָם, וּבְרִית הַתּוֹרָה לֹא תִזְדַּמֵּן לִפְנֵיהֶם. זֶהוּ שֶׁכָּתוּב ה' בְּצֵאתְךְ מִשֵּׂעִיר בְּצַעְדְּךְ מִשְּׂדֵה אֱדוֹם אֶרֶץ רָעָשָׁה. וַדַּאי מִשּׁוּם שֶׁהַתּוֹרָה לֹא נִתְּנָה (משום שהיא ברית קדושה) אֶלָּא לְמִי שֶׁיֵּשׁ בּוֹ בְּרִית קֹדֶשׁ. וּמִי שֶׁמְּלַמֵּד תּוֹרָה לְמִי שֶׁלֹּא נִמּוֹל, מְשַׁקֵּר בִּשְׁתֵּי בְרִיתוֹת - מְשַׁקֵּר בִּבְרִית הַתּוֹרָה, וּמְשַׁקֵּר בַּבְּרִית שֶׁל צַדִּיק וּכְנֶסֶת יִשְׂרָאֵל, שֶׁהַתּוֹרָה נִתְּנָה לַמָּקוֹם הַזֶּה, וְלֹא לְאַחֵר.</p>\n<p>רַבִּי אַבָּא אָמַר, מְשַׁקֵּר בִּשְׁלֹשָׁה מְקוֹמוֹת עֶלְיוֹנִים - מְשַׁקֵּר בַּתּוֹרָה, מְשַׁקֵּר בַּנְּבִיאִים, מְשַׁקֵּר בַּכְּתוּבִים. מְשַׁקֵּר בַּתּוֹרָה, שֶׁכָּתוּב (דברים ד) וְזֹּאת הַתּוֹרָה וְגוֹ'. מְשַׁקֵּר בַּנְּבִיאִים, שֶׁכָּתוּב (ישעיה נד) וְכָל בָּנַיִךְ לִמּוּדֵי ה'. הֵם לִמּוּדֵי ה' וְלֹא אַחֵר, וְכָתוּב (שם ח) חֲתוֹם תּוֹרָה בְּלִמֻּדָי, הֵם וְלֹא אַחֵר. מְשַׁקֵּר בַּכְּתוּבִים, שֶׁכָּתוּב (תהלים עח) וַיָּקֶם עֵדוּת בְּיַעֲקֹב וְתוֹרָה שָׂם בְּיִשְׂרָאֵל, וְכָתוּב (שם קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ. מִי הַצַּדִּיקִים? זֶה צַדִּיק וּכְנֶסֶת יִשְׂרָאֵל. שֶׁמִּי שֶׁלֹּא נִמּוֹל וְלֹא נִכְנַס לַבְּרִית שֶׁלָּהֶם, לֹא יוֹדוּ לִשְׁמוֹ הַקָּדוֹשׁ, שֶׁהִיא הַתּוֹרָה. אָמַר רַבִּי חִיָּיא, כֵּיוָן שֶׁהִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַר סִינַי לָתֵת תּוֹרָה לְיִשְׂרָאֵל, שָׁכְכָה הָאָרֶץ וְשָׁבָה לִמְנוּחָה. זֶהוּ שֶׁכָּתוּב (שם עו) אֶרֶץ יָרְאָה וְשָׁקָטָה.</p>"],[9522012200,"<p>בֹּא רְאֵה, אָדָם שֶׁנּוֹלַד לֹא הִתְמַנָּה עָלָיו הַכֹּחַ שֶׁלְּמַעְלָה עַד שֶׁנִּמּוֹל. כֵּיוָן שֶׁנִּמּוֹל, מִתְעוֹרֶרֶת עָלָיו (רוח) הִתְעוֹרְרוּת שֶׁל רוּחַ שֶׁל מַעְלָה. זוֹכֶה לְהִתְעַסֵּק בַּתּוֹרָה - מִתְעוֹרֶרֶת עָלָיו הִתְעוֹרְרוּת יְתֵרָה. זוֹכֶה וְעוֹשֶׂה מִצְווֹת הַתּוֹרָה, מִתְעוֹרֶרֶת עָלָיו הִתְעוֹרְרוּת יְתֵרָה. זוֹכֶה וְנוֹשֵׂא - זוֹכֶה וּמוֹלִיד בָּנִים וּמְלַמֵּד אוֹתָם אֶת דַּרְכֵי הַמֶּלֶךְ הַקָּדוֹשׁ, הֲרֵי אָז הוּא אָדָם שָׁלֵם, שָׁלֵם בַּכֹּל.</p>\n<p>אֲבָל בְּהֵמָה שֶׁנּוֹלְדָה, בְּאוֹתָהּ שָׁעָה שֶׁנּוֹלְדָה, אוֹתוֹ כֹחַ שֶׁיֵּשׁ לָהּ בְּסוֹפָהּ יֵשׁ לָהּ בְּאוֹתָהּ שָׁעָה שֶׁנּוֹלְדָה, וְהִתְמַנָּה עָלֶיהָ. וּמִשּׁוּם כָּךְ כָּתוּב, שׁוֹר אוֹ כֶשֶׂב אוֹ עֵז כִּי יִוָּלֵד. עֵגֶל אוֹ טָלֶה אוֹ שָׂעִיר אוֹ גְדִי לֹא נֶאֱמַר, אֶלָּא שׁוֹר אוֹ כֶשֶׂב אוֹ עֵז. אוֹתוֹ שֶׁיֵּשׁ לוֹ לַסּוֹף - יֵשׁ לוֹ בְּשָׁעָה שֶׁנּוֹלַד.</p>\n<p>וְהָיָה שִׁבְעַת יָמִים תַּחַת אִמּוֹ, כְּדֵי לְיַשֵּׁב בּוֹ אוֹתוֹ כֹחַ וּמִתְקַיֵּם בּוֹ. וּבַמֶּה יִתְקַיֵּם בּוֹ? כְּשֶׁתִּשְׁרֶה עָלָיו שַׁבָּת אַחַת, וְאִם לֹא - לֹא יִתְקַיֵּם. (ועוד, שיתיבש מזהמת אמו) וְאַחַר שֶׁיִּתְקַיֵּם בּוֹ אוֹתוֹ הַכֹּחַ, כָּתוּב יֵרָצֶה לְקָרְבַּן אִשֶּׁה לַה', בְּקִיּוּם שֶׁל שַׁבָּת אַחַת שֶׁעָבְרָה עָלָיו.</p>\n<p>וּבֶן אָדָם, בְּקִיּוּם שֶׁל שַׁבָּת אַחַת מִתְקַיֶּמֶת בּוֹ הִתְעוֹרְרוּת שֶׁל הָעוֹלָם הַזֶּה וְהַכֹּחַ שֶׁלּוֹ. אַחַר שֶׁנִּמּוֹל, מִתְעוֹרֶרֶת עָלָיו הִתְעוֹרְרוּת שֶׁל רוּחַ עֶלְיוֹנָה, וּכְנֶסֶת יִשְׂרָאֵל עוֹבֶרֶת עָלָיו וְרוֹאָה אוֹתוֹ בְּרֹשֶׁם קָדוֹשׁ, וּמִתְעוֹרֶרֶת עָלָיו וְשׁוֹרָה עָלָיו הָרוּחַ שֶׁל אוֹתוֹ עוֹלָם קָדוֹשׁ, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל טז) וָאֶעֱבֹר עָלַיִךְ וָאֶרְאֵךְ מִתְבּוֹסֶסֶת בְּדָמָיִךְ וְגוֹ'. בְּדָמָיִךְ - בִּשְׁנַיִם.</p>\n<p>וְאִם תֹּאמַר, שָׁם כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, שֶׁהָיוּ מָצוּי בֵּינֵיהֶם דַּם פֶּסַח וְדַם מִילָה, אֲזַי כָּתוּב בְּדָמַיִךְ חֲיִי, כָּאן מַה זֶּה בְּדָמַיִךְ? אֶלָּא שְׁנַיִם - אֶחָד שֶׁל מִילָה וְאֶחָד שֶׁל פְּרִיעָה. אֶחָד שֶׁל מִילָה שֶׁל כְּנֶסֶת יִשְׂרָאֵל, וְאֶחָד שֶׁל פְּרִיעָה בְּצַדִּיק יְסוֹד עוֹלָם. וְאֵלּוּ שְׁנֵי דָמִים שֶׁאָדָם עוֹמֵד בִּשְׁבִילָם בַּקִּיּוּם שֶׁל הָעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב בְּדָמַיִךְ חֲיִי.</p>"],[9522012201,"<p>רַבִּי שִׁמְעוֹן אָמַר, (תהלים כה) סוֹד ה' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם. סוֹד ה' לִירֵאָיו - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וּבְרִיתוֹ לְהוֹדִיעָם - זֶה צַדִּיק יְסוֹד עוֹלָם, בְּקֶשֶׁר אֶחָד.</p>\n<p>יוֹ\"ד, שָׁלֹשׁ אוֹתִיּוֹת, הַשְּׁלֵמוּת שֶׁל הַכֹּל. י' רֵאשִׁית הַכֹּל. י' עֶלְיוֹנָה שֶׁל הַכֹּל, וָא\"ו אֶמְצַע, שְׁלֵמוּתָם שֶׁל כָּל הַצְּדָדִים, מַעֲבִיר אֶת כָּל הָרוּחוֹת, בּוֹ תְּלוּיָה הָאֱמוּנָה. דָּלֶ\"ת, הַגָּן, צְרוֹר הַחַיִּים. הָאוֹת הַזּוֹ קְטַנָּה, שְׁלֵמוּת שֶׁל הַכֹּל.</p>\n<p>הָאוֹת הַזּוֹ סְתוּמָה שֶׁל כָּל הַצְּדָדִים. כְּשֶׁיּוֹצֵאת, יוֹצֵאת כְּמוֹ מֶלֶךְ עִם חֵילוֹתָיו. שָׁבָה (יושבת) אַחַר כָּךְ י' לְבַדָּהּ, בָּהּ נִסְתָּר הַדָּבָר, בָּהּ יוֹצֵא, סוֹגֵר וּפוֹתֵחַ. (שופע ויוצא ופותח).</p>\n<p>הֵ\"א (זו) הַשְּׁלֵמוּת שֶׁל הַכֹּל, לְמַעְלָה וּלְמַטָּה. וַהֲרֵי נִתְבָּאֵר, הֵ\"א ה', הֲרֵי יְדוּעָה. א' הִיא יוֹ\"ד, שְׁלֵמוּת שֶׁל שָׁלֹשׁ אוֹתִיּוֹת שֶׁהֵן בָּרֹאשׁ, שֶׁסְּתוּמוֹת (ביו\"ד, והרי פרשוה) בּוֹ ו' עַל גַּבֵּי א' (שא' הא), וַהֲרֵי פֵּרְשׁוּהָ (בי', והרי פרשוה), וְהַכֹּל הוּא דָּבָר אֶחָד, שְׁלֵמוּת הַשֵּׁם הַקָּדוֹשׁ, הוּא שְׁלֵמוּת שֶׁל מַעְלָה (ומטה). מִשּׁוּם כָּךְ לִפְעָמִים הֵ\"א נוֹטֶלֶת א', בִּזְמַן שֶׁהִיא מִתְעַטֶּרֶת בְּעַטְרוֹתָיו.</p>\n<p>בֹּא רְאֵה, בְּכָל אוֹת וָאוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ נִרְאֵית הַשְּׁלֵמוּת שֶׁל כָּל הַשֵּׁם. יוֹ\"ד הֲרֵי נִתְבָּאֵר שְׁלֵמוּת הַכֹּל. ה' שְׁלֵמוּת שֶׁל הַכֹּל, וְאַף עַל גַּב שֶׁאֵינָהּ בְּאָלֶף, ה' בִּלְבַדָּהּ, הֲרֵי נִתְבָּאֵר בִּדְיוֹקַן (זו א' היא וכו') ה\"י (היא) (זו ה'). הוּא שְׁלֵמוּת הַכֹּל. ו' בֵּין בְּצַד זֶה בֵּין בְּצַד אַחֵר, שְׁלֵמוּת הוּא שֶׁל הַכֹּל. ו\"ה הִיא שְׁלֵמוּת יְתֵרָה, לְעַטֵּר אֶת הַכֹּל זֶה שֶׁהַכֹּל אֶחָד, וַהֲרֵי הִתְעוֹרְרוּ בוֹ הַחֲבֵרִים.</p>\n<p>בֹּא רְאֵה, וְהָיָה שִׁבְעַת יָמִים וְגוֹ'. יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א (וא,, ו ה,, א יו,, ד ה\"א) - נֶחְקְקוּ אוֹתִיּוֹת (והיה). ו' ה', הֲרֵי שִׁבְעַת יָמִים נִכְלְלוּ כְאֶחָד. י' ה', שִׁבְעַת יָמִים. י' אֶחָד, הַכְּלָל שֶׁל הַכֹּל. ה' שְׁלֹשָׁה, הִיא וּשְׁנֵי בָנִים. וּבֵן אֶחָד, שְׁנֵי אָבוֹת כְּלוּלִים בּו - הֲרֵי שִׁשָּׁה (חמשה). בַּת נְקֵבָה אַחַת - הֲרֵי שִׁבְעָה (ששה). נִשְׁמָע שֶׁה' עֶלְיוֹנָה כְּלָל שֶׁל שִׁשָּׁה. י\"ה הֲרֵי שִׁבְעָה. הַיְנוּ שֶׁכָּתוּב (מלכים א ח) שִׁבְעַת יָמִים וְשִׁבְעַת יָמִים אַרְבָּעָה עָשָׂר יוֹם.</p>\n<p>וְהָיָה שִׁבְעַת יָמִים תַּחַת אִמּוֹ. תַּחַת אִמּוֹ, הִתְעַטְּרוּ שִׁבְעַת יָמִים, שֶׁכָּתוּב (דברי הימים א כט) לְךְ ה' הַגְּדֻלָּה וְהַגְּבוּרָה וְגוֹ'. וְעַל כֵּן שִׁבְעַת יָמִים לְמַטָּה לִכְבוֹד הָאֵם הָעֶלְיוֹנָה. תַּחַת אִמּוֹ לְמַטָּה, שֶׁכָּתוּב (שמואל א ב) עַד עֲקָרָה יָלְדָה שִׁבְעָה וְרַבַּת בָּנִים אֻמְלָלָה. הָעִקָּר שֶׁל כָּל הַבַּיִת, יָלְדָה שִׁבְעָה, אֵלּוּ שִׁבְעַת הַיָּמִים שֶׁל חַג הַסֻּכּוֹת. וְרַבַּת בָּנִים אֻמְלָלָה - אֵלּוּ קָרְבְּנוֹת הֶחָג שֶׁיּוֹרְדִים בְּכָל יוֹם מִן הַמִּנְיָן.</p>\n<p>וּבֹא רְאֵה, אֵלּוּ עוֹלִים לְמַעְלָה לְמַעְלָה, וְאֵלּוּ יוֹרְדִים לְמַטָּה לְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (עובדיה א) אִם תַּגְבִּיהַּ כַּנֶּשֶׁר וְאִם בֵּין כּוֹכָבִים שִׂים קִנֶּךְ מִשָּׁם אוֹרִידְךְ נְאֻם ה'. וְיִשְׂרָאֵל עוֹלִים מִמַּטָּה לְמַעְלָה, שֶׁכָּתוּב (בראשית כח) וְהָיָה זַרְעֲךְ כַּעֲפַר הָאָרֶץ, וְכָתוּב (שם כו) וְהִרְבֵּיתִי אֶת זַרְעֲךְ כְּכוֹכְבֵי הַשָּׁמַיִם. וְאַחַר כָּךְ עוֹלִים עַל הַכֹּל וְנִדְבָּקִים בְּמָקוֹם עֶלְיוֹן עַל הַכֹּל. זֶהוּ שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם וְגוֹ'.</p>"],[9522012202,"<p>וְשׁוֹר אוֹ שֶׂה אֹתוֹ וְאֶת בְּנוֹ. אָמַר רַבִּי יוֹסֵי, כְּתַרְגּוּמוֹ: אוֹתָהּ וְאֶת בְּנָהּ. שֶׁעִקַּר הָאֵם לָדַעַת אֶת בְּנָהּ, וְהוֹא הוֹלֵךְ אַחֲרֶיהָ, וְלֹא הוֹלֵךְ אַחַר אָבִיו, וְאָנוּ לֹא יוֹדְעִים מִי הוּא? לֹא תִשְׁחֲטוּ בְּיוֹם אֶחָד.</p>\n<p>אָמַר רַבִּי יְהוּדָה, מָה הַטַּעַם? אִם תֹּאמַר מִשּׁוּם עָגְמַת נֶפֶשׁ שֶׁל הַבְּהֵמָה, אָז נִשְׁחַט אֶת זֶה בְּבַיִת אֶחָד וְאֶת הַהוּא בְּבַיִת אַחֵר, אוֹ אֶת זֶה עַכְשָׁו וְאֶת זֶה אַחַר כָּךְ. אָמַר לוֹ, יֵשׁ מִי שֶׁמַּתִּיר, וְלֹא כָּךְ, אֶלָּא בְּיוֹם אֶחָד מַמָּשׁ.</p>\n<p>בֹּא רְאֵה, יָפָה תַּעֲנִית לַחֲלוֹם כְּאֵשׁ לַנְּעֹרֶת. וְעִקַּר הַתַּעֲנִית הִיא בְּאוֹתוֹ יוֹם מַמָּשׁ, וְלֹא בְיוֹם אַחֵר. מָה הַטַּעַם? מִשּׁוּם שֶׁאֵין לְךְ יוֹם לְמַטָּה שֶׁלֹּא שׁוֹלֵט בּוֹ יוֹם אַחֵר עֶלְיוֹן. וּכְשֶׁהוּא שָׁרוּי בְּתַעֲנִית חֲלוֹם, לָמַדְנוּ שֶׁאוֹתוֹ יוֹם לֹא מוּסָר, עַד שֶׁמִּתְבַּטֶּלֶת אוֹתָהּ גְּזֵרָה. וְאִם דּוֹחֶה אוֹתָהּ לְיוֹם אַחֵר, הֲרֵי שִׁלְטוֹנוֹ שֶׁל הַיּוֹם הָאַחֵר הוּא, וְלֹא נִכְנָס יוֹם בְּיוֹם אַחֵר שֶׁל חֲבֵרוֹ. כְּמוֹ זֶה, אֵין לְךְ יוֹם שֶׁלֹּא הִתְמַנָּה עָלָיו יוֹם עֶלְיוֹן לְמַעְלָה. וְצָרִיךְ אָדָם לְהִשָּׁמֵר שֶׁלֹּא יַעֲשֶׂה פְגָם בְּאוֹתוֹ הַיּוֹם, וְלֹא יִפָּגֵם לִפְנֵי שְׁאָר הַיָּמִים הָאֲחֵ רִים.</p>\n<p>וְשָׁנִינוּ, בַּמַּעֲשֶׂה שֶׁלְּמַטָּה מִתְעוֹרֵר מַעֲשֶׂה לְמַעְלָה. אִם אָדָם עוֹשֶׂה מַעֲשֶׂה לְמַטָּה כָּרָאוּי, כָּךְ מִתְעוֹרֵר כֹּחַ כָּרָאוּי לְמַעְלָה. עוֹשֶׂה אָדָם חֶסֶד בָּעוֹלָם - מִתְעוֹרֵר חֶסֶד לְמַעְלָה, וְשׁוֹרֶה בְּאוֹתוֹ הַיּוֹם, וּמִתְעַטֵּר בּוֹ בִּשְׁבִילוֹ. וְאִם נוֹהֵג אָדָם בְּרַחֲמִים לְמַטָּה - מְעוֹרֵר רַחֲמִים עַל אוֹתוֹ יוֹם, וּמִתְעַטֵּר בְּרַחֲמִים בִּשְׁבִילוֹ. וְאָז אוֹתוֹ הַיּוֹם עוֹמֵד עָלָיו לִהְיוֹת אַפּוֹטְרוֹפּוֹס עָלָיו בְּשָׁעָה שֶׁיִּצְטָרֵךְ אוֹתוֹ.</p>\n<p>כְּמוֹ זֶה בַּהֵפֶךְ שֶׁל זֶה. (ועל הכל) אִם עוֹשֶׂה אָדָם מַעֲשֶׂה אַכְזָרִי, כָּךְ מְעוֹרֵר בְּאוֹתוֹ יוֹם וּפוֹגֵם אוֹתוֹ, וְאַחַר כָּךְ עוֹמֵד עָלָיו כְּמוֹ אַכְזָרִי לְכַלּוֹתוֹ מִן הָעוֹלָם. בְּאוֹתָהּ מִדָּה שֶׁאָדָם מוֹדֵד - בָּהּ מוֹדְדִין לוֹ.</p>\n<p>שָׁנִינוּ, שֶׁיִּשְׂרָאֵל נִמְנְעָה מֵהֶם אַכְזָרִיּוּת מִכָּל שְׁאָר הָעַמִּים, וְלֹא יִירְאוּ מֵהֶם מַעֲשֶׂה בָּעוֹלָם. שֶׁהֲרֵי כַּמָּה בַּעֲלֵי עֵינַיִם עוֹמְדִים עַל הָאָדָם בְּאוֹתוֹ הַמַּעֲשֶׂה. אַשְׁרֵי מִי שֶׁמַּרְאֶה מַעֲשֶׂה כָּשֵׁר לְמַטָּה, שֶׁהֲרֵי בְּמַעֲשֶׂה תָּלוּי הַדָּבָר בַּכֹּל, לְעוֹרֵר דָּבָר אַחֵר.</p>"],[9522012203,"<p>רַבִּי שִׁמְעוֹן פָּתַח, (בראשית מב) וַיַּרְא יַעֲקֹב כִּי יֵשׁ שֶׁבֶר בְּמִצְרָיִם. בְּפָסוּק זֶה יֵשׁ סוֹד שֶׁל חָכְמָה, וְיֵשׁ לָנוּ לְהִתְבּוֹנֵן בּוֹ, שֶׁאֵין סוֹפוֹ רֹאשׁוֹ וְאֵין רֹאשׁוֹ סוֹפוֹ.</p>\n<p>אֶלָּא בֹּא רְאֵה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לָדוּן אֶת הָעוֹלָם בְּרָעָב, אֵינוֹ נוֹתֵן דָּבָר זֶה לִידֵי הַכָּרוֹז, שֶׁהֲרֵי כָּל הַדִּינִים הָאֲחֵרִים שֶׁל הָעוֹלָם, הַכָּרוֹז מַכְרִיז עֲלֵיהֶם טֶרֶם שֶׁיָּבאוּ לָעוֹלָם, וְהַדִּין הַזֶּה לֹא נִתָּן לַכָּרוֹז, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְרִיז עָלָיו וְקוֹרֵא. זֶהוּ שֶׁכָּתוּב (מלכים ב ח) כִּי קָרָא ה' לָרָעָב. מֵאוֹתָהּ שָׁעָה נִפְקָדִים עַל הָעוֹלָם מְמֻנִּים אֲחֵרִים בִּפְקִידַת הָרָעָב (של השערים).</p>\n<p>וְאָסוּר לְאָדָם שֶׁיֵּשׁ לוֹ שּׁבַע לְהַרְאוֹת בְּעַצְמוֹ שּׁבַע, שֶׁהֲרֵי מַרְאֶה פְגָם לְמַעְלָה וּמַכְחִישׁ אֶת דְּבַר הַמֶּלֶךְ, וְכִבְיָכוֹל הֶעֱבִיר אֶת הַמְמֻנִּים שֶׁל הַמֶּלֶךְ מִמְּקוֹמָם. וְעַל כֵּן אָמַר יַעֲקֹב לְבָנָיו לָמָּה תִּתְרָאוּ, לָמָּה תַעֲשׂוּ פְגָם לְמַעְלָה וּלְמַטָּה וּלְהַכְחִישׁ אֶת דְּבַר הַמֶּלֶךְ וְכָל אוֹתָם הַמְמֻנִּים בַּכְּרִיזָה שֶׁלּוֹ.</p>\n<p>אֲבָל הִנֵּה שָׁמַעְתִּי כִּי יֶשׁ שֶׁבֶר בְּמִצְרָיִם רְדוּ שָׁמָּה, וְשָׁם הַרְאוּ אֶת עַצְמְכֶם בְּשּׁבַע, וְאַל תַּכְחִישׁוּ פָמַלְיָא שֶׁל מַעְלָה כָּאן. וּבא רְאֵה, כַּמָּה תְבוּאָה הָיְתָה לְיַעֲקֹב, וְלֹא רָצָה לִשְׁבֹּר אֶלָּא בְּתוֹךְ הַבָּאִים, כְּדֵי שֶׁלֹּא יִמָּצֵא פְגָם בְּמַעֲשֵׂהוּ.</p>"],[9522012204,"<p>עוֹד פָּתַח וְאָמַר, (ויקרא ט) וַיִּשָּׂא אַהֲרֹן אֶת יָדָו אֶל הָעָם וַיְבָרֲכֵם. וְשָׁנִינוּ, יָדוֹ כָּתוּב, שֶׁרָצָה לִזְקֹף יָמִין עַל שְׂמֹאל. וְלָמָּה? לְהַרְאוֹת מַעֲשֶׂה לְמַטָּה, כְּדֵי שֶׁיִּתְעוֹרֵר מַעֲשֶׂה לְמַעְלָה.</p>\n<p>כָּתוּב (שם כה) וְהַעֲבַרְתָּ שׁוֹפַר תְּרוּעָה בַּחֹדֶשׁ הַשְּׁבִעִי וְגוֹ'. לָמָּה שׁוֹפַר תְּרוּעָה? אֶלָּא שׁוֹפָר שֶׁמְּשַׁבֵּר שַׁלְשְׁלָאוֹת, שֶׁמְּשַׁבֵּר אֶת הַשִּׁלְטוֹן מִכָּל הָעֲבָדִים. וְצָרִיךְ לְהַרְאוֹת שׁוֹפָר שֶׁהוּא פָּשׁוּט, וְלֹא כָפוּף, לְהַרְאוֹת חֵרוּת לַכֹּל, שֶׁהֲרֵי הַיּוֹם גּוֹרֵם. וּבַכֹּל צָרִיךְ לְהַרְאוֹת מַעֲשֶׂה, וְעַל כֵּן שׁוֹפָר וְלֹא קֶרֶן, כְּדֵי לְהַרְאוֹת מִיהוּ הַמָּקוֹם שֶׁנִּקְרָא שׁוֹפָר.</p>\n<p>אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהֵם יוֹדְעִים לְהִדָּבֵק בַּמֶּלֶךְ הַקָּדוֹשׁ, וּלְעוֹרֵר כֹּחַ שֶׁלְּמַעְלָה, וּלְהַמְשִׁיךְ אֶת קְדֻשַּׁת רִבּוֹנָם עֲלֵיהֶם. מִשּׁוּם כָּךְ כָּתוּב, (דברים לג) אַשְׁרֶיךְ יִשְׂרָאֵל מִי כָמוֹךְ וְגוֹ'. (שם ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. הַקדָּמַת רַעיָּא מְהֵיּמְנָא</p>\n<p>וּשְׁמַרְתֶּם מִצְותַי וַעֲשִׂיתֶם אֹתָם וְגוֹ'. מִצְווֹתָיו שֶׁל רִבּוֹן הָעוֹלָם, הֲרֵי שָׁנִינוּ, שֶׁכָּתוּב וּשְׁמַרְתֶּם מִצְותַי וַעֲשִׂיתֶם אֹתָם. אִי שְׁמִירָה הֵם צְרִיכִים, לָמָּה מַעֲשֶׂה? וְעוֹד, כָּל מִצְווֹת הַתּוֹרָה הֵם בִּשְׁנֵי גְוָנִים שֶׁהֵם אֶחָד, זָכוֹר וְשָׁמוֹר. זָכוֹר לְזָכָר, וְשָׁמוֹר לִנְקֵבָה, וְכֻלָּם כְּלָל אֶחָד. אִם שָׁמוֹר לִנְקֵבָה, לָמָּה כָּתוּב וּשְׁמַרְתֶּם (את כל) מִצְותַי?</p>\n<p>אֶלָּא הַכֹּל בַּפָּסוּק הַזֶּה. וּשְׁמַרְתֶּם - זֶה שָׁמוֹר. וַעֲשִׂיתֶם - זֶה זָכוֹר, שֶׁהַכֹּל סוֹד אֶחָד. זְכִירָה זוֹהִי עֲשִׂיָּה. שֶׁהֲרֵי מִי שֶׁמַּזְכִּיר הַדָּבָר לְמַטָּה, מַתְקִין (עושים משם לאותו סוד שלמעלה, וכל מי שעושה דבר למטה) וְנַעֲשֶׂה אוֹתוֹ הַסּוֹד שֶׁלְּמַעְלָה. מִצְווֹת הַתּוֹרָה אֵלּוּ הֵן שֵׁשׁ מֵאוֹת וּשְׁלֹשׁ עֶשְׂרֵה מִצְווֹת, שֶׁהֵן כְּלָל שֶׁל זָכָר וּנְקֵבָה, וְהַכֹּל סוֹד אֶחָד.</p>"],[9522012205,"<p>וְלֹא תְחַלְּלוּ אֶת שֵׁם קָדְשִׁי וְנִקְדַּשְׁתִּי בְּתוֹךְ בְּנֵי יִשְׂרָאֵל וְגוֹ'. מִצְוָה זוֹ לְקַדֵּשׁ אוֹתוֹ בְּכָל יוֹם לְהַעֲלוֹת קְדֻשָּׁתוֹ מִמַּטָּה לְמַעְלָה, כְּמוֹ שֶׁהוּא קָדוֹשׁ לְמַעְלָה, עַד שֶׁעוֹלָה קְדֻשָּׁתוֹ לְאָבוֹת וּבָנִים. וְסוֹד זֶה, וְנִקְדַּשְׁתִּי בְּתוֹךְ בְּנֵי יִשְׂרָאֵל, מַעְלָה וּמַטָּה. מַעְלָה בְּשָׁלֹשׁ דְּרָגוֹת, לְמַטָּה בְּשָׁלֹשׁ דְּרָגוֹת.</p>\n<p>קְדֻשָּׁה זוֹ הֲרֵי בֵּאַרְנוּ בְּכַמָּה מְקוֹמוֹת, אֲבָל כְּמוֹ שֶׁיֵּשׁ קְדֻשָּׁה לְמַעְלָה עַל הַכֹּל, כָּךְ יֵשׁ קְדֻשָּׁה בָּאֶמְצַע, קְדֻשָּׁה לְמַטָּה. וְהַכֹּל בַּסּוֹד שֶׁלְּמַטָּה (בשלשה), קְדֻשָּׁה שֶׁלְּמַעְלָה לְמַעְלָה, בְּסוֹד אֶחָד. קְדֻשָּׁה בָּאֶמְצַע וּלְמַטָּה, שָׁלֹשׁ דְּרָגוֹת שֶׁהֵן אַחַת.</p>\n<p>קָדוֹשׁ הוּא צַד עֶלְיוֹן, שֶׁנִּמְצָא רֵאשִׁית לְכָל הַדְּרָגוֹת. וְאַף עַל גַּב שֶׁהוּא צַד טָמִיר וְנִקְרָא קֹדֶשׁ, מִשָּׁם הִתְפַּשְּׁטָה הִתְפַּשְּׁטוּת, שֶׁמְּאִירָה בִּשְׁבִיל אֶחָד דַּק וְנִסְתָּר תּוֹךְ הָאֶמְצַע. כֵּיוָן שֶׁמְּאִירָה הָאֶמְצָעִית, אָז נִרְשֶׁמֶת ו' אַחַת שֶׁמְּאִירָה בְּתוֹךְ הַקֹּדֶשׁ הַזֶּה, וְנִקְרֵאת קָדוֹשׁ. מֵהָאוֹר הַזֶּה מִתְפַּשֶּׁטֶת הִתְפַּשְּׁטוּת לְמַטָּה, הַסּוֹף שֶׁל כָּל הַדְּרָגוֹת. כֵּיוָן שֶׁמְּאִירָה בַּסּוֹף, אָז נִרְשֶׁמֶת בָּאוֹר ה' אַחַת, וְנִקְרֵאת קְדֻשָּׁה, וַהֲרֵי בֵּאַ רְנוּהָ.</p>\n<p>וּמַה שֶּׁנִּקְרָא קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, שֶׁהֲרֵי קֹדֶשׁ צָרִיךְ לוֹ, הַסּוֹד שֶׁל רֵאשִׁית (שהוא ראשית) הַכֹּל, הוֹאִיל וּמִשָּׁם נִמְצָא, וְאִם כָּךְ, לָמָּה נִקְרָא לְמַעְלָה קָדוֹשׁ, שֶׁהֲרֵי שָׁם לֹא נִמְצֵאת ו'?</p>\n<p>אֶלָּא הַסּוֹד כָּךְ הוּא וַדַּאי, וְיִשְׂרָאֵל מְקַדְּשִׁים לְמַטָּה כְּמוֹ שֶׁהַמַּלְאָכִים הָעֶלְיוֹנִים לְמַעְלָה, שֶׁכָּתוּב בָּהֶם (ישעיהו) וְקָרָא זֶה אֶל זֶה וְאָמַר קָדוֹשׁ. וְכֵיוָן שֶׁיִּשְׂרָאֵל מְקַדְּשִׁים, הֵם מַעֲלִים מִמַּטָּה לְמַעְלָה אֶת הַכָּבוֹד הָעֶלְיוֹן, עַד שֶׁמִּתְעַלֵּית ו', שֶׁהִיא סוֹד שֶׁל הַשָּׁמַיִם הָעֶלְיוֹנִים לְמַעְלָה. כֵּיוָן שֶׁאוֹתָם הַשָּׁמַיִם הִתְעַלּוּ לְמַעְלָה, מֵאִיר בָּהֶם אוֹתוֹ הַקֹּדֶשׁ, וְאָז נִקְרָא לְמַעְלָה קָדוֹשׁ. וְאַחַר כָּךְ מֵאִיר אוֹתוֹ אוֹר עֶלְיוֹן עַל הַכִּסֵּא, שֶׁהוּא שָׁמַיִם. וְאוֹתָם שָׁמַיִם שָׁבִים לִמְקוֹמָם, וְהִתְיַשְּׁבוּ בוֹ בְּאוֹתוֹ הָאוֹר, וְאָז נִקְרָא קָדוֹשׁ. אַחַר כָּךְ יוֹרֵד אוֹתוֹ הָאוֹר, עַד שֶׁנּוֹטֵל הַכֹּל צַדִּיק עֶלְיוֹן אֶחָד, הַדַּרְגָּה הַנִּכְבָּדָה לְקַדֵּשׁ הַכֹּל לְמַטָּה. כֵּיוָן שֶׁהוּא נוֹטֵל אֶת הַכֹּל, אָז נִקְרָא קָדוֹשׁ, וְזֶהוּ הַסּוֹד שֶׁל הַכֹּל.</p>\n<p>וּמִי שֶׁשָּׂם רְצוֹנוֹ בָּזֶה, עוֹשֶׂה יָפֶה. וּמִי שֶׁשָּׂם רְצוֹנוֹ בִּשְׁלֹשׁ הַדְּרָגוֹת שֶׁל הָאָבוֹת בִּכְלָל אֶחָד, לְיַחֵד אוֹתָם בְּתוֹךְ הַקְּדֻשָּׁה הַזּוֹ, אִם אֵינוֹ יָכוֹל לָשִׂים רְצוֹנוֹ יוֹתֵר, הוּא עוֹשֶׂה יָפֶה, וְהַכֹּל לְהוֹרִיד מִתּוֹךְ הַקְּדֻשָּׁה שֶׁלְּמַעְלָה לְמַטָּה. שֶׁכָּל אֶחָד יְקַדֵּשׁ אֶת עַצְמוֹ בַּקְּדֻשָּׁה הַזּוֹ וְלִשְׁמֹר אוֹתָהּ, לִפְרֹשׂ אֶת פְּרִישַׂת הַקְּדֻשָּׁה עָלָיו. וְסוֹד זֶה, וְנִקְדַּשְׁתִּי בְּתוֹךְ בְּנֵי יִשְׂרָאֵל - בָּרִאשׁוֹנָה, וְאַחַר כָּךְ - אֲנִי ה' מְקַדִּשְׁכֶם.</p>\n<p>בְּאֵיזְהִ מָקוֹם יְקַדֵּשׁ אָדָם אֶת עַצְמוֹ בְּתוֹךְ הַקְּדֻשָּׁה הַזּוֹ לְהַכְלִיל אֶת עַצְמוֹ בָּהּ? כְּשֶׁמַּגִּיעַ אָדָם לַשֵּׁם הַקָּדוֹשׁ ה' צְבָאוֹת, וְסוֹד זֶה - אֲנִי ה' מְקַדִּשְׁכֶם. זֶה מָצָאנוּ בַּסּוֹד שֶׁל סִפְרֵי הַקַּדְמוֹנִים, וְאָנוּ לֹא עוֹשִׂים כָּךְ, אֶלָּא אַחַר ה' צְבָאוֹת לְבַדּוֹ. וְאַחַר כָּךְ כְּשֶׁמַּגִּיעַ אָדָם לִמְלֹא כָל הָאָרֶץ כְּבוֹדוֹ, אָז יִכְלֹל אֶת עַצְמוֹ בְּאוֹתָהּ קְדֻשָּׁה, לְהִתְקַדֵּשׁ לְמַטָּה בְּתוֹךְ אוֹתוֹ הַכָּבוֹד שֶׁלְּמַטָּה, וְסוֹד זֶה - (שמות כט) וְנִקְדָּשׁ בִּכְבוֹדִי. וְאַחַר כָּךְ יַעֲשֶׂה בְּדֶרֶךְ פְּרָט, שֶׁיִּתְקַדֵּשׁ הַכֹּל. כְּמוֹ שֶׁאָנוּ עוֹשִׂים לְעֻמָּתָם שֶׁל הַמַּלְאָכִים הָעֶלְיוֹנִים, שֶׁאוֹמְרִים (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ, זֶה כָּבוֹד עֶלְיוֹן. וְאַחַר כָּךְ, (תהלים קמו) יִמְלֹךְ ה' לְעוֹלָם וְכוּ', זֶה הַכָּבוֹד שֶׁלְּמַטָּה.</p>\n<p>וּבְסִפְרוֹ שֶׁל רַב יֵיבָא סָבָא, קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ וְכוּ' - זוֹהִי הַקְּדֻשָּׁה שֶׁתִּתְקַדֵּשׁ תּוֹרָה שֶׁבִּכְתָב בִּכְלָל אֶחָד. וְאַחַר כָּךְ לְעֻמָּתָם בָּרוּךְ כְּבוֹד ה' - אֵלּוּ נְבִיאִים. וְאַחַר כָּךְ יִמְלֹךְ ה' לְעוֹלָם. סוֹד זֶה אָנוּ צְרִיכִים בִּקְדֻשָּׁה זוֹ, שֶׁתִּמָּצֵא שָׁם קְדֻשָּׁה וּבְרָכָה וּמַלְכוּת שֶׁיִּמָּצֵא הַכֹּל כְּאֶחָד. קְדֻשָּׁה, כְּמוֹ שֶׁנֶּאֱמַר קָדוֹשׁ. בְּרָכָה, בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. מַלְכוּת, יִמְלֹךְ ה' לְעוֹלָם. וְעַל כֵּן אָנוּ צְרִיכִים לְהַשְׁלִים אֶת הַכֹּל, וְעַל כֵּן יְכַוֵּן אָדָם וְיָשִׂים אֶת רְצוֹנוֹ בְּכָל יוֹם. (ע\"כ רעיא מהימנא).</p>"],[9522012206,"<p>דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵהֶם מוֹעֲדֵי ה' אֲשֶׁר תִּקְרְאוּ אֹתָם מִקְרָאֵי קֹדֶשׁ אֵלֶּה הֵם מוֹעֲדָי. רַבִּי יִצְחָק פָּתַח, (בראשית א) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם וְגוֹ'. שָׁנִינוּ, הָאוֹר שֶׁהָיָה בָּרִאשׁוֹנָה הָיָה מֵאִיר מִסּוֹף הָעוֹלָם עַד סוֹף הָעוֹלָם, כְּשֶׁהִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרְשָׁעִים שֶׁעֲתִידִים לַעֲמֹד בָּעוֹלָם, גָּנַז אוֹתוֹ לַצַּדִּיקִים לָעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב (איוב לח) וְיִמָּנַע מֵרְשָׁעִים אוֹרָם. וְכָתוּב (תהלים צז) אוֹר זָרֻעַ לַצַּדִּיק.</p>\n<p>בֹּא רְאֵה, וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם וְלַחֹשֶׁךְ קָרָא לָיְלָה. הֲרֵי שָׁנִינוּ, יְהִי אוֹר, אוֹר שֶׁכְּבָר הָיָה. וְכָאן, אִם תֹּאמַר אוֹר שֶׁהוּא יוֹם בִּלְבַדּוֹ, חָזַר וְאָמַר, וְלַחֹשֶׁךְ קָרָא לָיְלָה. אִם תֹּאמַר כָּל אֶחָד לְבַדּוֹ - חָזַר וְאָמַר, וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. שֶׁאֵין לַיְלָה בְּלִי יוֹם, וְאֵין יוֹם בְּלִי לַיְלָה. וְלֹא נִקְרָא אֶחָד אֶלָּא בְּזִוּוּג אֶחָד, וְהַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל נִקְרָא אֶחָד, וְזֶה בְּלִי זֶה לֹא נִקְרָא אֶחָד.</p>\n<p>בֹּא רְאֵה, מִשּׁוּם שֶׁכְּנֶסֶת יִשְׂרָאֵל עַכְשָׁו בַּגָּלוּת, כִּבְיָכוֹל לֹא נִקְרָא אֶחָד. וּמָתַי נִקְרָא אֶחָד? בְּשָׁעָה שֶׁיֵּצְאוּ יִשְׂרָאֵל מִן הַגָּלוּת, וּכְנֶסֶת יִשְׂרָאֵל תַּחֲזֹר לִמְקוֹמָהּ לְהִזְדַּוֵּג עִם הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. (משום כך ויהי ערב ויהי בקר יום אחד) וְזֶה בְּלִי זֶה לֹא נִקְרָא אֶחָד.</p>\n<p>בֹּא רְאֵה, מוֹעֲדֵי ה' אֲשֶׁר תִּקְרְאוּ אֹתָם וְגוֹ'. לְזַמֵּן אֶת הַכֹּל לְמָקוֹם אֶחָד וְשֶׁיִּמָּצֵא הַכֹּל בִּשְׁלֵמוּת בְּסוֹד שֶׁל אֶחָד, וְלִהְיוֹת יִשְׂרָאֵל (בזווג אחד) לְמַטָּה גּוֹי אֶחָד בָּאָרֶץ. נַנִּיחַ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עִם כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרָא אֶחָד - יִשְׂרָאֵל לְמַטָּה שֶׁהֵם מְזֻמָּנִים כְּמוֹ שֶׁלְּמַעְלָה, בַּמֶּה יִהְיוּ נִקְרָאִים אֶחָד?</p>\n<p>אֶלָּא בִּירוּשָׁלַיִם שֶׁל מַטָּה יִקָּרְאוּ יִשְׂרָאֵל אֶחָד. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שמואל ב ז) גּוֹי אֶחָד בָּאָרֶץ. וַדַּאי, בָּאָרֶץ הֵם גּוֹי אֶחָד, עִמָּהּ הֵם נִקְרָאִים אֶחָד, וְאֵינָם לְבַדָּם. שֶׁהֲרֵי וּמִי כְעַמְּךְ יִשְׂרָאֵל גּוֹי אֶחָד מַסְפִּיק לוֹ, אֲבָל לֹא נִקְרְאוּ אֶחָד אֶלָּא בָּאָרֶץ, בַּזִּוּוּג שֶׁל הָאָרֶץ הַזּוֹ כְּמוֹ שֶׁלְּמַעְלָה. וּמִשּׁוּם כָּךְ הַכֹּל קָשׁוּר זֶה עִם זֶה בְּזִוּוּג אֶחָד. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל. שֵׁשֶׁת יָמִים תֵּעָשֶׂה מְלָאכָה נֶאֱמַר, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>--</p>"],[9522012207,"<p>אֵלֶּה מוֹעֲדֵי ה' מִקְרָאֵי קֹדֶשׁ אֲשֶׁר תִּקְרְאוּ אֹתָם בְּמוֹעֲדָם. רַבִּי יִצְחָק פָּתַח, (תהלים כז) לְךְ אָמַר לִבִּי בַּקְּשׁוּ פָנָי אֶת פָּנֶיךְ ה' אֲבַקֵּשׁ. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּ הַחֲבֵרִים בְּכַמָּה מְקוֹמוֹת, אֲבָל הַפָּסוּק הַזֶּה כָּךְ נֶאֱמַר, לְךְ אָמַר לִבִּי, דָּוִד הַמֶּלֶךְ אָמַר אֶת זֶה בִּשְׁבִיל כְּנֶסֶת יִשְׂרָאֵל כְּנֶגֶד הַמֶּלֶךְ הַקָּדוֹשׁ. וּמָה אָמַר? לְךְ אָמַר לִבִּי, בִּשְׁבִילְךְ אָמַר לִבִּי לִבְנֵי הָעוֹלָם, וְהִזְהִיר אוֹתָם לִבִּי, שֶׁהוּא אָחוּז בּוֹ, שֶׁאֶת זֶה בִּשְׁבִיל הַמֶּלֶךְ הָעֶלְיוֹן הוּא אָמַר. בַּקְּשׁוּ פָנָי, אֵלּוּ עַטְרוֹת הַמֶּלֶךְ שֶׁהוּא אָחוּז בָּהֶן, וְהֵם בּוֹ. הֵם שְׁמוֹ, וְהוּא וּשְׁמוֹ דָּבָר אֶחָד הוּא. מִשּׁוּם כָּךְ אָמַר דָּוִד, אֶת פָּנֶיךְ ה' אֲבַקֵּשׁ, כְּמוֹ שֶׁנֶּאֱמַר (שם קה) דִּרְשׁוּ ה' וְעֻזּוֹ בַּקְּשׁוּ פָנָיו תָּמִיד.</p>\n<p>בֹּא רְאֵה, רָאוּי הוּא דָּוִד הַמֶּלֶךְ לוֹמַר שִׁירָה בִּשְׁבִיל כְּנֶסֶת יִשְׂרָאֵל יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם, וְלוֹמַר דְּבָרִים שֶׁל כְּנֶסֶת יִשְׂרָאֵל לַמֶּלֶךְ, מִשּׁוּם שֶׁהוּא אָחוּז בָּהּ.</p>"],[9522012208,"<p>דָּבָר אַחֵר לְךְ אָמַר לִבִּי בַּקְּשׁוּ פָנָי - בִּשְׁבִילְךְ אָמַר לִבִּי לִבְנֵי הָעוֹלָם בַּקְּשׁוּ פָנָי, (את פניך ה' אבקש) אֵלּוּ זְמַנִּים וְחַגִּים שֶׁכֻּלָּם הִזְמִין לָהֶם לְמָקוֹם שֶׁנִּקְרָא קֹדֶשׁ, כְּדֵי לְעַטֵּר אוֹתָם כָּל אֶחָד וְאֶחָד בְּיוֹמוֹ, כָּל אֶחָד וְאֶחָד בִּזְמַנּוֹ, וְיִשְׁאֲבוּ כֻלָּם מֵאוֹתוֹ עֹמֶק הָעֳמָקִים שֶׁהַנְּחָלִים וְהַמַּעְיָנוֹת יוֹצְאִים מִשָּׁם. מִשּׁוּם כָּךְ כָּתוּב מִקְרָאֵי קֹדֶשׁ, מְזֻמָּנִים הֵם לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא קֹדֶשׁ, לְהִתְעַטֵּר בּוֹ וּלְהִשָּׁאֵב בּוֹ, כְּדֵי שֶׁיִּתְקַדְּשׁוּ כֻלָּם כְּאֶחָד, וְתִמָּצֵא בָהֶם שִׂמְחָה.</p>\n<p>רַבִּי אַבָּא אָמַר, מִקְרָאֵי קֹדֶשׁ - זְמַנִּים שֶׁל קֹדֶשׁ. וּכְשֶׁמִּזֶּה הֵם מְזֻמָּנִים, הֵם מְזֻמָּנִים מִן הַנַּחַל שֶׁשּׁוֹפֵעַ וְיוֹצֵא. לְמֶלֶךְ שֶׁהִזְמִין בְּנֵי אָדָם לִסְעוּדָתוֹ, עִטֵּר לִפְנֵיהֶם בְּכָל מִינֵי מַאֲכָלִים שֶׁבָּעוֹלָם, פָּתַח לָהֶם חָבִית יַיִן, יָפֶה בְּרֵיחַ וְיָפֶה לְמִשְׁתֶּה. שֶׁכָּךְ רָאוּי, מִי שֶׁמַּזְמִין - לְמַאֲכָל וּלְמִשְׁתֶּה הוּא מַזְמִין. כָּךְ מִקְרָאֵי קֹדֶשׁ - כֵּיוָן שֶׁהֵם מְזֻמָּנִים לִסְעוּדַת הַמֶּלֶךְ, מְזֻמָּנִים הֵם לְיַיִן טוֹב וְיָפֶה שֶׁמְּשֻׁמָּר. (כמו שנאמר (שיר השירים א) כי טובים דדיך מיין) וְעַל כֵּן כָּתוּב מִקְרָאֵי קֹדֶשׁ.</p>\n<p>אֲשֶׁר תִּקְרְאוּ אֹתָם בְּמוֹעֲדָם, כָּתוּב (שמות כב) וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי. יִשְׂרָאֵל לְמַטָּה נִקְרָאִים אַנְשֵׁי קֹדֶשׁ. כֵּיוָן שֶׁהֵם מְזֻמָּנִים מִקֹּדֶשׁ שֶׁלְּמַעְלָה, אַתֶּם אַנְשֵׁי קֹדֶשׁ לְמַטָּה הַזְמִינוּ אוֹתָם, אָז הַתְקִינוּ סְעוּדָה וְשִׂמְחוּ, שֶׁהֲרֵי לָכֶם רָאוּי זֶה, מִשּׁוּם שֶׁאַתֶּם נִקְרָאִים אַנְשֵׁי קֹדֶשׁ, וְיִהְיוּ כֻלָּם מְזֻמָּנִים בְּכָל הַצְּדָדִים שֶׁל קֹדֶשׁ לְמַעְלָה וּלְמַטָּה.</p>\n<p>דָּבָר אַחֵר אֵלֶּה מוֹעֲדֵי ה', מַה זֶּה מוֹעֲדֵי ה'? רַבִּי שִׁמְעוֹן אָמַר, הֵם מֵה', שֶׁבּוֹ נִקְשְׁרוּ מִמַּטָּה לְמַעְלָה וּמִמַּעְלָה לְמַטָּה. כֻּלָּם קְשׁוּרִים בּוֹ, וְכֻלָּם מִתְעַטְּרִים (ומזמנים) (ומתאחדים) לְהִקָּשֵׁר קֶשֶׁר אֶחָד בַּקֶּשֶׁר שֶׁל הַמֶּלֶךְ. מָה הַטַּעַם? כְּמוֹ שֶׁמֶּלֶךְ יוֹרֵשׁ אֶת הָאָב וְהָאֵם, וְאָחוּז בְּאוֹתוֹ קֹדֶשׁ וּמִתְעַטֵּר בָּהֶם. (בשביל) כָּךְ כָּל אוֹתָם שֶׁאֲחוּזִים בַּמֶּלֶךְ צְרִיכִים לְהִזְדַּמֵּן לְאוֹתוֹ מָקוֹם עֶלְיוֹן שֶׁנִּקְרָא קֹדֶשׁ, כְּדֵי שֶׁכֻּלָּם יִתְאַחֲדוּ כְאֶחָד (למלך). וְעַל כֵּן נִקְרָא מוֹעֲדֵי ה', וְאַחַר כָּךְ מִקְרָאֵי קֹדֶשׁ, שֶׁהֲרֵי בָּהֶם מִתְעַטֵּר בַּמֶּלֶךְ.</p>\n<p>אֲשֶׁר תִּקְרְאוּ אֹתָם בְּמוֹעֲדָם, שְׁנֵי חֲלָקִים יֵשׁ לְיִשְׂרָאֵל בָּהֶם. אִם מִצַּד הַמֶּלֶךְ - יֵשׁ לְיִשְׂרָאֵל חֵלֶק עֶלְיוֹן בּוֹ, שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם וְגוֹ', (שם לב) כִּי חֵלֶק ה' עַמּוֹ. וְאִם מִצַּד הָעֶלְיוֹן שֶׁל קֹדֶשׁ - יֵשׁ לְיִשְׂרָאֵל חֵלֶק עֶלְיוֹן בּוֹ, שֶׁכָּתוּב וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי, וְכָתוּב (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה'. וְעַל כֵּן רָאוּי לָכֶם לְזַמֵּן אוֹתָם וּלְתַקֵּן לַכֹּהֲנִים שִׂמְחָה וּסְעוּדָה וְלִשְׂמֹחַ בָּהֶם.</p>\n<p>וּמִי שֶׁמְּזַמֵּן לְאַחֵר (לאורח), צָרִיךְ לְהַרְאוֹת לוֹ שִׂמְחָה וּפָנִים מְאִירוֹת לְעַטֵּר (לשמר) אֶת אוֹרְחוֹ שֶׁל אוֹתוֹ הָאוֹרֵחַ. לְמֶלֶךְ שֶׁהִזְמִין אוֹרֵחַ יָקָר, אָמַר לִבְנֵי הֵיכָלוֹ: כָּל שְׁאָר הַיָּמִים הֱיִיתֶם כָּל אֶחָד בְּבֵיתוֹ, זֶה עוֹשֶׂה עֲבוֹדָתוֹ, וְזֶה הוֹלֵךְ עִם סְחוֹרָתוֹ, וְזֶה הוֹלֵךְ בְּשָׂדֵהוּ. פְּרָט לְאוֹתוֹ יוֹם שֶׁלִּי, שֶׁכֻּלָּם מִתְעוֹרְרִים (מזמנים) לְשִׂמְחָתִי. עַכְשָׁו הִזְמַנְתִּי אוֹרֵחַ עֶלְיוֹן וְיָקָר, אֵינִי רוֹצֶה שֶׁתִּשְׁתַּדְּלוּ בַעֲבוֹדָה, וְלֹא בִסְחוֹרָה, וְלֹא בְמִדְבָּרִיּוֹת, אֶלָּא כֻּלָּם הִזְדַּמְּנוּ, כְּמוֹ שֶׁאוֹתוֹ יוֹם שֶׁלִּי, וְהַתְקִינוּ עַצְמְכֶם לְקַבֵּל אֶת אוֹתוֹ אוֹרֵחַ בְּפָנִים מְאִירוֹת, בְּשִׂמְחָה וּבְתִשְׁבַּחַת. הַתְקִינוּ לוֹ סְעוּדָה נִכְבָּדָה כְּדֵי שֶׁיִּהְיֶה מִזְדַּמֵּן אֵלַי בְּכָל הַצְּדָדִים.</p>\n<p>כָּךָ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל: בָּנַי, כָּל שְׁאָר הַיָּמִים אַתֶּם מִשְׁתַּדְּלִים בַּעֲבוֹדָה וּבִסְחוֹרָה, פְּרָט לְאוֹתוֹ יוֹם שֶׁלִּי. עַכְשָׁו אוֹרֵחַ עֶלְיוֹן וְיָקָר הִזְמַנְתִּי, אַתֶּם קַבְּלוּ אוֹתוֹ בְּפָנִים מְאִירוֹת, הַזְמִינוּ אוֹתוֹ, תַּקְּנוּ לוֹ סְעוּדוֹת עֶלְיוֹנוֹת, שֻׁלְחָנוֹת עֲרוּכִים, כְּמוֹ שֶׁאוֹתוֹ הַיּוֹם שֶׁלִּי. מִשּׁוּם כָּךְ, תִּקְרְאוּ אֹתָם בְּמוֹעֲדָם.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁיִּשְׂרָאֵל לְמַטָּה שְׂמֵחִים בַּמּוֹעֲדִים הַלָּלוּ וּמְשַׁבְּחִים שֶׁבַח לַקָּדוֹשׁ בָּרוּךְ הוּא, עוֹרְכִים שֻׁלְחָנוֹת, מְתַקְּנִים עַצְמָם בִּכְלֵי נִכְבָּדִים, הַמַּלְאָכִים הָעֶלְיוֹנִים אוֹמְרִים: מַה טִּיבָם שֶׁל יִשְׂרָאֵל בְּכָךְ? אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא, אוֹרֵחַ עֶלְיוֹן יֵשׁ לָהֶם בַּיּוֹם הַזֶּה. אוֹמְרִים: וְלֹא שֶׁלְּךְ הוּא, מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא קֹדֶשׁ? אוֹמֵר לָהֶם: וְכִי יִשְׂרָאֵל אֵינָם קֹדֶשׁ, וְנִקְרָאִים קֹדֶשׁ?! לָהֶם רָאוּי לְהַזְמִין אֶת הָאוֹרֵחַ שֶׁלִּי, אֶחָד מֵהַצַּד שֶׁלִּי, שֶׁהֲרֵי הֵם דְּבֵקִים בִּי, וְאֶחָד מִצַּד שֶׁל קֹדֶשׁ, שֶׁכָּתוּב (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה'. הוֹאִיל וְיִשְׂרָאֵל נִקְרָאִים קֹדֶשׁ, וַדַּאי שֶׁהוּא אוֹרֵחַ שֶׁלָּהֶם, מִשּׁוּם שֶׁהַזְמָנַת הָאוֹרֵחַ הַזֶּה הִיא מִקֹּדֶשׁ, שֶׁכָּתוּב מִקְרָאֵי קֹדֶשׁ. פָּתְחוּ כֻלָּם וְאָמְרוּ: (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ.</p>\n<p>שְׁלֹשָה הֵם מְזֻמָּנִים מִקֹּדֶשׁ, וְלֹא יוֹתֵר: חַג הַמַּצּוֹת, וְחַג הַשָּׁבוּעוֹת, וְחַג הַסֻּכּוֹת. אָמַר לוֹ רַבִּי אַבָּא, וְכִי שַׁבָּת אֵינָהּ מִקֹּדֶשׁ מְזֻמֶּנֶת? אָמַר לוֹ, לֹא, בִּשְׁנֵי צְדָדִים, אֶחָד - שֶׁהוּא וַדַּאי נִקְרָא קֹדֶשׁ, שֶׁכָּתוּב (שמות לא) וּשְׁמַרְתֶּם אֶת הַשַּׁבָּת כִּי קֹדֶשׁ הִיא לָכֶם. וְאֶחָד - שֶׁשַּׁבָּת אֵינָהּ זְמִינָה, שֶׁהֲרֵי יְרֻשָּׁתוֹ הִיא וַדַּאי. יְרֻשָּׁה שֶׁל קֹדֶשׁ הוּא יוֹרֵשׁ וְאֵינוֹ מְזֻמָּן, וְעַל כֵּן כֻּלָּם מְזֻמָּנִים בַּקֹּדֶשׁ, וּמִתְקַשְּׁרִים בְּשַׁבָּת וּמִתְעַטְּרִים בּוֹ. בּוֹ. בָּזֶה הַיּוֹם הַשְּׁבִיעִי מִתְעַטֵּר בּוֹ, וְעַל כֵּן שַׁבָּת אֵינָהּ מְזֻמֶּנֶת.</p>\n<p>לְבֵן שֶׁנִּכְנַס לְבֵית אָבִיו וְאִמּוֹ וְאָכַל וְשָׁתָה בְּשָׁעָה שֶׁהוּא רוֹצֶה. לְמֶלֶךְ שֶׁהָיָה לוֹ בֵּן יָחִיד, חֲבִיב נַפְשׁוֹ, נָתַן לוֹ שׁוֹשְׁבִין לִשְׁמֹר אוֹתוֹ וּלְהִתְחַבֵּר עִמּוֹ. אָמַר הַמֶּלֶךְ, נָאֶה הוּא לְהַזְמִין אֶת הַשּׁוֹשְׁבִינִים הַלָּלוּ שֶׁל בְּנִי וּלְהַרְאוֹת אֶת הַכָּבוֹד וְהַחֲבִיבוּת שֶׁלִּי עִמָּם. הִזְמִין אֶת הַשּׁוֹשְׁבִינִים הַלָּלוּ. הַבֵּן לֹא רָאוּי לְזַמֵּן, אֶלָּא לְהִכָּנֵס וְלֶאֱכֹל וְלִשְׁתּוֹת בְּבֵית אָבִיו בְּשָׁעָה שֶׁהוּא רוֹצֶה. זֶהוּ שֶׁכָּתוּב (שם טו) מִי כָמֹכָה בָּאֵלִם ה' מִי כָּמֹכָה נֶאְדָּר בַּקֹּדֶשׁ. נֶאְדָּר בַּקֹּדֶשׁ וַדַּאי, כְּבֵן שֶׁהִתְתַּקֵּן (שהתחזק) בְּאָבִיו נֶאְדָּר בַּקֹּדֶשׁ, וְלֹא מְזֻמָּן מֵהַקֹּדֶשׁ.</p>\n<p>שֵׁשֶׁת יָמִים תֵּעָשֶׂה מְלָאכָה. שֵׁשֶׁת יָמִים מַה מַּעֲשֵׂיהֶם? אָמַר רַבִּי יוֹסֵי, כָּתוּב כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וְלֹא כָתוּב בְּשֵׁשֶׁת, וַהֲרֵי פֵּרְשׁוּהָ, וְכָל יוֹם וָיוֹם עוֹשֶׂה מַעֲשֵׂהוּ, וְנִקְרָאִים יְמֵי מְלָאכָה.</p>\n<p>אָמַר רַבִּי יִצְחָק, אִם כָּךְ, לָמָּה נִקְרְאוּ שֵׁשֶׁת יְמֵי חֹל? לָמָּה חֹל? אָמַר רַבִּי יוֹסֵי, עַכְשָׁו מִתְנַהֵג הָעוֹלָם עַל יְדֵי הַשְּׁלוּחִים שֶׁלָּהֶם, מִשּׁוּם כָּךְ נִקְרָאִים יְמֵי חֹל.</p>\n<p>רַבִּי חִיָּיא אָמַר, מִשּׁוּם שֶׁמֻּתָּר לַעֲשׂוֹת בָּהֶם עֲבוֹדָה, וּמִשּׁוּם כָּךְ לֹא נִקְרָאִים קֹדֶשׁ, וּמִי שֶׁלֹּא נִקְרָאִים קֹדֶשׁ, נִקְרָאִים חֹל, וְעַל כֵּן הִתְקִינוּ הַחֲבֵרִים בַּהַבְדָּלָה, בֵּין קֹדֶשׁ לְחֹל. מָה הַהַבְדָּלָה כָּאן? אֶלָּא קֹדֶשׁ הוּא דָּבָר בְּעַצְמוֹ, וּמַתְחִילוֹת מִמֶּנּוּ הָאוֹתִיּוֹת. וְעַל כֵּן אֵלּוּ לְמַעֲשֶׂה, וְאֵלּוּ לִשְׁמֹר. וּמָתַי נִמְצֵאת בָּהֶם שְׁמִירָה? כְּשֶׁמְּזֻמָּנִים מִקֹּדֶשׁ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, הַשִּׂמְחָה וְהַשְּׁמִירָה שֶׁל יוֹם הַשַּׁבָּת הֵם עַל הַכֹּל, וּמִשּׁוּם שֶׁהַיּוֹם הַזֶּה מִתְעַטֵּר בְּאַבָּא וּבְאִמָּא, וְנוֹסֶפֶת קְדֻשָּׁה עַל קְדֻשָּׁתוֹ, מַה שֶּׁאֵין כֵּן בִּשְׁאָר הַיָּמִים, שֶׁהֲרֵי הוּא קֹדֶשׁ וּמִתְעַטֵּר בְּקֹדֶשׁ, וּמוֹסִיף קְדֻשָּׁה עַל קְדֻשָּׁתוֹ, מִשּׁוּם כָּךְ הַיּוֹם הַזֶּה הוּא שִׂמְחַת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, כֻּלָּם שְׂמֵחִים בּוֹ, מְמַלֵּא בְרָכוֹת בְּכָל הָעוֹלָמוֹת. כֻּלָּם נִתְקְנוּ (נזונו) מִמֶּנּוּ. בַּיּוֹם הַזֶּה מְנוּחַת עֶלְיוֹנִים וְתַחְתּוֹנִים. בַּיּוֹם הַזֶּה מְנוּחַת הָרְשָׁעִים בַּגֵּיהִנֹּם.</p>\n<p>לְמֶלֶךְ שֶׁעָשָׂה הִלּוּלָא לִבְנוֹ הַיָּחִיד, עִטֵּר אוֹתוֹ בַּעֲטָרָה עֶלְיוֹנָה, מִנָּה אוֹתוֹ הַמֶּלֶךְ עַל הַכֹּל. בַּיּוֹם הַזֶּה שִׂמְחַת הַכֹּל. שׁוֹטֵר אֶחָד שֶׁהָיָה מֻפְקָד עַל דִּינָם שֶׁל בְּנֵי אָדָם, הָיוּ בְיָדוֹ גְּבָרִים שֶׁצְּרִיכִים הֲרִיגָה, וּגְבָרִים שֶׁהָיוּ צְרִיכִים לְהַלְקָאָה. בִּשְׁבִיל כְּבוֹד הַיּוֹם הַזֶּה שֶׁל שִׂמְחַת הַמֶּלֶךְ עוֹזֵב אֶת דִּינָיו, וְשׁוֹמֵר אֶת שִׂמְחַת הַמֶּלֶךְ.</p>\n<p>כָּךָ אוֹתוֹ הַיּוֹם, הִלּוּלַת הַמֶּלֶךְ עִם הַגְּבִירָה, שִׂמְחַת הָאָב וְהָאֵם עָלָיו, שִׂמְחַת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים. בְּשִׂמְחַת הַמֶּלֶךְ כֻּלָּם שְׂמֵחִים, וְלֹא יִצְטַעֲרוּ בוֹ. עַל זֶה כָּתוּב (ישעיה נח) וְקָרָאתָ לַשַּׁבָּת עֹנֶג. מַה זֶּה עֹנֶג? עֹנֶג לֹא נִמְצָא אֶלָּא בְּמָקוֹם שֶׁשּׁוֹרֶה הַקֹּדֶשׁ הָעֶלְיוֹן, כְּמוֹ שֶׁנֶּאֱמַר אָז תִּתְעַנַּג עַל ה'. שֶׁהֲרֵי עֹנֶג הוּא עַל ה'. וְהַיּוֹם הַזֶּה שֶׁהוּא הִלּוּלַת הַמֶּלֶךְ, מִתְעַטֵּר בְּאוֹתָהּ עֲטָרָה שֶׁל עֹנֶג. זֶהוּ שֶׁכָּתוּב וְקָרָאתָ לַשַּׁבָּת עֹנֶג, מַה שֶּׁאֵין נִמְצָא כֵּן בִּשְׁאָר הַיָּמִים.</p>\n<p>בַּיּוֹם הַזֶּה שָׁלֹשׁ סְעוּדוֹת צְרִיכִים בְּנֵי הַמֶּלֶךְ לְזַמֵּן וְלַעֲרֹךְ שֻׁלְחָנוֹת בִּשְׁבִיל כְּבוֹד הַמֶּלֶךְ, כְּמוֹ שֶׁבֵּאַרְנוּ. וּכְשֶׁמִּזְדַּמֵּן בּוֹ חַג אוֹ זְמַן, לֹא יְסַדֵּר אָדָם שְׁנֵי שֻׁלְחָנוֹת בְּכָל סְעוּדָה, אֶחָד לְשַׁבָּת וְאֶחָד לָאוֹרֵחַ, מִשּׁוּם שֶׁכָּתוּב (שמואל ב ט) עַל שֻׁלְחַן הַמֶּלֶךְ תָּמִיד הוּא אֹכֵל, הַהֲנָאָה הִיא בְּשֻׁלְחַן הַמֶּלֶךְ לְאוֹתוֹ הָאוֹרֵחַ שֶׁבָּא אֵלָיו. וְעַל כֵּן צָרִיךְ אָדָם לַעֲרֹךְ שֻׁלְחָן שָׁלֵם לַמֶּלֶךְ, וְהוּא נוֹתֵן מִמֶּנּוּ לָאוֹרֵחַ.</p>"],[9522012209,"<p>אָמַר רַבִּי אֶלְעָזָר, הַסְּעוּדָה הַשְּׁלִישִׁית שֶׁל שַׁבָּת, כְּשֶׁנִּקְרָה בָּהּ אוֹרֵחַ, הַאִם עוֹזְבִים אוֹתָהּ אוֹ לֹא עוֹזְבִים אוֹתָהּ? אִם לֹא עוֹזְבִים אוֹתָהּ, נִמְצָא הָאוֹרֵחַ דָּחוּי מִשֻּׁלְחַן הַמֶּלֶךְ. וְאִם עוֹזְבִים אוֹתָהּ, נִמְצָא פְגָם בְּשֻׁלְחַן הַמֶּלֶךְ.</p>\n<p>אָמַר לוֹ רַבִּי שִׁמְעוֹן אָבִיו, לְמֶלֶךְ שֶׁנִּקְרָה לוֹ אוֹרֵחַ, וְלָקַח מַאֲכָל מִלְּפָנָיו וְהֶעֱלָהוּ לָאוֹרֵחַ. נִמְצָא, אַף עַל גַּב שֶׁהַמֶּלֶךְ לֹא אָכַל עִמּוֹ - מִמַּאֲכַל הַמֶּלֶךְ הוּא אוֹכֵל, וְהַמֶּלֶךְ נָתַן לוֹ לֶאֱכֹל. וְכָל זֶה מִשּׁוּם שֶׁהוּא אוֹרֵחַ הַמֶּלֶךְ. וּבְבֵית רַב הַמְנוּנָא סָבָא לֹא חוֹשְׁשִׁים לְאוֹרֵחַ בְּשָׁעָה זוֹ, וְאַחַר כָּךְ עוֹרְכִים שֻׁלְחָן לָאוֹרֵחַ.</p>\n<p>בַּיּוֹם הַזֶּה אָסוּר דִּבּוּר, זֶהוּ שֶׁכָּתוּב (ישעיה נח) מִמְּצֹא חֶפְצְךְ וְדַבֵּר דָּבָר. וְשָׁנִינוּ, חֶפְצְךְ כָּתוּב, מִשּׁוּם שֶׁבְּיוֹם זֶה נִקְשֶׁרֶת בּוֹ כָּל הָאֱמוּנָה.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, וְאֵיךְ אָנוּ עוֹשִׂים שֶׁלֹּא לַעֲרֹךְ (לסלק) סְעוּדַת הַמֶּלֶךְ לָאוֹרֵחַ, שֶׁהֲרֵי אַרְבָּעָה עָשָׂר שֶׁחָל לִהְיוֹת בְּשַׁבָּת, עוֹלָה סְעוּדַת הַמֶּלֶךְ לְפֶסַח, אַף עַל גַּב שֶׁאֵינוֹ הָאוֹרֵחַ שֶׁלּוֹ.</p>\n<p>אָמַר לוֹ, כָּךְ אֲנִי אוֹמֵר, שֶׁאִם הוּא הָאוֹרֵחַ שֶׁלּוֹ - (כל אותו יום) יָכוֹל לְהַעֲלוֹת אוֹתוֹ, וְאִם לֹא - אֵינוֹ מַעֲלֶה אוֹתוֹ. וְאִם נֹאמַר שֶׁי\"ד שֶׁחָל לִהְיוֹת בְּשַׁבָּת, נִדְחֵית סְעוּדַת הַמֶּלֶךְ מִלִּפְנֵי סְעוּדַת הַפֶּסַח - שׁוֹנֶה הַפֶּסַח, שֶׁסְּעוּדַת שַׁבָּת נִדְחֵית מִכַּמָּה גְוָנִים: אֶחָד בִּשְׁבִיל מַצּוֹת וּמְרוֹרִים, שֶׁצָּרִיךְ שֶׁאָדָם יִהְיֶה תָאֵב. וְאֶחָד מִשּׁוּם פֶּסַח. וַהֲרֵי לֶחֶם אֵינוֹ נִמְצָא מִשֵּׁשׁ שָׁעוֹת וָמַעְלָה, שֶׁעֲרִיכַת הַשֻּׁלְחָן בְּלִי לֶחֶם אֵינָהּ עֲרִיכָה.</p>\n<p>וְאִם תֹּאמַר בְּיַיִן - בְּיַיִן מֻתָּר, מִשּׁוּם שֶׁהַלֵּב תָּאֵב (שגורר. ס\"א שגובר). אֲבָל מִיָּמַי הִשְׁתַּדַּלְתִּי שֶׁלֹּא בִטַּלְתִּי סְעוּדַת שַׁבָּת, אֲפִלּוּ אוֹתָם יָמִים שֶׁנִּמְצָא בּוֹ. בַּיּוֹם הַזֶּה שְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים מִתְבָּרֵךְ, וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים, וְהַיּוֹם הַזֶּה הוּא הַקִּשּׁוּר שֶׁל הַתּוֹרָה.</p>\n<p>אָמַר רַבִּי אַבָּא, כָּךְ הָיָה עוֹשֶׂה רַבִּי שִׁמְעוֹן בִּזְמַן שֶׁעָלְתָה סְעוּדַת שַׁבָּת, עוֹרֵךְ שֻׁלְחָנוֹ וּמִשְׁתַּדֵּל בְּמַעֲשֵׂה מֶרְכָּבָה, וְהָיָה אוֹמֵר: הֲרֵי סְעוּדַת הַמֶּלֶךְ שֶׁיָּבא לֶאֱכֹל אֶצְלִי. מִשּׁוּם כָּךְ נִמְצֵאת שַׁבָּת עֲדִיפָה בַּכֹּל מִכָּל הַזְּמַנִּים וְהַחַגִּים, וְנִקְרֵאת קֹדֶשׁ וְלֹא מִקְרָא קֹדֶשׁ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּל הַמּוֹעֲדִים קוֹרְאִים בָּהֶם מִקְרָאֵי קֹדֶשׁ. אֲבָל יוֹצְאִים רֹאשׁ הַשָּׁנָה וְיוֹם כִּפּוּר שֶׁלֹּא נִמְצֵאת בָּהֶם שִׂמְחָה, שֶׁהֲרֵי הֵם דִּין הֵם, אֲבָל אֵלּוּ הַשְּׁלֹשָׁה מְזֻמָּנִים מֵהַקֹּדֶשׁ לְשִׂמְחַת הַכֹּל, לְהִשְׁתַּעֲשֵׁעַ בָּהֶם בַּקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב (דברים יב) וּשְׂמַחְתֶּם לִפְנֵי ה' אֱלֹהֵיכֶם, וְכָתוּב (שם כז) וְשָׂמַחְתָּ לִפְנֵי ה' אֱלֹהֶיךְ. בְּיוֹם הַשַּׁבָּת הַזֶּה נִשְׁכָּח כָּל הַצַּעַר וְכָל הָרֹגֶז וְכָל הַדֹּחַק מִכָּל הָעוֹלָם, מִשּׁוּם שֶׁהוּא יוֹם הִלּוּלַת הַמֶּלֶךְ, שֶׁנְּשָׁמוֹת מִתּוֹסְפוֹת, כְּמוֹ שֶׁהָעוֹלָם הַבָּא.</p>\n<p>אָמַר רַבִּי יִצְחָק לְרַבִּי יְהוּדָה, כָּתוּב (שמות כ) זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ, וְשָׁנִינוּ, זָכְרֵהוּ עַל הַיַּיִן. לָמָּה עַל הַיַּיִן? אָמַר לוֹ, מִשּׁוּם שֶׁיַּיִן הוּא שִׂמְחַת הַתּוֹרָה, וְיֵינָהּ שֶׁל תּוֹרָה הוּא שִׂמְחַת הַכֹּל. וְהַיַּיִן הַזֶּה מְעַטֵּר אֶת הַמֶּלֶךְ בְּעַטְרוֹתָיו. זֶהוּ שֶׁכָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ. וְשָׁנִינוּ, בַּכֹּל צָרִיךְ לְהַרְאוֹת אָדָם מַעֲשֶׂה. שֶׁלֹּא נִמְצֵאת קְדֻשָּׁה אֶלָּא בְּיַיִן, כְּמוֹ שֶׁנֶּאֱמַר (שיר א) כִּי טוֹבִים דֹּדֶיךְ מִיָּיִן, מִיַּיִן הֵם טוֹבִים, נַזְכִּירָה דדֶיךְ מִיַּיִן. וְעַל כֵּן קְדֻשָּׁה שֶׁל שַׁבָּת בְּיַיִן, וַהֲרֵי פֵּרְשׁוּהָ, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522012210,"<p>וּבַחֹדֶשׁ הָרִאשׁוֹן בְּאַרְבָּעָה עָשָׂר יוֹם לַחֹדֶשׁ וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (שם ה) אֲנִי יְשֵׁנָה וְלִבִּי עֵר קוֹל דּוֹדִי דּוֹפֵק וְגוֹ'. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, אֲנִי יְשֵׁנָה - בְּגָלוּת מִצְרַיִם, שֶׁהָיוּ בָנַי בְּשִׁעְבּוּד שֶׁל קֹשִׁי. וְלִבִּי עֵר - לִשְׁמֹר אוֹתָם שֶׁלֹּא יִכְלוּ בַגָּלוּת. קוֹל דּוֹדִי דוֹפֵק - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאָמַר (שמות ג) וָאֶזְכֹּר אֶת בְּרִיתִי.</p>\n<p>פִּתְחִי לִי פֶּתַח כְּפִתְחוֹ שֶׁל מַחַט, וַאֲנִי אֶפְתַּח לָכֶם שְׁעָרִים עֶלְיוֹנִים. פִּתְחִי לִי אֲחֹתִי, שֶׁהֲרֵי הַפֶּתַח לְהַכְנִיס אוֹתִי הוּא בָּךְ, שֶׁלֹּא יִכָּנְסוּ אֶצְלִי בָּנַי אֶלָּא בָּךְ, אַתְּ הוּא הַפֶּתַח לְהַכְנִיס אוֹתִי (בך). אִם אַתְּ לֹא תִפְתְּחִי פִתְחֵךְ, הֲרֵי אֲנִי סָגוּר, שֶׁלֹּא יִמְצְאוּ אוֹתִי. מִשּׁוּם כָּךְ פִּתְחִי לִי. פִּתְחִי לִי וַדַּאי. וְעַל כֵּן אָמַר דָּוִד, כְּשֶׁרָצָה לְהִכָּנֵס לַמֶּלֶךְ, אָמַר (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבא בָם אוֹדֶה יָהּ. זֶה הַשַּׁעַר לַה', זֶהוּ וַדַּאי הַפֶּתַח לְהִכָּנֵס לַמֶּלֶךְ. זֶה הַשַּׁעַר לַה', לִמְצֹא אוֹתוֹ וּלְהִדָּבֵק בּוֹ, וְעַל כֵּן פִּתְחִי לִי אֲחֹתִי רַעְיָתִי שֶׁרֹאשִׁי וְגוֹ'. כְּדֵי לְהִזְדַּוֵּג עִמְּךְ, וְלִהְיוֹת עִמְּךְ בְּשָׁלוֹם לְעוֹלָמִים.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה הוֹרֵג אֶת בְּכוֹרֵי מִצְרַיִם, כָּל אוֹתָם שֶׁהָרַג בַּחֲצוֹת הַלַּיְלָה וְהוֹרִיד דְּרָגוֹת מִמַּעְלָה לְמַטָּה, בְּאוֹתָהּ שָׁעָה נִכְנְסוּ יִשְׂרָאֵל בַּקִּיּוּם שֶׁל הָאוֹת הַקָּדוֹשׁ, נִמּוֹלוּ וְהִשְׁתַּתְּפוּ עִם כְּנֶסֶת יִשְׂרָאֵל, וְנֶאֶחְזוּ בָהּ. אָז אוֹתוֹ הַדָּם הֶרְאוּ אוֹתוֹ עַל הַפֶּתַח. וּשְׁנֵי דָמִים הָיוּ - אֶחָד שֶׁל הַפֶּסַח, וְאֶחָד הַדָּם שֶׁנִּמּוֹלוּ. וְהָיָה רָשׁוּם עַל הַפֶּתַח רֹשֶׁם הָאֱמוּנָה, אֶחָד כָּאן וְאֶחָד כָּאן וְאֶחָד בֵּינֵיהֶם, וַהֲרֵי נֶאֱמַר (שמות יב), וְנָתְנוּ עַל שְׁתֵּי הַמְּזוּזוֹת וְעַל הַמַּשְׁקוֹף, כְּדֵי לְהַרְאוֹת אֱמוּנָה.</p>\n<p>וּבְאַרְבָּעָה (ובחמשה) עָשָׂר, הֲרֵי נֶאֱמַר, שֶׁהֲרֵי אָז מְבַטְּלִים חָמֵץ וּשְׂאוֹר, וְהִתְעַלּוּ יִשְׂרָאֵל מֵרָשׁוּת הָאַחֶרֶת, וְנֶעֶקְרוּ מִמֶּנָּה וְנֶאֶחְזוּ בְּמַצָּה, הַקֶּשֶׁר הַקָּדוֹשׁ. אַחַר שֶׁנִּמּוֹלוּ נִכְנְסוּ בָהּ, עַד שֶׁנִּפְרְעוּ וְהִתְגַּלָּה הָרֹשֶׁם שֶׁלָּהֶם, וְאָז נָתַן לָהֶם קֶשֶׁר בְּמָקוֹם עֶלְיוֹן, בַּקֶּשֶׁר שֶׁל הָאֱמוּנָה, בְּמָקוֹם שֶׁכָּתוּב (שמות טז) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם, מִן הַשָּׁמָיִם דַּוְקָא, וַהֲרֵי פֵּרְשׁוּהָ.</p>"],[9522012211,"<p>בֹּא רְאֵה, בְּאַרְבָּעָה (בחמשה) עָשָׂר, בְּשָׁעָה שֶׁזִּוּוּג הַלְּבָנָה נִמְצָא בִשְׁלֵמוּת עִם הַשֶּׁמֶשׁ, וְהַכְּתָרִים הַתַּחְתּוֹנִים לֹא נִמְצָאִים כָּל כָּךְ בָּעוֹלָם, שֶׁהֲרֵי בְּחִדּוּשׁ הַלְּבָנָה נִמְצָאִים מִינִים רָעִים, וּמִתְעוֹרְרִים לְהִתְפַּשֵּׁט בָּעוֹלָם. וּבְשָׁעָה שֶׁהַזִּוּוּג שֶׁל הַלְּבָנָה נִמְצָא בְּאוֹר הַשֶּׁמֶשׁ בִּשְׁלֵמוּת, כֻּלָּם מִתְכַּנְּסִים לְמָקוֹם אֶחָד, וְהַקְּדֻשּׁוֹת שֶׁל הַמֶּלֶךְ מִתְעוֹרְרוֹת. אָז כָּתוּב, (שם יב) לֵיל שִׁמֻּרִים הוּא לַה', שֶׁהֲרֵי הַזִּוּוּג הַקָּדוֹשׁ נִמְצָא, וְהוּא שִׁמּוּרִים בַּכֹּל.</p>\n<p>רַבִּי אָחָא אָמַר, מִשּׁוּם כָּךְ תִּקּוּן שֶׁל הַכֹּל (של הכלה) הוּא בְּאוֹתוֹ יוֹם, וּבַלַּיְלָה נִמְצָא הַיִּשּׁוּב שֶׁל הַבַּיִת. אוֹי לְאוֹתָם שֶׁאֵינָם מִבְּנֵי הַבַּיִת, כְּשֶׁבָּאִים לְהִזְדַּוֵּג הַתּוֹרָה (האריות) יַחַד. אוֹי לְאוֹתָם שֶׁלֹּא נוֹדָעִים אֶצְלָם. מִשּׁוּם כָּךְ יִשְׂרָאֵל הַקְּדוֹשִׁים מְתַקְּנִים לָהֶם הַבַּיִת כָּל אוֹתוֹ הַיּוֹם, וְעַל יָדָם נִכְנָסִים מִי שֶׁנִּכְנָסִים, וְהֵם שְׂמֵחִים וּמְזַמְּרִים שְׁנֵיהֶם. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>אָמַר רַבִּי יוֹסֵי, לָמָּה לָנוּ לְהַטְרִיחַ כָּל זֶה, מִקְרָא שָׁלֵם הוּא, שֶׁהֲרֵי בַּלַּיְלָה הַזֶּה הַזִּוּוּג הָעֶלְיוֹן הַקָּדוֹשׁ מִתְעוֹרֵר וְנִמְצָא. זֶהוּ שֶׁכָּתוּב הוּא הַלַּיְלָה הַזֶּה לַה' שִׁמֻּרִים. מַה זֶּה שִׁמֻּרִים? שְׁנַיִם, הַזִּוּוּג שֶׁל הַלְּבָנָה עִם הַשֶּׁמֶשׁ. לְכָל בְּנֵי יִשְׂרָאֵל לְדרֹתָם, שֶׁהֲרֵי מִכָּאן וָהָלְאָה נִתְאַחֲדוּ וְנִקְשְׁרוּ בַקֶּשֶׁר שֶׁל הַשֵּׁם הַקָּדוֹשׁ וְיָצְאוּ מֵרָשׁוּת אַחֶרֶת. מִשּׁוּם כָּךְ בְּאַרְבָּעָה עָשָׂר מְתַקְּנִים אֶת עַצְמָם, וּמְבַעֲרִים חָמֵץ מִבֵּינֵיהֶם וְנִכְנָסִים לָרָשׁוּת הַקְּדוֹשָׁה, וְאָז מִתְעַטְּרִים חָתָן וְכַלָּה בְּעַטְרוֹת הָאֵם הָעֶלְיוֹנָה, וְצָרִיךְ אָדָם לְהַרְאוֹת אֶת עַצְמוֹ בֶּן חוֹרִין.</p>"],[9522012212,"<p>אָמַר רַבִּי יוֹסֵי, אַרְבַּע הַכּוֹסוֹת הַלָּלוּ שֶׁל אוֹתוֹ הַלַּיְלָה לָמָּה? אָמַר רַבִּי אַבָּא, הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, כְּנֶגֶד אַרְבַּע גְּאֻלּוֹת. אֲבָל יָפֶה הוּא בְּסִפְרוֹ שֶׁל רַב יֵיסָא סָבָא, שֶׁאָמַר, הוֹאִיל וְהַזִּוּוּג הַקָּדוֹשׁ נִמְצָא בַּלַּיְלָה הַזֶּה בְּכָל הַצְּדָדִים, וְהַזִּוּוּג הוּא בְּאַרְבָּעָה קְשָׁרִים, שֶׁהֵם אַרְבַּע דְּרָגוֹת, וְלֹא נִפְרָדִים זֶה מִזֶּה, כְּשֶׁהַזִּוּוּג הַזֶּה נִמְצָא, וְאָנוּ בְשִׂמְחָתָם מִתְעוֹרְרִים, מִשּׁוּם שֶׁהֲרֵי זָכִינוּ בָהֶם, שֶׁמִּי שֶׁאוֹחֵז בָּזֶה - זוֹכֶה בַכֹּל. וְעַל כֵּן הִשְׁתַּנָּה הַלַּיְלָה הַזֶּה מִכָּל שְׁאָר הַלֵּילוֹת, וּצְרִיכִים לַעֲשׂות שֵׁם בַּכּל וְלִשְׂמחַ בַּלַּיְלָה הַזֶּה, מִשּׁוּם שֶׁשִּׂמְחָה הִיא לְמַעְלָה וּלְמַטָּה.</p>\n<p>וְעוֹד אָמַר, שֶׁאַרְבַּע אֵלּוּ אַרְבַּע גְּאֻלּוֹת קוֹרְאִים לָהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁהַדַּרְגָּה הָאַחֲרוֹנָה הַזּוֹ נִקְרֵאת גּוֹאֵל, הַמַּלְאָךְ הַגּוֹאֵל. וְלֹא נִקְרֵאת גּוֹאֵל אֶלָּא עַל יְדֵי דַרְגָּה אַחֶרֶת עֶלְיוֹנָה שֶׁעוֹמֶדֶת עָלֶיהָ וּמְאִירָה לָהּ, וְזוֹ לֹא מוֹצִיאָה לָהּ אוֹר, אֶלָּא בִּשְׁתֵּי (באותן דרגות) הַדְּרָגוֹת הַלָּלוּ שֶׁעָלָיו. נִמְצָא שֶׁאַרְבַּע אֵלּוּ הֵן אַרְבַּע גְּאֻלּוֹת.</p>"],[9522012213,"<p>רַבִּי יְהוּדָה שָׁאַל אֶת רַבִּי אַבָּא, הֲרֵי כָּתוּב (זהו שכתוב) שִׁבְעַת יָמִים שְׂאוֹר לֹא יִמָּצֵא בְּבָתֵּיכֶם, וְשִׂמְחָה הִיא כָּל שִׁבְעָה, לָמָּה לֹא נִשְׁלָם הַלֵּל כָּל שִׁבְעַת הַיָּמִים כְּמוֹ בְסֻכּוֹת, שֶׁנִּמְצָא שְׁמוֹנָה יָמִים הַלֵּל, בִּשְׁלֵמוּת שֶׁל שִׂמְחָה כָּל יוֹם וָיוֹם?</p>\n<p>אָמַר לוֹ, יָפֶה אָמַרְתָּ, אֲבָל יָדוּעַ הוּא, שֶׁהֲרֵי כָּאן לֹא נִקְשְׁרוּ יִשְׂרָאֵל כָּל כָּךְ בַּכֹּל כְּמוֹ שֶׁנִּקְשְׁרוּ אַחַר כָּךְ. מִשּׁוּם כָּךְ בַּלַּיְלָה הַזֶּה, שֶׁזִּוּוּג נִמְצָא (בכל אותן דרגות עליונות) וְשִׂמְחַת הַכֹּל נִמְצֵאת, וְיִשְׂרָאֵל נִקְשְׁרוּ בְּאוֹתָהּ שִׂמְחָה, עוֹשִׂים שְׁלֵמוּת, וְהַהַלֵּל נִשְׁלָם. (אבל באותן דרגות עליונות) אַחַר כָּךְ, אַף עַל גַּב שֶׁכֻּלָּם נִמְצָאִים, עַד כָּעֵת יִשְׂרָאֵל לֹא נִקְשְׁרוּ בָהֶם, וְלֹא נִפְרְעוּ לְגַלּוֹת אֶת הָרֹשֶׁם הַקָּדוֹשׁ, וְלֹא קִבְּלוּ תוֹרָה, וְלֹא נִכְנְסוּ בְּמַה שֶּׁנִּכְנְסוּ אַחַר כָּךְ. מִשּׁוּם כָּךְ בַּסֻּכּוֹת שְׁלֵמוּת הַכֹּל נִמְצֵאת בּוֹ וְשִׂמְחָה שֶׁל הַכֹּל יוֹתֵר, אֲבָל כָּאן עַד עַכְשָׁו לֹא זָכוּ, וְלֹא נִמְצֵאת בּוֹ שְׁלֵמוּת כָּל כָּךְ, אַף עַל גַּב שֶׁנִּמְצָאִים כָּל הַשִּׁבְעָה אֵינוֹ בְהִתְגַּלּוּת, וְיִשְׂרָאֵל טֶרֶם נִקְשְׁרוּ בָהֶם כָּרָאוּי.</p>\n<p>וְעַל כֵּן שִׂמְחַת הַכֹּל וּשְׁלֵמוּת הַהַלֵּל בַּלַּיְלָה הַזֶּה, מִשּׁוּם אוֹתוֹ הַחֵלֶק שֶׁנִּקְשְׁרוּ בוֹ. מָה הַטַּעַם? שֶׁכֵּיוָן שֶׁנִּמְצָא בְּאוֹתוֹ הַלַּיְלָה זִוּוּג, כָּל הַקֶּשֶׁר שֶׁל הַכֹּל נִמְצָא בַּצַּד שֶׁל הַזִּוּוּג, וְלֹא בַּצַּד שֶׁל יִשְׂרָאֵל. שֶׁכַּאֲשֶׁר זִוּוּג נִמְצָא בָהּ, נִמְצָאוֹת שְׁתֵּי (שלש) הַדְּרָגוֹת הַלָּלוּ שֶׁעוֹמְדוֹת עָלֶיהָ. וּכְשֶׁאֵלֶּה נִמְצָאוֹת, הֲרֵי כָּל הַגּוּף נִמְצָא בָהֶם, וְאָז שְׁלֵמוּת הַכֹּל, וְשִׂמְחָה מִן הַכֹּל, וְהַהַלֵּל נִשְׁלָם, שֶׁהֲרֵי אָז מִתְעַטֶּרֶת הַלְּבָנָה בַּכֹּל, אֲבָל לֹא אַחַר כָּךְ, שֶׁכָּל יוֹם וָיוֹם נִמְצָאִים, וְיִשְׂרָאֵל טֶרֶם זָכוּ בָהֶם, הֲרֵי אֵין הַהַלֵּל שָׁלֵם כְּמוֹ בִּזְמַנִּים אֲחֵרִים.</p>"],[9522012214,"<p>אָמַר לוֹ רַבִּי יְהוּדָה, יָפֶה הוּא, וְכָךְ הוּא וַדַּאי, וַהֲרֵי פַּעַם אַחֶרֶת שָׁמַעְתִּי אוֹתוֹ בַּגָּוֶן הַזֶּה, וְשָׁכַחְתִּי אֶת הַדְּבָרִים. עַכְשָׁו דָּבָר אַחֵר אֲנִי רוֹצֶה לָדַעַת, הֲרֵי רָאִינוּ בְּפֶסַח ז' וּבְסֻכּוֹת ז', וּשְׁלֵמוּת הַשִּׂמְחָה בְּיוֹם אַחֵר. בְּשָׁבוּעוֹת לָמָּה נִמְצְאוּ בוֹ ז' יָמִים, וַהֲרֵי כָּאן רְאוּיִים יוֹתֵר מֵהַכֹּל?</p>\n<p>פָּתַח וְאָמַר, (שמואל ב ז) וּמִי כְעַמְּךְ כְּיִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ. וְכִי מַה שּׁוֹנֶה כָּאן שֶׁיִּשְׂרָאֵל נִקְרְאוּ אֶחָד יוֹתֵר מִמָּקוֹם אַחֵר? אֶלָּא כֵּיוָן שֶׁהַשֶּׁבַח שֶׁל יִשְׂרָאֵל בָּא לְפָרֵשׁ, קָרָא לָהֶם אֶחָד, שֶׁהֲרֵי בְּכָל מָקוֹם הַשֶּׁבַח שֶׁל יִשְׂרָאֵל הוּא אֶחָד. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל הַקֶּשֶׁר שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים נִמְצָא בַּמָּקוֹם הַזֶּה שֶׁנִּקְרָא יִשְׂרָאֵל. שֶׁנִּקְשָׁר בְּמַה שֶּׁלְּמַעְלָה, וְנִקְשָׁר בְּמַה שֶּׁלְּמַטָּה, וְנִקְשָׁר בִּכְנֶסֶת יִשְׂרָאֵל. וְעַל כֵּן הַכֹּל נִקְרָא אֶחָד. וּבַמָּקוֹם הַזֶּה נוֹדַעַת הָאֱמוּנָה, וְהַקֶּשֶׁר הַשָּׁלֵם, וְהַיִּחוּד הָעֶלְיוֹן הַקָּדוֹשׁ.</p>\n<p>וְעַל כֵּן הַיּוֹם הַזֶּה הוּא קֶשֶׁר הָאֱמוּנָה, הַקֶּשֶׁר שֶׁל הַכֹּל. וְכָתוּב (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ, עֵץ הוּא שֶׁנִּקְרָא אֶחָד. וְעַל כֵּן, מִשּׁוּם שֶׁהֵם נִקְשָׁרִים בַּמָּקוֹם הַזֶּה, נִקְרָא כָּךְ. וְעֵץ חַיִּים הוּא וַדַּאי אֶחָד נִקְרָא, מִשּׁוּם שֶׁהַכֹּל נִקְשָׁר בּוֹ, וְהַיּוֹם (והשם) שֶׁלּוֹ וַדַּאי אֶחָד, קֶשֶׁר שֶׁל הַכֹּל וְאֶמְצַע שֶׁל הַכֹּל.</p>\n<p>זֶהוּ שֶׁכָּתוּב (בראשית ב) וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן, בְּתוֹךְ מַמָּשׁ, בָּאֶמְצַע, וְאָחוּז בְּכָל הַצְּדָדִים וְנִקְשָׁר בּוֹ. וְעַל כֵּן פֶּסַח וְסֻכּוֹת, וְהוּא בָּאֶמְצַע. מִשּׁוּם שֶׁהוּא הָאֶמְצַע שֶׁל הַכֹּל, וְזֶהוּ הַשֶּׁבַח שֶׁל הַתּוֹרָה בַּיּוֹם הַזֶּה, וְלֹא יוֹתֵר. שֶׁבַח הָאֱמוּנָה וְקֶשֶׁר שֶׁל הַכֹּל. אָמַר רַבִּי יְהוּדָה, בָּרוּךְ הָרַחֲמָן שֶׁשָּׁאַלְתִּי וְזָכִיתִי לַדְּבָרִים הַלָּלוּ.</p>\n<p>אָמַר רַבִּי יִצְחָק, שִׂמְחָה וְשִׁירָה עֲתִידִים יִשְׂרָאֵל לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ הַשֶּׁבַח שֶׁמְּשַׁבְּחִים יִשְׂרָאֵל בְּלֵיל הַפֶּסַח, שֶׁכְּנֶסֶת יִשְׂרָאֵל מִתְקַדֶּשֶׁת בִּקְדֻשַּׁת הַמֶּלֶךְ. זֶהוּ שֶׁכָּתוּב (ישעיה ל) הַשִּׁיר יִהְיֶה לָכֶם כְּלֵיל הִתְקַדֶּשׁ חָג. כְּלֵיל הִתְקַדֶּשׁ חָג דַּוְקָא. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522012215,"<p>וּבְיוֹם הַבִּכּוּרִים בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה לַה' בְּשָׁבֻעֹתֵיכֶם מִקְרָא קֹדֶשׁ יִהְיֶה לָכֶם וְגוֹ' (במדברכח). רַבִּי שִׁמְעוֹן פָּתַח, (דברי הימים א טז) אָז יְרַנְּנוּ עֲצֵי הַיָּעַר מִלִּפְנֵי ה' כִּי בָא לִשְׁפּוֹט אֶת הָאָרֶץ. אַשְׁרֵי חֶלְקָם שֶׁל אוֹתָם הַמִּשְׁתַּדְּלִים בַּתּוֹרָה יוֹמָם וָלַיְלָה, שֶׁיּוֹדְעִים אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְנֶאֱחָזִים בִּשְׁמוֹ (כל יום). אוֹי לְאוֹתָם שֶׁלֹּא מִשְׁתַּדְּלִים בַּתּוֹרָה, שֶׁהֲרֵי אֵין לָהֶם חֵלֶק בַּשֵּׁם הַקָּדוֹשׁ, וְלֹא נֶאֱחָזִים בּוֹ, לֹא בָּעוֹלָם הַזֶּה וְלֹא בָּעוֹלָם הַבָּא. מִי שֶׁזּוֹכֶה בָּעוֹלָם הַזֶּה, זוֹכֶה בָּעוֹלָם הַבָּא. שֶׁכָּךְ שָׁנִינוּ, (שיר ז) דּוֹבֵב שִׂפְתֵי יְשֵׁנִים, אַף עַל גַּב שֶׁהֵם בְּאוֹתוֹ עוֹלָם, שִׂפְתוֹתֵיהֶם מְרַחֲשׁוֹת שָׁם תּוֹרָה.</p>\n<p>בֹּא רְאֵה, עַד עַכְשָׁו הִקְרִיבוּ יִשְׂרָאֵל תְּבוּאַת הָאָרֶץ, תְּבוּאַת הָאָרֶץ וַדַּאי, וְהִתְעַסְּקוּ בָהּ וְנִקְשְׁרוּ בְּאוֹתוֹ קֶשֶׁר. וְאַף עַל גַּב שֶׁהַדִּין נִמְצָא, נִמְצָא בּוֹ דִּין בְּשָׁלוֹם (שהעולם התנהג בו). וְהִקְרִיבוּ שְׂעוֹרִים, מִשּׁוּם שֶׁהוּא רִאשׁוֹן מִכָּל שְׁאָר הַתְּבוּאָה, וּמַקְרִיבִים מֵהָרִאשׁוֹן וְלֹא מֵאוֹתוֹ שֶׁמִּתְאַחֵר, שֶׁהֲרֵי הָאֲחִיזָה הָרִאשׁוֹנָה שֶׁיִּשְׂרָאֵל נֶאֶחְזוּ בַּקָּדוֹשׁ בָּרוּךְ הוּא הִיא כָּאן. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲנִי נָתַתִּי לָכֶם מָן בַּמִּדְבָּר מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא שָׁמַיִם, שֶׁכָּתוּב (שמות טז) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם, וְאַתֶּם מַקְרִיבִים לְפָנַי שְׂעוֹרִים.</p>\n<p>וְסוֹד הַדָּבָר - זֹּאת תּוֹרַת הַקְּנָאֹת, חָסֵר. אַזְהָרָה לִנְשׁוֹת הָעוֹלָם שֶׁלֹּא יִסְטוּ תַּחַת בַּעְלֵיהֶן. וְאִם לֹא, אָז קֶמַח שְׂעֹרִים עָתִיד לְהִקָּרֵב. וּמֵהַדָּבָר הַזֶּה נוֹדָע דָּבָר אַחֵר. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁהֲרֵי כְּנֶסֶת יִשְׂרָאֵל לֹא מְשַׁקֶּרֶת בַּמֶּלֶךְ הַקָּדוֹשׁ לְעוֹלָמִים. כְּנֶסֶת יִשְׂרָאֵל תְּמֵהָה, (במדבר ה) אֲשֶׁר תִּשְׂטֶה אִשָּׁה תַּחַת אִישָׁהּ?! מִשּׁוּם כָּךְ דִּין הָאִשָּׁה הַזּוֹ מִמְּקוֹמָהּ הִיא בָאָה. וּמִי הוּא מְקוֹמָהּ? אוֹתָהּ שֶׁכָּתוּב בָּהּ (משלי לא) אֵשֶׁת חַיִל מִי יִמְצָא וְרָחוֹק מִפְּנִינִים מִכְרָהּ. (שם יב) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ.</p>\n<p>וְאוֹתוֹ קֶמַח שְׂעוֹרִים שֶׁמְּבִיאָה אוֹתָהּ אִשָּׁה, נִקְרָא מִנְחַת קְנָאֹת, חָסֵר. כָּךְ נִקְרֵאת כְּנֶסֶת יִשְׂרָאֵל. וְעַל כֵּן כָּתוּב בְּפִנְחָס, תַּחַת אֲשֶׁר קִנֵּא לֵאלֹהָיו, שֶׁקִּנְאָה כָּאן נֶאֱחֶזֶת. שֶׁמִּי שֶׁמְּשַׁקֵּר בַּבְּרִית הַזּוֹ, מִתְעוֹרֶרֶת עָלָיו קִנְאָה, וְלָכֵן קַנָּאִים פּוֹגְעִים בּוֹ. בּא רְאֵה, קֶמַח שְׂעֹרִים, הָעֹמֶר הַזֶּה, שֶׁכֵּיוָן שֶׁהָיָה מַגִּיעַ לְרֵחַיִם שֶׁל גְּרוּסוֹת, מְפִיקִים מִמֶּנּוּ עִשָּׂרוֹן מְנֻפֶּה בִּשְׁלֹשׁ עֶשְׂרֵה נָפָה.</p>\n<p>וְזְהִ שֶׁבַע שַׁבָּתוֹת תְּמִימוֹת. אַחַר שֶׁעוֹלוֹת שֶׁבַע הַשַּׁבָּתוֹת הַלָּלוּ, בָּא הַמֶּלֶךְ הַקָּדוֹשׁ לְהִזְדַּוֵּג עִם כְּנֶסֶת יִשְׂרָאֵל, וְנִתְּנָה הַתּוֹרָה. וְאָז הִתְעַטֵּר הַמֶּלֶךְ בְּיִחוּד שָׁלֵם, וְנִמְצָא אֶחָד לְמַעְלָה וּלְמַטָּה. וּכְשֶׁמִּתְעוֹרֵר הַמֶּלֶךְ הַקָּדוֹשׁ וּמַגִּיעַ זְמַן הַתּוֹרָה, כָּל אוֹתָם הָאִילָנוֹת שֶׁמְּבַכְּרִים אֶת הַפֵּרוֹת שֶׁלָּהֶם, מַעֲלִים שִׁירָה. וּמַה הֵם אוֹמְרִים בְּשָׁעָה שֶׁלּוֹקְטִים אוֹתָם? פּוֹתְחִים וְאוֹמְרִים, (תהלים קג) ה' בַּשָּׁמַיִם הֵכִין כִּסְאוֹ וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה. (שם לו) ה' בְּהַשָּׁמַיִם חַסְדֶּךְ. וְכָתוּב (ישעיה נה) וְכָל עֲצֵי הַשָּׂדֶה יִמְחֲאוּ כָף.</p>"],[9522012216,"<p>עוֹד פָּתַח וְאָמַר, (תהלים צח) מִזְמוֹר שִׁירוּ לַה' שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה. שִׁיר חָדָשׁ הוּא נִקְרָא. מִשּׁוּם כָּךְ בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה. שָׁם מִנְחַת קְנָאֹת, כָּאן מִנְחָה חֲדָשָׁה. חֲדָשָׁה, שֶׁחִדּוּשׁ הַכֹּל (הכלה) יֵשׁ כָּאן. קֶשֶׁר שֶׁל הַכֹּל שֶׁל מַעְלָה וּמַטָּה, קֶשֶׁר הָאֱמוּנָה, וְלָכֵן יַעֲקֹב הַשָּׁלֵם הִתְעַטֵּר בְּעַטְרוֹתָיו, וְנִתְּנָה הַתּוֹרָה.</p>\n<p>וּכְשֶׁמַּגִּיעִים הַבִּכּוּרִים לַכֹּהֵן, הָיָה צָרִיךְ אָדָם לוֹמַר וּלְפָרֵשׁ דְּבָרִים עַל אוֹתוֹ הָעֵץ שֶׁבָּאָרֶץ, שֶׁנִּשְׁלָם כְּמוֹ שֶׁלְּמַעְלָה בִּשְׁנֵים עָשָׂר תְּחוּמִים, בְּשִׁבְעִים עֲנָפִים, וְצָרִיךְ לְאַבֵּד אֶת לָבָן הָאֲרַמִּי, שֶׁבִּגְלָלוֹ נִפְגַּם הָעוֹלָם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִצִּיל אוֹתוֹ וְהִתְעַטֵּר בְּדִינָיו (בבניו), כְּמוֹ שֶׁבֵּאַרְנוּ. מִשּׁוּם שֶׁאוֹתוֹ הָעֵץ, שֶׁכָּל קֶשֶׁר הָאֱמוּנָה תָּלוּי בּוֹ, וְעַל כֵּן נִקְרָא מִנְחָה חֲדָשָׁה. מָה הַטַּעַם? מִשּׁוּם שֶׁהִיא שִׂמְחַת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים וְשִׂמְחַת הַלְּבָנָה. וּבְכָל זְמַן שֶׁל הַלְּבָנָה, הוּא קֶשֶׁר הָאֱמוּנָה וְשִׂמְחָתָהּ (של הלבנה).</p>\n<p>לְמֶלֶךָ שֶׁהָיוּ לוֹ בָּנִים וּבַת אַחַת, הִתְקִין סְעוּדָה לְכָל הַבָּנִים, לֹא נִמְצְאָה אוֹתָהּ הַבַּת עַל הַשֻּׁלְחָן. כְּשֶׁבָּאָה, אָמְרָה לַמֶּלֶךְ: אֲדוֹנִי, אֶת כָּל אַחַי הִזְמַנְתָּ וְנָתַתָּ לְכָל אֶחָד כֵּלִים יְדוּעִים, וְלִי לֹא נָתַתָּ חֵלֶק בֵּינֵיהֶם. אָמַר לָהּ: חַיַּיִךְ בִּתִּי, הַכְּלִי שֶׁלָּךְ יִמָּצֵא עַל אֶחָד פִּי שְׁנַיִם, הֲרֵי כֻּלָּם יִתְּנוּ לָךְ מֵחֶלְקָם. נִמְצָא לְאַחַר בְּיָדֶיהָ חֲלָקִים, עַל כָּל אֶחָד פִּי שְׁנַיִם מֵהַכֹּל. כָּךְ כְּנֶסֶת יִשְׂרָאֵל, מֵהַכֹּל נָטְלָה חֲלָקִים, וְעַל כֵּן נִקְרֵאת כַּלָּה כְּלוּלָה, כְּכַלָּה שֶׁכֻּלָּם מַזְמִינִים לָהּ כֵּלִים וַחֲלָקִים וְתַכְשִׁיטִים. כָּךְ הִיא כְּנֶסֶת יִשְׂרָאֵל, הַחִדּוּשׁ שֶׁלָּהּ (שמחתה) בַּכֹּל, וְכֻלָּם נוֹתְנִים לָהּ חֲלָקִים וְכֵלִים.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ נִמְצָא בְּעַטְרוֹתָיו, זוֹ שִׂמְחָתָהּ שֶׁל כְּנֶסֶת יִשְׂרָאֵל. וּכְשֶׁתּוֹרָה נִתְּנָה, הִתְעַטְּרָה כְּנֶסֶת יִשְׂרָאֵל בַּעֲטָרוֹת עֶלְיוֹנוֹת, וּמִשּׁוּם שֶׁכָּל קֶשֶׁר הָאֱמוּנָה נִקְשָׁר בָּעֵץ הַזֶּה, נִקְרָא יוֹם אֶחָד, שֶׁכָּתוּב (זכריה יד) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה'. יוֹם אֶחָד וַדַּאי, שֶׁכְּנֶסֶת יִשְׂרָאֵל יוֹם אֶחָד בַּקֶּשֶׁר שֶׁלְּמַעְלָה.</p>\n<p>הַקֶּשֶׁר שֶׁלְּמַעְלָה - הָרֹאשׁ וְהַגֻּלְגֹּלֶת וְהַמֹּחִין. קֶשֶׁר אַחֵר - שְׁתֵּי זְרוֹעוֹת וְגוּף, שֶׁאֲחוּזִים מֵהַכֹּחַ שֶׁבָּרֹאשׁ. וּבֵאֲרָהּ רַב הַמְנוּנָא, (בשני) בִּשְׁלֹשֶׁת קִשְׁרֵי הָאָבוֹת (קשר אחר). שְׁנֵי עַמּוּדִים (כליות שלמטה) שֶׁנִּמְשְׁכוּ בְּשֶׁמֶן מִשְׁחָה (בקיום) בִּשְׁתֵּי דְרָגוֹת, שְׁנֵי נְחָלִים לְכַנֵּס אֶת הַזֶּרַע, לְהוֹצִיא לְדַרְגָּה אַחֶרֶת, בְּפִי הָאַמָּה. הָעֵץ הַזֶּה הוּא גּוּף הָאֶמְצַע, שֶׁאוֹחֵז אֶת כָּל אֵלֶּה, וְכֻלָּם מְקֻשָּׁרִים בּוֹ, וְהוּא בָהֶם, וְעַל כֵּן הַכֹּל אֶחָד. וּכְשֶׁמִּזְדַּוֶּגֶת עִמּוֹ הַגְּבִירָה, אֲזַי הוּא אֶחָד, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים.</p>\n<p>בֹּא רְאֵה, כָּתוּב בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת. מִי הָעֲצֶרֶת? אֶלָּא בְּאוֹתוֹ מָקוֹם שֶׁהַכֹּל נִקְשָׁרִים כְּאֶחָד נִקְרָא עֲצֶרֶת. מַה זֶּה עֲצֶרֶת? (כנופיה) הִתְכַּנְּסוּת. וְאִם תֹּאמַר, כָּאן שֶׁנִּקְרָא עֲצֶרֶת מָה הַטַּעַם? אֶלָּא בְּכָל אוֹתָם יָמִים, יְמֵי הַסְּעוּדוֹת שֶׁל עַנְפֵי הָאִילָן הָיוּ. וְעַל כֵּן שִׁבְעִים פָּרִים הֵם. אַחַר כָּךְ שִׂמְחַת (הגוף) הָאִילָן מַמָּשׁ וְשִׂמְחַת הַתּוֹרָה. וּבִגְלָלוֹ הוּא יוֹם אֶחָד עֲצֶרֶת. שִׂמְחַת הַתּוֹרָה, שִׂמְחַת הָאִילָן, שֶׁהוּא הַגּוּף.</p>\n<p>וְעַל כֵּן אֵין חֵלֶק בַּיּוֹם הַזֶּה אֶלָּא לַקָּדוֹשׁ בָּרוּךְ הוּא עִם כְּנֶסֶת יִשְׂרָאֵל. מִשּׁוּם כָּךְ עֲצֶרֶת תִּהְיֶה לָכֶם, לָכֶם וְלֹא לְאַחֵר. (אחר כך שמחת האילן ממש, ובגללו הוא יום אחד, ואין חלק ביום הזה אלא לקדוש ברוך הוא וכנסת ישראל, ולכן כתוב עצרת תהיה לכם. אף כאן ביום הזה שמחת התורה, שמחת האילן, שהוא גוף, והכל נמצא בו) שֶׁהֲרֵי בְּשָׁעָה שֶׁהַמֶּלֶךְ נִמְצָא, הַכֹּל נִמְצָא בּוֹ. וְעַל כֵּן שָׁנִינוּ, בַּעֲצֶרֶת עַל פֵּרוֹת הָאִילָן, וַהֲרֵי פֵּרְשׁוּהָ, מִשּׁוּם כָּךְ נִקְרָא אֶחָד, אֶחָד וַדַּאי, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>בֹּא רְאֵה, מַה כָּתוּב? מִמּוֹשְׁבתֵיכֶם תָּבִיאוּ לֶחֶם תְּנוּפָה וְגוֹ', סֹלֶת תִּהְיֶינָה חָמֵץ תֵּאָפֶינָה. מַה שּׁוֹנֶה כָּאן חָמֵץ (בכנסת ישראל) ? אֶלָּא מִשּׁוּם שֶׁהַכֹּל אֲחוּזִים בּוֹ (וכן) בָּאִילָן, שֶׁהֲרֵי בָּאִילָן אֲחוּזִים עֲנָפִים, בָּאִילָן אֲחוּזִים עָלִים, קְלִפּוֹת, דִּינִים רַבִּים בְּכָל הַצְּדָדִים, הַכֹּל נִמְצָא בּוֹ. וּמִשּׁוּם שֶׁהָאִילָן הַזֶּה מְכַפֵּר עַל יֵצֶר הָרָע, שֶׁהוּא בְּבֵית מוֹשַׁב הָאָדָם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, מֵהָאִילָן הַזֶּה נִזּוֹנִים כָּל שְׁאָר הָאִילָנוֹת לְמַטָּה, וְהוּא הִשְׁתָּרֵשׁ עַל נָהָר אֶחָד עָמֹק שֶׁשּׁוֹפֵעַ וְיוֹצֵא, וְאֵין פּוֹסְקִים מֵימָיו לְעוֹלָמִים. עָלָיו כָּתוּב (ירמיה יז) וְהָיָה כְּעֵץ שָׁתוּל עַל מַיִם וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו, וְעַל כֵּן נִקְרֵאת תּוֹרָה (משלי ג) עֵץ חַיִּים הִיא וְגוֹ'. וּמַה זֶּה וְתֹמְכֶיהָ מְאֻשָּׁר? הֲרֵי פֵּרְשׁוּהָ, אֲבָל וְתֹמְכֶיהָ מְאֻשָּׁר, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ל) בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָּנוֹת.</p>"],[9522012217,"<p>וְהֵנִיף אֶת הָעֹמֶר וְגוֹ'. מִצְוָה זוֹ לְהַקְרִיב קָרְבַּן הָעֹמֶר. הַקָּרְבָּן הַזֶּה הוּא כֻּלּוֹ בִּדְבֵקוּת מַעְלָה וּמַטָּה, הַגְּבִירָה וּבָנֶיהָ הוֹלְכִים כְּאֶחָד. הָעֹמֶר הַזֶּה מַקְרִיבִים יִשְׂרָאֵל בְּטָהֳרָתָם, וְאוֹתוֹ הַקָּרְבָּן הוּא מִשְּׂעוֹרִים, וְזֶה הִקְרִיבוּ, לְהַכְנִיס אַהֲבָה בֵּין אִשָּׁה וּבַעְלָהּ.</p>\n<p>אֵשֶׁת זְנוּנִים הִרְחִיקָה עַצְמָה מִבֵּינֵיהֶם, שֶׁלֹּא יְכוֹלָה לַעֲמֹד עַל גַּבָּהּ. אֵשֶׁת חַיִל הִקְרִיבָה עַצְמָהּ לְהִתְקָרֵב לַכֹּהֵן הַגָּדוֹל, וַדַּאי הִיא טְהוֹרָה, (במדבר ה) וְנִקְּתָה וְנִזְרְעָה זָרַע, וּמוֹסִיפָה כֹחַ וְאַהֲבָה לְבַעְלָהּ. אֵשֶׁת זְנוּנִים בּוֹרַחַת מֵהַמִּקְדָּשׁ, שֶׁלֹּא לְהִתְקָרֵב אֵלָיו, שֶׁאִלְמָלֵא בְּאוֹתוֹ זְמַן שֶׁאֵשֶׁת חַיִל בּוֹדֶקֶת עַצְמָהּ, הִיא מִתְקָרֶבֶת אֵלֶיהָ, הָיְתָה אוֹבֶדֶת מִן הָעוֹלָם. וְעַל כֵּן לֹא רוֹצָה לְהִתְקָרֵב לַמִּקְדָּשׁ, וּבוֹרַחַת מִמֶּנּוּ, וְנִשְׁאָרִים יִשְׂרָאֵל זַכָּאִים, בְּלִי עִרְבּוּב אַחֵר, אֶל סוֹד הָאֱמוּנָה.</p>\n<p>סוֹד הַסֵּתֶר הַזֶּה שְׁתֵּי אֲחָיוֹת. וּכְשֶׁהֵרִיחַ זוֹ אֶת זוֹ בַּבְּדִיקָה שֶׁלָּהּ, צָבְתָה בִטְנָהּ וְנָפְלָה יְרֵכָהּ. שֶׁהֲרֵי בְּדִיקַת אֵשֶׁת חַיִל הוּא סַם הַמָּוֶת לְאֵשֶׁת זְנוּנִים. וְזוֹהִי הָעֵצָה שֶׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לְבָנָיו לְהַקְרִיב קָרְבָּן זֶה בִּשְׁבִיל אֵשֶׁת חַיִל, שֶׁתִּבְרַח מִמֶּנָּה אֵשֶׁת זְנוּנִים, וְנִשְׁאָרִים יִשְׂרָאֵל בְּלִי עִרְבּוּבְיָא אַחֶרֶת. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. (ע\"כ רעיא מהימנא).</p>"],[9522012218,"<p>רַבִּי אַבָּא וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי חִיָּיא, כָּתוּב וּסְפַרְתֶּם לָכֶם מִמָּחֳרַת הַשַּׁבָּת מִיּוֹם הֲבִיאֲכֶם אֶת עֹמֶר הַתְּנוּפָה. מַה זֶּה אוֹמֵר? אָמַר לוֹ, הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים. אֲבָל בֹּא רְאֵה, כְּשֶׁהָיוּ יִשְׂרָאֵל בְּמִצְרַיִם, הָיוּ בְּרָשׁוּת אַחֶרֶת, וְהָיוּ אוחֲזִים בַּטֻּמְאָה כְּאִשָּׁה הַזּוֹ כְּשֶׁהִיא יוֹשֶׁבֶת בִּימֵי טֻמְאָתָהּ. אַחַר שֶׁנִּמּוֹלוּ, נִכְנְסוּ בַּחֵלֶק הַקָּדוֹשׁ, שֶׁנִּקְרָא בְּרִית. כֵּיוָן שֶׁנֶּאֶחְזוּ בוֹ, פָּסְקָה מֵהֶם הַטֻּמְאָה, כְּאִשָּׁה הַזּוֹ שֶׁפּוֹסְקִים מִמֶּנָּה דְּמֵי טֻמְאָתָהּ. אַחַר שֶׁפָּסְקוּ מִמֶּנָּה, מַה כָּתוּב? (ויקרא טו) וְסָפְרָה לָּהּ שִׁבְעַת יָמִים. אַף כָּאן, כֵּיוָן שֶׁנִּכְנְסוּ בַּחֵלֶק הַקָּדוֹשׁ, פָּסְקָה מֵהֶם טֻמְאָה, וְאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מִכָּאן וָהָלְאָה חֶשְׁבּוֹן לְטָהֳרָה.</p>\n<p>וּסְפַרְתֶּם לָכֶם, לָכֶם דַּוְקָא, כְּמוֹ שֶׁנֶּאֱמַר וְסָפְרָה לָּהּ שִׁבְעַת יָמִים. לָּהּ - לְעַצְמָהּ. אַף כָּאן לָכֶם - לְעַצְמְכֶם. וְלָמָּה? כְּדֵי לְהִטָּהֵר בְּמַיִם קְדוֹשִׁים עֶלְיוֹנִים, וְאַחַר כָּךְ לְהִתְחַבֵּר עִם הַמֶּלֶךְ וּלְקַבֵּל תּוֹרָה.</p>\n<p>שָׁם וְסָפְרָה לָּהּ שִׁבְעַת יָמִים, כָּאן שֶׁבַע שַׁבָּתוֹת. לָמָּה שֶׁבַע שַׁבָּתוֹת? כְּדֵי לִזְכּוֹת לְהִטָּהֵר בַּמַּיִם שֶׁל אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, וְנִקְרָא מַיִם חַיִּים. וְאוֹתוֹ הַנָּהָר, שֶׁבַע שַׁבָּתוֹת יָצְאוּ מִמֶּנּוּ. וְעַל כֵּן שֶׁבַע שַׁבָּתוֹת וַדַּאי, כְּדֵי לִזְכּוֹת בּוֹ, כְּמוֹ שֶׁאִשָּׁה טָהֳרָתָהּ בַּלַּיְלָה לְשַׁמֵּשׁ עִם בַּעְלָהּ.</p>\n<p>כָּךָ כָּתוּב, וּבְרֶדֶת הַטַּל עַל הַמַּחֲנֶה לָיְלָה. עַל הַמַּחֲנֶה כָּתוּב, וְלֹא כָתוּב וּבְרֶדֶת הַטַּל לָיְלָה, אֶלָּא עַל הַמַּחֲנֶה, מִשּׁוּם שֶׁיּוֹרֵד מֵאוֹתָהּ נְקֻדָּה עַל אוֹתָם הַיָּמִים שֶׁנִּקְרְאוּ מַחֲנֶה, וּמִתְחַבֶּרֶת עִם הַמֶּלֶךְ הַקָּדוֹשׁ. וּמָתַי יוֹרֵד הַטַּל הַזֶּה? כְּשֶׁקָּרְבוּ יִשְׂרָאֵל לְהַר סִינַי, אָז יָרַד אוֹתוֹ הַטַּל בִּשְׁלֵמוּת, וְנִטְהֲרוּ וּפָסְקָה זֻהַמְתָּם מֵהֶם, וְהִתְחַבְּרוּ עִם הַמֶּלֶךְ וְעִם כְּנֶסֶת יִשְׂרָאֵל וְקִבְּלוּ תוֹרָה, וַהֲרֵי בֵּאַרְנוּ. וּבְאוֹתוֹ זְמַן, וַדַּאי כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם, לְהִטָּהֵר וְלִרְחֹץ, וְהַכֹּל נִקְשְׁרוּ (התקדשו) וְהִתְחַבְּרוּ עִם הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>בֹּא רְאֵה, כָּל אָדָם שֶׁאֵינוֹ מוֹנֶה חֶשְׁבּוֹן זֶה, אוֹתָן שֶׁבַע שַׁבָּתוֹת תְּמִימוֹת, לִזְכּוֹת לַטָּהֳרָה הַזּוֹ, לֹא נִקְרָא טָהוֹר, וְאֵינוֹ בִּכְלַל שֶׁל טָהוֹר, וְאֵינוֹ כְּדַאי לִהְיוֹת לוֹ חֵלֶק בַּתּוֹרָה. וּמִי שֶׁמַּגִּיעַ טָהוֹר לַיּוֹם הַזֶּה וְהַחֶשְׁבּוֹן לֹא נֶאֱבָד מִמֶּנּוּ, כְּשֶׁמַּגִּיעַ לַלַּיְלָה הַזֶּה צָרִיךְ לוֹ לַעֲסֹק בַּתּוֹרָה, וּלְהִתְחַבֵּר עִמָּהּ, וְלִשְׁמֹר טָהֳרָה עֶלְיוֹנָה שֶׁמַּגִּיעָה עָלָיו בְּאוֹתוֹ הַלַּיְלָה, וְנִטְהָר.</p>"],[9522012219,"<p>וְלָמַדְנוּ, שֶׁהַתּוֹרָה שֶׁצָּרִיךְ לוֹ לַעֲסֹק בַּלַּיְלָה הַזֶּה - תּוֹרָה שֶׁבְּעַל פֶּה, כְּדֵי שֶׁיִּטָּהֲרוּ (שיתדבק) כְאֶחָד מִמַּעְיַן הַנַּחַל הֶעָמֹק. אַחַר כָּךְ בַּיּוֹם הַזֶּה תָּבֹא תּוֹרָה שֶׁבִּכְתָב, וְיִתְחַבֵּר (בהם) עִמָּהּ, וְיִמָּצְאוּ כְאֶחָד בְּזִוּוּג אֶחָד לְמַעְלָה. אָז מַכְרִיזִים עָלָיו וְאוֹמְרִים: (ישעיה נט) וַאֲנִי זֹּאת בְּרִיתִי אוֹתָם אָמַר ה' רוּחִי אֲשֶׁר עָלֶיךְ וּדְבָרַי אֲשֶׁר שַׂמְתִּי בְּפִיךְ וְגוֹ'.</p>\n<p>וְעַל כֵּן חֲסִידִים הָרִאשׁוֹנִים לֹא הָיוּ יְשֵׁנִים בַּלַּיְלָה הַזֶּה, וְהָיוּ עוֹסְקִים בַּתּוֹרָה וְאוֹמְרִים: נָבִיא אֶת הַיְרֻשָּׁה הַקְּדוֹשָׁה לָנוּ וּלְבָנֵינוּ בִּשְׁנֵי עוֹלָמוֹת. וְאוֹתוֹ הַלַּיְלָה מִתְעַטֶּרֶת כְּנֶסֶת יִשְׂרָאֵל עֲלֵיהֶם, וּבָאָה לְהִזְדַּוֵּג עִם הַמֶּלֶךְ, וּשְׁנֵיהֶם מִתְעַטְּרִים עַל רֹאשָׁם שֶׁל אוֹתָם שֶׁזּוֹכִים לָזֶה.</p>\n<p>רַבִּי שִׁמְעוֹן כָּךְ אָמַר, בְּשָׁעָה שֶׁמִּתְכַּנְּסִים הַחֲבֵרִים בַּלַּיְלָה הַזֶּה אֵלָיו, נָבא לְתַקֵּן אֶת תַּכְשִׁיטֵי הַכַּלָּה, כְּדֵי שֶׁתִּמָּצֵא לְמָחָר בְּתַכְשִׁיטֶיהָ וּבְתִקּוּנֶיהָ אֶל הַמֶּלֶךְ כָּרָאוּי. אַשְׁרֵי חֶלְקָם שֶׁל הַחֲבֵרִים כְּשֶׁיְּבַקֵּשׁ הַמֶּלֶךְ אֶת הַגְּבִירָה, מִי תִקֵּן תַּכְשִׁיטֶיהָ וְהֵאִיר אֶת הָעֲטֶרֶת שֶׁלָּהּ וְשָׂם אֶת תִּקּוּנֶיהָ. וְאֵין לְךְ בָּעוֹלָם מִי שֶׁיּוֹדֵעַ לְתַקֵּן אֶת תַּכְשִׁיטֵי הַכַּלָּה, אֶלָּא הַחֲבֵרִים. אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בֹּא רְאֵה, הַחֲבֵרִים מְתַקְּנִים בַּלַּיְלָה הַזֶּה אֶת הַתַּכְשִׁיטִים לַכַּלָּה, וּמְעַטְּרִים אוֹתָהּ בָּעֲטָרָה שֶׁלָּהּ אֶל הַמֶּלֶךְ. וּמִי מַתְקִין לַמֶּלֶךְ בַּלַּיְלָה הַזֶּה לְהִמָּצֵא עִם הַכַּלָּה, לְהִזְדַּוֵּג עִם הַגְּבִירָה? הַנָּהָר הַקָּדוֹשׁ הֶעָמֹק שֶׁל כָּל הַנְּהָרוֹת, הָאֵם הָעֶלְיוֹנָה. זֶהוּ שֶׁכָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה וְגוֹ'. אַחַר שֶׁהִתְקִינָה אֶת הַמֶּלֶךְ וְעִטְּרָה אוֹתוֹ, הִיא בָּאָה לְטַהֵר אֶת הַגְּבִירָה וְאֶת אוֹתָם שֶׁנִּמְצָאִים עִמָּהּ.</p>\n<p>לְמֶלֶךְ שֶׁהָיָה לוֹ בֵּן יָחִיד, בָּא לְזַוֵּג אוֹתוֹ עִם הַגְּבִירָה הָעֶלְיוֹנָה. מֶה עָשְׂתָה אִמּוֹ כָּל אוֹתוֹ הַלַּיְלָה? נִכְנְסָה לְבֵית גְּנָזֶיהָ, הוֹצִיאָה עֲטָרָה עֶלְיוֹנָה עִם שִׁבְעִים אֲבָנִים יְקָרוֹת סְבִיבָהּ וְעִטְּרָה אוֹתוֹ. הוֹצִיאָה כְּלֵי מִילַת וְהִלְבִּישָׁה אוֹתוֹ, וְתִקְּנָה אוֹתוֹ בְּתִקּוּנֵי מְלָכִים.</p>\n<p>אַחַר כָּךְ נִכְנְסָה לְבֵית הַכַּלָּה, רָאֲתָה אֶת עַלְמוֹתֶיהָ שֶׁמְּתַקְּנוֹת אֶת הָעֲטָרָה שֶׁלָּהּ וְאֶת לְבוּשֶׁיהָ וְאֶת תַּכְשִׁיטֶיהָ לְתַקֵּן אוֹתָהּ. אָמְרָה לָהֶן: הֲרֵי הִתְקַנְתִּי בֵּית טְבִילָה, מָקוֹם שֶׁמַּיִם נוֹבְעִים, וְכָל הָרֵיחוֹת וְהַבְּשָׂמִים סְבִיב אוֹתָם הַמַּיִם לְטַהֵר אֶת כַּלָּתִי, שֶׁתָּבֹא כַּלָּתִי, הַגְּבִירָה שֶׁל בְּנִי, וְעַלְמוֹתֶיהָ, וְיִטְהֲרוּ בְּאוֹתוֹ מָקוֹם שֶׁהִתְקַנְתִּי בְּאוֹתוֹ בֵּית הַטְּבִילָה שֶׁל הַמַּיִם הַנּוֹבְעִים שֶׁעִמִּי. אַחַר כָּךְ תַּקְּנוּ אוֹתָהּ בְּתַכְשִׁיטֶיהָ, הַלְבִּישׁוּ אוֹתָהּ אֶת לְבוּשֶׁיהָ, עַטְּרוּ אוֹתָהּ בָּעֲטָרָה שֶׁלָּהּ. לְמָחָר כְּשֶׁיָּבא בְנִי לְהִזְדַּוֵּג עִם הַגְּבִירָה, יְתַקֵּן הֵיכָל לְכֻלָּם, וְיִמְצָא אֶת מְדוֹרוֹ עִמָּכֶם כְּאֶחָד.</p>\n<p>כָּךָ הַמֶּלֶךְ הַקָּדוֹשׁ וְהַגְּבִירָה וְהַחֲבֵרִים כְּמוֹ זֶה, וְהָאֵם הָעֶלְיוֹנָה שֶׁמְּתַקֶּנֶת אֶת הַכֹּל. נִמְצָא שֶׁהַמֶּלֶךְ הָעֶלְיוֹן וְהַגְּבִירָה וְהַחֲבֵרִים, מְדוֹרָם כְּאֶחָד, וְאֵין נִפְרָדִים לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב, ה' מִי יָגוּר בְּאָהֳלֶךְ וְגוֹ', הוֹלֵךְ תָּמִים וּפֹעֵל צֶדֶק. מִי הוּא פֹּעֵל צֶדֶק? אֶלָּא אֵלּוּ שֶׁמְּתַקְּנִים אֶת הַגְּבִירָה עִם תַּכְשִׁיטֶיהָ, בִּלְבוּשֶׁיהָ, וּבָעֲטָרָה שֶׁלָּהּ. וְכָל אֶחָד נִקְרָא פּוֹעֵל צֶדֶק. אָמַר רַבִּי חִיָּיא, אִלְמָלֵא לֹא זָכִיתִי בָעוֹלָם אֶלָּא לִשְׁמֹעַ אֶת הַדְּבָרִים הַלָּלוּ - דַּי לִי. אַשְׁרֵי חֶלְקָם שֶׁל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְיוֹדְעִים אֶת דַּרְכֵי הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁרְצוֹנָם בַּתּוֹרָה, עֲלֵיהֶם כָּתוּב (תהלים צא) כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ. וְכָתוּב אֲחַלְּצֵהוּ וַאֲכַבְּדֵהוּ.</p>"],[9522012220,"<p>רעיָּא מְהֵיּמְנָא וּסְפַרְתֶּם לָכֶם מִמָּחֳרַת הַשַּׁבָּת וְגוֹ'. מִצְוָה זוֹ לִסְפֹּר סְפִירַת הָעֹמֶר הֲרֵי בֵּאַרְנוּ. וְסוֹד זֶה - יִשְׂרָאֵל, אַף עַל גַּב שֶׁנִּטְהֲרוּ לַעֲשׂוֹת פֶּסַח וְיָצְאוּ מִן הַטֻּמְאָה, לֹא הָיוּ שְׁלֵמִים וּטְהוֹרִים כָּרָאוּי. וְעַל כֵּן אֵין הַלֵּל גָּמוּר בִּימֵי הַפֶּסַח, שֶׁעַד עַכְשָׁו לֹא הִשְׁתַּלְּמוּ כָרָאוּי.</p>\n<p>כְּמוֹ אִשָּׁה שֶׁיּוֹצֵאת מִטֻּמְאָה, וְכֵיוָן שֶׁיָּצְאָה, מִשָּׁם וָהָלְאָה, וְסָפְרָה לָּהּ. אַף כָּאן יִשְׂרָאֵל כְּשֶׁיָּצְאוּ מִמִּצְרַיִם, יָצְאוּ מִטֻּמְאָה, וְעָשׂוּ פֶסַח לֶאֱכֹל בְּשֻׁלְחַן אֲבִיהֶם, וּמִשָּׁם וָהָלְאָה יַעֲשׂוּ חֶשְׁבּוֹן לִקְרַב אִשָּׁה לְבַעְלָהּ, לְהִתְחַבֵּר עִמּוֹ, וְאוֹתָם חֲמִשִּׁים יָמִים שֶׁל טָהֳרָה לְהִכָּנֵס לְסוֹד הָעוֹלָם הַבָּא, וּלְקַבֵּל תּוֹרָה, וְלִקְרַב אִשָּׁה לְבַעְלָהּ.</p>\n<p>וּמִשּׁוּם שֶׁהַיָּמִים הַלָּלוּ יָמִים שֶׁל עוֹלַם הַזָּכָר, לֹא נִמְסָר חֶשְׁבּוֹן זֶה אֶלָּא לַגְּבָרִים לְבַדָּם. וְלָכֵן חֶשְׁבּוֹן זֶה הוּא בַּעֲמִידָה, וְדִבְרֵי הָעוֹלָם הַתַּחְתּוֹן בִּישִׁיבָה, וְלֹא בַעֲמִידָה. וְסוֹד זֶה, תְּפִלַּת הָעֲמִידָה וּתְפִלָּה שֶׁל מְיֻשָּׁב.</p>\n<p>וְהַחֲמִשִּׁים הַלָּלוּ הֵם אַרְבָּעִים וָתֵשַׁע, כְּלַל הַפָּנִים שֶׁל הַתּוֹרָה, שֶׁהֲרֵי בְּיוֹם הַחֲמִשִּׁים הוּא סוֹד תּוֹרָה מַמָּשׁ. וְאֵלּוּ הֵם חֲמִשִּׁים יָמִים שֶׁבּוֹ שְׁמִטָּה וְיוֹבֵל. וְאִם תֹּאמַר, חֲמִשִּׁים? הֲרֵי הֵם אַרְבָּעִים וָתֵשַׁע! אֶחָד הוּא טָמִיר, וְהָעוֹלָם נִסְמָךְ עָלָיו. וּבְאוֹתוֹ יוֹם הַחֲמִשִּׁים הִתְגַּלָּה הַטָּמִיר וְהִתְכַּסָּה (ונמצא) בּוֹ, כְּמוֹ מֶלֶךְ שֶׁבָּא לְבֵית שׁוֹשְׁבִינוֹ וְנִמְצָא שָׁם, אַף כָּאן יוֹם הַחֲמִשִּׁים, וַהֲרֵי בֵּאַרְנוּ אֶת הַסּוֹד הַזֶּה.</p>"],[9522012221,"<p>הַמִּצְוָה (ל\"ג) שֶׁאַחַר זוֹ, לַעֲשׂוֹת חַג שָׁבוּעוֹת, שֶׁכָּתוּב (דברים טז) וְעָשִׂיתָ חַג שָׁבֻעוֹת לַה' אֱלֹהֶיךְ. שָׁבוּעוֹת - עַל שֶׁנִּכְנְסוּ יִשְׂרָאֵל לְסוֹד חֲמִשִּׁים הַיָּמִים, שֶׁהֵם שִׁבְעָה שָׁבוּעוֹת, וּבְקָרְבַּן הָעֹמֶר הִתְבַּטֵּל יֵצֶר הָרָע, שֶׁבּוֹרֵחַ מֵאֵשֶׁת חַיִל. וּכְשֶׁשָּׁם לֹא נִקְרַב, מִתְדַּבְּקִים יִשְׂרָאֵל עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִתְבַּטֵּל מִמַּעְלָה וּמִמַּטָּה.</p>\n<p>וּמִשּׁוּם כָּךְ נִקְרָא בְּגָוֶן זֶה עֲצֶרֶת, שֶׁיֵּשׁ בּוֹ בִּטּוּל יֵצֶר הָרָע, וְעַל כֵּן לֹא כָתוּב בּוֹ חַטָּאת כְּמוֹ שְׁאָר הַזְּמַנִּים שֶׁכָּתוּב בָּהֶם חַטָּאת (לה'). וְאָז כָּל הָאוֹרוֹת מִתְכַּנְּסִים לְאֵשֶׁת חַיִל, וּמִשּׁוּם כָּךְ עֲצֶרֶת.</p>\n<p>שָׁבֻעוֹת, וְלֹא כָתוּב כַּמָּה הֵם. אֶלָּא בְּכָל מָקוֹם שֶׁנֶּאֱמַר סְתָם, הַשֵּׁם גּוֹרֵם שֶׁהֵם מִן שֶׁבַע. וְכָתוּב (שם) שִׁבְעָה שָׁבֻעֹת תִּסְפָּר לָךְ, לָמָּה כָּתוּב שָׁבֻעֹת לְבַדּוֹ? אֶלָּא כָּךְ צָרִיךְ שָׁבוּעוֹת סְתָם, לְהַכְלִיל מַעְלָה וּמַטָּה, שֶׁהֲרֵי בְּכָל מָקוֹם שֶׁאֵלּוּ מִתְעוֹרְרִים, אַף אֵלֶּה מִתְעוֹרְרִים עִמָּם. טֶרֶם שֶׁהָיָה שְׁלֹמֹה, לֹא הָיוּ מִתְגַּלִּים. כֵּיוָן שֶׁבָּא שְׁלֹמֹה, עָשָׂה מֵהֶם פְּרָט, שֶׁכָּתוּב שִׁבְעַת יָמִים וְשִׁבְעַת יָמִים. זֶהוּ פְּרָט.</p>\n<p>בִּזְמַן אַחֵר בִּכְלָל, שָׁבוּעוֹת סְתָם. וְלֹא צָרִיךְ לְאָדָם אַחֵר לַעֲשׂוֹת מֵהֶם פְּרָט, חוּץ מִשְּׁלֹמֹה, מִשּׁוּם שֶׁהֵם שִׁבְעַת יָמִים שֶׁלְּמַטָּה, לֹא מְאִירִים בִשְׁלֵמוּת, עַד שֶׁבָּא שְׁלֹמֹה, וְאָז עָמְדָה הַלְּבָנָה בְּהַשְׁלָמָתָהּ בְּאוֹתָם שִׁבְעַת הַיָּמִים. וְכָאן חַג שָׁבוּעוֹת סְתָם, מִשּׁוּם שֶׁנִּכְלְלוּ תַחְתּוֹנִים בָּעֶלְיוֹנִים, וְלֹא הֵאִירוּ כְּמוֹ הַיּוֹם שֶׁל שְׁלֹמֹה.</p>\n<p>מִצְוָה (ל\"ד) אַחַר זוֹ - לְהַקְרִיב שְׁתֵּי הַלֶּחֶם. הֲרֵי בֵּאַרְנוּ, שְׁתֵּי הַלֶּחֶם - שְׁתֵּי שְׁכִינוֹת, עֶלְיוֹנָה וְתַחְתּוֹנָה, וְהִתְחַבְּרוּ כְאֶחָד. לְגַבֵּיהֶם, שְׁתֵּי הַלֶּחֶם בְּשַׁבָּת, שֶׁהוּא מָזוֹן שֶׁל אֶחָד שְׁנַיִם שֶׁל מַעְלָה וּמַטָּה. וְעַל זֶה כָּתוּב, שְׁנֵי הָעֹמֶר לָאֶחָד. לָאֶחָד וַדַּאי, לְהִתְיַחֵד בְּמָקוֹם אֶחָד אֶל אוֹתוֹ שֶׁנִּקְרָא אֶחָד. וּמִי הוּא? הַקֹּל קוֹל יַעֲקֹב, שֶׁהוּא יוֹרֵשׁ מַעְלָה וּמַטָּה שְׁנֵי לְחָמִים כְּאֶחָד. וּמִשּׁוּם שֶׁשַּׁבָּת הוּא סוֹד שֶׁל מַעְלָה וּמַטָּה, וְהַכֹּל הוּא שַׁבָּת, (נקראו) שְׁנֵי לְחָמִים. (עד כאן)</p>\n<p>מִצְוָה אַחַר זוֹ - לְהַסְדִּיר לֶחֶם וּלְבוֹנָה, לְהַקְרִיב עֹמֶר, שֶׁכָּתוּב וַעֲשִׂיתֶם בְּיוֹם הֲנִיפְכֶם אֶת הָעֹמֶר כֶּבֶשׂ תָּמִים לְעֹלָה. וְכֵן בְּשָׁבוּעוֹת לְהַקְרִיב שְׁתֵּי הַלֶּחֶם, וְכָךְ בְּכָל הַיָּמִים הַטּוֹבִים לְהַקְרִיב קָרְבָּן שֶׁל מוּסָפִים. אֶלָּא וַדַּאי בְּכָל יוֹם שֶׁל מוֹעֲדִים צָרִיךְ לְהַקְרִיב אֶת הַקָּרְבָּן שֶׁלּוֹ. צָרִיךְ לְהַקְרִיב עָלָיו תּוֹסֶפֶת שֶׁיֵּשׁ לוֹ, כְּמוֹ תּוֹסֶפֶת כְּתֻבָּה וּמַתָּנָה שֶׁמּוֹסִיף חָתָן לְכַלָּה. וְשַׁבָּת הַמַּלְכָּה, שֶׁהִיא כַלָּה, בְּשַׁבָּתוֹת וּבְכָל יָמִים טוֹבִים, צְרִיכָה תוֹסֶפֶת, שֶׁהֵם מוּסָפִים שֶׁל קָרְבָּנוֹת, וּמַתָּנוֹת, שֶׁהֵן מַתְּנוֹת כְּהֻנָּה.</p>\n<p>וּבְשָׁבוּעוֹת שֶׁהוּא מַתַּן תּוֹרָה, שֶׁנִּתְּנוּ שְׁנֵי לוּחוֹת הַתּוֹרָה מֵהַצַּד שֶׁל עֵץ הַחַיִּים, צָרִיךְ לְהַקְרִיב לָהֶם שְׁתֵּי הַלֶּחֶם, שֶׁהֵן ה\"ה. שֶׁשְּׁנֵי יָמִים שֶׁל שָׁבוּעוֹת הֵם י\"ו צָרִיךְ לְהַקְרִיב לָהֶם שְׁתֵּי הַלֶּחֶם מֵאוֹתָן ה\"ה, שֶׁזֶּהוּ לֶחֶם שֶׁל הַתּוֹרָה, שֶׁנֶּאֱמַר בּוֹ לְכוּ לַחֲמוּ בְלַחְמִי, ה\"ה, מִן הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ.</p>\n<p>וְזְהִוּ מַאֲכַל אָדָם, שֶׁהוּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. (במדבר יט) זֹּאת הַתּוֹרָה אָדָם. (ויקרא א) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַה'. עֹמֶר שְׂעוֹרִים, מַאֲכַל בְּהֵמוֹת, שֶׁהֵן חַיּוֹת הַקֹּדֶשׁ, שֶׁמֵּהֶם צָרִיךְ לְהַקְרִיב, זֶהוּ שֶׁכָּתוּב מִן הַבְּהֵמָה. אֵילִם - מְנַגְּחִים בַּמִּשְׁנָה, בְּאֵלּוּ הַפְּשָׁטִים. מִן הַבָּקָר - פָּרִים מְנַגְּחִים בַּמִּשְׁנָה, בְּחֹזֶק יָתֵר. וּמִן הַצֹּאן - שְׁאָר הָעָם, הַקָּרְבָּן שֶׁלָּהֶם תְּפִלּוֹת, וַעֲלֵיהֶם נֶאֱמַר (יחזקאל לד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם.</p>\n<p>שֶׁבַּעָלֵי קַבָּלָה וּבַעֲלֵי מִדּוֹת הֵם מִצַּד שֶׁל עֵץ הַחַיִּים. שְׁאָר הָעָם מֵהַצַּד שֶׁל עֵץ טוֹב וָרָע, אִסּוּר וְהֶתֵּר. וּמִשּׁוּם כָּךְ מִן הַבְּהֵמָה, מַאֲכָל שֶׁלָּהֶם עֹמֶר, לֶחֶם שְׂעוֹרִים. וַיָּמָד שֵׁשׁ שְׂעֹרִים וַיָּשֶׁת עָלֶיהָ - תּוֹרָה שֶׁבְּעַל פֶּה שֶׁל שִׁשָּׁה סִדְרֵי מִשְׁנָה. אֲבָל אֵלּוּ שֶׁל עֵץ הַחַיִּים, שֶׁהֵם אָדָם, הַתּוֹרָה שֶׁלָּהֶם הִיא לַחְמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב (משלי ט) לְכוּ לַחֲמוּ בְלַחְמִי, וְהַיְנוּ שְׁתֵּי הַלֶּחֶם. שָׂמְחוּ כָּל הַתַּנָּאִים וְהָאָמוֹרָאִים וְאָמְרוּ: מִי עוֹמֵד לִפְנֵי סִינַי? (ע\"כ רעיא מהימנא).</p>"],[9522012222,"<p>בַּחֹדֶשׁ הַשְּׁבִיעִי בְּאֶחָד לַחֹדֶשׁ. רַבִּי יִצְחָק פָּתַח, (שם פא) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קֵרַב אוֹתָם אֵלָיו מִכָּל הָאֻמּוֹת עוֹבְדֵי עֲבוֹדָה זָרָה וְהִתְרַצָּה בָהֶם, וּמִמָּקוֹם רָחוֹק קֵרַב אוֹתָם אֵלָיו. זֶהוּ שֶׁכָּתוּב (יהושע כד) וַיֹּאמֶר יְהוֹשֻׁעַ אֶל כָּל הָעָם כֹּה אָמַר ה' אֱלֹהֵי יִשְׂרָאֵל בְּעֵבֶר הַנָּהָר יָשְׁבוּ אֲבוֹתֵיכֶם מֵעוֹלָם. לְהַרְאוֹת שֶׁהֲרֵי מִמָּקוֹם רָחוֹק הִתְרַצָּה בָהֶם וְקֵרַב אוֹתָם אֵלָיו, וְכָתוּב, וָאֶקַּח אֶת אֲבִיכֶם אֶת אַבְרָהָם מֵעֵבֶר הַנָּהָר וְגוֹ'. בַּפְּסוּקִים הַלָּלוּ יֵשׁ לְהִסְתַּכֵּל, וְכִי כָל יִשְׂרָאֵל לֹא הָיוּ יוֹדְעִים אֶת זֶה, וְכָל שֶׁכֵּן יְהוֹשֻׁעַ?</p>\n<p>אֶלָּא כָּל הַתּוֹרָה נִסְתֶּרֶת וְנִגְלֵית, כְּמוֹ שֶׁהַשֵּׁם הַקָּדוֹשׁ נִסְתָּר וְנִגְלֶה, מִשּׁוּם שֶׁכָּל הַתּוֹרָה הִיא שֵׁם קָדוֹשׁ, וְעַל כֵּן הִיא נִסְתֶּרֶת וְנִגְלֵית. אִם יְהוֹשֻׁעַ וְיִשְׂרָאֵל הָיוּ יוֹדְעִים, לָמָּה כָּתוּב כֹּה אָמַר ה'? אֶלָּא וַדַּאי סֵתֶר הַדָּבָר - הַטּוֹב הָרַב שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא עִם יִשְׂרָאֵל, שֶׁהִתְרַצָּה בָּאָבוֹת, וְעָשָׂה אוֹתָם מֶרְכָּבָה קְדוֹשָׁה עֶלְיוֹנָה לִכְבוֹדוֹ, וְהוֹצִיא אוֹתָם מִתּוֹךְ נָהָר עֶלְיוֹן נִכְבָּד קָדוֹשׁ, מְאוֹר כָּל הַמְּאוֹרוֹת, כְּדֵי שֶׁיִּתְעַטֵּר בַּהֶם. זֶהוּ שֶׁכָּתוּב, כֹּה אָמַר ה' בְּעֵבֶר הַנָּהָר יָשְׁבוּ אֲבוֹתֵיכֶם מֵעוֹלָם. הַנָּהָר - אוֹתוֹ הַנָּהָר שֶׁמֻּכָּר וְנוֹדָע.</p>\n<p>מֵעוֹלָם - מַה הוּא רוֹצֶה כָּאן? אֶלָּא לְהַרְאוֹת חָכְמָה. מֵעֵבֶר הַנָּהָר מֵעוֹלָם, אֶלָּא אוֹתוֹ נָהָר נִקְרָא עוֹלָם, וְעַל כֵּן בְּעֵבֶר הַנָּהָר יָשְׁבוּ אֲבוֹתֵיכֶם מֵעוֹלָם, לְהַרְאוֹת הַטּוֹב וְהָאֱמֶת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא עִם יִשְׂרָאֵל. וָאֶקַּח אֶת אֲבִיכֶם אֶת אַבְרָהָם מֵעֵבֶר הַנָּהָר. מַה זֶּה אוֹמֵר? אֶלָּא אַבְרָהָם לֹא נִדְבַּק בְּאוֹתוֹ נָהָר כְּמוֹ יִצְחָק שֶׁנִּדְבַּק בּוֹ בְּצִדּוֹ לְהִתְחַזֵּק.</p>\n<p>בֹּא רְאֵה, הַנָּהָר הַזֶּה, אַף עַל גַּב שֶׁאֵינוֹ דִּין, יוֹצְאִים דִּינִים מִצִּדּוֹ וּמִתְחַזְּקִים בּוֹ. וּכְשֶׁיִּצְחָק מִתְחַזֵּק (בדיניו) בְּבָנָיו, אֲזַי הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים מִתְכַּנְּסִים לְדִין, וְכִסֵּא הַדִּין מִתְתַּקֵּן, וְהַמֶּלֶךְ הַקָּדוֹשׁ יוֹשֵׁב עַל כִּסֵּא דִין וְדָן אֶת הָעוֹלָם. אָז, תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁיּוֹדְעִים לְסַלֵּק כִּסֵּא הַדִּין וּלְתַקֵּן כִּסֵּא שֶׁל רַחֲמִים, וּבַמֶּה? בַּשּׁוֹפָר.</p>\n<p>רַבִּי אַבָּא הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, הֲרֵי פְּעָמִים רַבּוֹת שָׁאַלְתִּי עַל הַשּׁוֹפָר הַזֶּה מַה זֶּה אוֹמֵר, וְעַד כָּאן לֹא הִתְיַשַּׁבְתִּי בוֹ. אָמַר לוֹ, הֲרֵי וַדַּאי זֶהוּ בֵּרוּר הַדָּבָר, שֶׁיִּשְׂרָאֵל צְרִיכִים בְּיוֹם הַדִּין (הזה) שׁוֹפָר וְלֹא קֶרֶן, מִשּׁוּם שֶׁקֶּרֶן הֲרֵי נוֹדָע בְּאֵיזֶה מָקוֹם הִיא, וּלְהִדָּבֵק בְּדִין אֵינֶנּוּ רוֹצִים. אֲבָל הֲרֵי שָׁנִינוּ, בִּדְבָרִים וּבְמַעֲשִׂים צְרִיכִים לְהֵרָאוֹת וּלְהָעִיר דְּבָרִים נִסְתָּרִים.</p>\n<p>בֹּא רְאֵה, כְּשֶׁאוֹתוֹ שׁוֹפָר עֶלְיוֹן, שֶׁבּוֹ הָאוֹר שֶׁל הַכֹּל, מִסְתַּלֵּק וְלֹא מֵאִיר לַבָּנִים, אֲזַי מִתְעוֹרֵר הַדִּין, וְהַכִּסְאוֹת מְתֻקָּנִים לְבֵית הַדִּין, וְזֶה הַשּׁוֹפָר, נִקְרָא אֵילוֹ שֶׁל יִצְחָק, תָּקְפּוֹ שֶׁל יִצְחָק, תִּשְׁבַּחַת הָאָבוֹת, כְּשֶׁמִּתְעַלֶּה אוֹתוֹ שׁוֹפָר גָּדוֹל שֶׁאֵין מֵינִיק אֶת הַבָּנִים, אֲזַי יִצְחָק מִתְחַזֵּק, וּמִתְתַּקֵּן לָדוּן אֶת הָעוֹלָם.</p>\n<p>וּכְשֶׁמִּתְעוֹרֵר הַשּׁוֹפָר הַזֶּה וּכְשֶׁבְּנֵי אָדָם שָׁבִים מֵחֲטָאֵיהֶם, צְרִיכִים לְהַשְׁפִּיעַ קוֹל שׁוֹפָר מִמַּטָּה, וְאוֹתוֹ קוֹל עוֹלֶה לְמַעְלָה, אֲזַי מִתְעוֹרֵר שׁוֹפָר אַחֵר עֶלְיוֹן, וּמְעוֹרֵר רַחֲמִים וּמִסְתַּלֵּק הַדִּין. וּצְרִיכִים לְהַרְאוֹת מַעֲשֶׂה בַּשּׁוֹפָר, לְעוֹרֵר שׁוֹפָר אַחֵר, וּלְהוֹצִיא בַּשּׁוֹפָר הַזֶּה לְמַטָּה אוֹתָם קוֹלוֹת, לְהַרְאוֹת שֶׁכָּל אוֹתָם קוֹלוֹת שֶׁלְּמַעְלָה, שֶׁכֻּלָּם כְּלוּלִים בְּאוֹתוֹ שׁוֹפָר עֶלְיוֹן, יִתְעוֹרְרוּ לָצֵאת.</p>\n<p>וּבַקּוֹלוֹת הַלָּלוּ שֶׁלְּמַטָּה נוֹתְנִים יִשְׂרָאֵל כֹּחַ (לרחמים מלמטה, ומתעורר השופר הגדול) לְמַעְלָה, וְעַל כֵּן צְרִיכִים לְזַמֵּן שׁוֹפָר בַּיּוֹם הַזֶּה וְלַעֲרֹךְ קוֹלוֹת, לְכַוֵּן בּוֹ כְּדֵי לְעוֹרֵר שׁוֹפָר אַחֵר, שֶׁבּוֹ כְּלוּלִים הַקּוֹלוֹת לְמַעְלָה (ולסדר קולות בשופר).</p>\n<p>סִדְרָה רִאשׁוֹנָה - יוֹצֵא קוֹל וּמִתְעַטֵּר לְמַעְלָה, עוֹלֶה רְקִיעִים, וְנִבְקָע בֵּין הָרִים רָמִים, וּמַגִּיעַ לְאַבְרָהָם וְשׁוֹרֶה בְרֹאשׁוֹ וּמִתְעַטֵּר, וְהוּא מִתְעוֹרֵר וּמַתְקִין אֶת הַכִּסֵּא. וּבְסֵפֶר הָאַגָּדָה שָׁנִינוּ, בְּשָׁעָה שֶׁאוֹתוֹ קוֹל רִאשׁוֹן עוֹלֶה, מִתְעוֹרֵר וּמִתְעַטֵּר אַבְרָהָם, וּמַתְקִין אֶת הַכִּסֵּא, וּפוֹקֵד עָלָיו (אבא ואמא) אַבָּא.</p>\n<p>בֵּינְתַיִם עוֹלֶה הַשֵּׁנִי, הַתַּקִּיף (לחבר) לִשְׁבֹּר אֶת הַדִּינִים הַקָּשִׁים. וְזֶה הַסֵּדֶר הַשֵּׁנִי, אוֹתוֹ הַקּוֹל שׁוֹבֵר בְּכֹחוֹ. וְאָז עוֹלֶה, וְכָל הַדִּינִים שֶׁמִּתְעוֹרְרִים (שנקרים) לְפָנָיו נִשְׁבָּרִים, עַד שֶׁעוֹלֶה לִמְקוֹמוֹ שֶׁל יִצְחָק. כֵּיוָן שֶׁמִּתְעוֹרֵר יִצְחָק וְרוֹאֶה אֶת אַבְרָהָם, מְתַקֵּן אֶת הַכִּסֵּא לַעֲמֹד לְפָנָיו. אָז נִכְנָע, שׁוֹבֵר אֶת הַתֹּקֶף הַקָּשֶׁה. וּבָזֶה צָרִיךְ מִי שֶׁתּוֹקֵעַ לְכַוֵּן הַלֵּב וְהָרָצוֹן, כְּדֵי לִשְׁבֹּר הַכֹּחַ וְהַתֹּקֶף שֶׁל הַדִּין הַקָּשֶׁה. זֶהוּ שֶׁכָּתוּב (תהלים פט) אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה, יוֹדְעֵי תְרוּעָה וַדַּאי.</p>\n<p>סִדְרָה שְׁלִישִׁית - יוֹצֵא קוֹל וְעוֹלֶה, וּבוֹקֵעַ כָּל אוֹתָם רְקִיעִים, וּמִתְעוֹרְרִים רַחֲמִים, וּמַגִּיעַ אוֹתוֹ קוֹל לְרֹאשׁוֹ שֶׁל יַעֲקֹב, וְיַעֲקֹב מִתְעוֹרֵר וְרוֹאֶה אֶת אַבְרָהָם מִתְתַּקֵּן בַּצַּד הָאַחֵר. אֲזַי אוֹחֲזִים שְׁנֵיהֶם בְּיִצְחָק, זֶה מִצַּד זֶה וְזֶה מִצַּד זֶה, וְלֹא יְכוֹלִים הַתֹּקֶף שֶׁלּוֹ לָצֵאת הַחוּצָה, וּשְׁלֹשׁ הַסְּדָרוֹת הַלָּלוּ הֵן סִדְרָה אַחַת.</p>\n<p>סִדְרָה אַחֶרֶת - קוֹל יוֹצֵא וְעוֹלֶה, וְנוֹטֵל אֶת אַבְרָהָם מִמְּקוֹמוֹ, וּמַשְׁפִּיעַ אוֹתוֹ לְמַטָּה, לְמָקוֹם שֶׁהַגְּבוּרוֹת שֶׁל יִצְחָק שׁוֹרִים שָׁם, וּמְקַיְּמִים אֶת אַבְרָהָם בְּתוֹכָם.</p>\n<p>סִדְרָה שְׁנִיָּה - יוֹצֵא קוֹל שָׁבוּר, לֹא חָזָק כְּמוֹ הָרִאשׁוֹן. לֹא שֶׁחַלָּשׁ אוֹתוֹ קוֹל שֶׁתָּקַע, אֶלָּא שֶׁאוֹתוֹ קוֹל אֵינוֹ אֵצֶל יִצְחָק כְּבָרִאשׁוֹנָה, שֶׁשָּׁם שׁוֹרֶה הַתֹּקֶף הַתַּקִּיף, אֶלָּא רַק לְאוֹתָם בֵּית דִּין שֶׁל מַעְלָה שֶׁהֵם יוֹתֵר רָפִים, וְכֻלָּם רוֹאִים אֶת אַבְרָהָם אֶצְלָם, וְנִכְנָעִים לְפָנָיו.</p>\n<p>בֵּינְתַיִם סִדְרָה שְׁלִישִׁית - יוֹצֵא קוֹל וְעוֹלֶה, וּמִתְעַטֵּר בְּרֹאשׁוֹ שֶׁל יַעֲקֹב, וּמַשְׁפִּיעַ אוֹתוֹ לְאוֹתוֹ מָקוֹם שֶׁאוֹתָן הַגְּבוּרוֹת שׁוֹרוֹת, וְעוֹמֵד כְּנֶגְדָּן, אַבְרָהָם מִצַּד זֶה וְיַעֲקֹב מִצַּד זֶה, וְהֵם בָּאֶמְצַע, וְאָז כֻּלָּם נִכְנָעִים וְנִמְצָאִים (ושוככים) בִּמְקוֹמָם. וְאֵלּוּ כֻּלָּם סֵדֶר אַחֵר שֵׁנִי.</p>\n<p>סִדְרָה אַחֲרוֹנָה - שֶׁצָּרִיךְ לְהַעֲלוֹתָם לִמְקוֹמָם וּלְיַשֵּׁב (ולישר) בֵּינֵיהֶם אֶת יִצְחָק כְּמִקֹּדֶם, מִשּׁוּם שֶׁאֶת זֶה צָרִיךְ לְיַשֵּׁר בִּמְקוֹמוֹ, וְלֹא יֵצֵא בִגְבוּרוֹתָיו הַחוּצָה, אָז כָּל הַדִּינִים נִכְנָעִים, וּמִתְעוֹרְרִים רַחֲמִים.</p>\n<p>עַל כֵּן צָרִיךְ לְכַוֵּן אֶת הַלֵּב וְהָרָצוֹן בַּקּוֹלוֹת הַלָּלוּ, וְלַחֲזֹר בִּתְשׁוּבָה לִפְנֵי רִבּוֹנָם. אֲזַי כְּשֶׁיִּשְׂרָאֵל מְתַקְּנִים וּמְסַדְּרִים קוֹלוֹת בִּרְצוֹן הַלֵּב כָּרָאוּי בַּשּׁוֹפָר הַזֶּה, חוֹזֵר אוֹתוֹ שׁוֹפָר עֶלְיוֹן. וּכְשֶׁחוֹזֵר, מְעַטֵּר אֶת יַעֲקֹב, וְהַכֹּל נִתְקָן. וְכִסֵּא אַחֵר עוֹלֶה, וְאָז נִמְצֵאת שִׂמְחָה בַּכֹּל, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְרַחֵם עַל הָעוֹלָם. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁיּוֹדְעִים לְהַנְהִיג וְלִמְשֹׁךְ אֶת רִבּוֹנָם מִדִּין לְרַחֲמִים, וּלְתַקֵּן אֶת כָּל הָעוֹלָמוֹת עַל יְדֵיהֶם.</p>\n<p>בֹּא רְאֵה, כְּנֶגֶד זֶה נִפְתָּחִים שְׁלֹשָׁה סְפָרִים בְּיוֹם זֶה, וּכְמוֹ שֶׁרַחֲמִים מִתְעוֹרְרִים וְהַדִּינִים הַקָּשִׁים נִכְנָעִים וְנִכְנָסִים לִמְקוֹמָם - כָּךְ הוּא לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, הַדִּינִים הַקָּשִׁים נִכְנָעִים וּמָעֳבָרִים מִן הָעוֹלָם. וּמִי הֵם? אֵלּוּ אוֹתָם רְשָׁעִים גְּמוּרִים, שֶׁהֵם דִּינִים קָשִׁים שֶׁנִּכְנְעוּ וְהָעָבְרוּ מִן הָעוֹלָם. וְעַל כֵּן נִכְתָּבִים וְנֶחְתָּמִים וְכוּ'. אָמַר רַבִּי אַבָּא, וַדַּאי זֶהוּ בֵּרוּר הַדָּבָר. בָּרוּךְ הָרַחֲמָן שֶׁשָּׁאַלְתִּי וְהִרְוַחְתִּי אֶת הַדְּבָרִים הַלָּלוּ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּתוּב זִכְרוֹן תְּרוּעָה, עוֹשִׂים זִכָּרוֹן, לְכַוֵּן אֶת הַלֵּב וְהָרָצוֹן. יִשְׂרָאֵל עוֹשִׂים זִכָּרוֹן לְמַטָּה, בַּמֶּה? בְּמַעֲשֶׂה, כְּדֵי שֶׁיִּתְעוֹרֵר דָּבָר בְּאוֹתוֹ גָוֶן שֶׁלְּמַעְלָה.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, כָּתוּב (תהלים פא) בַּכֶּסֶה לְיוֹם חַגֵּנוּ, שֶׁמִּתְכַּסָּה בּוֹ הַלְּבָנָה. וְאֵיךְ מִתְכַּסָּה? אֶלָּא כְּשֶׁעוֹמֵד עָנָן וְהַשֶּׁמֶשׁ אֵינוֹ מֵאִיר, אֲזַי הַלְּבָנָה מִתְכַּסָּה וְלֹא מְאִירָה. וְעַל כֵּן מִלִּפְנֵי עָנָן הַשֶּׁמֶשׁ אֵינָהּ מְאִירָה, כָּל שֶׁכֵּן הַלְּבָנָה שֶׁמִּתְכַּסָּה וְאֵינָהּ מְאִירָה. וְעַל כֵּן בַּכֶּסֶה לְיוֹם חַגֵּנוּ, בְּהֵ\"א, שֶׁמִּתְכַּסָּה הַלְּבָנָה. וּבַמֶּה מְאִירָה? הַכֹּל בִּתְשׁוּבָה, וּבְקוֹל שׁוֹפָר, שֶׁכָּתוּב אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה. אָז - ה' בְּאוֹר פָּנֶיךְ יְהַלֵּכוּן.</p>"],[9522012223,"<p>בַּחֹדֶשׁ הַשְּׁבִיעִי בְּאֶחָד לַחֹדֶשׁ וְגוֹ'. מִצְוָה זוֹ לִתְקֹעַ שׁוֹפָר בְּרֹאשׁ הַשָּׁנָה, שֶׁהוּא יוֹם הַדִּין לָעוֹלָם, כְּמוֹ שֶׁבֵּאַרְנוּ. וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. וַהֲרֵי נִתְבָּאֵר. שֶׁזֶּהוּ יוֹם שֶׁבּוֹ מִתְכַּסָּה הַלְּבָנָה, וְהָעוֹלָם עוֹמֵד בְּדִין. מִשּׁוּם שֶׁאוֹתוֹ הַמְקַטְרֵג חוֹפֶה וּמְכַסֶּה וְנוֹעֵל אֶת הַפֶּתַח עַל הַמֶּלֶךְ, הַמָּקוֹם שֶׁהַדִּין שׁוֹרֶה לִתְבֹּעַ דִּין עַל הָעוֹלָם.</p>\n<p>וְאִם תֹּאמַר, אֵיךְ נִתֶּנֶת רְשׁוּת לְאוֹתוֹ הַמְקַטְרֵג לְכַסּוֹת וְלִתְבֹּעַ דִּין? אֶלָּא וַדַּאי בְּיַד הַמְקַטְרֵג הַזֶּה שָׂם הַקָּדוֹשׁ בָּרוּךְ הוּא לִתְבֹּעַ דִּין עַל כָּל הָעוֹלָם, וְשָׂם לוֹ יוֹם יָדוּעַ לִתְבֹּעַ לְפָנָיו אֶת כָּל דִּינֵי הָעוֹלָם, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אוֹתוֹ וְשָׂם אוֹתוֹ לְפָנָיו, שֶׁתִּהְיֶה יִרְאַת הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹלָה וְשׁוֹרָה עַל הַכֹּל. וְסוֹד זֶה - (קהלת ג) וְהָאֱלֹהִים עָשָׂה שֶׁיִּרְאוּ מִלְּפָנָיו. מֶה עָשָׂה? עָשָׂה אֶת הַמְקַטְרֵג הַזֶּה וְהִתְקִין אוֹתוֹ לְפָנָיו לִהְיוֹת חֶרֶב שְׁנוּנָה עַל כָּל הָעוֹלָם, וְכָל זֶה כְּדֵי שֶׁיִּירְאוּ כֻלָּם מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְזֶהוּ הַשּׁוֹטֵר שֶׁתּוֹבֵעַ אֶת חֲטָאֵי בְּנֵי הָאָדָם, וְתוֹבֵעַ דִּין, וְתוֹפֵס בְּנֵי אָדָם וְהוֹרֵג אוֹתָם, וּמַלְקֶה אוֹתָם, הַכֹּל כְּפִי שֶׁיּוֹצֵא מִן הַדִּין.</p>\n<p>כְּמוֹ אוֹתוֹ הַמְמֻנֶּה שֶׁל בֵּית הַדִּין שֶׁלְּמַטָּה, שֶׁנִּתְּנָה לוֹ רְשׁוּת לְהַזְכִּיר לִפְנֵי בֵּית הַדִּין: פְּלוֹנִי עָשָׂה כָּךְ, וּפְלוֹנִי עָבַר עַל כָּךְ. וְלִתְבֹּעַ עֲלֵיהֶם דִּין. וְשָׁנִינוּ, נִתְּנָה רְשׁוּת לְאוֹתוֹ מְמֻנֶּה בֵּית דִּין לִנְעֹל עַל בֵּית הַדִּין אֶת הַפֶּתַח עַד שֶׁיִּגְזְרוּ דִין עַל כָּל מַה שֶּׁהוּא תּוֹבֵעַ, וְאֵין רְשׁוּת לְבֵית הַדִּין לִדְחוֹת אוֹתוֹ, מִשּׁוּם (ישעיה סא) כִּי אֲנִי ה' אוֹהֵב מִשְׁפָּט. וְהוּא רוֹצֶה שֶׁהָעוֹלָם יַעֲמֹד בְּדִין, וּלְהוֹדִיעַ שֶׁיֵּשׁ דִּין וְיֵשׁ דַּיָּן.</p>\n<p>כְּמוֹ זֶה שָׂם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת זֶה לְפָנָיו, שֶׁהוּא תּוֹבֵעַ דִּין לִפְנֵי הַמֶּלֶךְ עַל כָּל בְּנֵי הָעוֹלָם, וּבַיּוֹם הַזֶּה נִתֶּנֶת לוֹ רְשׁוּת לְכַסּוֹת אֶת פֶּתַח הַמֶּלֶךְ, וְהַלְּבָנָה מִתְכַּסָּה לְפָנִים, עַד שֶׁיִּגָּזֵר הַדִּין עַל כָּל בְּנֵי הָעוֹלָם. וְאַף עַל גַּב שֶׁהַכֹּל גָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא צָרִיךְ אֶלָּא בְדִין.</p>\n<p>הַכֹּל כְּגָוֶן אֶחָד מַעְלָה וּמַטָּה, הִתְקִין כִּסֵּא דִין בַּיּוֹם הַזֶּה, וְהַשּׁוֹטֵר בָּא וְתוֹבֵעַ דִּין עַל כָּל מַעֲשֵׂי הָעוֹלָם, כָּל אֶחָד וְאֶחָד כְּפִי דַרְכּוֹ וּכְפִי מַה שֶּׁעָשָׂה, וְהָעֵדִים בָּאִים וּמְעִידִים עַל כָּל מַעֲשֵׂי בְּנֵי הָעוֹלָם. וְאֵלּוּ הֵם עֵינֵי ה', שֶׁהֵם מְשׁוֹטְטִים בְּכָל הָעוֹלָם. וְכַמָּה הֵם עֵינֵי ה', שֶׁאֵין לָהֶם חֶשְׁבּוֹן, שֶׁהוֹלְכִים וּמְשׁוֹטְטִים בְּכָל הָעוֹלָם, וְרוֹאִים כָּל מַעֲשֵׂי בְּנֵי הָעוֹלָם.</p>\n<p>אוֹי לְאוֹתָם שֶׁאֵינָם מַשְׁגִּיחִים וְלֹא מִסְתַּכְּלִים בְּמַעֲשֵׂיהֶם, שֶׁהֲרֵי לְגַבֵּיהֶם עוֹמְדִים הָעֵדִים שֶׁל הַמֶּלֶךְ הַלָּלוּ, וּמַשְׁגִּיחִים וְרוֹאִים אֶת כָּל מַה שֶּׁהֵם עוֹשִׂים, וְאוֹמְרִים, שֶׁהֲרֵי הֵם עוֹלִים וּמְעִידִים לִפְנֵי הַמֶּלֶךְ, וְהַשּׁוֹטֵר הַזֶּה עוֹמֵד לִפְנֵי הַמֶּלֶךְ וְתוֹבֵעַ דִּין: פְּלוֹנִי עָבַר עַל דִּין, וּפְלוֹנִי עָשָׂה כָּךְ. וַהֲרֵי כָּאן עֵדִים. וְעַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא שׁוֹאֵל אוֹתָם, אֵין לָהֶם רְשׁוּת לְהָעִיד, אָז הֵם עֵדִים שֶׁל הָעֵדוּת.</p>\n<p>וְהַכֹּל נִכְתָּב לִפְנֵי הַמֶּלֶךְ בְּפֶתֶק. בְּבֵית הַמֶּלֶךְ יֵשׁ הֵיכָל אֶחָד. הַהֵיכָל הַזֶּה מָלֵא בְּאֵשׁ לְבָנָה, וְהָאֵשׁ הַזּוֹ מִתְגַּלְגֶּלֶת בְּעִגּוּל, וְהַשְּׁבִיבִים לוֹהֲטִים, וְזֶה לֹא פוֹסֵק לְעוֹלָמִים. בְּתוֹךְ הַהֵיכָל הַזֶּה יֵשׁ הֵיכָל אַחֵר מָלֵא אֵשׁ שְׁחוֹרָה, שֶׁלֹּא פוֹסֶקֶת לְעוֹלָמִים. שְׁנֵי סוֹפְרִים עוֹמְדִים תָּמִיד לִפְנֵי הַמֶּלֶךְ. בִּשְׁעַת הַדִּין מְעִידִים כָּל הָעֵדִים לִפְנֵי הַמֶּלֶךְ. אוֹתָם עֵדִים נ\"א סוֹפְרִים) נוֹטְלִים מֵאוֹתוֹ עִגּוּל שֶׁל אֵשׁ לְבָנָה, וְכוֹתְבִים עָלָיו בְּאוֹתָהּ הָאֵשׁ הַשְּׁחֹרָה.</p>\n<p>וְאָז הַמֶּלֶךְ מְעַכֵּב אֶת הַדִּין עַד זְמַן יָדוּעַ, אוּלַי בֵּין כָּךְ וּבֵין כָּךְ יַחְזְרוּ בִתְשׁוּבָה. אִם יַחְזְרוּ - נִקְרָעִים הַפְּתָקִים. וְאִם לֹא - הַמֶּלֶךְ יוֹשֵׁב, וְכָל אוֹתָם שֶׁל בֵּית הַזְּכוּת עוֹמְדִים לְפָנָיו, הַכָּרוֹז קָם וּמַכְרִיז: פְּלוֹנִי עָשָׂה כָּךְ, מִי יְלַמֵּד עָלָיו זְכוּת? אִם יֵשׁ מִי שֶׁיְּלַמֵּד עָלָיו זְכוּת - יָפֶה. וְאִם לֹא - הוּא נִמְסָר לַשּׁוֹטֵר.</p>\n<p>וְהַכֹּל יוֹדֵעַ הַקָּדוֹשׁ בָּרוּךְ הוּא לָמָּה צָרִיךְ אֶת כָּל זֶה? שֶׁלֹּא כְּדֵי שֶׁלֹּא יִהְיֶה פִּתְחוֹן פֶּה לִבְנֵי הָעוֹלָם, אֶלָּא לְהַרְאוֹת שֶׁהַכֹּל עוֹשֶׂה בְּדֶרֶךְ אֱמֶת, וְנוֹחַ לְפָנָיו מִי שֶׁנִּצָּל מִן הַדִּין. וְאִם תֹּאמַר, מִנַּיִן לָנוּ? זֶה נִמְסַר לַחֲכָמִים. וַאֲפִלּוּ לְמִי שֶׁאֵין יוֹדְעִים, מִי שֶׁרוֹצֶה לְהִסְתַּכֵּל, יַשְׁגִּיחַ בְּמַה שֶּׁהוּא בְּנִגְלֶה, וְיֵדַע מַה שֶּׁהוּא בְּנִסְתָּר, שֶׁהֲרֵי הַכֹּל בְּגָוֶן אֶחָד. כָּל מַה שֶּׁמִּנָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ, הַכֹּל הוּא כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>הַיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה הוּא יוֹם הַדִּין, וְהַמֶּלֶךְ יוֹשֵׁב בְּכִסֵּא הַדִּין, הַשּׁוֹטֵר בָּא וּמְכַסֶּה אֶת פֶּתַח הַמֶּלֶךְ וְתוֹבֵעַ דִּין. וְאַף עַל גַּב שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֵב אֶת הַדִּין, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סא) כִּי אֲנִי ה' אוֹהֵב מִשְׁפָּט, מְנַצַּחַת אַהֲבַת בָּנָיו אֶת אַהֲבַת הַדִּין. וּבְשָׁעָה שֶׁהַשּׁוֹטֵר קָם לִטְעֹן דְּבָרִים עֲלֵיהֶם, הוּא מְצַוֶּה לִתְקֹעַ בַּשּׁוֹפָר, כְּדֵי לְעוֹרֵר רַחֲמִים מִלְּמַטָּה לְמַעְלָה בְּאוֹתוֹ שׁוֹפָר.</p>\n<p>אוֹתוֹ הַקּוֹל עוֹלֶה, כָּלוּל בְּאֵשׁ רוּחַ וּמַיִם, וְנַעֲשֶׂה מֵהֶם קוֹל אֶחָד, וּמִתְעוֹרֵר קוֹל אַחֵר לְמַעְלָה. כְּשֶׁאוֹתוֹ הַקּוֹל מִתְעוֹרֵר מִמַּעְלָה וּמִמַּטָּה, אֲזַי כָּל הַטְּעָנוֹת שֶׁטּוֹעֵן אוֹתוֹ מְקַטְרֵג מִתְעַרְבְּבוֹת.</p>\n<p>בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה יוֹצֵא יִצְחָק לְבַדּוֹ, וְקוֹרֵא לְעֵשָׂו, לְהַטְעִים אוֹתוֹ תַּבְשִׁילִים שֶׁל כָּל הָעוֹלָם, כָּל אֶחָד כְּפִי דַרְכּוֹ, שֶׁהֲרֵי בְּאוֹתָהּ הַשָּׁעָה (בראשית כז) וַתִּכְהֶיןָ עֵינָיו מֵרְאֹת, שֶׁיָּצָא מִמֶּנּוּ מִי שֶׁהֶחְשִׁיךְ אֶת פְּנֵי הַבְּרִיּוֹת, וְנִפְרַד, וְשׁוֹכֵב עַל מִטַּת הַדִּין, וְקוֹרֵא לְעֵשָׂו וְאוֹמֵר, וְצוּדָה לִּי צָיִדה וַעֲשֵׂה לִי מַטְעַמִּים, וְהָבִיאָה לִּי.</p>\n<p>וְרִבְקָה אָמְרָה אֶל יַעֲקֹב בְּנָהּ, אֲהוּב נַפְשָׁהּ, הַבֵּן הָאָהוּב שֶׁנִּמְסַר לָהּ מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, וּמְצַוָּה אוֹתוֹ שֶׁהוּא יִתְעוֹרֵר בְּאוֹתָם מַטְעַמִּים שֶׁלּוֹ. וְיַעֲקֹב מִתְעוֹרֵר מִלְּמַטָּה, מְלֻבָּשׁ בִּתְפִלּוֹת וּבְבַקָּשׁוֹת, וְהַקֹּל קוֹל יַעֲקֹב בְּאוֹתוֹ שׁוֹפָר שֶׁעוֹלֶה, וּמִתְעוֹרֵר יַעֲקֹב אֵלָיו, וְנִקְרָב עִמּוֹ, וַיַּגֶּשׁ לוֹ וַיֹּאכַל, וְנִכְלָלִים זֶה עִם זֶה. כֵּיוָן שֶׁנִּכְלָל עִמּוֹ, וַיָּבֵא לוֹ יַיִן, זֶה יַיִן הַמְשֻׁמָּר, הַיַּיִן שֶׁהוּא שִׂמְחַת הַלֵּב, הַסּוֹד שֶׁל הָעוֹלָם הַבָּא. אָז - וַיָּרַח אֶת רֵיחַ בְּגָדָיו, הַתְּפִלּוֹת שֶׁעוֹלוֹת וְהַבַּקָּשׁוֹת. וַיְבָרֲכֵהוּ, נָח הָרֹגֶז וְשָׂמֵחַ הַלֵּב, וְהַכֹּל הוּא רַחֲמִים.</p>\n<p>כֵּיוָן שֶׁנִּכְלַל בְּיַעֲקֹב, כָּל אוֹתָם חֲיָלוֹת וּגְבוּרוֹת שֶׁהָיוּ מְזֻמָּנִים הִתְפַּזְּרוּ, וְלֹא נִמְצְאוּ שָׁם. וְיִשְׂרָאֵל יוֹצְאִים מִן הַדִּין בְּשִׂמְחָה וּבִבְרָכוֹת. וַיְהִי אַךְ יָצֹא יָצָא יַעֲקֹב מֵאֵת פְּנֵי יִצְחָק אָבִיו, בַּיּוֹם הַזֶּה, בְּשִׂמְחָה וּבִבְרָכוֹת עֶלְיוֹנוֹת, וְעֵשָׂו אָחִיו בָּא מִצֵּידוֹ, טוֹעֵן טְעָנוֹת מִמַּעֲשֵׂי הָעוֹלָם, וַיַּעַשׂ גַּם הוּא מַטְעַמִּים, לְשׁוֹנוֹ חַדָּה לִטְעֹן טְעָנוֹת. מְסַדֵּר עֵדִים, וַיָּבֵא לְאָבִיו וַיֹּאמֶר יָקֻם אָבִי, יִתְעוֹרֵר עִם דִּינָיו, וְיֹאכַל כַּמָּה מַעֲשִׂים רָעִים שֶׁל כָּל הָעוֹלָם שֶׁמָּצָאתִי.</p>\n<p>וַיֶּחֱרַד יִצְחָק חֲרָדָה גְּדֹלָה עַד מְאֹד, שֶׁהֲרֵי אֵינוֹ יָכוֹל לְהִפָּרֵד מִכְּלָל שֶׁל יַעֲקֹב, שֶׁהוּא בְשִׂמְחָה. וַיֹּאמֶר מִי אֵפוֹא הוּא הַצָּד צַיִד, בְּכַמָּה תְפִלּוֹת וּבַקָּשׁוֹת, וָאֹכַל מִכֹּל בְּטֶרֶם תָּבוֹא וַאֲבָרֲכֵהוּ גַּם בָּרוּךְ יִהְיֶה. כִּשְׁמֹעַ עֵשָׂו אֶת דִּבְרֵי (יִצְחָק) אָבִיו וַיִּצְעַק צְעָקָה גְּדֹלָה וְגוֹ', שֶׁרָאָה שֶׁהֲרֵי צֵידוֹ לֹא הָיָה כְלוּם. עַד לְאַחַר שֶׁאָמַר לוֹ, הִנֵּה מִשְׁמַנֵּי הָאָרֶץ וְגוֹ', אֵלּוּ הַחֲזָקִים וְהַהֲמוֹנִים שֶׁל שְׁאָר הָעַמִּים, וְזֶה קָשֶׁה לוֹ מֵהַכֹּל. וַיִּשְׂטֹם עֵשָׂו אֶת יַעֲקֹב, לָלֶכֶת אַחֲרָיו וּלְהִתְגָּרוֹת בּוֹ תָּמִיד.</p>\n<p>וְיַעֲקֹב הָלַךְ בְּאוֹתָם יָמִים שֶׁבֵּין רֹאשׁ הַשָּׁנָה לְיוֹם הַכִּפּוּרִים, בָּרַח לְהִנָּצֵל מִמֶּנּוּ. שָׁב בִּתְשׁוּבָה, וְשָׂם עַצְמוֹ בְּתַעֲנִית, עַד שֶׁבָּא רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים, אָז יוֹדְעִים יִשְׂרָאֵל שֶׁעֵשָׂו בָּא, וְעִמּוֹ אַרְבַּע מֵאוֹת אִישׁ, כֻּלָּם מְקַטְרְגִים מְזֻמָּנִים לְקַטְרֵג לָהֶם. מִיָּד - וַיִּירָא יַעֲקֹב מְאֹד וַיֵּצֶר לוֹ, וְהִרְבָּה בִּתְפִלּוֹת וּבַקָּשׁוֹת. (בראשית לב) וַיֹּאמֶר יַעֲקֹב אֱלֹהֵי אָבִי אַבְרָהָם וֵאלֹהֵי אָבִי וְגוֹ'. עַד שֶׁנָּטַל עֵצָה וְאָמַר, כִּי אָמַר אֲכַפְּרָה פָנָיו בַּמִּנְחָה הַהֹלֶכֶת לְפָנָי. וַיִּקַּח מִן הַבָּא בְיָדוֹ מִנְחָה וְגוֹ', עִזִּים מָאתַיִם וּתְיָשִׁים עֶשְׂרִים רְחֵלִים מָאתַיִם וְגוֹ'.</p>\n<p>גְּמַלִּים וְגוֹ', כָּךְ הוּא הַצַּד שֶׁלּוֹ. גְּמַלִּים הוּא נָחָשׁ, כְּמִין גָּמָל. בְּשָׁעָה שֶׁפִּתָּה סָמָאֵ\"ל אֶת אָדָם, רָכַב עַל נָחָשׁ כְּמִין גָּמָל. שָׁנִינוּ, מִי שֶׁרוֹאֶה גָמָל בַּחֲלוֹמוֹ, מִיתָה נִקְנְסָה עָלָיו מִלְמַעְלָה וְנִצּוֹל מִמֶּנָּה. וְהַכֹּל אֶחָד.</p>\n<p>וְאָז חָזַר עֵשָׂו לְאַפּוֹטְרוֹפּוֹס שֶׁל יַעֲקֹב, וְיַעֲקֹב לֹא רָצָה דֻבְשׁוֹ וְעֻקְצוֹ. יַעֲבָר נָא אֲדֹנִי לִפְנֵי עַבְדּוֹ. אָז - וַיָּשָׁב בַּיּוֹם הַהוּא עֵשָׂו לְדַרְכּוֹ. מָתַי? בִּשְׁעַת נְעִילָה, שֶׁהֲרֵי נִפְרָד מִן הָעָם הַקָּדוֹשׁ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹזֵב אֶת חֲטָאֵיהֶם וּמְכַפֵּר עֲלֵיהֶם. כֵּיוָן שֶׁאוֹתוֹ הַמְקַטְרֵג הוֹלֵךְ עִם אוֹתוֹ דוֹרוֹן וְנִפְרָד מֵהֶם, רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׂמֹחַ עִם בָּנָיו. מַה כָּתוּב? וְיַעֲקֹב נָסַע סֻכֹּתָה וַיִּבֶן לוֹ בָּיִת וְגוֹ'. עַל כֵּן קָרָא שֵׁם הַמָּקוֹם סֻכּוֹת. כֵּיוָן שֶׁיּוֹשְׁבִים בַּסֻּכּוֹת, הֲרֵי נִצּוֹלוּ מִן הַמְקַטְרֵג, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שָׂמֵחַ עִם בָּנָיו. אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. (ע\"כ רעיא מהימנא).</p>"],[9522012224,"<p>בֹּא רְאֵה, בַּיּוֹם הַזֶּה מִתְכַּסָּה הַלְּבָנָה, וְלֹא מְאִירָה עַד בֶּעָשׂוֹר לַחֹדֶשׁ, כְּשֶׁכָּל יִשְׂרָאֵל שָׁבִים בִּתְשׁוּבָה, וְהָאֵם הָעֶלְיוֹנָה שָׁבָה וּמְאִירָה לָהּ. וְהַיּוֹם הַזֶּה אֶת אוֹר הָאֵם נוֹטֵל, וְנִמְצֵאת שִׂמְחָה בַּכֹּל. וְעַל כֵּן כָּתוּב, יוֹם הַכִּפֻּרִים הוּא. יוֹם כִּפּוּר הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה יוֹם הַכִּפֻּרִים? אֶלָּא מִשּׁוּם שֶׁשְּׁנֵי מְאוֹרוֹת מְאִירִים כְּאֶחָד. הַמָּאוֹר הָעֶלְיוֹן מֵאִיר לַמָּאוֹר הַתַּחְתּוֹן, וּבַיּוֹם הַזֶּה מֵאִיר מֵהָאוֹר הָעֶלְיוֹן, וְלֹא מֵאוֹר הַשֶּׁמֶשׁ, וּמִשּׁוּם כָּךְ כָּתוּב בַּכֶּסֶה לְיוֹם חַגֵּנוּ.</p>\n<p>רַבִּי אַבָּא שָׁלַח לְרַבִּי שִׁמְעוֹן. אָמַר, מָתַי הַזִּוּוּג שֶׁל כְּנֶסֶת יִשְׂרָאֵל עִם הַמֶּלֶךְ הַקָּדוֹשׁ? שָׁלַח לוֹ, (בראשית כ) וְגַם אָמְנָה אֲחֹתִי בַת אָבִי הִיא אַךְ לֹא בַת אִמִּי וַתְּהִי לִי לְאִשָּׁה. הִתְרַגֵּשׁ רַבִּי אַבָּא, הֵרִים קוֹלוֹ, בָּכָה וְאָמַר, רַבִּי רַבִּי מְנוֹרָה הַקְּדוֹשָׁה, אוֹי וַאֲבוֹי לָעוֹלָם כְּשֶׁתֵּצֵא מִמֶּנּוּ! אוֹי לַדּוֹר שֶׁיִּהְיו בָעוֹלָם כְּשֶׁתִּסְתַּלֵּק מֵהֶם וְיִשָּׁאֲרוּ יְתוֹמִים מִמְּךְ! אָמַר לוֹ רַבִּי חִיָּיא לְרַבִּי אַבָּא, זֶה שֶׁשָּׁלַח לְעֻמָּתְךְ, מָה אָמַר?</p>\n<p>אָמַר, וַדַּאי שֶׁאֵין זִוּוּג הַמֶּלֶךְ עִם הַגְּבִירָה אֶלָּא בִּזְמַן שֶׁמֵּאִיר מֵהָאָב הָעֶלְיוֹן, וּכְשֶׁנָּאוֹר מִמֶּנּוּ, קוֹרְאִים לוֹ קֹדֶשׁ, שֶׁהֲרֵי מִבֵּית אַבָּא זֶה נוֹטֵל, וְאָז מִזְדַּוְּגִים כְּאֶחָד, מִשּׁוּם שֶׁהַמֶּלֶךְ נִקְרָא קֹדֶשׁ, שֶׁכָּתוּב (ירמיה כ) קֹדֶשׁ יִשְׂרָאֵל לַה', שֶׁנּוֹטֵל מִמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ. אֲזַי אֲחֹתִי בַת אָבִי הִוא אַךְ לֹא בַת אִמִּי, שֶׁהֲרֵי מִבֵּית אַבָּא הַשֵּׁם הַזֶּה, וְלֹא מִבֵּית אִמָּא. וְעַל כֵּן וַתְּהִי לִי לְאִשָּׁה, לְהִזְדַּוֵּג כְּאֶחָד, בַּזְּמַן הַזֶּה וְלֹא בִּזְמַן אַחֵר, בִּזְמַן שֶׁנּוֹטְלִים מִבֵּית אַבָּא, וְלֹא בִּזְמַן שֶׁנּוֹטְלִים מִבֵּית אִמָּא. וְיוֹם הַכִּפּוּרִים מוֹכִיחַ, שֶׁתַּשְׁמִישׁ הַמִּטָּה אָסוּר, מִשּׁוּם שֶׁאֵין נִמְצָא זִוּוּג, שֶׁהֲרֵי מִבֵּית אִמָּא נוֹטֵל, וְלֹא מִבֵּית אַבָּא. אָמַר רַבִּי חִיָּיא, וַדַּאי אַשְׁרֵי הַדּוֹר שֶׁרַבִּי שִׁמְעוֹן שָׁרוּי בְּתוֹכוֹ. אַשְׁרֵי אוֹתָם שֶׁעוֹמְדִים לְפָנָיו כָּל יוֹם.</p>\n<p>אָמַר רַבִּי אַבָּא, בְּרֹאשׁ הַשָּׁנָה נִבְרָא אָדָם, וְעָמַד בְּדִין לִפְנֵי אֲדוֹנוֹ וְשָׁב בִּתְשׁוּבָה, וְקִבֵּל אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר לוֹ, אָדָם, אַתָּה תִּהְיֶה סִימָן לְבָנֶיךְ לְדוֹרֵי דוֹרוֹת, בַּיּוֹם הַזֶּה יַעַמְדוּ בְדִין. אִם יָשׁוּבוּ, אֲנִי אֲקַבֵּל אוֹתָם, וְאֶעֱמֹד מִכִּסֵּא דִין, וְאֶתְיַשֵּׁב עַל כִּסֵּא רַחֲמִים וַאֲרַחֵם עֲלֵיהֶם. וְדָוִד אָמַר, (תהלים קד) אָהַבְתִּי כִּי יִשְׁמַע ה' אֶת קוֹלִי תַּחֲנוּנָי. וְעַל זֶה כָּתוּב, (שם קל) כִּי עִמְּךְ הַסְּלִיחָה לְמַעַן תִּוָּרֵא. וְכָתוּב, (שם לו) כִּי עִמְּךְ מְקוֹר חַיִּים בְּאוֹרְךְ נִרְאֶה אוֹר. מִצְוָה זוֹ, לְהִתְעַנּוֹת בְּיוֹם הַכִּפּוּרִים, לְהַכְנִיעַ אֶת הַגּוּף וְאֶת הַנֶּפֶשׁ, בְּסוֹד שֶׁל חֲמִשָּׁה עִנּוּיִים שֶׁל חָמֵשׁ דְּרָגוֹת שֶׁל יוֹם הַכִּפּוּרִים. שֶׁהֲרֵי הַמְקַטְרֵג בָּא לְהַזְכִּיר אֶת חֲטָאֵיהֶם, כְּמוֹ שֶׁנִּתְבָּאֵר, וְכֻלָּם בִּתְשׁוּבָה שְׁלֵמָה לִפְנֵי אֲבִיהֶם. הַכֹּל כְּמוֹ שֶׁנֶּאֱמַר בְּכַמָּה מְקוֹמוֹת. (ע\"כ רעיא מהימנא).</p>\n<p>אַךָ בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה יוֹם הַכִּפֻּרִים הוּא מִקְרָא קֹדֶשׁ יִהְיֶה לָכֶם. רַבִּי חִיָּיא פָּתַח, (שם לב) לְדָוִד מַשְׂכִּיל אַשְׁרֵי נְשׂוּי פֶּשַׁע כְּסוּי חֲטָאָה. לְדָוִד מַשְׂכִּיל, הֲרֵי שָׁנִינוּ, בַּעֲשָׂרָה מִינֵי זֶמֶר נִקְרָא (נתקן) סֵפֶר תְּהִלִּים: בְּנִצּוּחַ, בְּנִגּוּן, בְּמַשְׂכִּיל, בְּמִכְתָּם, בְּמִזְמוֹר, בְּשִׁיר, בְּאַשְׁרֵי, בִּתְפִלָּה, בְּהוֹדָאָה, בְּהַלְלוּיָהּ. וְהָעֶלְיוֹן מִכֻּלָּם - הַלְלוּיָהּ, וַהֲרֵי פֵּרְשׁוּהָ. דַ יָּא מְהֵיּמְנָא</p>\n<p>כָּאן מַשְׂכִּיל, מְקוֹמוֹ יָדוּעַ. מַהוּ מַשְׂכִּיל? מַיִם שֶׁמַּחְכִּימִים אֶת אוֹתָם שֶׁשּׁוֹתִים אוֹתָם, אוֹתוֹ הַמָּקוֹם (שמשתדלים באותו מקום) שֶׁנִּקְרָא מַשְׂכִּיל, כְּמוֹ שֶׁנֶּאֱמַר (משלי יז) מַשְׂכִּיל עַל דָּבָר יִמְצָא טוֹב. וּמִשּׁוּם שֶׁנִּקְרָא כָּךְ, תְּלוּיָה בּוֹ סְלִיחָה, חֵרוּת הַחֵרֻיּוֹת. זֶהוּ שֶׁכָּתוּב אַשְׁרֵי נְשׂוּי פֶּשַׁע כְּסוּי חֲטָאָה.</p>\n<p>מַה זֶּה כְּסוּי חֲטָאָה? הֲרֵי פֵּרְשׁוּהָ, שֶׁהוּא כִּסּוּי מִבְּנֵי אָדָם אוֹתוֹ חֵטְא שֶׁחָטָא לַקָּדוֹשׁ בָּרוּךְ הוּא וְהוֹדָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אֲבָל (כסוי חטָאָה) בא ראה, כשאדם חוטא, ומתחיב פעם אחת ופעמים ושלש ולא חוזר בו, הרי חטאיו הם בגלוי, ומפרסמים אותם למעלה, ומפרסמים אותם למטה. והכרוזים הולכים לפניו ומכריזים: הסתלקו מסביב לפלוני, נזוף הוא מאדונו, נזוף הוא למעלה, נזוף הוא למטה, אוי לו שפגם את דיוקן רבונו! אוי לו שאינו חושש על כבוד רבונו! הקדוש ברוך הוא מגלה חטאו למעלה. זהו שכתוב, (איוב כ) יגלו שמים עונו וארץ מתקוממה לו. וכשאדם הולך בדרך רבונו ומשתדל בעבודתו, והזדמן לו חטא אחד - הכל מכסים עליו, עליונים ותחתונים, זה נקרא כסוי חטאה.</p>\n<p>אָמַר לוֹ רַבִּי אַבָּא, עַד עַכְשָׁו לֹא הִגַּעְתָּ לְעִקַּר הַדָּבָר, וְיָפֶה אָמַרְתָּ. וְזֶהוּ שֶׁאָמְרוּ הַחֲבֵרִים - יָפֶה. אֲבָל אִם כָּךְ, מְכֻסֶּה חֲטָאָה הָיָה צָרִיךְ לִהְיוֹת! מַהוּ כְּסוּי חֲטָאָה?</p>\n<p>אֶלָּא שְׁנֵי דִּבְרֵי חָכְמָה יֵשׁ בּוֹ, וּשְׁנֵיהֶם כָּךְ. אֶחָד, כְּמוֹ שֶׁשָּׁנִינוּ, שֶׁמַּעֲשִׂים טוֹבִים שֶׁאָדָם עוֹשֶׂה בָּעוֹלָם הַזֶּה, עוֹשִׂים לוֹ בְּאוֹתוֹ הָעוֹלָם לְבוּשׁ נִכְבָּד עֶלְיוֹן לְהִתְלַבֵּשׁ בָּהֶם. וּכְשֶׁאָדָם מְתַקֵּן מַעֲשִׂים טוֹבִים, וְגוֹבְרִים עָלָיו מַעֲשִׂים רָעִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ בּוֹ, וּמַעֲשָׂיו הָרָעִים רַבִּים, וְהוּא רָשָׁע, שֶׁנִּמְצָא חוֹטֵא לִפְנֵי אֲדוֹנוֹ, וְתוֹהֶה עַל אוֹתָן טוֹבוֹת שֶׁעָשָׂה בָּרִאשׁוֹנָה, הֲרֵי נֶאֱבָד הוּא מִן הַכֹּל, מֵהָעוֹלָם הַזֶּה וּמֵהָעוֹלָם הַבָּא. מָה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתָן טוֹבוֹת שֶׁעָשָׂה הַחוֹטֵא הַזֶּה בָּרִאשׁוֹנָה?</p>\n<p>אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא, אַף עַל גַּב שֶׁאוֹתוֹ רָשָׁע חוֹטֵא נֶאֱבָד, אוֹתָן טוֹבוֹת וּזְכֻיּוֹת לֹא נֶאֱבָדוֹת. יֵשׁ צַדִּיק שֶׁהוֹלֵךְ בְּדַרְכֵי הַמֶּלֶךְ הָעֶלְיוֹן וּמַתְקִין לְבוּשָׁיו מִמַּעֲשָׂיו, וְטֶרֶם שֶׁהִשְׁלִים אֶת לְבוּשָׁיו הִסְתַּלֵּק - הַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁלִים לוֹ מֵאוֹתָם הַמַּעֲשִׂים שֶׁעָשָׂה (שאבד) הָרָשָׁע הַחוֹטֵא הַזֶּה, וּמַשְׁלִים אֶת לְבוּשָׁיו שֶׁיִּתְתַּקֵּן בָּהֶם בְּאוֹתוֹ עוֹלָם. זֶהוּ שֶׁכָּתוּב (שם כז) יָכִין וְצַדִּיק יִלְבָּשׁ. אוֹתוֹ חוֹטֵא הִתְקִין, וְהַצַּדִּיק מִתְכַּסֶּה מִמַּה שֶּׁהוּא הִתְקִין. זֶהוּ שֶׁכָּתוּב כְּסוּי חֲטָאָה, (הכסוי הוא מזה החטאה, מתכסה מהחטאה) וְעַל כֵּן לֹא כָתוּב מְכֻסֶּה, אֶלָּא כְּסוּי.</p>\n<p>וְאֶחָד, שֶׁהִתְכַּסָּה אוֹתוֹ הַחֵטְא שֶׁל הַצַּדִּיק הַזֶּה בְּאוֹתָם שֶׁנִּקְרָאִים מְצוּלוֹת יָם, שֶׁהֲרֵי מִי שֶׁנּוֹפֵל בִּמְצוּלוֹת יָם, לֹא נִמְצָא לְעוֹלָמִים, מִשּׁוּם שֶׁהַמַּיִם מְכַסִּים עֲלֵיהֶם, (מהו המצולות ים, ') כְּמוֹ שֶׁנֶּאֱמַר (מיכה ז) וְתַשְׁלִיךְ בִּמְצֻלוֹת יָם כָּל חַטֹּאתָם. מִי הֵם מְצֻלוֹת יָם? אֶלָּא סוֹד נִכְבָּד הוּא, וַהֲרֵי (בארה רבי שמעון אמר) בֵּאֵר אוֹתוֹ רַבִּי שִׁמְעוֹן וְאָמַר, כָּל אוֹתָם שֶׁבָּאוּ מִצַּד הַקָּשֶׁה, וְנֶאֶחְזוּ בְּמִינִים רָעִים, בַּכְּתָרִים הַתַּחְתּוֹנִים, כְּמוֹ עֲזָאזֵל בְּיוֹם הַכִּפּוּרִים, זֶה נִקְרָא מְצוּלוֹת יָם, כְּמוֹ פְּסֹלֶת הַכֶּסֶף כְּשֶׁבּוֹחֲנִים אוֹתוֹ בָּאֵשׁ. זֶהוּ שֶׁכָּתוּב הָגוֹ סִיגִים מִכָּסֶף.</p>\n<p>כָּךָ זֶה, הוּא מֵאוֹתָם מְצוּלוֹת יָם, וְנִקְרָא מְצוּלוֹת יָם, מְצוּלוֹת מֵאוֹתוֹ יָם קָדוֹשׁ, מְצוּלוֹת - זֻהֲמַת הַכֶּסֶף. וְעַל כֵּן כָּל אוֹתָם הַחֲטָאִים שֶׁל יִשְׂרָאֵל שׁוֹרִים לְתוֹכוֹ (אצלו), וְהוּא מְקַבֵּל אוֹתָם, וְנִשְׁאָבִים לְתוֹכוֹ. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא נִקְרָא חוֹטֵא. מַה זֶּה חוֹטֵא? חִסָּרוֹן. וְעַל כֵּן הוּא חִסָּרוֹן שֶׁל הַכֹּל, וְנָטַל אֶת חֶסְרוֹן הַגּוּף וְהַנֶּפֶשׁ. בַּיּוֹם הַזֶּה יוֹרֵד מְצוּלוֹת הַיָּם הַזֶּה, זֻהֲמַת (הכסף) הַנֶּפֶשׁ, וְנוֹטֵל זֻהֲמַת הַגּוּף. מִי הוּא זֻהֲמַת הַגּוּף? זֶה אֵלּוּ הַחֲטָאִים שֶׁנַּעֲשׂוּ עַל יְדֵי יֵצֶר הָרָע שֶׁנִּקְרָא מְזֹּהָם מְנֻוָּל.</p>\n<p>אָמַר רַבִּי יוֹסֵי, שָׁנִינוּ, וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִם גֹּרָלוֹת, אִם כָּךְ, כָּבוֹד הוּא שֶׁל הָעֲזָאזֵל, רְאִיתֶם עֶבֶד שֶׁזּוֹרֵק גּוֹרָלוֹת עִם רִבּוֹנוֹ?! דֶּרֶךְ הָעוֹלָם שֶׁעֶבֶד אֵינוֹ נוֹטֵל אֶלָּא מַה שֶּׁנּוֹתֵן לוֹ רִבּוֹנוֹ. אֲבָל מִשּׁוּם שֶׁסָּמָאֵ\"ל מְזֻמָּן בַּיּוֹם הַזֶּה עַל מַלְשִׁינוּת, וּכְדֵי שֶׁלֹּא יִהְיֶה לוֹ פִּתְחוֹן פֶּה, (בגורל הזה הוא עולה בו) נוֹתְנִים לוֹ חֵלֶק בָּזֶה.</p>\n<p>וְהַגּוֹרָל הַזֶּה מֵעַצְמוֹ הוּא שֶׁעוֹלֶה בּוֹ. שֶׁאָמַר רַבִּי יְהוּדָה אָמַר רַבִּי יִצְחָק, דָּבָר עֶלְיוֹן מָצָאנוּ בַגּוֹרָל. בַּגּוֹרָל שֶׁל יְהוֹשֻׁעַ כָּתוּב בּוֹ, (במדבר כז) עַל פִּי הַגּוֹרָל, עַל פִּי הַגּוֹרָל וַדַּאי, שֶׁהוּא אָמַר: זֶה חֶלְקוֹ שֶׁל יְהוּדָה, זֶה שֶׁל בִּנְיָמִין וְכוּ', וְכֵן כֻּלָּם. אַף כָּאן, כֵּיוָן שֶׁהַכֹּהֵן שָׂם יָדָיו, אוֹתָם הַגּוֹרָלוֹת מְדַלְּגִים וְעוֹלִים בְּיַד הַכֹּהֵן (ועולים הגורלות ביד הכהן, הם מדלגים מידיו) וְשׁוֹרִים בִּמְקוֹמָם. זֶהוּ שֶׁכָּתוּב, וְהַשָּׂעִיר אֲשֶׁר עָלָה עָלָיו הַגּוֹרָל, עָלָה עָלָיו וַדַּאי.</p>\n<p>וְלֹא זֶה בִּלְבַדּוֹ, אֶלָּא בְּכָל פַּעַם שֶׁמְּזֻמָּן הַמַּלְשִׁין וְנִתֶּנֶת לוֹ רְשׁוּת, צְרִיכִים לָשִׂים כְּנֶגְדּוֹ בְּמַה שֶּׁיִּתְעַסֵּק וְיַעֲזֹב אֶת יִשְׂרָאֵל. בַּיּוֹם הַזֶּה מְזֻמָּן הַמַּלְשִׁין לְרַגֵּל אֶת הָאָרֶץ. זֶהוּ שֶׁכָּתוּב (איוב א) וַיֹּאמֶר ה' אֶל הַשָּׂטָן מֵאַיִן תָּבא. וַהֲרֵי שָׁנִינוּ, מִשּׁוּט בָּאָרֶץ, מַה זֶּה? אֶלָּא זֶהוּ הַמַּלְשִׁין הַגָּדוֹל מְקַטְרְגָם שֶׁל יִשְׂרָאֵל.</p>\n<p>וַהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים, (שודאי) בְּאוֹתָהּ שָׁעָה שֶׁהָיוּ יִשְׂרָאֵל מְזֻמָּנִים לַעֲבֹר בַּיָּם וּלְהִפָּרַע מִן הַמִּצְרִים, אָמַר: אֲנִי עָבַרְתִּי בָּאָרֶץ הַקְדוֹשָׁה, וְרָאִיתִי שֶׁאֵלֶּה לֹא רְאוּיִים לְהִכָּנֵס לְתוֹכָהּ. אִם אַתָּה דָּן דִּין - הַדִּינִים שֶׁלָּהֶם כָּאן כְּמוֹ הַמִּצְרִים. מַה שּׁוֹנִים אֵלּוּ מֵאֵלּוּ? אוֹ שֶׁיָּמוּתוּ כֻלָּם כְּאֶחָד, אוֹ שֶׁיַּחְזְרוּ כֻלָּם לְמִצְרַיִם. וְלֹא אַתָּה הוּא שֶׁאָמַרְתָּ, (בראשית טו) וַעֲבָדוּם וְעִנּוּ אֹתָם אַרְבַּע מֵאוֹת שָׁנָה? וַהֲרֵי לֹא עָלוּ מֵחֶשְׁבּוֹנוֹ אֶלָּא מָאתַיִם וְעֶשֶׂר, וְלֹא יוֹתֵר.</p>\n<p>אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מָה אֶעֱשֶׂה? כָּאן צְרִיכָה הִשְׁתַּדְּלוּת, לְהָבִיא קְרָב כְּנֶגְדּוֹ. אֶתֵּן לוֹ בְּמַה שֶּׁיִּתְעַסֵּק, וְיַעֲזֹּב אֶת בָּנַי, וַהֲרֵי נִמְצָא בְּמַה שֶּׁיִּתְעַסֵּק. מִיָּד אָמַר לוֹ: הֲשָׂמְתָּ לִבְּךְ אֶל עַבְדִּי אִיּוֹב כִּי אֵין כָּמֹהוּ בָּאָרֶץ. מִיָּד חָלַק לוֹ הַמַּלְשִׁין בִּדְבָרִים, וַיַּעַן הַשָּׂטָן אֶת ה' וַיֹּאמַר הַחִנָּם יָרֵא אִיּוֹב אֱלֹהִים.</p>\n<p>לְרוֹעָה שֶׁרָצָה לְהַעֲבִיר צֹאנוֹ בְּנָהָר אֶחָד. עָבַר זְאֵב לְהִתְגָּרוֹת בְּצֹאנוֹ. הָרוֹעֶה הָיָה חָכָם, אָמַר: מָה אֶעֱשֶׂה, שֶׁבְּעוֹד שֶׁאֲנִי מַעֲבִיר אֶת הַטְּלָאִים, הוּא יִתְגָּרֶה בַּצּאן? הֵרִים עֵינָיו וְרָאָה בֵּין הַצּאן תַּיִשׁ אֶחָד מֵאוֹתָם תֵּישֵׁי הַבָּר, שֶׁהָיָה גָּדוֹל וְחָזָק. אָמַר: אֶזְרֹק זֶה כְּנֶגְדּוֹ, וּבְעוֹד שֶׁמִּתְגָּרִים זֶה בָּזֶה, אַעֲבִיר אֶת כָּל הַצּאן וְיִנָּצְלוּ מִמֶּנּוּ.</p>\n<p>כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר: וַדַּאי הַתַּיִשׁ הַזֶּה גָּדוֹל אֶחָד וְחָזָק וְאַלִּים, אֶזְרֹק כְּנֶגְדּוֹ, וּבְעוֹד שֶׁהוּא מִתְעַסֵּק עִמּוֹ, יַעַבְרוּ בָנַי, וְלֹא יִמָּצֵא קָטֵגוֹר עֲלֵיהֶם. מִיָּד - וַיֹּאמֶר ה' אֶל הַשָּׂטָן הֲשַׂמְתָּ לִבְּךְ. עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא זִוֵּג אוֹתָם כְּאֶחָד, שֶׁכָּתוּב הִנּוֹ בְיָדֶךְ. בְּעוֹד שֶׁהוּא מִתְעַסֵּק בּוֹ, עָזַב אֶת יִשְׂרָאֵל, וְלֹא נִמְצָא מְקַטְרֵג אֲלֵיהֶם.</p>\n<p>אַף כָּאן בַּיּוֹם הַזֶּה הַמַּלְשִׁין מְזֻמָּן לְרַגֵּל אֶת הָאָרֶץ, וּצְרִיכִים לִשְׁלֹחַ כְּנֶגְדּוֹ בְּמַה שֶּׁיִּתְעַסֵּק (בדגמה שלו), וּבְעוֹד שֶׁהוּא מִתְעַסֵּק בּוֹ, עוֹזֵב אֶת יִשְׂרָאֵל. וּמָשָׁל אוֹמְרִים לַמְזֻלְזָל שֶׁל בֵּית הַמֶּלֶךְ: תֵּן לוֹ מְעַט יַיִן, וִישַׁבַּחֲךְ לִפְנֵי הַמֶּלֶךְ. וְאִם לֹא, יֹאמַר לַמֶּלֶךְ דִּבּוּר רָע. לִפְעָמִים נוֹטְלִים אֶת אוֹתוֹ דִבּוּר עֶלְיוֹנֵי בֵּית הַמֶּלֶךְ, וְהַמֶּלֶךְ עוֹשֶׂה בִּגְלָלוֹ דִּין.</p>\n<p>רַבִּי יִצְחָק אָמַר, לְשׁוֹטֶה שֶׁעוֹמֵד לִפְנֵי הַמֶּלֶךְ, תֵּן לוֹ יַיִן, וְאַחַר כָּךְ אֱמֹר לוֹ וְהַרְאֵה לוֹ כָּל אוֹתָן טָעֻיּוֹת שֶׁעָשִׂיתָ וְכָל אוֹתָן רָעוֹת, וְהוּא יָבא וִישַׁבַּח אוֹתְךְ, וְיֹאמַר שֶׁלֹּא נִמְצָא בָּעוֹלָם כְּמוֹתְךְ. אַף כָּאן, הֲרֵי עוֹמֵד הַמַּלְשִׁין תָּמִיד לִפְנֵי הַמֶּלֶךְ, יִשְׂרָאֵל נוֹתְנִים לוֹ אֶת הַדּוֹרוֹן הַזֶּה, וּבַדּוֹרוֹן הַזֶּה פֶּתֶק לְכָל הָרָעוֹת וּלְכָל הַטָּעֻיּוֹת וּלְכָל הַחֲטָאִים שֶׁעָשׂוּ יִשְׂרָאֵל, וְהוּא בָּא וּמְשַׁבֵּחַ אֶת יִשְׂרָאֵל, וְנַעֲשֶׂה עֲלֵיהֶם סָנֵגוֹר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַחֲזִיר אֶת הַכֹּל לְרֹאשׁ הָרָעִים שֶׁל עַמּוֹ, מִשּׁוּם שֶׁכָּתוּב (משלי כה) כִּי גֶחָלִים אַתָּה חֹתֶה עַל רֹאשׁוֹ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אוֹי לוֹ לָעָם שֶׁל עֵשָׂו בְּשָׁעָה שֶׁשּׁוֹלְחִים אֶת הַשָּׂעִיר הַזֶּה לְאוֹתוֹ הַמַּלְשִׁין שֶׁמְּמֻנֶּה עֲלֵיהֶם, שֶׁבִּגְלָלוֹ בָּא לְשַׁבֵּחַ אֶת יִשְׂרָאֵל, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַחֲזִיר אֶת כָּל הַחֲטָאִים עַל רֹאשׁ עַמּוֹ, מִשּׁוּם שֶׁכָּתוּב (תהלים קא) דֹּבֵר שְׁקָרִים לֹא יִכּוֹן לְנֶגֶד עֵינָי. אָמַר רַבִּי יְהוּדָה, אִלְמָלֵא הָיוּ יוֹדְעִים אֻמּוֹת הָעוֹלָם מֵהַשָּׂעִיר הַזֶּה, לֹא מַשְׁאִירִים אֶת יִשְׂרָאֵל יוֹם אֶחָד בָּעוֹלָם.</p>\n<p>בֹּא רְאֵה, כָּל אוֹתוֹ יוֹם הוּא מִתְעַסֵּק עִם אוֹתוֹ שָׂעִיר, וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מְכַפֵּר לְיִשְׂרָאֵל וּמְטַהֵר אוֹתָם מֵהַכֹּל, וְלֹא נִמְצֵאת קָטֵגוֹרְיָה לְפָנָיו. אַחַר כָּךְ הוּא בָּא וּמְשַׁבֵּחַ אֶת יִשְׂרָאֵל, וְאָז שׁוֹאֵל אוֹתוֹ, כְּמוֹ שֶׁנֶּאֱמַר, וַיֹּאמֶר ה' אֶל הַשָּׂטָן מֵאַיִן תָּבא. מֵשִׁיב בְּתִשְׁבַּחְתָּם שֶׁל יִשְׂרָאֵל, וְהַקָּטֵגוֹר נַעֲשֶׂה סָנֵגוֹר וְהוֹלֵךְ לוֹ.</p>\n<p>אָז הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר לְשִׁבְעִים הַשָּׂרִים שֶׁסְּבִיב הַכִּסֵּא: רְאִיתֶם אֶת הַמַּלְשִׁין הַזֶּה, אֵיךְ עוֹמֵד עַל בָּנַי תָּמִיד? (מסכימים) הֲרֵי שָׂעִיר אֶחָד שֶׁנִּמְצָא (שנשלח) אֶצְלוֹ בְּפֶתֶק עִם כָּל חֲטָאֵיהֶם וְכָל טָעֻיּוֹתֵיהֶם, וְכָל מַה שֶּׁחָטְאוּ וְחָבוּ לְפָנַי, וְהוּא קִבֵּל אוֹתָם. אֲזַי כֻּלָּם מַסְכִּימִים שֶׁיַּחְזְרוּ אוֹתָם הַחֲטָאִים עַל עַמּוֹ.</p>\n<p>רַבִּי אַבָּא אָמַר, כָּל אוֹתָם עֲווֹנוֹת וַחֲטָאִים נִדְבָּקִים בּוֹ, כְּמוֹ שֶׁכָּתוּב (מיכה ז) וְתַשְׁלִיךְ בִּמְצֻלוֹת יָם כָּל חַטֹּאתָם. וְאַחַר כָּךְ כֻּלָּם חוֹזְרִים עַל רָאשֵׁי עַמּוֹ, זֶהוּ שֶׁכָּתוּב (ויקרא טז) וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲונֹתָם אֶל אֶרֶץ גְּזֵרָה. בַּיּוֹם הַזֶּה מִתְעַטֵּר הַכֹּהֵן בַּעֲטָרוֹת עֶלְיוֹנוֹת, וְהוּא עוֹמֵד בֵּין עֶלְיוֹנִים וְתַחְתּוֹנִים, וּמְכַפֵּר עָלָיו וְעַל בֵּיתוֹ, וְעַל הַכֹּהֲנִים, וְעַל הַמִּקְדָּשׁ, וְעַל כָּל יִשְׂרָאֵל.</p>\n<p>לָמַדְנוּ, בְּשָׁעָה שֶׁנִּכְנָס עִם דַּם הַפַּר, מְכַוֵּן בְּרֹאשׁ הָאֱמוּנָה, וּמַזֶּה בְאֶצְבָּעוֹ, כַּכָּתוּב וְהִזָּה אֹתוֹ עַל הַכַּפֹּרֶת וְלִפְנֵי הַכַּפֹּרֶת. וְאֵיךְ עוֹשֶׂה? טוֹבֵל בְּרָאשֵׁי (בדבוק) הָאֶצְבָּעוֹת, וּמַזֶּה כְמַצְלִיף בְּטִפּוֹת הָאֶצְבַּע לְצִדֵּי הַטַּבּוּר (השפוע) (הכפרת), מַזֶּה וּמִתְכַּוֵּן, וּמַתְחִיל לִמְנוֹת: אַחַת, אַחַת וְאַחַת. אַחַת לְבַדָּהּ, וְאַחַת שֶׁכּוֹלֶלֶת הַכֹּל. אַחַת הַשֶּׁבַח שֶׁל הַכֹּל, הָאַחַת שֶׁהַכֹּל חוֹזְרִים כְּנֶגְדָּהּ, אַחַת הָרֹאשׁ שֶׁל הַכֹּל. אַחַר כָּךְ אַחַת וְאַחַת, שֶׁהֵם שׁוֹרִים כְּאֶחָד, בְּרָצוֹן וּבְאַחֲוָה, וְלֹא נִפְרָדִים לְעוֹלָמִים.</p>\n<p>אַחַר שֶׁמַּגִּיעַ לַוְּאַחַת הַזּוֹ, שֶׁהִיא אֵם הַכֹּל, מִכָּאן מַתְחִיל לִמְנוֹת בְּזִוּוּג, וּמוֹנֶה וְאוֹמֵר: אַחַת וּשְׁתַּיִם, אַחַת וְשָׁלֹשׁ, אַחַת וְאַרְבַּע, אַחַת וְחָמֵשׁ, אַחַת וָשֵׁשׁ, אַחַת וָשֶׁבַע. כְּדֵי לִמְשֹׁךְ וּלְהַשְׁפִּיעַ לָאַחַת הַזּוֹ, שֶׁהִיא הָאֵם (הים) הָעֶלְיוֹנָה, בִּדְרָגוֹת יְדוּעוֹת, לַכֶּתֶר (לנהר לאמא) שֶׁל אִמָּא הַתַּחְתּוֹנָה, וּלְהַמְשִׁיךְ נְהָרוֹת עֲמֻקִּים מִמְּקוֹמָם לִכְנֶסֶת יִשְׂרָאֵל. וְעַל כֵּן בַּיּוֹם הַשֵּׁנִי שְׁנֵי אוֹרוֹת מְאִירִים כְּאֶחָד, הָאֵם הָעֶלְיוֹנָה מְאִירָה לָאֵם הַתַּחְתּוֹנָה, וְעַל כֵּן כָּתוּב יוֹם הַכִּפּוּרִים, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>אָמַר רַבִּי יִצְחָק, שַׁרְשֶׁרֶת אַחַת קְשׁוּרָה לְרַגְלֵי הַכֹּהֵן בְּשָׁעָה שֶׁהָיָה נִכְנָס, שֶׁאִם יָמוּת שָׁם, יוֹצִיאוּהוּ מִבַּחוּץ. וּבַמֶּה יוֹדְעִים? בְּאוֹתָהּ זְהוֹרִית נוֹדַע וְהֻכַּר, כְּשֶׁלֹּא נֶהְפַּךְ צִבְעוֹ. בְּאוֹתָהּ שָׁעָה נוֹדַע שֶׁהַכֹּהֵן נִמְצָא בִּפְנִים בְּחֵטְא. וְאִם יֵצֵא בְשָׁלוֹם, בַּזְּהוֹרִית יִוָּדַע וְיֻכַּר, שֶׁיֵּהָפֵךְ צִבְעוֹ לְלָבָן, אֲזַי שִׂמְחָה הִיא בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים. וְאִם לֹא, כֻּלָּם נִמְצְאוּ בְצַעַר, וְהָיוּ כֻלָּם יוֹדְעִים שֶׁלֹּא הִתְקַבְּלוּ תְפִלּוֹתֵיהֶ ם.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כֵּיוָן שֶׁהָיָה נִכְנָס, וְטִמְטֵם אֶת עֵינָיו שֶׁלֹּא לְהִסְתַּכֵּל בְּמַה שֶּׁלֹּא צָרִיךְ, וְהָיָה שׁוֹמֵעַ קוֹל כַּנְפֵי הַכְּרוּבִים מְזַמְּרִים וּמְשַׁבְּחִים, הָיָה יוֹדֵעַ הַכֹּהֵן שֶׁהַכֹּל הָיָה בְשִׂמְחָה, וְיֵּצֵא בְשָׁלוֹם. וְעִם כָּל זֶה, בִּתְפִלָּתוֹ הָיָה יוֹדֵעַ, שֶׁהַמִּלִּים יוֹצְאִים בְּשִׂמְחָה וּמִתְקַבְּלִים וּמִתְבָּרְכִים כָּרָאוּי, וְאָז הִיא שִׂמְחָה בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים.</p>\n<p>רַבִּי אֶלְעָזָר שָׁאַל אֶת רַבִּי שִׁמְעוֹן אָבִיו. אָמַר לוֹ, לָמָּה בַּמָּקוֹם הַזֶּה הַיּוֹם הַזֶּה תָּלוּי וְלֹא בְדַרְגָּה אַחֶרֶת, שֶׁרָאוּי הוּא לִהְיוֹת בְּדַרְגָּה שֶׁשָּׁם שׁוֹרֶה הַמֶּלֶךְ יוֹתֵר מֵהַכֹּל? אָמַר לוֹ רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּנִי, כָּךְ הוּא וַדַּאי, וְיָפֶה שָׁאַלְתָּ.</p>\n<p>בֹּא רְאֵה, הַמֶּלֶךְ הַקָּדוֹשׁ הִשְׁאִיר אֶת הֵיכָלוֹ וּבֵיתוֹ בְּיַד הַגְּבִירָה, וְהִשְׁאִיר אֶת בָּנָיו עִמָּהּ כְּדֵי לְהַנְהִיגָם וּלְהַלְקוֹתָם וְלִשְׁרוֹת בְּתוֹכָם. שֶׁאִם זוֹכִים, הַגְּבִירָה נִכְנֶסֶת בְּשִׂמְחָה וּבְכָבוֹד אֶל הַמֶּלֶךְ. וְאִם לֹא זוֹכִים, הִיא וְהֵם חוֹזְרִים לַגָּלוּת. וַהֲרֵי בֵּאַרְנוּ, כְּמוֹ שֶׁכָּתוּב (משלי יט) מְשַׁדֶּד אָב יַבְרִיחַ אֵם. וְכָתוּב (ישעיה נ) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם.</p>\n<p>וְעַל כֵּן יֵשׁ יוֹם אֶחָד בְּשָׁנָה לְהַשְׁגִּיחַ בָּהֶם וּלְעַיֵּן בָּהֶם. וּכְשֶׁמִּזְדַּמֵּן הַיּוֹם הַזֶּה, הָאֵם הָעֶלְיוֹנָה, שֶׁכָּל הַחֵרוּת בְּיָדֶיהָ, מִזְדַּמֶּנֶת כְּנֶגְדּוֹ לְהִסְתַּכֵּל בְּיִשְׂרָאֵל. וְיִשְׂרָאֵל מִזְדָּרְזִים בַּיּוֹם הַזֶּה בְּכַמָּה עֲבוֹדוֹת, בְּכַמָּה תְפִלּוֹת, בְּכַמָּה עִנּוּיִים, כֻּלָּם בִּזְכוּת. וְאָז מִזְדַּמֶּנֶת לָהֶם חֵרוּת, מֵהַמָּקוֹם שֶׁכָּל הַחֵרוּת בְּיָדֶיהָ שֶׁל הַגְּבִירָה. בְּנֵי הַמֶּלֶךְ בָּנֶיהָ, שֶׁנִּפְקְדוּ בְיָדֶיהָ, כֻּלָּם זַכָּאִים, כֻּלָּם בְּלִי חֲטָאִים, בְּלִי עֲווֹנוֹת. אָז מִזְדַּוֶּגֶת (וכאשר מזדמן היום הזה וישראל הזדמנו ביום הזה בכמה עבודות, בכמה תפלות, בכמה ענויים הכל בזכות. אז האם העליונה שכל החרות בידיה מזדמנת כנגדו להסתכל בישראל, ורואה את בני המלך בניה (בּנָהּ) שנפקדו בידיה של הגבירה, כלם זכאים בלי חטאים, בלי חובות, ואז מזמנת להם חרות ממקום שכל החרות בידיה של הגבירה, ואז הגבירה העליונה) לַמֶּלֶךְ בְּאוֹר, בְּשִׂמְחָה, בִּשְׁלֵמוּת, בְּרָצוֹן. שֶׁהֲרֵי גִּדְּלָה בָנִים לַמֶּלֶךְ הָעֶלְיוֹן כָּרָאוּי.</p>\n<p>וּכְשֶׁבַּיּוֹם הַזֶּה אֵינָם נִמְצָאִים כָּרָאוּי - אוֹי לָהֶם! אוֹי לִשְׁלוּחֵיהֶם! אוֹי שֶׁהֲרֵי הַגְּבִירָה הִתְרַחֲקָה מִן הַמֶּלֶךְ, וְהָאֵם הָעֶלְיוֹנָה מִסְתַּלֶּקֶת, וְלֹא יוֹצֵאת מִמֶּנּוּ חֵרוּת לְעוֹלָמִים. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לִמֵּד אוֹתָם אֶת דְּרָכָיו כְּדֵי לְהִנָּצֵל מִן הַדִּין, וְיִמָּצְאוּ צַדִּיקִים לְפָנָיו. זֶהוּ שֶׁכָּתוּב (ויקראטז) כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם לְטַהֵר אֶתְכֶם. וְכָתוּב (יחזקאל לז) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם מִכֹּל טֻמְאוֹתֵיכֶם וְגוֹ'.</p>"],[9522012225,"<p>וּבַחֲמִשָּׁה עָשָׂר יוֹם לַחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ'. רַבִּי יוֹסֵי שָׁאַל אֶת רַבִּי אַבָּא. אָמַר לוֹ, הַחֲמִשָּׁה עָשָׂר יוֹם הַלָּלוּ, מַה הֵם אוֹמְרִים? אָמַר לוֹ, וַדַּאי זֶהוּ סוֹד נִכְבָּד. בֹּא רְאֵה, בֵּין לְמַעְלָה בֵּין לְמַטָּה, כָּל אֶחָד וְאֶחָד בְּדַרְכּוֹ נוֹסֵעַ, וּבְדַרְכּוֹ יוֹשֵׁב, וּבְדַרְכּוֹ מִתְעוֹרֵר וְעוֹשֶׂה מַה שֶּׁעוֹשֶׂה. הֶעָשׂוֹר הַזֶּה הֵם מִכְּנֶסֶת יִשְׂרָאֵל. וְהַיּוֹם הָעֲשִׂירִי עוֹמֵד בָּעֲשִׂירִי. וְעַל כֵּן, (שמות יב) בֶּעָשׂוֹר לַחֹדֶשׁ הַזֶּה וְיִקְחוּ לָהֶם אִישׁ שֶׂה לְבֵית וְגוֹ'. וְהַיּוֹם הַזֶּה הוּא שֶׁלָּהּ. וַחֲמִשָּׁה יָמִים אֲחֵרִים הוּא שֶׁל הַמֶּלֶךְ, הַיּוֹם שֶׁבָּא עָלֶיהָ. שֶׁהֲרֵי הַחֲמִישִׁי, בּוֹ יוֹשֵׁב הַמֶּלֶךְ בְּכִסֵּא. וּבְכָל מָקוֹם בֶּעָשׂוֹר, הוּא שֶׁל הַגְּבִירָה. חֲמִשָּׁה עֲלֵיהֶם, שֶׁל הַמֶּלֶךְ הוּא (אותו היום שעליה משום שהדרגה החמישית בה יושב המלך בכסא, ובכל מקום וכו'). אוֹתוֹ הַיּוֹם שֶׁבָּא עָלֶיהָ, שֶׁהֲרֵי הַחֲמִישִׁי, בּוֹ יוֹשֵׁב הַמֶּלֶךְ בַּשַּׁעַר.</p>\n<p>וּבְכָל מָקוֹם בֶּעָשׂוֹר, הוּא שֶׁל הַגְּבִירָה. חֲמִשָּׁה עֲלֵיהֶם, שֶׁל הַמֶּלֶךְ הוּא, אוֹתוֹ יוֹם שֶׁבָּא עָלֶיהָ. מִשּׁוּם כָּךְ חֲמִשָּׁה יָמִים מֵהַחֹדֶשׁ לַתּוֹרָה. וְאִם תֹּאמַר שְׁבִיעִי, בִּזְמַן שֶׁשְּׁנֵי אָבוֹת נִמְצָאִים בּוֹ, שֶׁהֲרֵי הַמֶּלֶךְ בָּהֶם, וְאָז מִתְעַטֵּר בַּכֹּל. וְדָבָר אֶחָד שְׁבִיעִי וַחֲמִישִׁי.</p>\n<p>בֹּא רְאֵה, הַחֲמִישִׁי הוּא שֶׁלּוֹ וַדַּאי, כְּמוֹ שֶׁנִּתְבָּאֵר, וְאָז מֵאִיר הָאָב לָאֵם, וּמְאִירִים מִמֶּנָּה חֲמִשִּׁים שְׁעָרִים לְהָאִיר לַחֲמִישִׁי. וְאִם תֹּאמַר הַשְּׁבִיעִי, מִשּׁוּם שֶׁהַמֶּלֶךְ בַּשְּׁלֵמוּת שֶׁל הָאָבוֹת, וַעֲטָרָה יוֹרֵשׁ מֵהַשְּׁבִיעִי, כְּמוֹ שֶׁכָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן. וְעַל זֶה בַּשְּׁבִיעִי הוּא הַיּוֹם שֶׁמְּעֻטָּר הַמֶּלֶךְ בַּעֲטַרְתּוֹ, וְאָז יוֹרֵשׁ הַמֶּלֶךְ אֶת הָאָב וְאֶת הָאֵם, שֶׁמִּזְדַּוְּגִים כְּאֶחָד. וְעַל כֵּן הַכֹּל תָּלוּי בְּאֶחָד. וּבַחֲמִשָּׁה עָשָׂר יוֹם. רַבִּי יְהוּדָה פָּתַח, (במדבר כא) וַיִּשְׁמַע הַכְּנַעֲנִי מֶלֶךְ עֲרָד. שָׁנִינוּ, שָׁלֹשׁ מַתָּנוֹת עֶלְיוֹנוֹת הִזְדַּמְּנוּ לְיִשְׂרָאֵל עַל יְדֵי שְׁלֹשָׁה אַחִים: מֹשֶׁה, אַהֲרֹן וּמִרְיָם. מָן - בִּזְכוּת מֹשֶׁה. עַנְנֵי כָבוֹד - בִּזְכוּת אַהֲרֹן. בְּאֵר - בִּזְכוּת מִרְיָם. וְכֻלָּם אֲחוּזִים לְמַעְלָה. מָן בִּזְכוּת מֹשֶׁה, שֶׁכָּתוּב (שמות טז) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. מִן הַשָּׁמָיִם (דוקא) - זֶה מֹשֶׁה.</p>"],[9522012226,"<p>עֵנְנֵי כָבוֹד בִּזְכוּת אַהֲרֹן, שֶׁכָּתוּב (במדבר יד) אֲשֶׁר עַיִן בְּעַיִן (אהרן) נִרְאָה אַתָּה ה' וְגוֹ', וְכָתוּב (ויקרא טז) וְכִסָּה עֲנַן הַקְּטֹרֶת. מַה לְמַעְלָה שִׁבְעָה, אַף כָּאן גַּם שִׁבְעָה, שֶׁהֲרֵי בַּקְּטֹרֶת שִׁבְעָה עֲנָנִים נִקְשָׁרִים כְּאֶחָד (ועוד). וְאַהֲרֹן הוּא רֹאשׁ לְכָל שִׁבְעַת הָעֲנָנִים, וְהוּא קוֹשֵׁר אֶת שֵׁשֶׁת הָאֲחֵרִים עִמּוֹ בְּכָל יוֹם.</p>\n<p>בְּאֵר בִּזְכוּת מִרְיָם, שֶׁהֲרֵי הִיא וַדַּאי נִקְרֵאת בְּאֵר. וּבְסֵפֶר הָאַגָּדָה, (שמות ב) וַתֵּתַצַּב אֲחֹתוֹ מֵרָחֹק לְדֵעָה וְגוֹ' - זוֹהִי בְּאֵר מַיִם חַיִּים, וְהַכֹּל קֶשֶׁר אֶחָד. מֵתָה מִרְיָם - הִסְתַּלְּקָה הַבְּאֵר, שֶׁכָּתוּב (במדבר ב) וְלֹא הָיָה מַיִם לָעֵדָה. וּבְאוֹתָהּ שָׁעָה רָצְתָה בְּאֵר אַחֶרֶת לְהִסְתַּלֵּק, שֶׁהָיְתָה מְצוּיָה עִם יִשְׂרָאֵל. כְּשֶׁרָאֲתָה שִׁשָּׁה עֲנָנִים שֶׁהָיוּ קְשׁוּרִים עָלֶיהָ, נִקְשְׁרָה הִיא בָּהֶם.</p>\n<p>מֵת אַהֲרֹן, הִסְתַּלְּקוּ אוֹתָם עֲנָנִים וְהִסְתַּלֵּק עֲנַן הַבְּאֵר עִמָּהֶם. בָּא מֹשֶׁה, הֶחֱזִיר אוֹתָם. זֶהוּ שֶׁכָּתוּב (תהלים סח) עָלִיתָ לַמָּרוֹם שָׁבִיתָ שֶּׁבִי לָקַחְתָּ מַתָּנוֹת בָּאָדָם. לָקַחְתָּ מַתָּנוֹת וַדַּאי, אוֹתָן מַתָּנוֹת שֶׁהָיוּ בָרִאשׁוֹנָה - בְּאֵר וַעֲנָנִים.</p>\n<p>בְּאֵר - זוֹ בְּאֵרוֹ שֶׁל יִצְחָק. עֲנָנִים - אֵלּוּ הָעֲנָנִים שֶׁל אַהֲרֹן. אָמַר רַבִּי יִצְחָק, מִפְּנֵי מָה זָכָה אַהֲרֹן לָזֶה? מִשּׁוּם שֶׁהוּא קָשׁוּר בָּעֲנָנִים (ראש לעננים), וְהוּא נִקְשָׁר כָּל יוֹם וָיוֹם לְכֻלָּם כְּאֶחָד, שֶׁכֻּלָּם מִתְבָּרְכִים עַל יָדוֹ.</p>\n<p>בֹּא רְאֵה, עַל כָּל חֶסֶד שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא עִם יִשְׂרָאֵל, קָשַׁר עִמָּם שִׁבְעָה עֲנָנִים נִכְבָּדִים, וְקָשַׁר אוֹתָם עִם כְּנֶסֶת יִשְׂרָאֵל, שֶׁהֲרֵי הֶעָנָן שֶׁלָּהּ נִקְשָׁר עִם שִׁשָּׁה אֲחֵרִים. וְעִם כָּל הַשִּׁבְעָה הָלְכוּ יִשְׂרָאֵל בַּמִּדְבָּר. מָה הַטַּעַם? מִשּׁוּם שֶׁכֻּלָּם הֵם הַקֶּשֶׁר שֶׁל הָאֱמוּנָה, וְעַל זֶה בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים. מַה זֶּה אוֹמֵר? מִשּׁוּם שֶׁכָּתוּב (שירב) בְּצִלּוֹ חִמַּדְתִּי וְיָשַׁבְתִּי וּפִרְיוֹ מָתוֹק לְחִכִּי. וְצָרִיךְ אָדָם לְהַרְאוֹת אֶת עַצְמוֹ שֶׁיּוֹשֵׁב תַּחַת צֵל הָאֱמוּנָה.</p>\n<p>בֹּא רְאֵה, כָּל אוֹתָן הַשָּׁנִים שֶׁעָמַד אַהֲרֹן, הָיוּ יִשְׂרָאֵל בְּצֵל הָאֱמוּנָה תַּחַת הָעֲנָנִים הַלָּלוּ. אַחַר שֶׁמֵּת אַהֲרֹן, הִסְתַּלֵּק עָנָן אֶחָד, שֶׁהוּא הַיָּמִין שֶׁל הַכֹּל. וּכְשֶׁזֶּה הִסְתַּלֵּק, הִסְתַּלְּקוּ כָּל הַשְּׁאָר עִמּוֹ (עננים) וְנִרְאוּ כֻלָּם בְּחִסָּרוֹן. וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב (במדבר כא) וַיִּרְאוּ כָּל הָעֵדָה כִּי גָוַע אַהֲרֹן. אַל תִּקְרֵי וַיִּרְאוּ אֶלָּא וַיִּירְאוּ. מִיָּד - וַיִּשְׁמַע הַכְּנַעֲנִי מֶלֶךְ עֲרָד יֹשֵׁב הַנֶּגֶב כִּי בָּא יִשְׂרָאֵל דֶּרֶךְ הָאֲתָרִים. שָׁמַע שֶׁהִסְתַּלְּקוּ אוֹתָם הָעֲנָנִים, וּמֵת הַתַּיָּר הַגָּדוֹל שֶׁכָּל אוֹתָם הָעֲנָנִים נִקְשְׁרוּ עִמּוֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק, הַכְּנַעֲנִי מֶלֶךְ עֲרָד יֹשֵׁב הַנֶּגֶב וַדַּאי. וּכְשֶׁבָּאוּ אוֹתָם מְרַגְּלִים שֶׁשָּׁלַח מֹשֶׁה, אָמְרוּ (שם יג) עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב, כְּדֵי לִשְׁבֹּר אֶת לִבָּם, שֶׁהֲרֵי בָּעֲמָלֵק נִשְׁבַּר כֹּחָם בָּרִאשׁוֹנָה.</p>\n<p>אָמַר רַבִּי אַבָּא, וַיִּשְׁמַע הַכְּנַעֲנִי, מַה זֶּה אוֹמֵר כָּאן אַחַר שֶׁהִסְתַּלְּקוּ אוֹתָם הָעֲנָנִים? אֶלָּא בִּכְנַעַן כָּתוּב, וַיֹּאמֶר אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו. כָּאן לָמַדְנוּ, מִי שֶׁמּוֹצִיא אֶת עַצְמוֹ מִצֵּל הָאֱמוּנָה, רָאוּי לִהְיוֹת עֶבֶד לְעַבְדֵי עֲבָדִים. זֶהוּ שֶׁכָּתוּב וַיִּלָּחֶם בְּיִשְׂרָאֵל וַיִּשְׁבְּ מִמֶּנּוּ שֶׁבִי. הוּא נָטַל עֲבָדִים מִיִּשְׂרָאֵל לְעַצְמוֹ.</p>\n<p>וְעַל כֵּן כָּתוּב, כָּל הָאֶזְרָח בְּיִשְׂרָאֵל יֵשְׁבוּ בַּסֻּכֹּת. כָּל מִי שֶׁהוּא מִשֹּׁרֶשׁ וְגֶזַע קָדוֹשׁ שֶׁל יִשְׂרָאֵל, יֵשְׁבוּ בַּסֻּכֹּת, תַּחַת צֵל הָאֱמוּנָה. וּמִי שֶׁאֵינוֹ מִגֶּזַע וְשֹׁרֶשׁ קָדוֹשׁ שֶׁל יִשְׂרָאֵל, לֹא יוֹשֵׁב בָּהֶם, וּמוֹצִיא אֶת עַצְמוֹ מִתַּחַת צֵל הָאֱמוּנָה.</p>\n<p>כָּתוּב (הושע יב) כְּנַעַן בְּיָדוֹ מֹאזְנֵי מִרְמָה, זֶה אֱלִיעֶזֶר עֶבֶד אַבְרָהָם. וּבֹא רְאֵה, כָּתוּב אָרוּר כְּנָעַן, וּמִשּׁוּם שֶׁזָּכָה כְּנַעַן זֶה לְשַׁמֵּשׁ אֶת אַבְרָהָם, כֵּיוָן שֶׁשִּׁמֵּשׁ אֶת אַבְרָהָם, יָשַׁב תַּחַת צֵל הָאֱמוּנָה, זָכָה לָצֵאת מֵאוֹתָהּ קְלָלָה שֶׁהִתְקַלֵּל, וְלֹא עוֹד, אֶלָּא שֶׁכָּתוּב בּוֹ בְּרָכָה, שֶׁכָּתוּב (בראשית כד) וַיֹּאמְרוּ בֹּא בְּרוּךְ ה'. מַה זֶּה אוֹמֵר? שֶׁכָּל מִי שֶׁיּוֹשֵׁב תַּחַת צֵל הָאֱמוּנָה, יוֹרֵשׁ חֵרוּת לוֹ וּלְבָנָיו לְעוֹלָמִים וּמִתְבָּרֵךְ בְּרָכָה עֶלְיוֹנָה. וּמִי שֶׁמּוֹצִיא אֶת עַצְמוֹ מִצֵּל הָאֱמוּנָה, יוֹרֵשׁ גָּלוּת לוֹ וּלְבָנָיו, שֶׁכָּתוּב וַיִּלָּחֶם בְּיִשְׂרָאֵל וַיִּשְׁבְּ מִמֶּנּוּ שֶׁבִי.</p>"],[9522012227,"<p>בַּסֻּכֹּת תֵּשְׁבוּ חָסֵר, וְזֶה עָנָן אֶחָד שֶׁכֻּלָּם קְשׁוּרִים בּוֹ, שֶׁכָּתוּב כִּי עֲנַן ה' עֲלֵיהֶם יוֹמָם. וְכָתוּב וּבְעַמֻּד עָנָן אַתָּה הֹלֵךְ לִפְנֵיהֶם יוֹמָם. זֶהוּ עֲנָנוֹ שֶׁל אַהֲרֹן, שֶׁנִּקְרָא יוֹמָם, שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ. עָנָן אֶחָד נוֹטֵל עִמּוֹ חֲמִשָּׁה אֲחֵרִים, וְהֵם שִׁשָּׁה. וְעָנָן אַחֵר, שֶׁכָּתוּב וּבְעַמּוּד אֵשׁ לָיְלָה, זֶה הֵאִיר לְיִשְׂרָאֵל מֵהָאוֹר שֶׁל אוֹתָם הַשִּׁשָּׁה.</p>\n<p>בַּסֻּכּת תֵּשְׁבוּ שִׁבְעַת יָמִים וְגוֹ'. מִצְוָה (מ\"ה) זוֹ לֵישֵׁב בְּסֻכָּה. וַהֲרֵי בֵּאַרְנוּ, כְּדֵי לְהַרְאוֹת שֶׁיִּשְׂרָאֵל יוֹשְׁבִים בְּסוֹד הָאֱמוּנָה בְּלִי פַחַד כְּלָל, שֶׁהֲרֵי הַמְקַטְרֵג נִפְרָד מֵהֶם, וְכָל מִי שֶׁהוּא בְּסוֹד הָאֱמוּנָה, יוֹשֵׁב בַּסֻּכָּה, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב כָּל הָאֶזְרָח בְּיִשְׂרָאֵל יֵשְׁבוּ בַּסֻּכֹּת. מִי שֶׁהוּא בְּסוֹד הָאֱמוּנָה וּמֵהַזֶּרַע וְהַשֹּׁרֶשׁ שֶׁל יִשְׂרָאֵל, יֵשְׁבוּ בַּסֻּכֹּת. וְהַסּוֹד הַזֶּה נֶאֱמַר בְּכַמָּה מְקוֹמוֹת.</p>\n<p>מִצְוָה (מ\"ו) אַחַר זוֹ, לְהַקְרִיב קָרְבָּן בְּכָל יוֹם, וְהַקָּרְבָּן הַזֶּה לִהְיוֹת חֵלֶק בַּכֹּל, בְּשִׂמְחַת בָּנָיו, מִכֵּיוָן שֶׁכֻּלָּם אֲחוּזִים בָּאִילָן. הָעֲנָפִים שֶׁלְּמַטָּה שֶׁלְּגַבֵּי שֹׁרֶשׁ הָאִילָן, הַכֹּל מִתְבָּרְכִים מִשּׁוּם הָאִילָן. אַף עַל גַּב שֶׁאֵין בָּהֶם תּוֹעֶלֶת, כֻּלָּם מִתְבָּרְכִים. וְשִׂמְחַת יִשְׂרָאֵל בַּאֲבִיהֶם שֶׁלְּמַעְלָה, נוֹתְנִים חֵלֶק שֶׁל בְּרָכוֹת לְכָל אוֹתָם שְׁאָר הָעַמִּים שֶׁיֵּשׁ לָהֶם אֲחִיזָה וְנֶאֶחְזוּ בָהֶם בְּיִשְׂרָאֵל.</p>\n<p>וְכָל הַקָּרְבָּנוֹת הַלָּלוּ, לָתֵת מָזוֹן לְאוֹתָם הַמְמֻנִּים שֶׁל שְׁאָר הָעַמִּים, שֶׁהֲרֵי מִתּוֹךְ הָאַהֲבָה שֶׁאוֹהֵב הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת בָּנָיו, רוֹצֶה שֶׁכֻּלָּם יִהְיוּ אוֹהֲבִים שֶׁלָּהֶם. וְסוֹד זֶה - (משלי יז) בִּרְצוֹת ה' דַּרְכֵי אִישׁ גַּם אוֹיְבָיו יַשְׁלִם אִתּוֹ. אֲפִלּוּ כָּל אוֹתָם הַמְקַטְרְגִים הָעֶלְיוֹנִים, כֻּלָּם חוֹזְרִים לִהְיוֹת אוֹהֲבִים אֶת יִשְׂרָאֵל, וּכְשֶׁהַחֲיָלוֹת שֶׁל מַעְלָה הוֹפְכִים לְאוֹהֲבֵי יִשְׂרָאֵל - כָּל אוֹתָם שֶׁלְּמַטָּה עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>וְאִם תֹּאמַר, לָהֶם הָיוּ מַקְרִיבִים הַקָּרְבָּן? לֹא כָּךְ. אֶלָּא הַכֹּל עוֹלֶה לַקָּדוֹשׁ בָּרוּךְ הוּא וְנִקְרָב. וְהוּא מַפְרִיד הַמָּזוֹן לְכָל הַהֲמוֹנִים שֶׁל הַצְּדָדִים הָאֲחֵרִים שֶׁיֵּהָנוּ בְּאוֹתוֹ הַדּוֹרוֹן שֶׁל בָּנָיו, וְיֵהָפְכוּ לָאוֹהֲבִים שֶׁלָּהֶם, שֶׁיֵּדְעוּ לְמַעְלָה וּלְמַטָּה שֶׁאֵין עַם כְּעַם יִשְׂרָאֵל, שֶׁהֵם חֶלְקוֹ וְגוֹרָלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִתְעַלֶּה כְבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מַעְלָה וּמַטָּה כָּרָאוּי. וְכָל הָאוּכְלוּסִים הָעֶלְיוֹנִים פּוֹתְחִים וְאוֹמְרִים: (שמואל ב ז) וּמִי כְעַמְּךְ כְּיִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ. (עד כאן רעיא מהימנא).</p>\n<p>רַבִּי אֶלְעָזָר פָּתַח, כֹּה אָמַר ה' זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ וְגוֹ'. הַפָּסוּק הַזֶּה נֶאֱמַר עַל כְּנֶסֶת יִשְׂרָאֵל בְּשָׁעָה שֶׁהָיְתָה הוֹלֶכֶת בַּמִּדְבָּר עִם יִשְׂרָאֵל. זָכַרְתִּי לָךְ חֶסֶד - זֶהוּ עֲנָנוֹ שֶׁל אַהֲרֹן שֶׁנּוֹסֵעַ עִם חֲמִשָּׁה אֲחֵרִים שֶׁנִּקְשְׁרוּ עָלֶיךְ וּמְאִירִים עָלֶיךְ. אַהֲבַת כְּלוּלֹתָיִךְ - שֶׁנִּתְקְנוּ לְךְ (וכלם נתקנו בך) וְעִטְּרוּ אוֹתָךְ, וְהִתְקִינוּ אוֹתְךְ כְּמוֹ כַלָּה שֶׁעוֹנֶדֶת אֶת תַּכְשִׁיטֶיהָ. וְכָל כָּךְ לָמָּה? בִּשְׁבִיל לֶכְתֵּךְ אַחֲרַי בַּמִּדְבָּר בְּאֶרֶץ לֹא זְרוּעָה.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁאָדָם יוֹשֵׁב בַּמָּדוֹר הַזֶּה, צֵל הָאֱמוּנָה, הַשְּׁכִינָה פּוֹרֶסֶת אֶת כְּנָפֶיהָ עָלָיו מִלְמַעְלָה, וְאַבְרָהָם וַחֲמִשָּׁה צַדִּיקִים אֲחֵרִים שָׂמִים אֶת מְדוֹרָם עִמּוֹ. אָמַר רַבִּי אַבָּא, אַבְרָהָם וַחֲמִשָּׁה צַדִּיקִים וְדָוִד הַמֶּלֶךְ שָׂמִים מְדוֹרֵיהֶם עִמּוֹ. זֶהוּ שֶׁכָּתוּב, בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים. שִׁבְעַת יָמִים כָּתוּב, וְלֹא בְּשִׁבְעַת יָמִים. כְּמוֹ זֶה כָּתוּב (שמות לא) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְגוֹ'. וְצָרִיךְ אָדָם לִשְׂמֹחַ בְּכָל יוֹם וָיוֹם בְּפָנִים מְאִירוֹת בָּאוֹרְחִים הַלָּלוּ שֶׁשּׁוֹרִים עִמּוֹ.</p>\n<p>וְאָמַר רַבִּי אַבָּא, כָּתוּב בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים, וְאַחַר כָּךְ יֵשְׁבוּ בַּסֻּכֹּת. בָּרִאשׁוֹנָה תֵּשְׁבוּ, וְאַחַר כָּךְ יֵשְׁבוּ. אֶלָּא הָרִאשׁוֹן לָאוֹרְחִים, הַשֵּׁנִי לִבְנֵי הָעוֹלָם. הָרִאשׁוֹן לָאוֹרְחִים, כְּמוֹ שֶׁרַב הַמְנוּנָא סָבָא, כְּשֶׁהָיָה נִכְנָס לַסֻּכָּה הָיָה שָׂמֵחַ, וְעוֹמֵד עַל פֶּתַח הַסֻּכָּה מִבַּחוּץ וְאוֹמֵר: נְזַמֵּן לָאוֹרְחִים. מְסַדֵּר (נסדר) אֶת הַשֻּׁלְחָן, וְעוֹמֵד עַל רַגְלָיו, וּמְבָרֵךְ וְאוֹמֵר: בַּסֻּכּוֹת תֵּשְׁבוּ שִׁבְעַת יָמִים. שְׁבוּ אוֹרְחִים עֶלְיוֹנִים, שְׁבוּ. שְׁבוּ אוֹרְחֵי הָאֱמוּנָה, שְׁבוּ. הֵרִים (רחץ) יָדָיו וְשָׂמַח, וְאָמַר: אַשְׁרֵי חֶלְקֵנוּ, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ וְגוֹ'. וְהָיָה יוֹשֵׁב.</p>\n<p>הַשֵּׁנִי - לִבְנֵי הָעוֹלָם, שֶׁמִּי שֶׁיֵּשׁ לוֹ חֵלֶק בָּעָם וּבָאָרֶץ הַקְּדוֹשָׁה, יוֹשֵׁב בְּצֵל הָאֱמוּנָה, לְקַבֵּל אֶת הָאוֹרְחִים, לִשְׂמֹחַ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וְצָרִיךְ לְשַׂמֵּחַ אֶת הָעֲנִיִּים. מָה הַטַּעַם? מִשּׁוּם שֶׁהַחֵלֶק שֶׁל אוֹתָם אוֹרְחִים שֶׁזִּמֵּן, הוּא לָעֲנִיִּים. וְאוֹתוֹ שֶׁיּוֹשֵׁב בַּצֵּל הַזֶּה שֶׁל הָאֱמוּנָה, וּמַזְמִין אֶת הָאוֹרְחִים הָעֶלְיוֹנִים הַלָּלוּ, אוֹרְחֵי הָאֱמוּנָה, וְלֹא נוֹתֵן לָהֶם חֶלְקָם, כֻּלָּם קָמִים מִמֶּנּוּ וְאוֹמְרִים: (משלי כג) אַל תִּלְחַם אֶת לֶחֶם רַע עַיִן וְגוֹ'. נִמְצָא שֶׁאוֹתוֹ שֻׁלְחָן שֶׁתִּקֵּן - שֶׁלּוֹ הוּא, וְלֹא שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. עָלָיו כָּתוּב (מלאכי ב) וְזֵרִיתִי פֶרֶשׁ עַל פְּנֵיכֶם וְגוֹ', פֶּרֶשׁ חַגֵּיכֶם, וְלֹא חַגַּי. אוֹי לוֹ לְאוֹתוֹ אָדָם בְּשָׁעָה שֶׁאוֹרְחֵי הָאֱמוּנָה הַלָּלוּ קָמִים מִשֻּׁלְחָנוֹ.</p>\n<p>וְאָמַר רַבִּי אַבָּא, אַבְרָהָם, כָּל יָמָיו הָיָה עוֹמֵד בְּפָרָשַׁת דְּרָכִים לְזַמֵּן אוֹרְחִים וּלְסַדֵּר לָהֶם שֻׁלְחָנוֹת. עַכְשָׁו שֶׁמַּזְמִינִים אוֹתוֹ וְאֶת כָּל הַצַּדִּיקִים וְאֶת דָּוִד הַמֶּלֶךְ וְאֵין נוֹתְנִים לָהֶם אֶת חֶלְקָם, אַבְרָהָם עוֹמֵד מֵהַשֻּׁלְחָן וְקוֹרֵא: (במדבר טז) סוּרוּ נָא מֵעַל אָהֳלֵי הָאֲנָשִׁים הָרְשָׁעִים הָאֵלֶּה. וְכֻלָּם עוֹלִים אַחֲרָיו. יִצְחָק אָמַר, (משלי יג) וּבֶטֶן רְשָׁעִים תֶּחְסָר. יַעֲקֹב אָמַר, (שם כג) פִּתְּךְ אָכַלְתָּ תְקִיאֶנָּה. וּשְׁאָר כָּל הַצַּדִּיקִים אוֹמְרִים, (ישעיה כח) כִּי כָּל שֻׁלְחָנוֹת מָלְאוּ קִיא צֹאָה בְּלִי מָקוֹם.</p>\n<p>דָּוִד הַמֶּלֶךְ אָמַר, וְהִשְׁלִים דִּינוֹ, שֶׁכָּתוּב (שמואל א כה) וַיְהִי כַּעֲשֶׂרֶת הַיָּמִים וַיִּגֹּף ה' אֶת נָבָל וַיָּמֹת. מַה זֶּה אוֹמֵר? מִשּׁוּם שֶׁדָּוִד שָׁאַל מִנָּבָל וְנַעֲשָׂה לוֹ אוֹרֵחַ, וְלֹא רָצָה. וְזֶה הִזְמִין אוֹתוֹ, וְלֹא נָתַן לוֹ חֵלֶק. וּבְאוֹתָם עֲשָׂרָה יָמִים שֶׁדָּוִד הַמֶּלֶךְ דָּן אֶת הָעוֹלָם, נִדּוֹן עָלָיו אוֹתוֹ אָדָם שֶׁהִשְׁלִים לוֹ רַע יוֹתֵר מִנָּבָל.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, (משום כך) אֵין הַתּוֹרָה מַטְרִיחָה עַל אָדָם יוֹתֵר, אֶלָּא כְּמוֹ שֶׁהוּא יָכוֹל, שֶׁכָּתוּב (דברים טז) אִישׁ כְּמַתְּנַת יָדוֹ וְגוֹ'. וְלֹא יֹאמַר אָדָם אֹכַל וְאֶשְׂבַּע וְאֶשְׁתֶּה בָּרִאשׁוֹנָה, וּמַה שֶּׁיִּשָּׁאֵר אֶתֵּן לָעֲנִיִּים. אֶלָּא רֵאשִׁית הַכֹּל הוּא שֶׁל הָאוֹרְחִים. וְאִם שִׂמַּח אֶת הָאוֹרְחִים וְהִשְׁקָה אוֹתָם, הַקָּדוֹשׁ בָּרוּךְ הוּא שָׂמֵחַ עִמּוֹ, וְאַבְרָהָם קוֹרֵא עָלָיו, (ישעיהנח) אָז תִּתְעַנַּג עַל ה' וְגוֹ'. וְיִצְחָק קוֹרֵא עָלָיו, (שם נד) כָּל כְּלִי יוּצַר עָלַיִךְ לֹא יִצְלָח. אָמַר רַבִּי שִׁמְעוֹן, אֶת זֶה דָּוִד הַמֶּלֶךְ אָמַר אוֹתוֹ, מִשּׁוּם שֶׁכָּל כְּלֵי הַזַּיִן שֶׁל הַמֶּלֶךְ וְהַקְּרָבוֹת שֶׁל הַמֶּלֶךְ נִפְקְדוּ בְּיַד דָּוִד. אֲבָל יִצְחָק אָמַר, (תהלים קב) גִּבּוֹר בָּאָרֶץ יִהְיֶה זַרְעוֹ וְגוֹ', הוֹן וָעֹשֶׁר וְגוֹ'.</p>\n<p>יַעָקֹב אָמַר, (ישעיה נח) אָז יִבָּקַע כַּשַּׁחַר אוֹרֶךְ וְגוֹ'. שְׁאָר הַצַּדִּיקִים אוֹמְרִים, (שם) וְנָחֲךְ ה' תָּמִיד וְהִשְׂבִּיעַ וְגוֹ'. דָּוִד הַמֶּלֶךְ אָמַר, (שם נד) כָּל כְּלִי יוּצַר עָלַיִךְ לֹא יִצְלָח, שֶׁהֲרֵי הוּא נִפְקָד עַל כָּל כְּלֵי הַזַּיִן שֶׁל הָעוֹלָם. אַשְׁרֵי חֶלְקוֹ שֶׁל הָאָדָם שֶׁזּוֹכֶה לְכָל זֶה. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (שם ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'. וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן וְגוֹ'. רַעְיָא מְהֵימְנָא מִצְוָה (מ\"ז) זוֹ לִטֹּל לוּלָב בְּאוֹתוֹ יוֹם עִם אוֹתָם הַמִּינִים שֶׁלּוֹ, וְהַסּוֹד הַזֶּה בֵּאַרְנוּ, וּפֵרְשׁוּהָ הַחֲבֵרִים, כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹטֵל אֶת יִשְׂרָאֵל בַּיָּמִים הַלָּלוּ וְשָׂמֵחַ בָּהֶם, אַף כָּךְ יִשְׂרָאֵל נוֹטְלִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לְחֶלְקָם וּשְׂמֵחִים עִמּוֹ. וְזֶהוּ הַסּוֹד שֶׁל הַלּוּלָב וְהַמִּינִים שֶׁבּוֹ, שֶׁהוּא סוֹד הַדְּמוּת שֶׁל אָדָם, וַהֲרֵי נִתְבָּאֵר. (ע\"כ רעיא מהימנא).</p>"],[9522012228,"<p>רַבִּי שִׁמְעוֹן פָּתַח, (שם מג) כֹּל הַנִּקְרָא בִשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו יְצַרְתִּיו אַף עֲשִׂיתִיו. כֹּל הַנִּקְרָא בִשְׁמִי - זֶה אָדָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אוֹתוֹ בִּשְׁמוֹ (בדמותו), שֶׁכָּתוּב (בראשית ב) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ. וְקָרָא לוֹ בִּשְׁמוֹ, בְּשָׁעָה שֶׁהוֹצִיא אֱמֶת וְדִין בָּעוֹלָם, וְנִקְרָא אֱלֹהִים, שֶׁכָּתוּב (שמות כב) אֱלֹהִים לֹא תְקַלֵּל.</p>\n<p>קָרָא לוֹ בִּשְׁמוֹ, שֶׁכָּתוּב וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ, וְיָפֶה. הֲרֵי בֵּאַרְנוּ, שֶׁכָּתוּב נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, בְּשָׁעָה שֶׁהַזִּוּוּג נֶאֱמַר. וְכָךְ הוּא בַּזִּוּוּג שֶׁל שְׁנֵיהֶם, בְּצֶלֶם וּדְמוּת. וְאָדָם יָצָא מִזָּכָר וּנְקֵבָה.</p>\n<p>וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ. בְּסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ מָצָאנוּ, שֶׁבְּשָׁעָה שֶׁהַזִּוּוּג נִמְצָא לְמַטָּה, שׁוֹלֵחַ הַקָּדוֹשׁ בָּרוּךְ הוּא דְּיוֹקָן אֶחָד כְּמוֹ פַּרְצוּף אָדָם, רָשׁוּם חָקוּק בְּצֶלֶם, וְעוֹמֵד עַל אוֹתוֹ זִוּוּג. וְאִלְמָלֵא נִתְּנָה רְשׁוּת לָעַיִן לִרְאוֹת, רוֹאֶה אָדָם עַל רֹאשׁוֹ צֶלֶם אֶחָד רָשׁוּם בְּפַרְצוּף שֶׁל אָדָם, וּבְאוֹתוֹ צֶלֶם נִבְרָא הָאָדָם. וְעַד שֶׁעוֹמֵד (וטרם שעומד) אוֹתוֹ צֶלֶם שֶׁשָּׁלַח לוֹ רִבּוֹנוֹ עַל רֹאשׁוֹ וְיִמָּצֵא שָׁם, לֹא נִבְרָא הָאָדָם. זֶהוּ שֶׁכָּתוּב וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ.</p>\n<p>אוֹתוֹ הַצֶּלֶם מִזְדַּמֵּן כְּנֶגְדּוֹ עַד שֶׁיּוֹצֵא לָעוֹלָם. כְּשֶׁיּוֹצֵא, הוּא מִתְגַּדֵּל עִם אוֹתוֹ צֶלֶם, בְּאוֹתוֹ צֶלֶם הוֹלֵךְ. זֶהוּ שֶׁכָּתוּב (תהלים לט) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ. וְהַצֶּלֶם הַזֶּה הוּא מִלְמַעְלָה.</p>\n<p>בְּשָׁעָה שֶׁאוֹתָן רוּחוֹת יוֹצְאוֹת מִמְּקוֹמָן, כָּל רוּחַ וְרוּחַ מִתְתַּקֶּנֶת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ בְּתִקּוּנֵי כָבוֹד, בְּפַרְצוּף שֶׁעוֹמֵד בָּעוֹלָם הַזֶּה, וּמֵאוֹתוֹ דְיוֹקָן תִּקּוּן כָּבוֹד יוֹצֵא הַצֶּלֶם הַזֶּה. וְזֶה שְׁלִישִׁי לָרוּחַ, וּמַקְדִּימָה בָּעוֹלָם הַזֶּה בִּזְמַן שֶׁנִּמְצָא הַזִּוּוּג. וְאֵין לְךְ זִוּוּג בָּעוֹלָם שֶׁלֹּא נִמְצָא בְתוֹכָם צֶלֶם. אֲבָל יִשְׂרָאֵל קְדוֹשִׁים, הַצֶּלֶם הַזֶּה קָדוֹשׁ, וּמִמָּקוֹם קָדוֹשׁ הוּא נִמְצָא בְתוֹכָם. וּלְעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת צֶלֶם מֵאוֹתָם הַמִּינִים הָרָעִים, מִצַּד הַטֻּמְאָה נִמְצָא בְתוֹכָם. וְעַל כֵּן לֹא צָרִיךְ לְאָדָם לְעָרֵב צֶלֶם שֶׁלּוֹ בְּצֶלֶם שֶׁל עוֹבְדֵי עֲבוֹדָה זָרָה, מִשּׁוּם שֶׁזֶּה קָדוֹשׁ - וְזֶה טָמֵא. בּא רְאֵה מַה בֵּין יִשְׂרָאֵל לְעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת וְכוּ'.</p>"],[9522012229,"<p>שֶׁכָּתוּב (במדבר כט) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם, שֶׁהֲרֵי הַיּוֹם הַזֶּה מֵהַמֶּלֶךְ הוּא בִּלְבַדּוֹ, שִׂמְחָתוֹ עִם יִשְׂרָאֵל. מָשָׁל לְמֶלֶךְ שֶׁהִזְמִין אוֹרְחִים, וְהִשְׁתַּדְּלוּ עִמָּהֶם כָּל בְּנֵי הֵיכָלוֹ. אַחַר כָּךְ אָמַר הַמֶּלֶךְ: עַד כָּאן אֲנִי וְאַתֶּם הִתְעַסַּקְנוּ כֻלָּם בָּאוֹרְחִים, וְהִקְרַבְתֶּם קָרְבָּנוֹת עַל שְׁאָר הָעַמִּים בְּכָל יוֹם, מִכָּאן וָהָלְאָה אֲנִי וְאַתֶּם נִשְׂמַח יוֹם אֶחָד. זֶהוּ שֶׁכָּתוּב בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. לָכֶם, לְהַקְרִיב קָרְבָּנוֹת עֲלֵיכֶם. אֲבָל אוֹרְחֵי הָאֱמוּנָה נִמְצָאִים בַּמֶּלֶךְ תָּדִיר, וּבַיּוֹם שֶׁל שִׂמְחַת הַמֶּלֶךְ, כֻּלָּם מִתְכַּנְּסִים עִמּוֹ וְנִמְצָאִים. וְעַל זֶה כָּתוּב עֲצֶרֶת, תַּרְגּוּמוֹ: כִּנּוּס.</p>\n<p>וְהַיּוֹם הַזֶּה יַעֲקֹב הוּא רֹאשׁ לַשִּׂמְחָה, וְכָל אוֹתָם אוֹרְחִים שְׂמֵחִים עִמּוֹ. וְעַל כֵּן כָּתוּב (דברים לג) אַשְׁרֶיךְ יִשְׂרָאֵל מִי כָמוֹךְ. וְכָתוּב (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>\n<p>וְיִקְחוּ אֵלֶיךְ שֶׁמֶן זַיִת זַךְ כָּתִית לַמָּאוֹר וְגוֹ'. אָמַר רַבִּי אֶלְעָזָר, הֲרֵי פֵּרְשׁוּהָ. אֲבָל לָמָּה הִסְמִיךְ הַקָּדוֹשׁ בָּרוּךְ הוּא פָּרָשָׁה זוֹ לְפָרָשַׁת מוֹעֲדִים? אֶלָּא כָּל הַמְּאוֹרוֹת הָעֶלְיוֹנִים, כֻּלָּם מְאוֹרוֹת לְהַדְלִיק שֶׁמֶן מִשְׁחָה עֶלְיוֹן, וַהֲרֵי נִתְבָּאֵר. וְעַל יְדֵי יִשְׂרָאֵל מִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים, וְנִדְלָקִים הַמְּאוֹרוֹת, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (משלי כז) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב, שִׂמְחַת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים.</p>\n<p>רַבִּי אַבָּא פָּתַח, (תהלים לב) שִׂמְחוּ בַה' וְגִילוּ צַדִּיקִים, (שמחו בה', כמו שנאמר) וְכָתוּב (שם קיח) זֶה הַיּוֹם עָשָׂה ה' נָגִילָה וְנִשְׂמְחָה בוֹ. וּפֵרְשׁוּהָ, שֶׁהֲרֵי בַּקָּדוֹשׁ בָּרוּךְ הוּא (במועדים) צָרִיךְ לִשְׂמֹחַ וּלְהָאִיר פָּנִים, וְיִמָּצֵא אָדָם בְּשִׂמְחָה, מִשּׁוּם שֶׁאוֹתָהּ שִׂמְחָה הִיא שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב נָגִילָה וְנִשְׂמְחָה בוֹ - בַּיּוֹם. בוֹ - בַּקָּדוֹשׁ בָּרוּךְ הוּא, וְהַכֹּל דָּבָר אֶחָד.</p>\n<p>שִׂמְחוּ בַה', כְּשֶׁהַדִּינִים נִכְנָעִים וּמִתְעוֹרְרִים רַחֲמִים, וְכַאֲשֶׁר מִתְעוֹרְרִים הָרַחֲמִים, אֲזַי וְגִילוּ צַדִּיקִים, (כתוב) צַדִּיק וְצֶדֶק מִתְבָּרְכִים יַחַד, שֶׁנִּקְרָאִים צַדִּיקִים, כְּמוֹ שֶׁנִּתְבָּאֵר, שֶׁהֲרֵי אֵלּוּ מִתְבָּרְכִים (מברכים) לְעוֹלָמִים, וּשְׂמֵחִים לְעוֹלָמִים כֻּלָּם. וְהַרְנִינוּ כָּל יִשְׁרֵי לֵב - אֵלּוּ בְּנֵי הָאֱמוּנָה, לְהִקָּשֵׁר לָהֶם.</p>\n<p>וּבַכֹּל צָרִיךְ מַעֲשֶׂה לְמַטָּה לְעוֹרֵר לְמַעְלָה. בֹּא רְאֵה, מִי שֶׁאוֹמֵר שֶׁלֹּא צָרִיךְ מַעֲשֶׂה בַּכֹּל, אוֹ דְבָרִים לְהוֹצִיא אוֹתָם וְלַעֲשׂוֹת בָּהֶם קוֹל, תִּפַּח רוּחוֹ. וַהֲרֵי כָּאן הַפָּרָשָׁה הַזּוֹ תּוֹכִיחַ, הַדְלָקַת הַנֵּרוֹת וּקְטֹרֶת הַבְּשָׂמִים, (כאחד, משום) שֶׁכָּתוּב שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. (ובזה) וּבַמַּעֲשֶׂה הַזֶּה נִמְצֵאת הַדְלָקָה לְמַעְלָה וְשִׂמְחָה לְמַטָּה (הדלקה ושמחה למעלה ולמטה) וְהִתְקַשְּׁרוּת יַחַד כָּרָאוּי. (ובמעשה שלמטה מתעורר מעשה שלמעלה) אָמַר רַבִּי יְהוּדָה, הַמִּזְבֵּחַ שֶׁלְּמַטָּה מְעוֹרֵר מִזְבֵּחַ אַחֵר. הַכֹּהֵן שֶׁלְּמַטָּה מְעוֹרֵר כֹּהֵן אַחֵר. בַּמַּעֲשֶׂה שֶׁלְּמַטָּה מִתְעוֹרֵר מַעֲשֶׂה שֶׁלְּמַעְלָה.</p>"],[9522012230,"<p>רַבִּי יוֹסֵי וְרַבִּי יִצְחָק הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי לְרַבִּי יִצְחָק, כָּתוּב (ישעיה נח) וְקָרָאתָ לַשַּׁבָּת עֹנֶג לִקְדוֹשׁ ה' מְכֻבָּד וְגוֹ', וְכִבַּדְתּוֹ מֵעֲשׂוֹת דְּרָכֶיךְ - יָפֶה. אֲבָל מִמְּצוֹא חֶפְצְךְ וְדַבֵּר דָּבָר מַה זֶּה? וּמַה חִסָּרוֹן הוּא לְשַׁבָּת?</p>\n<p>אָמַר לוֹ, וַדַּאי שֶׁזֶּהוּ חִסָּרוֹן, שֶׁאֵין לְךְ דִּבּוּר וְדִבּוּר שֶׁיּוֹצֵא מִפִּיו שֶׁל אָדָם שֶׁאֵין לוֹ קוֹל, וְעוֹלֶה לְמַעְלָה וּמְעוֹרֵר דִּבּוּר אַחֵר. וּמַה הוּא? אוֹתוֹ שֶׁנִּקְרָא חֹל, (למעלה) מֵאוֹתָם יָמִים שֶׁל חֹל וּכְשֶׁמִּתְעוֹרֵר חֹל בְּיוֹם קָדוֹשׁ, וַדַּאי זֶהוּ חִסָּרוֹן לְמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל שׁוֹאֲלִים עָלָיו: מִי הוּא שֶׁרוֹצֶה לְהַפְרִיד הַזִּוּוּג שֶׁלָּנוּ? מִי הוּא שֶׁרוֹצֶה חֹל כָּאן? הָעַתִּיק הַקָּדוֹשׁ לֹא נִרְאֶה, וְלֹא שׁוֹרֶה עַל חֹל.</p>\n<p>מִשּׁוּם כָּךְ הִרְהוּר מֻתָּר. מָה הַטַּעַם? מִשּׁוּם שֶׁהִרְהוּר לֹא עוֹשֶׂה דָבָר וְלֹא נַעֲשֶׂה מִמֶּנּוּ קוֹל, וְלֹא עוֹלֶה. אֲבָל אַחַר שֶׁהוֹצִיא דִבּוּר מִפִּיו, אוֹתוֹ דִבּוּר נַעֲשֶׂה קוֹל, וּבוֹקֵעַ אֲוִירִים וּרְקִיעִים, וְעוֹלֶה לְמַעְלָה וּמְעוֹרֵר דָּבָר אַחֵר, וְעַל כֵּן כָּתוּב מִמְּצוֹא חֶפְצְךְ וְדַבֵּר דָּבָר. וּמִי שֶׁמּוֹצִיא דִבּוּר קָדוֹשׁ מִפִּיו, דְּבַר תּוֹרָה, נַעֲשֶׂה מִמֶּנּוּ קוֹל וְעוֹלֶה לְמַעְלָה, וּמִתְעוֹרְרוֹת קְדֻשּׁוֹת הַמֶּלֶךְ הָעֶלְיוֹן וּמִתְעַטְּרוֹת בְּרֹאשׁוֹ, וְאָז נִמְצֵאת שִׂמְחָה לְמַעְלָה וּלְמַטָּה.</p>"],[9522012231,"<p>אָמַר לוֹ, וַדַּאי כָּךְ הוּא, וַהֲרֵי שָׁמַעְנוּ אֶת הַדָּבָר. אֲבָל מִי שֶׁשָּׁרוּי בְּתַעֲנִית בְּשַׁבָּת, עוֹשֶׂה חִסָּרוֹן לְשַׁבָּת אוֹ לֹא? אִם תֹּאמַר שֶׁלֹּא עוֹשֶׂה חִסָּרוֹן, הֲרֵי סְעוּדַת הָאֱמוּנָה בִּטֵּל מִמֶּנּוּ וְעָנְשׁוֹ רַב, הֲרֵי שִׂמְחַת הַשַּׁבָּת בִּטֵּל מִמֶּנּוּ.</p>\n<p>אָמַר לוֹ, דָּבָר זֶה שָׁמַעְתִּי, שֶׁזֶּהוּ שֶׁמַּשְׁגִּיחִים עָלָיו מִלְמַעְלָה מִכָּל בְּנֵי הָעוֹלָם, מִשּׁוּם שֶׁהַיּוֹם הַזֶּה הוּא שִׂמְחָה לְמַעְלָה וּלְמַטָּה, שִׂמְחַת כָּל הַשְּׂמָחוֹת, שִׂמְחָה שֶׁכָּל הָאֱמוּנָה נִמְצֵאת בָּהּ, וַאֲפִלּוּ הָרְשָׁעִים שֶׁל הַגֵּיהִנֹּם נָחִים בַּיּוֹם הַזֶּה. וְהָאִישׁ הַזֶּה אֵין לוֹ שִׂמְחָה וְאֵין לוֹ מְנוּחָה, וְזֶה שׁוֹנֶה מִכָּל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים. כֻּלָּם שׁוֹאֲלִים עָלָיו: מַה שּׁוֹנֶה שֶׁפְּלוֹנִי הוּא בְּצַעַר?</p>\n<p>וּבְשָׁעָה שֶׁהָעַתִּיק הַקָּדוֹשׁ מִתְגַּלֶּה בַּיּוֹם הַזֶּה וְזֶה נִמְצָא בְצַעַר, תְּפִלָּתוֹ עוֹלָה וְעוֹמֶדֶת לְפָנָיו, אָז נִקְרָעִים כָּל גִּזְרֵי הַדִּינִים שֶׁנִּגְזְרוּ עָלָיו, וַאֲפִלּוּ הִסְכִּימוּ בְּבֵית הַדִּין שֶׁל הַמֶּלֶךְ עָלָיו לְרַע - הַכֹּל נִקְרָע, מִשּׁוּם שֶׁבְּשָׁעָה שֶׁמִּתְגַּלֶּה הָעַתִּיק, נִמְצָאִים כָּל הַחֵרוּת וְכָל הַשִּׂמְחָה, מִשּׁוּם שֶׁמִּתְגַּלֶּה בְּהִלּוּלַת הַמֶּלֶךְ.</p>\n<p>וְעַל זֶה שָׁנִינוּ, קוֹרְעִים לוֹ גְּזַר דִּינוֹ שֶׁל שִׁבְעִים שָׁנָה. מִי הַשִּׁבְעִים שָׁנָה? אֶלָּא, אַף עַל גַּב שֶׁהִסְכִּימוּ עָלָיו כָּל אוֹתָם שִׁבְעִים כִּתְרֵי הַמֶּלֶךְ, שֶׁהוּא נִרְאֶה בָהֶם, הַכֹּל נִקְרָע, מִשּׁוּם שֶׁהָעַתִּיק הַקָּדוֹשׁ נוֹטֵל (מבטל אותו ומהנה) אֶת הָאָדָם, וְהַדְּבָרִים הַלָּלוּ, כְּשֶׁמִּתְעוֹרְרִים עָלָיו בַּחֲלוֹם בְּלֵיל שַׁבָּת.</p>\n<p>לְמֶלֶךָ שֶׁעָשָׂה הִלּוּלָא לִבְנוֹ, וְגָזַר שִׂמְחָה עַל הַכֹּל. בַּיּוֹם הַזֶּה שֶׁל הַהִלּוּלָא כָּל הָעוֹלָם הָיוּ שְׂמֵחִים, וְאִישׁ אֶחָד הָיָה עָצוּב, תָּפוּס בְּקוֹלָר. בָּא הַמֶּלֶךְ לַשִּׂמְחָה, רָאָה אֶת כָּל הָעָם שְׂמֵחִים כְּמוֹ שֶׁהוּא גָּזַר. הֵרִים עֵינָיו, רָאָה אֶת אוֹתוֹ הָאִישׁ הַתָּפוּס בַּקּוֹלָר עָצוּב. אָמַר, וּמַה כָּל בְּנֵי הָעוֹלָם שְׂמֵחִים בַּהִלּוּלָא שֶׁל בְּנִי, וְזֶה תָּפוּס בְּקוֹלָר? מִיָּד צִוָּה וְהוֹצִיאוּ אוֹתוֹ וְהִתִּירוּ אוֹתוֹ מִקּוֹלָרוֹ (מקשריו).</p>\n<p>כָּךָ זֶה שֶׁשָּׁרוּי בְּתַעֲנִית בְּשַׁבָּת, כָּל הָעוֹלָם שְׂמֵחִים - וְהוּא עָצוּב, וְזֶה נִתְפָּס בְּקוֹלָר. בְּשָׁעָה שֶׁהָעַתִּיק הַקָּדוֹשׁ מִתְגַּלֶּה בַּיּוֹם הַזֶּה וְנִמְצָא הָאִישׁ הַזֶּה תָּפוּס בְּקוֹלָר - אַף עַל גַּב שֶׁהִסְכִּימוּ עָלָיו כָּל אוֹתָם שִׁבְעִים שָׁנִים שֶׁאָמַרְנוּ, הַכֹּל נִקְרָע, וְלֹא שׁוֹרֶה עָלָיו הַדִּין. בְּיוֹם אַחֵר יֵשׁ בּוֹ רְשׁוּת לִקְרֹעַ אוֹתוֹ. בְּאוֹתוֹ יוֹם, כָּל שֶׁכֵּן בְּשַׁבָּת.</p>\n<p>שֶׁאֵין לְךְ יוֹם שֶׁלֹּא נִמְצָא בּוֹ כֹּחַ, וּמִי שֶׁשָּׁרוּי בְּתַעֲנִית חֲלוֹם בְּאוֹתוֹ הַיּוֹם, לֹא עוֹלֶה אוֹתוֹ הַיּוֹם עַד שֶׁקּוֹרֵעַ דִּינוֹ. אֲבָל לֹא שֶׁשִּׁבְעִים שָׁנָה כְּיוֹם הַשַּׁבָּת. מִשּׁוּם כָּךְ, בְּאוֹתוֹ יוֹם מַמָּשׁ, וְלֹא בְּיוֹם אַחֵר, שֶׁאֵין רְשׁוּת לְיוֹם עַל יוֹם אַחֵר. כָּל יוֹם, מַה שֶּׁאֵרַע בְּיוֹמוֹ - עוֹשֶׂה. שֶׁלֹּא אֵרַע בְּיוֹמוֹ - אֵינוֹ עוֹשֶׂה. וְעַל כֵּן לֹא צָרִיךְ לָאָדָם לְהַעֲלוֹת אוֹתוֹ מִיּוֹם זֶה לְיוֹם אַחֵר. וּמִשּׁוּם כָּךְ שָׁנִינוּ, דְּבַר יוֹם בְּיוֹמוֹ, וְלֹא דְבַר יוֹם לְיוֹם אַחֵר.</p>\n<p>וּבֹא רְאֵה, לֹא לְחִנָּם מִתְעוֹרְרִים עָלָיו בַּחֲלוֹם, כְּדֵי לְבַקֵּשׁ עָלָיו רַחֲמִים. אוֹי לְאוֹתוֹ אָדָם שֶׁלֹּא מִתְעוֹרְרִים עָלָיו וְלֹא מוֹדִיעִים לוֹ בַּחֲלוֹם, שֶׁזֶּה נִקְרָא רָע. וּמִשּׁוּם כָּךְ כָּתוּב, (תהלים ה) לֹא יְגֻרְךְ רָע. וְכָתוּב (משלי יט) בַּל יִפָּקֶד רָע. בַּל יִפָּקֶד, מִשּׁוּם שֶׁהוּא רָע.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּתוּב (ישעיה נח) מִמְּצוֹא חֶפְצְךְ וְדַבֵּר דָּבָר. כֵּיוָן שֶׁכָּתוּב מִמְּצוֹא חֶפְצְךְ, מַהוּ וְדַבֵּר דָּבָר? אֶלָּא, עַד שֶׁיִּגָּזֵר הַדָּבָר כָּרָאוּי וִידַבֵּר אִתּוֹ. וַדַּאי כָּךְ הוּא בֵּרוּר הַדָּבָר, מַשְׁמָע שֶׁכָּתוּב וְדַבֵּר דָּבָר. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב וַיֹּאמֶר אַךְ עַמִּי הֵמָּה בָּנִים לֹא יְשַׁקֵּרוּ וַיְהִי לָהֶם לְמוֹשִׁיעַ.</p>"],[9522012232,"<p>וַיֵּצֵא בֶּן אִשָּׁה יִשְׂרְאֵלִית וְהוּא בֶּן אִישׁ מִצְרִי וְגוֹ'. וַיֵּצֵא, רַבִּי יְהוּדָה אָמַר, יָצָא מִכְּלָל שֶׁל הַחֵלֶק שֶׁל יִשְׂרָאֵל, שֶׁיָּצָא מִכְּלַל הַכֹּל, יָצָא מִכְּלַל הָאֱמוּנָה. וַיִּנָּצוּ בַּמַּחֲנֶה, מִכָּאן לָמַדְנוּ, כָּל מִי שֶׁבָּא מִזֻּהֲמַת הַזֶּרַע, בַּסּוֹף מְגַלִּים אוֹתוֹ לִפְנֵי הַכֹּל. מִי גָרַם לוֹ? זֻהֲמַת הַחֵלֶק הָרָע שֶׁיֵּשׁ בּוֹ, שֶׁאֵין לוֹ חֵלֶק בִּכְלַל יִשְׂרָאֵל.</p>\n<p>רַבִּי חִיָּיא פָּתַח, (משלי כה) כְּבֹד אֱלֹהִים הַסְתֵּר דָּבָר וּכְבֹד מְלָכִים חֲקֹר דָּבָר. כְּבֹד אֱלֹהִים הַסְתֵּר דָּבָר, שֶׁאֵין רְשׁוּת לְאִישׁ לְגַלּוֹת דְּבָרִים סְתוּמִים שֶׁלֹּא נִמְסְרוּ לְגִלּוּי, דְּבָרִים שֶׁכִּסָּה אוֹתָם אוֹתָם עַתִּיק הַיָּמִים, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כג) לֶאֱכֹל לְשָׂבְעָה וְלִמְכַסֶּה עָתִיק. לֶאֱכֹל לְשָׂבְעָה, עַד אוֹתוֹ מָקוֹם שֶׁיֵּשׁ לוֹ רְשׁוּת וְלֹא יוֹתֵר. וְעִם כָּל זֶה, וְלִמְכַסֶּה עָתִיק, לִמְכַסֶּה עָתִיק וַדַּאי.</p>\n<p>דָּבָר אַחֵר לֶאֱכֹל לְשָׂבְעָה - אוֹתָם הַחֲבֵרִים שֶׁיּוֹדְעִים דְּרָכִים וּשְׁבִילִים לָלֶכֶת בְּדֶרֶךְ הָאֱמוּנָה כָּרָאוּי, כְּמוֹ הַדּוֹר שֶׁרַבִּי שִׁמְעוֹן שָׁרוּי בְּתוֹכוֹ. וְלִמְכַסֶּה עָתִיק - מִדּוֹרוֹת אֲחֵרִים, שֶׁהֲרֵי כֻּלָּם לֹא רְאוּיִים לֶאֱכֹל וּלְשָׂבְעָה וְשֶׁיִּתְגַּלּוּ דְבָרִים בְּתוֹכָם, אֶלָּא לִמְכַסֶּה עָתִיק, כְּמוֹ שֶׁנֶּאֱמַר (קהלת ה) אַל תִּתֵּן אֶת פִּיךְ לַחֲטִיא אֶת בְּשָׂרֶךְ.</p>\n<p>בִּימֵי רַבִּי שִׁמְעוֹן הָיָה אָדָם אוֹמֵר לַחֲבֵרוֹ: פְּתַח פִּיךְ וְיָאִירוּ דְבָרֶיךְ. אַחַר שֶׁנִּפְטַר, הָיוּ אוֹמְרִים: אַל תִּתֵּן אֶת פִּיךְ וְגוֹ'. בְּיָמָיו - לֶאֱכֹל לְשָׂבְעָה. אַחַר שֶׁנִּפְטַר - וְלִמְכַסֶּה עָתִיק. שֶׁהַחֲבֵרִים מְגַמְגְּמִים וְלֹא עוֹמְדִים בַּדְּבָרִים. דָּבָר אַחֵר לֶאֱכֹל לְשָׂבְעָה - בְּאוֹתָם דְּבָרִים שֶׁהִתְגַּלּוּ. וְלִמְכַסֶּה עָתִיק - בְּאוֹתָם דְּבָרִים שֶׁהִתְכַּסּוּ.</p>\n<p>וַיִּקֹּב בֶּן הָאִשָּׁה הַיִּשְׂרְאֵלִית אֶת הַשֵּׁם. מַה זֶּה וַיִּקֹּב? רַבִּי אַבָּא אָמַר, וַיִּקֹּב וַדַּאי, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א יב) וַיִּקֹּב חֹר בְּדַלְתּוֹ, נָקַב אֶת מַה שֶּׁהָיָה סָתוּם. וְשֵׁם אִמּוֹ שְׁלֹמִית בַּת דִּבְרִי, עַד כָּאן נִסְתַּר הַשֵּׁם שֶׁל אִמּוֹ. כֵּיוָן שֶׁכָּתוּב וַיִּקֹּב, נָקַב אֶת שֵׁם אִמּוֹ.</p>\n<p>אָמַר רַבִּי אַבָּא, אִם לֹא שֶׁהַמְּנוֹרָה הַקְּדוֹשָׁה עוֹמֵד בָּעוֹלָם, לֹא הֻרְשֵׁינוּ לְגַלּוֹת, (מכאן והלאה) שֶׁהֲרֵי לֹא נִתָּן דָּבָר זֶה לְגִלּוּי אֶלָּא לַחֲבֵרִים, שֶׁהֵם בֵּין קוֹצְרֵי הַשָּׂדֶה. (שאם לאו) תִּפַּח רוּחָם שֶׁל אֵלּוּ שֶׁבָּאִים לְגַלּוֹת לְאוֹתָם שֶׁלֹּא יוֹדְעִים.</p>\n<p>בֹּא רְאֵה, כָּתוּב וַיִּנָּצוּ בַּמַּחֲנֶה בֶּן הַיִּשְׂרְאֵלִית וְאִישׁ הַיִּשְׂרְאֵלִי. הַפָּסוּק הַזֶּה הֲרֵי בֵּאַרְנוּ, אֲבָל זֶה בֶּן אִשָּׁה אַחֶרֶת שֶׁל אָבִיו, בַּעְלָהּ שֶׁל שְׁלוֹמִית הָיָה. וְכֵיוָן שֶׁבָּא עָלֶיהָ אוֹתוֹ הַמִּצְרִי, בַּחֲצוֹת הַלַּיְלָה, שָׁב לְבֵיתוֹ וְיָדַע אֶת הַדָּבָר, נִפְרַד מִמֶּנָּה וְלֹא בָא עָלֶיהָ. וְנָשָׂא אִשָּׁה אַחֶרֶת וְהוֹלִיד אֶת זֶה, וְנִקְרָא אִישׁ הַיִּשְׂרְאֵלִי, וְהָאַחֵר בֶּן הַיִּשְׂרְאֵלִית. אִם הֵם רָבוּ כָּאן יַחַד, מָה רוֹצֶה כָּאן הַשֵּׁם הַקָּדוֹשׁ? וְלָמָּה קִלֵּל אֶת הַשֵּׁם הַקָּדוֹשׁ?</p>\n<p>אֶלָּא, אִישׁ הַיִּשְׂרְאֵלִי אָמַר הַדָּבָר מֵאִמּוֹ מִתּוֹךְ קְטָטָה. מִיָּד - וַיִּקֹּב בֶּן הָאִשָּׁה הַיִּשְׂרְאֵלִית, כְּמוֹ שֶׁנֶּאֱמַר וַיִּקֹּב חֹר בְּדַלְתּוֹ. סוֹד הַדָּבָר - נָטַל ה' שֶׁל הַשֵּׁם הַקָּדוֹשׁ וְקִלֵּל, לְהָגֵן עַל אִמּוֹ. וְזוֹהִי נְקִיבָה, שֶׁהוּא נָקַב וּפֵרַשׁ אֶת הַשֵּׁם הַקָּדוֹשׁ, וְנֶאֱמַר לְקוֹצְרֵי הַשָּׂדֶה. וְסוֹד הַדָּבָר - (משלי ל) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁיּוֹדְעִים דָּבָר וּמְכַסִּים אוֹתוֹ, וְעַל זֶה נֶאֱמַר (שם כה) רִיבְךְ רִיב אֶת רֵעֶךְ וְסוֹד אַחֵר אַל תְּגָל.</p>\n<p>ה' אַחֲרוֹנָה הָיְתָה נְקֵבָה שֶׁיּוֹנֶקֶת בִּשְׁנֵי צְדָדִים, מִשּׁוּם כָּךְ נָטְלָה אֶת כְּלֵי זֵינוֹ שֶׁל הַמֶּלֶךְ וְנוֹקֶמֶת נִקְמוֹתֶיהָ, שֶׁכָּתוּב הוֹצֵא אֶת הַמְקַלֵּל. עַל זֶה כָּתוּב, אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ, יִרְאַת הָאֵם הִקְדִּים לָאָב. אַשְׁרֵי יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"]]});
